def _admin_auth_path():
    return get_application_dir() / ADMIN_AUTH_CONFIG_NAME

def load_admin_auth_config():
    """Load the per-PC administrator TOTP configuration."""
    global ADMIN_TOTP_SECRET_B32, ADMIN_TOTP_DEVICE_ID, ADMIN_TOTP_ACCOUNT
    ADMIN_TOTP_SECRET_B32 = ""
    ADMIN_TOTP_DEVICE_ID = ""
    ADMIN_TOTP_ACCOUNT = ""
    try:
        auth_path = _admin_auth_path()
        if not auth_path.exists():
            return False, "Administrator authentication is not configured for this PC."
        data = json.loads(auth_path.read_text(encoding="utf-8"))
        secret = re.sub(r"[^A-Z2-7]", "", str(data.get("secret", "")).upper())
        if len(secret) < 16:
            return False, "admin_auth.json contains an invalid TOTP secret."
        ADMIN_TOTP_SECRET_B32 = secret
        ADMIN_TOTP_DEVICE_ID = str(data.get("device_id", "")).strip()
        ADMIN_TOTP_ACCOUNT = str(data.get("account", "")).strip()
        return True, "Administrator authentication loaded."
    except Exception as exc:
        return False, f"Could not read admin_auth.json: {exc}"

def admin_auth_status():
    ok, msg = load_admin_auth_config()
    return {
        "configured": ok,
        "message": msg,
        "device_id": ADMIN_TOTP_DEVICE_ID,
        "account": ADMIN_TOTP_ACCOUNT,
    }


