def configure_tesseract():
    """Find Tesseract automatically and verify that the OCR engine actually works."""
    global OCR_ENGINE_READY, OCR_ENGINE_PATH

    if not OCR_AVAILABLE:
        return False, (
            "OCR Python packages are missing. Install: "
            "py -m pip install pytesseract pillow"
        )

    # PyTesseract ultimately launches the external Tesseract executable with
    # subprocess.Popen. In frozen Windows GUI builds, we enforce the Windows
    # no-console flags at BOTH layers:
    #   1) PyTesseract's subprocess_args()
    #   2) the subprocess.Popen implementation used by PyTesseract
    #
    # The second layer is intentional: it protects against PyTesseract/package
    # version differences and prevents a child process from allocating a black
    # console window even for calls made outside run_tesseract().
    if os.name == "nt":
        try:
            import subprocess as _subprocess

            if not getattr(pytesseract.pytesseract, "_hvpnl_no_console_patch", False):
                _original_subprocess_args = pytesseract.pytesseract.subprocess_args

                def _hvpnl_subprocess_args(include_stdout=True):
                    kwargs = _original_subprocess_args(include_stdout)
                    if hasattr(_subprocess, "CREATE_NO_WINDOW"):
                        kwargs["creationflags"] = (
                            kwargs.get("creationflags", 0)
                            | _subprocess.CREATE_NO_WINDOW
                        )
                    if hasattr(_subprocess, "STARTUPINFO"):
                        si = kwargs.get("startupinfo")
                        if si is None:
                            si = _subprocess.STARTUPINFO()
                        si.dwFlags |= _subprocess.STARTF_USESHOWWINDOW
                        si.wShowWindow = _subprocess.SW_HIDE
                        kwargs["startupinfo"] = si
                    return kwargs

                pytesseract.pytesseract.subprocess_args = _hvpnl_subprocess_args

                # Strict fallback: every Popen initiated through the standard
                # subprocess module receives the no-console flag unless the
                # caller explicitly supplies a stronger creation configuration.
                _original_popen = _subprocess.Popen

                def _hvpnl_quiet_popen(*args, **kwargs):
                    flags = kwargs.get("creationflags", 0)
                    if hasattr(_subprocess, "CREATE_NO_WINDOW"):
                        kwargs["creationflags"] = flags | _subprocess.CREATE_NO_WINDOW

                    si = kwargs.get("startupinfo")
                    if hasattr(_subprocess, "STARTUPINFO"):
                        if si is None:
                            si = _subprocess.STARTUPINFO()
                        si.dwFlags |= _subprocess.STARTF_USESHOWWINDOW
                        si.wShowWindow = _subprocess.SW_HIDE
                        kwargs["startupinfo"] = si

                    return _original_popen(*args, **kwargs)

                _subprocess.Popen = _hvpnl_quiet_popen
                # PyTesseract's module holds the same subprocess module object,
                # so its subprocess.Popen is covered by the wrapper above.
                pytesseract.pytesseract._hvpnl_no_console_patch = True
        except Exception:
            # OCR can still work using PyTesseract's normal hidden-window path.
            pass

    candidates = []

    # Existing PATH first.
    found = shutil.which("tesseract")
    if found:
        candidates.append(found)

    # Common Windows installations.
    for env_name in ("ProgramFiles", "ProgramFiles(x86)", "LOCALAPPDATA"):
        base = os.environ.get(env_name)
        if base:
            candidates.append(
                os.path.join(base, "Tesseract-OCR", "tesseract.exe")
            )

    candidates += [
        r"C:\Program Files\Tesseract-OCR\tesseract.exe",
        r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
    ]

    for candidate in candidates:
        if candidate and os.path.isfile(candidate):
            try:
                pytesseract.pytesseract.tesseract_cmd = candidate
                version = pytesseract.get_tesseract_version()
                OCR_ENGINE_READY = True
                OCR_ENGINE_PATH = candidate
                return True, f"Tesseract OCR ready: {version} ({candidate})"
            except Exception:
                continue

    # Try the default command one final time.
    try:
        version = pytesseract.get_tesseract_version()
        OCR_ENGINE_READY = True
        OCR_ENGINE_PATH = "PATH"
        return True, f"Tesseract OCR ready: {version}"
    except Exception:
        OCR_ENGINE_READY = False
        OCR_ENGINE_PATH = None
        return False, (
            "Tesseract OCR engine was not found. Install Tesseract OCR or place "
            "tesseract.exe in C:\\Program Files\\Tesseract-OCR."
        )

