SSTN_DB_CANDIDATES = (
    "SSTN_MASTER.db",
    "SSTN.db",
    "MASTER_with_SSTN_TESTED.db",
)

def resolve_sstn_database_path():
    override = str(os.environ.get(SSTN_DB_ENV, "") or "").strip()
    if override:
        p = Path(override)
        if not p.is_absolute():
            p = BASE_DIR / p
        return p
    for name in SSTN_DB_CANDIDATES:
        p = BASE_DIR / name
        if p.exists():
            return p
    # Also support a renamed SSTN database, provided it actually contains
    # SSTN_MASTER.  This prevents accidental selection of MASTER.db.
    try:
        for p in sorted(BASE_DIR.glob("*.db")):
            if p.name.casefold() == "master.db":
                continue
            try:
                con = sqlite3.connect(str(p), timeout=3)
                ok = bool(con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='SSTN_MASTER'").fetchone())
                con.close()
                if ok:
                    return p
            except Exception:
                try: con.close()
                except Exception: pass
    except Exception:
        pass
    return BASE_DIR / "SSTN_MASTER.db"

SSTN_DB_PATH = resolve_sstn_database_path()

