def _license_registry_connect():
    con = sqlite3.connect(str(DEVELOPER_LICENSE_REGISTRY_PATH), timeout=30)
    con.execute("""
        CREATE TABLE IF NOT EXISTS developer_licences(
            licence_id TEXT PRIMARY KEY,
            user_name TEXT, organisation TEXT, remarks TEXT, fingerprint TEXT NOT NULL,
            issued_at TEXT, expires_on TEXT, days INTEGER, status TEXT, activation_code TEXT
        )
    """)
    con.commit()
    return con


def save_developer_licence(payload, activation_code, remarks="", status="ACTIVE"):
    con = _license_registry_connect()
    try:
        con.execute("""
            INSERT OR REPLACE INTO developer_licences
            (licence_id,user_name,organisation,remarks,fingerprint,issued_at,expires_on,days,status,activation_code)
            VALUES (?,?,?,?,?,?,?,?,?,?)
        """, (
            payload.get("licence_id"), payload.get("user_name", ""), payload.get("organisation", ""),
            str(remarks or ""), payload.get("fingerprint", ""), payload.get("issued_at", ""),
            payload.get("expires_on", ""), int(payload.get("days", 0) or 0), status, activation_code
        ))
        con.commit()
    finally:
        con.close()


def list_developer_licences():
    con = _license_registry_connect()
    try:
        return con.execute("""
            SELECT licence_id,user_name,organisation,fingerprint,issued_at,expires_on,days,status,remarks
            FROM developer_licences ORDER BY issued_at DESC
        """).fetchall()
    finally:
        con.close()


