class IndexDatabase:
    def __init__(self, path=INDEX_DB_PATH):
        self.path = str(path)
        self.initialize()

    def connect(self):
        # V21 deliberately uses SQLite's rollback journal instead of WAL for
        # the disposable index.  index.db is encrypted/persisted as a single
        # file at shutdown and on every verified publish.  WAL can keep
        # committed data in a sidecar (-wal) file, which is dangerous when a
        # single encrypted database file is copied/decrypted on the next
        # startup.  DELETE + FULL makes the main database file itself the
        # authoritative durable snapshot.
        con = sqlite3.connect(self.path, timeout=60)
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA busy_timeout=60000")
        try:
            con.execute("PRAGMA journal_mode=DELETE")
            con.execute("PRAGMA synchronous=FULL")
        except sqlite3.DatabaseError:
            pass
        return con

    def initialize(self):
        # If an earlier interrupted run left a malformed SQLite file, preserve
        # that file as a backup and automatically create a clean database.
        try:
            con = self.connect()
            try:
                ok = con.execute("PRAGMA integrity_check").fetchone()[0]
                if str(ok).lower() != "ok":
                    raise sqlite3.DatabaseError(f"integrity_check: {ok}")
                # integrity_check alone does not detect an otherwise-valid SQLite
                # file from an incompatible application/build. Validate the schema
                # required by this index before allowing search to use it.
                required_doc_cols = {
                    "id", "file_path", "file_name", "file_hash", "file_size",
                    "modified_time", "page_count", "approval_number",
                    "approval_number_numeric", "approval_code", "approval_date",
                    "approval_date_sort", "file_number", "memo_number", "subject",
                    "full_text", "indexed_at"
                }
                actual_doc_cols = {r[1] for r in con.execute("PRAGMA table_info(documents)").fetchall()}
                if actual_doc_cols and not required_doc_cols.issubset(actual_doc_cols):
                    missing = ", ".join(sorted(required_doc_cols - actual_doc_cols))
                    raise sqlite3.DatabaseError(f"index.db schema mismatch; missing documents columns: {missing}")
                tables = {str(r[0]) for r in con.execute("SELECT name FROM sqlite_master WHERE type IN ('table','view')").fetchall()}
                required_tables = {"documents", "documents_fts", "pages", "semantic_chunks"}
                if tables and not required_tables.issubset(tables):
                    missing = ", ".join(sorted(required_tables - tables))
                    raise sqlite3.DatabaseError(f"index.db schema mismatch; missing tables: {missing}")
            finally:
                con.close()
        except Exception:
            db_file = Path(self.path)
            if db_file.exists():
                stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                backup = db_file.with_name(db_file.stem + f"_CORRUPT_{stamp}" + db_file.suffix)
                try:
                    db_file.rename(backup)
                except Exception:
                    # If Windows is temporarily holding the file, do not destroy
                    # it. The caller will receive a clear error instead.
                    raise RuntimeError(
                        f"Database is corrupt but cannot be renamed. Close any other "
                        f"instance of this app, then remove/rename: {db_file}"
                    )

            # Also remove stale WAL/SHM files belonging to the corrupt DB.
            for suffix in ("-wal", "-shm"):
                stale = Path(str(db_file) + suffix)
                try:
                    if stale.exists():
                        stale.unlink()
                except Exception:
                    pass

        con = self.connect()
        cur = con.cursor()

        cur.execute("""
        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            file_path TEXT UNIQUE NOT NULL,
            file_name TEXT NOT NULL,
            file_hash TEXT,
            file_size INTEGER,
            modified_time REAL,
            page_count INTEGER DEFAULT 0,

            approval_number TEXT,
            approval_number_numeric INTEGER DEFAULT 0,
            approval_code TEXT,
            approval_date TEXT,
            approval_date_sort TEXT,
            file_number TEXT,
            memo_number TEXT,
            subject TEXT,

            full_text TEXT,
            indexed_at TEXT
        )
        """)

        cur.execute("""
        CREATE VIRTUAL TABLE IF NOT EXISTS documents_fts
        USING fts5(
            full_text,
            file_name,
            approval_number,
            approval_code,
            subject,
            tokenize='unicode61'
        )
        """)

        cur.execute("""
        CREATE TABLE IF NOT EXISTS pages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            document_id INTEGER NOT NULL,
            page_number INTEGER NOT NULL,
            page_text TEXT,
            UNIQUE(document_id, page_number),
            FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE
        )
        """)

        cur.execute("CREATE INDEX IF NOT EXISTS idx_doc_approval_num ON documents(approval_number_numeric DESC)")
        cur.execute("CREATE INDEX IF NOT EXISTS idx_doc_path ON documents(file_path)")
        # User data survives re-indexing.
        cur.execute("CREATE TABLE IF NOT EXISTS favorites (document_id INTEGER PRIMARY KEY, created_at TEXT NOT NULL, FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE)")
        cur.execute("CREATE TABLE IF NOT EXISTS document_notes (document_id INTEGER PRIMARY KEY, note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE)")
        cur.execute("CREATE TABLE IF NOT EXISTS search_history (id INTEGER PRIMARY KEY AUTOINCREMENT, query TEXT UNIQUE NOT NULL, searched_at TEXT NOT NULL, use_count INTEGER NOT NULL DEFAULT 1)")

        cur.execute("""
        CREATE TABLE IF NOT EXISTS semantic_chunks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            document_id INTEGER NOT NULL,
            page_number INTEGER NOT NULL,
            chunk_text TEXT NOT NULL,
            embedding BLOB,
            embedding_dim INTEGER DEFAULT 0,
            FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE
        )
        """)
        cur.execute("CREATE INDEX IF NOT EXISTS idx_sem_doc ON semantic_chunks(document_id)")
        # V21 persistent verification marker.  This marker is stored INSIDE
        # the encrypted index database, so it survives application restart.
        # It records the exact MASTER-derived logical fingerprint that was
        # successfully validated before publication.
        cur.execute("""
        CREATE TABLE IF NOT EXISTS index_verification (
            id INTEGER PRIMARY KEY CHECK(id=1),
            verification_version INTEGER NOT NULL DEFAULT 1,
            master_fingerprint TEXT NOT NULL,
            index_fingerprint TEXT NOT NULL,
            document_count INTEGER NOT NULL,
            verified_at TEXT NOT NULL
        )
        """)

        con.commit()
        con.close()
        # V26: DO NOT mutate the verified index during application startup.
        # Earlier builds called repair_duplicate_documents() here.  Even though
        # that repair was intended only for legacy duplicates, startup must be a
        # read/verify operation.  Any repair/rebuild is handled explicitly by the
        # indexing transaction after the startup gate has decided that the index
        # is not valid/current.


    def reset_database_file(self, reason="database corruption"):
        """Rebuild a damaged SQLite index and remove stale journal sidecars."""
        db_file = Path(self.path)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        # Remove sidecars first. A stale WAL/SHM can preserve a bad database state.
        for suffix in ("-wal", "-shm", "-journal"):
            sidecar = Path(str(db_file) + suffix)
            try:
                if sidecar.exists():
                    sidecar.unlink()
            except PermissionError as e:
                raise RuntimeError(
                    f"Database recovery blocked: {sidecar.name} is in use. "
                    "Close every other HVPNL Approval Search window and retry."
                ) from e

        # Preserve the corrupt database instead of trying to write over it.
        if db_file.exists():
            backup = db_file.with_name(
                db_file.stem + f"_CORRUPT_{stamp}" + db_file.suffix
            )
            try:
                db_file.replace(backup)
            except PermissionError as e:
                raise RuntimeError(
                    "Database recovery blocked: hvpnl_index.db is in use. "
                    "Close every other HVPNL Approval Search window and retry."
                ) from e

        # Create a completely fresh database.
        self.initialize()

    @staticmethod
    def is_corruption_error(error):
        text = str(error).lower()
        return any(x in text for x in (
            "database disk image is malformed",
            "database malformed",
            "file is not a database",
            "database corrupt",
        ))

    def get_document_by_path(self, path):
        """Exact stored-path lookup."""
        con = self.connect()
        try:
            return con.execute(
                "SELECT * FROM documents WHERE file_path=?",
                (str(path),)
            ).fetchone()
        finally:
            con.close()

    def get_document_candidates(self, path):
        """
        Find the existing index record even when the folder spelling/case has
        changed.  Old index.db files may have been created with a different
        absolute folder path, so exact path alone is not sufficient.
        """
        path = Path(path)
        exact = str(path)
        name = path.name

        con = self.connect()
        try:
            rows = con.execute(
                """
                SELECT * FROM documents
                WHERE file_path=? OR file_name=?
                ORDER BY CASE WHEN file_path=? THEN 0 ELSE 1 END, id DESC
                """,
                (exact, name, exact)
            ).fetchall()
            return rows
        finally:
            con.close()

    def document_is_current(self, path, size, modified_time, file_hash=None):
        """
        Incremental indexing check.

        Fast path (no hashing/OCR):
            same indexed PDF record + same file size + same modified timestamp
            => current.

        Compatibility path:
            if timestamp changed but the caller supplies a SHA-256 hash, compare
            against the stored hash.  This avoids needless re-indexing when a
            PDF was copied/touched without its contents changing.

        Legacy records:
            filename is also used as a fallback because earlier index.db builds
            may contain a different absolute document-folder path.

        Important: no OCR or text extraction occurs inside this check.
        """
        candidates = self.get_document_candidates(path)
        if not candidates:
            return False

        # 1) Fast incremental check: size + timestamp.  No SHA calculation needed.
        for row in candidates:
            try:
                same_size = int(row["file_size"] or -1) == int(size)
                same_time = abs(float(row["modified_time"] or 0.0) - float(modified_time)) < 0.01
                if same_size and same_time:
                    return True
            except Exception:
                pass

        # 2) Content check only when the fast metadata check failed and a hash
        # has actually been calculated by the caller.
        if file_hash:
            wanted = str(file_hash).strip().lower()
            for row in candidates:
                stored = str(row["file_hash"] or "").strip().lower()
                if stored and stored == wanted:
                    return True

        return False

    def update_metadata(self, document_id, approval_number, file_number, approval_date, subject):
        approval_number = (approval_number or "").strip()
        file_number = (file_number or "").strip()
        approval_date = (approval_date or "").strip()
        subject = (subject or "").strip()
        numeric = 0
        m = re.search(r"\d+", approval_number)
        if m:
            try:
                numeric = int(m.group())
            except Exception:
                numeric = 0
        approval_date_sort = parse_date(approval_date)
        con = self.connect()
        try:
            con.execute("BEGIN IMMEDIATE")
            con.execute("""
                UPDATE documents
                SET approval_number=?, approval_number_numeric=?,
                    file_number=?, memo_number=?, approval_code=?,
                    approval_date=?, approval_date_sort=?, subject=?
                WHERE id=?
            """, (
                approval_number, numeric,
                file_number, file_number, file_number,
                approval_date, approval_date_sort, subject, document_id
            ))
            row = con.execute("SELECT * FROM documents WHERE id=?", (document_id,)).fetchone()
            if row:
                con.execute("DELETE FROM documents_fts WHERE rowid=?", (document_id,))
                con.execute("""
                    INSERT INTO documents_fts(rowid,full_text,file_name,approval_number,approval_code,subject)
                    VALUES (?,?,?,?,?,?)
                """, (document_id, row["full_text"] or "", row["file_name"] or "", row["approval_number"] or "", row["approval_code"] or "", row["subject"] or ""))
            con.commit()
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()

    def repair_duplicate_documents(self):
        """Repair legacy duplicate index rows created when the document root
        changed.

        Older builds used absolute file_path as the SQLite identity. Moving
        the same 1,584 PDFs to a different developer folder therefore created
        a second row for every PDF.  A document is logically identified here
        by filename; when duplicate rows have the same filename, the newest
        row is retained and all dependent records are moved/cleaned.

        This is deliberately conservative: a filename is only collapsed when
        the duplicate rows have the same SHA-256.  Different-content files
        with the same filename are left alone.
        """
        con = self.connect()
        try:
            cur = con.cursor()
            groups = cur.execute("""
                SELECT LOWER(file_name) AS k, COUNT(*) AS n
                FROM documents
                GROUP BY LOWER(file_name)
                HAVING COUNT(*) > 1
            """).fetchall()

            removed = 0
            for g in groups:
                rows = cur.execute("""
                    SELECT id,file_name,file_hash,file_path
                    FROM documents
                    WHERE LOWER(file_name)=?
                    ORDER BY id
                """, (g["k"],)).fetchall()

                # Only repair if all duplicates represent the same PDF bytes.
                hashes = {str(r["file_hash"] or "").lower() for r in rows}
                if len(rows) < 2 or len(hashes) != 1:
                    continue

                keep = rows[-1]  # retain the most recently created row
                keep_id = int(keep["id"])

                for row in rows[:-1]:
                    old_id = int(row["id"])
                    if old_id == keep_id:
                        continue

                    # The retained row already contains the current document
                    # data. Remove only dependent records belonging to the
                    # duplicate row and then remove the duplicate document.
                    for table in ("pages", "semantic_chunks"):
                        cur.execute(
                            f"DELETE FROM {table} WHERE document_id=?",
                            (old_id,)
                        )
                    cur.execute(
                        "DELETE FROM documents_fts WHERE rowid=?",
                        (old_id,)
                    )
                    cur.execute(
                        "DELETE FROM documents WHERE id=?",
                        (old_id,)
                    )
                    removed += 1

            if removed:
                con.commit()
            return removed
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()

    def _find_existing_document_id(self, data):
        """Find the logical document before inserting.

        Prefer the exact path. If the path changed, use the PDF filename so
        relocating the document folder does not create a second index row.
        """
        con = self.connect()
        try:
            row = con.execute(
                "SELECT id FROM documents WHERE file_path=? LIMIT 1",
                (data["file_path"],)
            ).fetchone()
            if row:
                return int(row["id"])

            row = con.execute("""
                SELECT id FROM documents
                WHERE LOWER(file_name)=LOWER(?)
                ORDER BY id DESC
                LIMIT 1
            """, (data["file_name"],)).fetchone()
            return int(row["id"]) if row else None
        finally:
            con.close()

    def upsert_document(self, data, pages, semantic_chunks=None):
        con = self.connect()
        try:
            cur = con.cursor()
            cur.execute("BEGIN IMMEDIATE")

            existing = cur.execute(
                "SELECT id FROM documents WHERE file_path=? LIMIT 1",
                (data["file_path"],)
            ).fetchone()

            if not existing:
                # A folder move must not duplicate the same approval.
                # Filename is the logical document identity in this archive.
                existing = cur.execute("""
                    SELECT id FROM documents
                    WHERE LOWER(file_name)=LOWER(?)
                    ORDER BY id DESC
                    LIMIT 1
                """, (data["file_name"],)).fetchone()

            if existing:
                doc_id = int(existing["id"])
                cur.execute("""
                    UPDATE documents SET
                        file_path=:file_path,
                        file_name=:file_name,
                        file_hash=:file_hash,
                        file_size=:file_size,
                        modified_time=:modified_time,
                        page_count=:page_count,
                        approval_number=:approval_number,
                        approval_number_numeric=:approval_number_numeric,
                        approval_code=:approval_code,
                        approval_date=:approval_date,
                        approval_date_sort=:approval_date_sort,
                        file_number=:file_number,
                        memo_number=:memo_number,
                        subject=:subject,
                        full_text=:full_text,
                        indexed_at=:indexed_at
                    WHERE id=:id
                """, {**data, "id": doc_id})
            else:
                cur.execute("""
                    INSERT INTO documents (
                        file_path,file_name,file_hash,file_size,modified_time,page_count,
                        approval_number,approval_number_numeric,approval_code,
                        approval_date,approval_date_sort,file_number,memo_number,
                        subject,full_text,indexed_at
                    ) VALUES (
                        :file_path,:file_name,:file_hash,:file_size,:modified_time,:page_count,
                        :approval_number,:approval_number_numeric,:approval_code,
                        :approval_date,:approval_date_sort,:file_number,:memo_number,
                        :subject,:full_text,:indexed_at
                    )
                """, data)
                doc_id = int(cur.lastrowid)

            cur.execute("DELETE FROM pages WHERE document_id=?", (doc_id,))
            cur.execute("DELETE FROM documents_fts WHERE rowid=?", (doc_id,))
            cur.execute("""
                INSERT INTO documents_fts(
                    rowid, full_text, file_name, approval_number, approval_code, subject
                ) VALUES (?, ?, ?, ?, ?, ?)
            """, (
                doc_id, data["full_text"], data["file_name"],
                data["approval_number"], data["approval_code"], data["subject"]
            ))

            cur.executemany(
                "INSERT INTO pages(document_id,page_number,page_text) VALUES (?,?,?)",
                [(doc_id, n, txt) for n, txt in pages]
            )

            cur.execute("DELETE FROM semantic_chunks WHERE document_id=?", (doc_id,))
            if semantic_chunks:
                cur.executemany(
                    "INSERT INTO semantic_chunks("
                    "document_id,page_number,chunk_text,embedding,embedding_dim"
                    ") VALUES (?,?,?,?,?)",
                    [
                        (doc_id, pg, txt, emb.tobytes(), int(len(emb)))
                        for pg, txt, emb in semantic_chunks
                    ]
                )

            con.commit()

        except Exception:
            try:
                con.rollback()
            except Exception:
                pass
            raise
        finally:
            con.close()

    def delete_path(self, path):
        con = self.connect()
        row = con.execute("SELECT id FROM documents WHERE file_path=?", (str(path),)).fetchone()
        if row:
            con.execute("DELETE FROM documents_fts WHERE rowid=?", (row["id"],))
            con.execute("DELETE FROM pages WHERE document_id=?", (row["id"],))
            con.execute("DELETE FROM semantic_chunks WHERE document_id=?", (row["id"],))
            con.execute("DELETE FROM documents WHERE id=?", (row["id"],))
        con.commit()
        con.close()

    def count_documents(self):
        con = self.connect()
        n = con.execute("SELECT COUNT(*) FROM documents").fetchone()[0]
        con.close()
        return n

    def search(self, terms, exact_phrase=None, close_search=False, max_gap=10):
        """
        Normal search: every term may occur anywhere in the approval.
        Close search (+): all terms must occur in one compact cluster in the
        indexed PDF text, in either direction/order.
        """
        con = self.connect()
        sql = """
        SELECT d.* FROM documents d
        WHERE 1=1
        """
        params = []

        if exact_phrase:
            sql += " AND LOWER(COALESCE(d.full_text, '')) LIKE ?"
            params.append(f"%{exact_phrase.lower()}%")

        numeric_only_query = (
            len(terms) == 1
            and re.fullmatch(r"\d+", (terms[0] or "").strip()) is not None
            and not exact_phrase
            and not close_search
        )

        if numeric_only_query:
            number_text = terms[0].strip()
            number_value = int(number_text)
            sql += """
                AND (
                    d.approval_number_numeric = ?
                    OR TRIM(COALESCE(d.approval_number, '')) = ?
                    OR LOWER(COALESCE(d.file_name, '')) LIKE ?
                    OR LOWER(COALESCE(d.full_text, '')) LIKE ?
                )
            """
            params.extend([number_value, number_text, f"%{number_text}.pdf", f"%{number_text}%"])
        else:
            searchable = """
                LOWER(
                    COALESCE(d.full_text, '') || ' ' ||
                    COALESCE(d.file_name, '') || ' ' ||
                    COALESCE(d.approval_number, '') || ' ' ||
                    COALESCE(d.approval_code, '') || ' ' ||
                    COALESCE(d.file_number, '') || ' ' ||
                    COALESCE(d.memo_number, '') || ' ' ||
                    COALESCE(d.subject, '')
                )
            """
            for term in terms:
                t = term.lower().strip()
                if t:
                    sql += f" AND {searchable} LIKE ?"
                    params.append(f"%{t}%")

        sql += """
        ORDER BY
            CASE WHEN approval_number_numeric > 0 THEN 0 ELSE 1 END,
            approval_number_numeric DESC,
            file_name COLLATE NOCASE ASC
        """
        rows = con.execute(sql, params).fetchall()
        con.close()

        if close_search and terms:
            rows = [
                row for row in rows
                if text_has_close_terms(row["full_text"] or "", terms, max_gap=max_gap)
            ]
        return rows

    def add_search_history(self, query):
        query = normalize_spaces(query or "")
        if not query: return
        con=self.connect()
        try:
            con.execute("INSERT INTO search_history(query,searched_at,use_count) VALUES (?,?,1) ON CONFLICT(query) DO UPDATE SET searched_at=excluded.searched_at,use_count=use_count+1",(query,datetime.now().isoformat(timespec="seconds"))); con.commit()
        finally: con.close()
    def get_search_history(self, limit=30):
        con=self.connect(); rows=con.execute("SELECT query,searched_at,use_count FROM search_history ORDER BY searched_at DESC LIMIT ?",(int(limit),)).fetchall(); con.close(); return rows
    def clear_search_history(self):
        con=self.connect(); con.execute("DELETE FROM search_history"); con.commit(); con.close()
    def is_favorite(self, document_id):
        con=self.connect(); r=con.execute("SELECT 1 FROM favorites WHERE document_id=?",(document_id,)).fetchone(); con.close(); return bool(r)
    def set_favorite(self, document_id, enabled):
        con=self.connect()
        try:
            if enabled: con.execute("INSERT OR IGNORE INTO favorites(document_id,created_at) VALUES (?,?)",(document_id,datetime.now().isoformat(timespec="seconds")))
            else: con.execute("DELETE FROM favorites WHERE document_id=?",(document_id,))
            con.commit()
        finally: con.close()
    def favorite_documents(self):
        con=self.connect(); rows=con.execute("SELECT d.* FROM favorites f JOIN documents d ON d.id=f.document_id ORDER BY f.created_at DESC").fetchall(); con.close(); return rows
    def get_note(self, document_id):
        con=self.connect(); r=con.execute("SELECT note FROM document_notes WHERE document_id=?",(document_id,)).fetchone(); con.close(); return r["note"] if r else ""
    def save_note(self, document_id, note):
        note=(note or "").strip(); con=self.connect()
        try:
            if note:
                con.execute("INSERT INTO document_notes(document_id,note,updated_at) VALUES (?,?,?) ON CONFLICT(document_id) DO UPDATE SET note=excluded.note,updated_at=excluded.updated_at",(document_id,note,datetime.now().isoformat(timespec="seconds")))
            else:
                con.execute("DELETE FROM document_notes WHERE document_id=?",(document_id,))
            con.commit()
        finally: con.close()
    def document_note_ids(self, document_ids):
        ids=[int(x) for x in document_ids if x is not None]
        if not ids: return set()
        con=self.connect()
        try:
            marks=",".join("?" for _ in ids)
            rows=con.execute(f"SELECT document_id FROM document_notes WHERE document_id IN ({marks}) AND TRIM(note)<>''",ids).fetchall()
            return {int(r["document_id"]) for r in rows}
        finally: con.close()
    def noted_documents(self):
        con=self.connect()
        try:
            return con.execute("SELECT d.*,n.note,n.updated_at AS note_updated_at FROM document_notes n JOIN documents d ON d.id=n.document_id WHERE TRIM(n.note)<>'' ORDER BY n.updated_at DESC").fetchall()
        finally: con.close()
    def smart_suggestions(self, prefix, limit=12):
        prefix=normalize_spaces(prefix or "")
        if len(prefix)<2: return []
        like=f"%{prefix.lower()}%"; con=self.connect()
        rows=con.execute("""SELECT DISTINCT value FROM (SELECT subject value FROM documents WHERE subject IS NOT NULL AND LOWER(subject) LIKE ? UNION SELECT approval_number value FROM documents WHERE approval_number IS NOT NULL AND LOWER(approval_number) LIKE ? UNION SELECT approval_code value FROM documents WHERE approval_code IS NOT NULL AND LOWER(approval_code) LIKE ? UNION SELECT file_name value FROM documents WHERE LOWER(file_name) LIKE ?) WHERE value IS NOT NULL AND TRIM(value)<>'' LIMIT ?""",(like,like,like,like,int(limit))).fetchall(); con.close()
        return [normalize_spaces(r["value"])[:140] for r in rows if r["value"]]

    def semantic_search(self, query_vector, limit=100):
        con = self.connect()
        rows = con.execute("""
            SELECT s.*, d.file_path, d.file_name, d.approval_number,
                   d.approval_number_numeric, d.approval_code, d.approval_date,
                   d.subject, d.full_text, d.indexed_at
            FROM semantic_chunks s
            JOIN documents d ON d.id=s.document_id
            WHERE s.embedding IS NOT NULL AND s.embedding_dim > 0
        """).fetchall()
        con.close()

        best = {}
        q = np.asarray(query_vector, dtype=np.float32)
        for row in rows:
            emb = np.frombuffer(row["embedding"], dtype=np.float32)
            if len(emb) != len(q):
                continue
            score = float(np.dot(q, emb))  # normalized embeddings => cosine similarity
            did = row["document_id"]
            if did not in best or score > best[did]["semantic_score"]:
                item = dict(row)
                item["semantic_score"] = score
                best[did] = item

        result = list(best.values())
        result.sort(key=lambda x: (-x["semantic_score"], -(x.get("approval_number_numeric") or 0)))
        return result[:limit]


# ============================================================
# MASTER DATABASE ADAPTER
# ============================================================

class SSTNMiniChart(QWidget):
    """Compact interactive Qt chart used by the SSTN Statistics dashboard.

    The chart is deliberately dependency-free.  Values are permanently printed
    on every bar/point; hover is only a visual aid and click emits the category
    for drill-down.
    """
    clicked = Signal(str, float, int)

    def __init__(self, chart_type="bar", title="", parent=None):
        super().__init__(parent)
        self.chart_type = str(chart_type or "bar")
        self.title = str(title or "")
        self.data = []
        self.display_values = []
        self._hit_boxes = []
        self._hover_index = -1
        self.setMinimumHeight(250)
        self.setMouseTracking(True)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)

    def set_data(self, data, display_values=None):
        self.data = [(str(a), float(b or 0)) for a, b in (data or [])]
        self.display_values = [str(x) for x in (display_values or [])]
        if len(self.display_values) != len(self.data):
            self.display_values = [""] * len(self.data)
        self._hit_boxes = []
        self._hover_index = -1
        self.update()

    def _fmt(self, v):
        v = float(v or 0)
        return f"{v:,.1f}" if v % 1 else f"{v:,.0f}"

    def _unit(self):
        t = self.title.lower()
        if 'mva' in t:
            return ' MVA'
        if 'tf' in t or 'transformer' in t or 'quantity' in t:
            return ' TF'
        return ''

    def _label_for(self, i):
        if 0 <= i < len(self.display_values) and self.display_values[i]:
            return self.display_values[i]
        return self._fmt(self.data[i][1]) + self._unit()

    def mouseMoveEvent(self, event):
        from PySide6.QtWidgets import QToolTip
        pos = event.position().toPoint()
        found = -1
        for i, rect in enumerate(self._hit_boxes):
            if rect.contains(pos):
                found = i
                break
        self._hover_index = found
        self.update()
        if 0 <= found < len(self.data):
            lab, val = self.data[found]
            QToolTip.showText(self.mapToGlobal(pos), f"{lab}\n{self._label_for(found)}", self)
        else:
            QToolTip.hideText()
        super().mouseMoveEvent(event)

    def _chart_index_at(self, pos):
        for i, rect in enumerate(self._hit_boxes):
            try:
                if rect.contains(pos):
                    return i
            except Exception:
                pass

        # Fallback: use the complete category slot, not only the painted bar.
        # This also makes zero/very-short bars clickable.
        if self.chart_type != 'line' and self.data:
            left, right = 58, 20
            cw = max(1, self.width() - left - right)
            gap = 10
            n = len(self.data)
            bw = max(12, (cw - gap * (n + 1)) / max(1, n))
            for i in range(n):
                x = left + gap + i * (bw + gap)
                if x <= pos.x() <= x + bw:
                    return i
        return -1

    def _emit_chart_click(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            return False
        try:
            pos = event.position().toPoint()
        except Exception:
            return False
        idx = self._chart_index_at(pos)
        if 0 <= idx < len(self.data):
            lab, val = self.data[idx]
            self.clicked.emit(str(lab), float(val), int(idx))
            return True
        return False

    def mousePressEvent(self, event):
        if self._emit_chart_click(event):
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if self._emit_chart_click(event):
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def leaveEvent(self, event):
        from PySide6.QtWidgets import QToolTip
        self._hover_index = -1
        QToolTip.hideText()
        self.update()
        super().leaveEvent(event)

    def paintEvent(self, event):
        from PySide6.QtGui import QPainter, QPen, QBrush, QFont, QColor
        from PySide6.QtCore import QRectF, Qt
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.fillRect(self.rect(), self.palette().base())

        w, h = self.width(), self.height()
        textc = self.palette().text().color()
        gridc = self.palette().mid().color()
        p.setPen(QPen(textc))
        p.setFont(QFont('Segoe UI', 11, QFont.Weight.Bold))
        p.drawText(12, 20, self.title)

        if not self.data:
            p.setFont(QFont('Segoe UI', 10))
            p.drawText(12, 52, 'No data recorded for the selected filter.')
            p.end()
            return

        left, top, right, bottom = 58, 44, 20, 58
        cw, ch = max(1, w - left - right), max(1, h - top - bottom)
        vals = [float(v or 0) for _, v in self.data]
        vmax = max(vals) if vals else 0
        if vmax <= 0:
            vmax = 1.0

        p.setFont(QFont('Segoe UI', 8))
        p.setPen(QPen(gridc, 1))
        for i in range(5):
            yy = top + ch * i / 4
            p.drawLine(left, int(yy), w - right, int(yy))
            p.setPen(QPen(textc, 1))
            label = f'{vmax * (1 - i / 4):,.0f}' if vmax >= 10 else f'{vmax * (1 - i / 4):.1f}'
            p.drawText(4, int(yy + 4), 48, 14, Qt.AlignmentFlag.AlignRight, label)
            p.setPen(QPen(gridc, 1))

        palette = ['#00B8D9', '#7C4DFF', '#FF6D00', '#00C853', '#FF4081', '#FFC107', '#26A69A', '#5C6BC0', '#EC407A', '#8BC34A']
        self._hit_boxes = []

        if self.chart_type == 'line':
            step = cw / max(1, len(self.data) - 1)
            pts = []
            for i, (lab, val) in enumerate(self.data):
                x = left + (i * step if len(self.data) > 1 else cw / 2)
                y = top + ch - (val / vmax) * ch
                pts.append((x, y))
                self._hit_boxes.append(QRectF(x - 11, y - 11, 22, 22))
            for i, (a, b) in enumerate(zip(pts, pts[1:])):
                p.setPen(QPen(QColor(palette[i % len(palette)]), 3))
                p.drawLine(int(a[0]), int(a[1]), int(b[0]), int(b[1]))
            for i, (x, y) in enumerate(pts):
                c = QColor(palette[i % len(palette)])
                r = 7 if i == self._hover_index else 5
                p.setBrush(QBrush(c))
                p.setPen(QPen(c.darker(130), 1))
                p.drawEllipse(QRectF(x - r, y - r, 2 * r, 2 * r))
                p.setPen(QPen(textc, 1))
                p.setFont(QFont('Segoe UI', 8, QFont.Weight.Bold))
                p.drawText(QRectF(x - 70, max(top, y - 30), 140, 20), Qt.AlignmentFlag.AlignCenter, self._label_for(i))
        else:
            n = len(self.data)
            gap = 10
            bw = max(12, (cw - gap * (n + 1)) / max(1, n))
            for i, (lab, val) in enumerate(self.data):
                x = left + gap + i * (bw + gap)
                bh = (val / vmax) * ch if val > 0 else 0
                y = top + ch - bh
                rect = QRectF(x, y, bw, max(4, bh))
                self._hit_boxes.append(rect)
                c = QColor(palette[i % len(palette)])
                if i == self._hover_index:
                    c = c.lighter(125)
                p.setBrush(QBrush(c))
                p.setPen(QPen(c.darker(130), 1))
                p.drawRoundedRect(rect, 6, 6)
                p.setPen(QPen(textc, 1))
                p.setFont(QFont('Segoe UI', 8, QFont.Weight.Bold))
                p.drawText(QRectF(x - 24, max(top, y - 22), bw + 48, 20), Qt.AlignmentFlag.AlignCenter, self._label_for(i))

        p.setPen(QPen(textc, 1))
        p.setFont(QFont('Segoe UI', 8))
        for i, (lab, val) in enumerate(self.data):
            if self.chart_type == 'line':
                x = left + (i * cw / max(1, len(self.data) - 1) if len(self.data) > 1 else cw / 2)
            else:
                n = len(self.data)
                gap = 10
                bw = max(12, (cw - gap * (n + 1)) / max(1, n))
                x = left + gap + i * (bw + gap) + bw / 2
            txt = str(lab)
            if len(txt) > 18:
                txt = txt[:17] + '…'
            p.drawText(QRectF(x - 70, h - bottom + 4, 140, 36), Qt.AlignmentFlag.AlignCenter | Qt.AlignmentFlag.AlignTop, txt)
        p.end()
def _sstn_parse_transformers(text):
    """Parse SSTN transformer capacity notation into individual transformer rows.

    Examples handled explicitly:
      3x1000 + 1x1500 MVA, 765/400kV
      2x315 MVA, 400/220kV
      25/31.5 MVA, 220/132kV

    The high-side voltage is retained so voltage-wise statistics can bucket
    transformers by the actual ratio rather than by the parent SSTN voltage.
    """
    out=[]
    raw=str(text or '').strip()
    if not raw:
        return out
    term = r'(?:\d+\s*[xX×]\s*)?\d+(?:\.\d+)?(?:\s*/\s*\d+(?:\.\d+)?)?'
    clause_pat = re.compile(
        rf'(?P<body>\(?\s*{term}(?:\s*\+\s*{term})*\s*\)?)\s*MVA\s*,?\s*'
        rf'(?P<hv>\d+(?:\.\d+)?)\s*/\s*(?P<lv>\d+(?:\.\d+)?)\s*kV', re.I)
    for m in clause_pat.finditer(raw):
        body=(m.group('body') or '').strip().strip('()').strip()
        hi_v=float(m.group('hv')); lo_v=float(m.group('lv'))
        ratio=f'{hi_v:g}/{lo_v:g} kV'
        for tok in re.split(r'\s*\+\s*', body):
            tok=tok.strip().strip('()')
            mm=re.fullmatch(r'(?:(\d+)\s*[xX×]\s*)?(\d+(?:\.\d+)?)(?:\s*/\s*(\d+(?:\.\d+)?))?', tok)
            if not mm:
                continue
            count=int(mm.group(1) or 1)
            a=float(mm.group(2)); b=float(mm.group(3)) if mm.group(3) else a
            out.append({'count':count,'low_mva':min(a,b),'high_mva':max(a,b),'ratio':ratio,'hv':hi_v,'lv':lo_v})
    return out


def _sstn_transformer_totals(text):
    rows=_sstn_parse_transformers(text)
    return {
        'tf_count':sum(x['count'] for x in rows),
        'mva':sum(x['count']*x['high_mva'] for x in rows),
        'by_ratio':rows,
    }

class Database:
    @staticmethod
    def is_corruption_error(error):
        """Compatibility facade used by the background index worker."""
        return IndexDatabase.is_corruption_error(error)

    """
    Application database facade.

    MASTER mode:
      MASTER.db        = authoritative metadata + embedded PDF BLOBs
      index.db         = searchable OCR/full-text index (encrypted at rest)
      hvpnl_user_data.db = local favourites, notes and search history

    This keeps the existing GUI/search code intact while ensuring that PDFs are
    opened from MASTER.db rather than from an exposed documents folder.
    """
    def __init__(self, path=DB_PATH):
        self.path = str(path)
        p = Path(path)
        self.master_mode = p.name.lower() == "master.db" or (MASTER_DB_PATH.exists() and p.resolve() == MASTER_DB_PATH.resolve())
        self.master_path = p if self.master_mode else MASTER_DB_PATH
        # MASTER.db and index.db are encrypted storage files. DB_STORE.prepare()
        # decrypts them to the runtime paths before Database() is constructed.
        # Never derive the index path from MASTER.db here, otherwise the old
        # legacy name hvpnl_index.db is searched beside the runtime MASTER file.
        self.index_path = INDEX_DB_PATH if self.master_mode else p
        if self.master_mode and not self.master_path.exists():
            raise FileNotFoundError(f"MASTER database runtime copy not found: {self.master_path}")
        # index.db may legitimately be absent in Developer mode when the
        # developer intentionally wants to rebuild the searchable/OCR index
        # from MASTER.db + the configured document folder. EncryptedDatabaseStore
        # prepares an empty runtime SQLite file in that case, so do not reject it.
        if self.master_mode and not self.index_path.exists():
            try:
                Path(self.index_path).parent.mkdir(parents=True, exist_ok=True)
                con = sqlite3.connect(str(self.index_path))
                con.close()
            except Exception as e:
                raise FileNotFoundError(
                    f"Could not create a fresh runtime index database: {e}"
                )
        self.index = IndexDatabase(self.index_path)
        self.user_path = USER_DB_PATH if self.master_mode else p.with_name("hvpnl_user_data.db")
        self._init_user_db()

    def _master_connect(self, readonly=False):
        if readonly:
            uri = f"file:{Path(self.master_path).resolve().as_posix()}?mode=ro"
            con = sqlite3.connect(uri, uri=True, timeout=60)
        else:
            con = sqlite3.connect(str(self.master_path), timeout=60)
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA busy_timeout=60000")
        # V9.4 metadata_history compatibility migration
        # Existing MASTER approvals/PDF BLOBs are never rebuilt or replaced.
        if not readonly:
            con.execute("""
                CREATE TABLE IF NOT EXISTS metadata_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    approval_id INTEGER NOT NULL,
                    field_name TEXT NOT NULL,
                    old_value TEXT,
                    new_value TEXT,
                    changed_on TEXT NOT NULL,
                    change_reason TEXT
                )
            """)
            con.commit()
        if not readonly:
            try:
                cols = {r[1] for r in con.execute("PRAGMA table_info(approvals)").fetchall()}
                if cols and "metadata_updated_on" not in cols:
                    con.execute("ALTER TABLE approvals ADD COLUMN metadata_updated_on TEXT")
                    con.commit()
            except sqlite3.DatabaseError:
                pass
            # Developer-managed non-approval reference documents. PDFs are stored
            # as BLOBs here so they remain part of the versioned MASTER database.
            con.execute("""
                CREATE TABLE IF NOT EXISTS reference_documents (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    category TEXT NOT NULL DEFAULT 'Other',
                    title TEXT NOT NULL,
                    original_filename TEXT NOT NULL UNIQUE,
                    description TEXT DEFAULT '',
                    district TEXT DEFAULT '',
                    pdf_blob BLOB NOT NULL,
                    pdf_sha256 TEXT NOT NULL,
                    full_text TEXT DEFAULT '',
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                )
            """)
            try:
                rcols = {r[1] for r in con.execute("PRAGMA table_info(reference_documents)").fetchall()}
                if "district" not in rcols:
                    con.execute("ALTER TABLE reference_documents ADD COLUMN district TEXT DEFAULT ''")
                    con.commit()
            except sqlite3.DatabaseError:
                pass
            # Haryana transmission substation master list. Coordinates are
            # developer-maintained; no coordinates are invented by the app.
            con.execute("""
                CREATE TABLE IF NOT EXISTS substations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    voltage_kv INTEGER NOT NULL,
                    latitude REAL NOT NULL,
                    longitude REAL NOT NULL,
                    district TEXT DEFAULT '',
                    substation_type TEXT NOT NULL DEFAULT 'AIS',
                    existing_capacity TEXT DEFAULT '',
                    approved_capacity TEXT DEFAULT '',
                    approved_rno TEXT DEFAULT '',
                    remarks TEXT DEFAULT '',
                    updated_at TEXT NOT NULL
                )
            """)
            # Backward-compatible schema upgrades for older MASTER.db files.
            try:
                scols = {r[1] for r in con.execute("PRAGMA table_info(substations)").fetchall()}
                if "substation_type" not in scols:
                    con.execute("ALTER TABLE substations ADD COLUMN substation_type TEXT NOT NULL DEFAULT 'AIS'")
                if "existing_capacity" not in scols:
                    con.execute("ALTER TABLE substations ADD COLUMN existing_capacity TEXT DEFAULT ''")
                if "approved_capacity" not in scols:
                    con.execute("ALTER TABLE substations ADD COLUMN approved_capacity TEXT DEFAULT ''")
                if "approved_rno" not in scols:
                    con.execute("ALTER TABLE substations ADD COLUMN approved_rno TEXT DEFAULT ''")
                con.commit()
            except sqlite3.DatabaseError:
                pass
            con.commit()
        return con

    def _user_connect(self):
        con = sqlite3.connect(str(self.user_path), timeout=60)
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA busy_timeout=60000")
        return con

    def _init_user_db(self):
        con = self._user_connect()
        try:
            con.execute("CREATE TABLE IF NOT EXISTS favorites (document_id INTEGER PRIMARY KEY, created_at TEXT NOT NULL)")
            con.execute("CREATE TABLE IF NOT EXISTS document_notes (document_id INTEGER PRIMARY KEY, note TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL)")
            con.execute("CREATE TABLE IF NOT EXISTS search_history (id INTEGER PRIMARY KEY AUTOINCREMENT, query TEXT UNIQUE NOT NULL, searched_at TEXT NOT NULL, use_count INTEGER NOT NULL DEFAULT 1)")
            con.commit()
        finally:
            con.close()

    # Canonical identity rule -------------------------------------------------
    # PDF filename is the authoritative approval identity:
    # 1234.pdf <-> R.No. 1234; 1234A.pdf <-> R.No. 1234A.
    @staticmethod
    def _canonical_pdf_filename(value):
        value = Path(str(value or '')).name.strip()
        if not value:
            return ''
        if not value.lower().endswith('.pdf'):
            value += '.pdf'
        return value.casefold()

    @staticmethod
    def _approval_number_from_filename(value):
        name = Path(str(value or '')).name.strip()
        if name.lower().endswith('.pdf'):
            name = name[:-4]
        return name.strip()

    def _master_row_by_pdf_filename(self, con, file_name):
        """Return an approval/PDF row using the actual MASTER schema.

        Different MASTER.db generations use either ``sha256`` or
        ``pdf_sha256`` for the PDF digest.  The digest is optional for lookup;
        the BLOB itself is authoritative.  Always alias the available digest
        column back to the stable key ``pdf_sha256`` so callers do not depend
        on a particular physical schema.
        """
        key = self._canonical_pdf_filename(file_name)
        if not key:
            return None

        pcols = {str(r[1]) for r in con.execute(
            "PRAGMA table_info(pdf_documents)"
        ).fetchall()}
        if "original_filename" not in pcols or "pdf_blob" not in pcols:
            raise RuntimeError(
                "MASTER.db pdf_documents must contain original_filename and pdf_blob."
            )

        if "sha256" in pcols:
            hash_expr = "p.sha256"
        elif "pdf_sha256" in pcols:
            hash_expr = "p.pdf_sha256"
        else:
            hash_expr = "''"

        return con.execute(
            "SELECT a.*, p.original_filename, p.pdf_blob, "
            f"{hash_expr} AS pdf_sha256 "
            "FROM approvals a "
            "JOIN pdf_documents p ON p.approval_id = a.approval_id "
            "WHERE LOWER(p.original_filename) = ? "
            "LIMIT 1",
            (key,),
        ).fetchone()


    def _merge_row(self, row):
        if row is None: return None
        data = dict(row)
        if not self.master_mode: return data
        filename = str(data.get("file_name") or "").strip()
        if not filename: return data
        con = self._master_connect(readonly=True)
        try:
            m = con.execute("SELECT a.*, p.original_filename FROM approvals a INNER JOIN pdf_documents p ON p.approval_id=a.approval_id WHERE LOWER(TRIM(p.original_filename))=LOWER(TRIM(?)) LIMIT 1", (filename,)).fetchone()
            if m:
                m = dict(m)
                for key in ("approval_number","approval_number_numeric","approval_code","memo_number","file_number","approval_date","approval_date_sort","subject"):
                    if key in m and m.get(key) is not None: data[key] = m[key]
                data["master_approval_id"] = m.get("approval_id")
                data["metadata_status"] = m.get("metadata_status")
                data["verified"] = m.get("verified")
        finally:
            con.close()
        return data


    def _merge_row(self, row):
        if row is None: return None
        data = dict(row)
        if not self.master_mode: return data
        filename = str(data.get("file_name") or "").strip()
        if not filename: return data
        con = self._master_connect(readonly=True)
        try:
            m = con.execute("SELECT a.*, p.original_filename FROM approvals a INNER JOIN pdf_documents p ON p.approval_id=a.approval_id WHERE LOWER(TRIM(p.original_filename))=LOWER(TRIM(?)) LIMIT 1", (filename,)).fetchone()
            if m:
                m = dict(m)
                for key in ("approval_number","approval_number_numeric","approval_code","memo_number","file_number","approval_date","approval_date_sort","subject"):
                    if key in m and m.get(key) is not None: data[key] = m[key]
                data["master_approval_id"] = m.get("approval_id")
                data["metadata_status"] = m.get("metadata_status")
                data["verified"] = m.get("verified")
        finally:
            con.close()
        return data

    def _merge_rows(self, rows):
        return [self._merge_row(r) for r in rows]

    def _merge_rows(self, rows):
        if not self.master_mode:
            return [dict(r) for r in rows]
        return [self._merge_row(r) for r in rows]

    def get_document_by_path(self, path):
        return self._merge_row(self.index.get_document_by_path(path))

    def count_documents(self):
        return self.index.count_documents()

    def get_latest_approval_for_startup(self):
        """Return the highest numeric Approval/R.No. with an embedded PDF.

        MASTER.db is authoritative for startup selection in embedded-PDF mode.
        The searchable index can contain historical/stale metadata, so it must
        not decide which approval is considered the latest at application start.
        """
        if getattr(self, "master_mode", False):
            try:
                con = self._master_connect(readonly=True)
                try:
                    row = con.execute(
                        "SELECT a.*, p.original_filename "
                        "FROM approvals a "
                        "INNER JOIN pdf_documents p ON p.approval_id = a.approval_id "
                        "WHERE COALESCE(a.approval_number_numeric,0) > 0 "
                        "AND LOWER(TRIM(p.original_filename)) LIKE '%.pdf' "
                        "AND length(COALESCE(p.pdf_blob, X'')) > 0 "
                        "ORDER BY a.approval_number_numeric DESC, a.approval_id DESC "
                        "LIMIT 1"
                    ).fetchone()
                finally:
                    con.close()
                return dict(row) if row else None
            except Exception:
                pass

        # Legacy/non-MASTER fallback.
        try:
            con = self.index.connect()
            try:
                candidates = con.execute(
                    "SELECT * FROM documents "
                    "WHERE COALESCE(approval_number_numeric,0) > 0 "
                    "AND LOWER(file_name) LIKE '%.pdf' "
                    "ORDER BY approval_number_numeric DESC, id DESC LIMIT 100"
                ).fetchall()
            finally:
                con.close()
            for row in candidates:
                d = dict(row)
                filename = str(d.get("file_name") or "").strip()
                if not filename:
                    continue
                try:
                    blob, original = self.get_pdf_blob_by_filename(filename)
                except Exception:
                    blob, original = None, None
                if blob:
                    d["original_filename"] = original or filename
                    return d
            return dict(candidates[0]) if candidates else None
        except Exception:
            return None


    def get_editable_documents(self):
        if not self.master_mode:
            con = self.index.connect()
            try:
                return [dict(r) for r in con.execute(
                    "SELECT * FROM documents "
                    "ORDER BY file_name COLLATE NOCASE, id ASC"
                ).fetchall()]
            finally:
                con.close()

        con = self._master_connect(readonly=True)
        try:
            rows = con.execute(
                "SELECT a.*, p.original_filename "
                "FROM approvals a "
                "INNER JOIN pdf_documents p ON p.approval_id=a.approval_id "
                "ORDER BY a.approval_id ASC"
            ).fetchall()

            out = []
            for r in rows:
                d = dict(r)
                filename = str(d.get("original_filename") or "").strip()
                if not filename:
                    continue

                d["id"] = d.get("approval_id")
                d["master_approval_id"] = d.get("approval_id")
                d["file_name"] = filename
                d["file_path"] = filename

                canonical = self._approval_number_from_filename(filename)
                d["approval_number"] = canonical
                mm = re.search(r"\d+", canonical)
                d["approval_number_numeric"] = int(mm.group()) if mm else 0

                d["approval_code"] = d.get("approval_code") or ""
                d["file_number"] = (
                    d.get("file_number")
                    or d.get("memo_number")
                    or d.get("approval_code")
                    or ""
                )
                d["memo_number"] = d.get("memo_number") or d["file_number"]
                d["approval_date"] = d.get("approval_date") or ""
                d["approval_date_sort"] = d.get("approval_date_sort") or ""
                d["subject"] = d.get("subject") or ""
                d["full_text"] = d.get("full_text") or ""
                d["metadata_status"] = d.get("metadata_status") or ""
                d["verified"] = d.get("verified")
                out.append(d)

            out.sort(
                key=lambda r: (
                    r.get("approval_number_numeric") or 0,
                    str(r.get("approval_number") or "").casefold(),
                    str(r.get("file_name") or "").casefold(),
                )
            )
            return out
        finally:
            con.close()

    def search(self, terms, exact_phrase=None, close_search=False, max_gap=10):
        """Search the current index, with an authoritative MASTER.db fallback.

        During a resumable rebuild index.db may contain only part of MASTER.db.
        Search therefore supplements indexed hits with matching MASTER metadata and
        stored full_text. This keeps the search box responsive and useful while
        indexing continues, instead of making the whole application appear frozen.
        """
        indexed_rows = []
        try:
            indexed_rows = self._merge_rows(self.index.search(terms, exact_phrase, close_search, max_gap))
        except Exception:
            indexed_rows = []

        if not self.master_mode:
            return indexed_rows

        wanted = [str(x).strip() for x in (terms or []) if str(x).strip()]
        phrase = str(exact_phrase or "").strip()
        con = self._master_connect(readonly=True)
        try:
            # While index.db is incomplete, search MASTER metadata directly.
            # Do not assume pdf_documents contains a full_text column.
            rows = con.execute(
                "SELECT a.*, p.original_filename "
                "FROM approvals a INNER JOIN pdf_documents p ON p.approval_id=a.approval_id "
                "WHERE length(COALESCE(p.pdf_blob, X'')) > 0 "
                "ORDER BY COALESCE(a.approval_number_numeric,0) DESC, a.approval_id ASC"
            ).fetchall()
        finally:
            con.close()

        master_matches = []
        for raw in rows:
            d = dict(raw)
            filename = str(d.get("original_filename") or "")
            master_text = str(d.get("pdf_full_text") or d.get("full_text") or "")
            hay = " ".join(
                str(d.get(k) or "") for k in
                ("approval_number", "approval_code", "memo_number", "file_number",
                 "approval_date", "subject", "original_filename")
            ) + " " + master_text
            hay = hay.casefold()
            match = (phrase.casefold() in hay) if phrase else (bool(wanted) and all(t.casefold() in hay for t in wanted))
            if not match:
                continue
            d["id"] = d.get("approval_id")
            d["master_approval_id"] = d.get("approval_id")
            d["file_name"] = filename
            d["file_path"] = f"MASTER:{d.get('approval_id')}"
            canonical = self._approval_number_from_filename(filename)
            d["approval_number"] = canonical or str(d.get("approval_number") or "")
            mm = re.search(r"\d+", canonical)
            d["approval_number_numeric"] = int(mm.group()) if mm else int(d.get("approval_number_numeric") or 0)
            d["file_number"] = d.get("file_number") or d.get("memo_number") or ""
            d["memo_number"] = d.get("memo_number") or d["file_number"]
            d["approval_date"] = d.get("approval_date") or ""
            d["approval_date_sort"] = d.get("approval_date_sort") or ""
            d["subject"] = d.get("subject") or ""
            d["full_text"] = master_text
            master_matches.append(d)

        # MASTER.db is authoritative while indexing. Deduplicate by approval_id,
        # preferring the indexed row when both sources contain the same approval.
        merged = {int(r.get("id")): r for r in master_matches if r.get("id") is not None}
        for r in indexed_rows:
            try:
                rid = int(r["id"])
            except Exception:
                continue
            merged[rid] = r
        out = list(merged.values())
        out.sort(key=lambda r: (
            -(r.get("approval_number_numeric") or 0),
            str(r.get("approval_number") or r.get("file_name") or "").casefold(),
            str(r.get("file_name") or "").casefold(),
        ))
        return out

    def semantic_search(self, query_vector, limit=100):
        return self._merge_rows(self.index.semantic_search(query_vector, limit))

    def get_pdf_blob_by_filename(self, file_name):
        """Return the exact embedded PDF whose filename matches the selected result.

        IMPORTANT: In this archive the PDF filename is the immutable identity:
            1639.pdf <-> Approval/R.No. 1639
            1223A.pdf <-> Approval/R.No. 1223A

        Do not resolve the PDF through a possibly stale document id or a generic
        approval_id lookup. This method always fetches the BLOB by the exact
        selected filename from the result card.
        """
        if not self.master_mode:
            return None, None

        key = self._canonical_pdf_filename(file_name)
        if not key:
            return None, None

        con = self._master_connect(readonly=True)
        try:
            # Never use an arbitrary LIMIT 1 row here.  The selected filename is
            # the canonical identity of the approval, and a duplicate filename in
            # MASTER.db must be reported rather than silently returning whichever
            # row SQLite happens to encounter first.
            rows = con.execute("""
                SELECT rowid AS _pdf_rowid, pdf_blob, original_filename
                FROM pdf_documents
                WHERE LOWER(TRIM(original_filename)) = ?
            """, (key,)).fetchall()
            if not rows:
                return None, None
            if len(rows) != 1:
                names = ", ".join(str(r["_pdf_rowid"]) for r in rows)
                raise RuntimeError(
                    f"Duplicate embedded PDF filename '{file_name}' in MASTER.db "
                    f"(rows: {names}). Refusing to display an ambiguous BLOB."
                )
            row = rows[0]
            blob = bytes(row["pdf_blob"] or b"")
            if not blob:
                return None, row["original_filename"]
            return blob, row["original_filename"]
        finally:
            con.close()


    def get_pdf_blob_by_filename(self, file_name):
        if not self.master_mode:
            return None, None

        key = self._canonical_pdf_filename(file_name)
        if not key:
            return None, None

        con = self._master_connect(readonly=True)
        try:
            sql = (
                "SELECT rowid AS _pdf_rowid, pdf_blob, original_filename "
                "FROM pdf_documents "
                "WHERE LOWER(TRIM(original_filename))=?"
            )
            rows = con.execute(sql, (key,)).fetchall()

            if not rows:
                # If it is not an approval PDF, try developer-managed reference documents.
                try:
                    blob, ref_name = self.get_reference_blob_by_filename(file_name)
                    if blob is not None:
                        return blob, ref_name
                except Exception:
                    pass
                return None, None
            if len(rows) != 1:
                ids = ", ".join(str(r["_pdf_rowid"]) for r in rows)
                raise RuntimeError(
                    f"Duplicate embedded PDF filename '{file_name}' in MASTER.db "
                    f"(rows: {ids})."
                )

            row = rows[0]
            blob = bytes(row["pdf_blob"] or b"")
            return (blob if blob else None), row["original_filename"]
        finally:
            con.close()

    def get_pdf_blob(self, document_id=None, file_name=None):
        if not self.master_mode:
            return None, None

        if file_name:
            return self.get_pdf_blob_by_filename(file_name)

        if document_id is None:
            return None, None

        # Search-result ID: index.db document ID -> canonical filename.
        try:
            icon = self.index.connect()
            try:
                idx = icon.execute(
                    "SELECT file_name FROM documents WHERE id=? LIMIT 1",
                    (int(document_id),),
                ).fetchone()
            finally:
                icon.close()

            if idx and idx["file_name"]:
                return self.get_pdf_blob_by_filename(idx["file_name"])
        except Exception:
            pass

        # MASTER editor ID: approval_id -> embedded PDF.
        con = self._master_connect(readonly=True)
        try:
            row = con.execute(
                "SELECT pdf_blob, original_filename FROM pdf_documents "
                "WHERE approval_id=? LIMIT 1",
                (int(document_id),),
            ).fetchone()

            if not row:
                return None, None

            blob = bytes(row["pdf_blob"] or b"")
            return (blob if blob else None), row["original_filename"]
        finally:
            con.close()


    def update_metadata(self, document_id, approval_number, file_number, approval_date, subject):
        if not self.master_mode:
            return self.index.update_metadata(
                document_id, approval_number, file_number,
                approval_date, subject
            )

        file_number = (file_number or "").strip()
        approval_date = normalize_display_date(approval_date)
        subject = (subject or "").strip()

        con = self._master_connect()
        try:
            con.execute("BEGIN IMMEDIATE")

            old_row = con.execute(
                "SELECT a.*, p.original_filename "
                "FROM approvals a "
                "INNER JOIN pdf_documents p ON p.approval_id=a.approval_id "
                "WHERE a.approval_id=? LIMIT 1",
                (int(document_id),),
            ).fetchone()

            if not old_row:
                raise RuntimeError(
                    f"MASTER approval record {document_id} was not found."
                )

            old = dict(old_row)
            file_name = str(old.get("original_filename") or "").strip()
            canonical = self._approval_number_from_filename(file_name)

            requested = (approval_number or "").strip()
            if requested and requested.casefold() != canonical.casefold():
                raise ValueError(
                    "R.No./Approval No. is fixed by the PDF filename.\n\n"
                    f"PDF: {file_name}\n"
                    f"Canonical R.No.: {canonical}\n"
                    f"Entered: {requested}"
                )

            mm = re.search(r"\d+", canonical)
            numeric = int(mm.group()) if mm else 0
            date_sort = parse_date(approval_date)

            cols = {
                r[1]
                for r in con.execute("PRAGMA table_info(approvals)").fetchall()
            }

            values = {
                "approval_number": canonical,
                "approval_number_numeric": numeric,
                "file_number": file_number,
                "memo_number": file_number,
                "approval_code": file_number,
                "approval_date": approval_date,
                "approval_date_sort": date_sort,
                "subject": subject,
                "metadata_status": "MANUALLY_CORRECTED",
                "metadata_updated_on": datetime.now().isoformat(timespec="seconds"),
            }
            values = {k: v for k, v in values.items() if k in cols}

            if values:
                con.execute(
                    "UPDATE approvals SET "
                    + ", ".join(f"{k}=?" for k in values)
                    + " WHERE approval_id=?",
                    list(values.values()) + [old["approval_id"]],
                )

            con.execute(
                "CREATE TABLE IF NOT EXISTS metadata_history ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT,"
                "approval_id INTEGER NOT NULL,"
                "field_name TEXT NOT NULL,"
                "old_value TEXT,"
                "new_value TEXT,"
                "changed_on TEXT NOT NULL,"
                "change_reason TEXT)"
            )

            changes = {
                "approval_number": canonical,
                "file_number": file_number,
                "approval_date": approval_date,
                "subject": subject,
            }
            now = datetime.now().isoformat(timespec="seconds")

            for field, new_value in changes.items():
                old_value = old.get(field) or ""
                if old_value != new_value:
                    con.execute(
                        "INSERT INTO metadata_history "
                        "(approval_id,field_name,old_value,new_value,changed_on,change_reason) "
                        "VALUES (?,?,?,?,?,?)",
                        (
                            old["approval_id"],
                            field,
                            old_value,
                            new_value,
                            now,
                            "Edited through HVPNL Approval Search",
                        ),
                    )

            con.commit()
        except Exception:
            try:
                con.rollback()
            except Exception:
                pass
            raise
        finally:
            con.close()

        # V22.3.43: MASTER.db is authoritative and sync_all() intentionally
        # skips MASTER.db. Persist the committed runtime MASTER snapshot to the
        # encrypted MASTER.db immediately after a successful metadata update.
        DB_STORE.sync_file(MASTER_DB_PATH, MASTER_STORAGE_PATH)
        DB_STORE.note_runtime_synced(MASTER_STORAGE_PATH, MASTER_DB_PATH)

        # Synchronize the search index only if this PDF is already indexed.
        try:
            icon = self.index.connect()
            try:
                idx = icon.execute(
                    "SELECT id FROM documents WHERE file_name=? LIMIT 1",
                    (file_name,),
                ).fetchone()
            finally:
                icon.close()

            if idx:
                try:
                    self.index.update_metadata(
                        idx["id"], canonical, file_number,
                        approval_date, subject
                    )
                except Exception:
                    pass
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Developer-managed reference documents (non-approval PDFs)
    # ------------------------------------------------------------------
    def _ensure_developer_auxiliary_tables(self):
        """Ensure Developer-only MASTER tables exist before read-only access.

        The distributed MASTER.db may have been created before the
        reference_documents/substations features were introduced.  Those
        tables are created by _master_connect() only on a writable connection.
        The previous code opened them read-only first, which caused:
            sqlite3.OperationalError: no such table: reference_documents
            sqlite3.OperationalError: no such table: substations

        Run this migration only while Developer mode is active.  User PCs are
        never modified merely by opening the map/reference-document screens.
        """
        if not self.master_mode:
            return
        if str(globals().get("ACTIVE_LICENSE_ROLE", "")).upper() != "DEVELOPER":
            return
        con = self._master_connect(readonly=False)
        con.close()

    def list_reference_documents(self):
        self._ensure_developer_auxiliary_tables()
        con = self._master_connect(readonly=True)
        try:
            try:
                return [dict(r) for r in con.execute(
                    "SELECT id,category,title,original_filename,description,district,pdf_sha256,created_at,updated_at "
                    "FROM reference_documents ORDER BY category,title"
                ).fetchall()]
            except sqlite3.OperationalError as exc:
                # Backward compatibility with an old USER database/release
                # which predates this optional table.
                if "no such table: reference_documents" in str(exc).lower():
                    return []
                raise
        finally:
            con.close()

    def get_reference_document(self, doc_id):
        self._ensure_developer_auxiliary_tables()
        con = self._master_connect(readonly=True)
        try:
            try:
                r = con.execute(
                    "SELECT * FROM reference_documents WHERE id=?",
                    (int(doc_id),)
                ).fetchone()
            except sqlite3.OperationalError as exc:
                if "no such table: reference_documents" in str(exc).lower():
                    return None
                raise
            return dict(r) if r else None
        finally:
            con.close()

    @staticmethod
    def _reference_district_from_filename(filename):
        """Infer Haryana district from conventional District_Infra/Map.pdf names."""
        stem = Path(str(filename or '')).stem.strip()
        m = re.match(r"^(.+?)\s*[_-]\s*(?:infra(?:structure)?|map|power[_ -]?map)$", stem, re.I)
        if m:
            return re.sub(r"\s+", " ", m.group(1)).strip()
        return ""

    def list_reference_districts(self):
        """Return alphabetically sorted districts represented by reference PDFs."""
        self._ensure_developer_auxiliary_tables()
        con = self._master_connect(readonly=True)
        try:
            try:
                rows = con.execute("SELECT district,category,title,original_filename FROM reference_documents").fetchall()
            except sqlite3.OperationalError as exc:
                if "no such table: reference_documents" in str(exc).lower():
                    return []
                raise
        finally:
            con.close()
        districts = set()
        for r in rows:
            d = str(r[0] or '').strip()
            if not d:
                d = self._reference_district_from_filename(r[3])
            if d:
                districts.add(d)
        return sorted(districts, key=lambda x: x.casefold())

    def add_or_update_reference_document(self, pdf_path, category, title, description='', existing_id=None, district=''):
        pdf_path = Path(pdf_path)
        if not pdf_path.exists() or pdf_path.suffix.lower() != '.pdf':
            raise FileNotFoundError(f"PDF not found: {pdf_path}")
        blob = pdf_path.read_bytes()
        digest = hashlib.sha256(blob).hexdigest()
        pages, full_text, _meta = extract_pdf(pdf_path)
        now = datetime.now().isoformat(timespec='seconds')
        filename = pdf_path.name
        district = str(district or '').strip() or self._reference_district_from_filename(filename)
        con = self._master_connect()
        try:
            con.execute('BEGIN IMMEDIATE')
            if existing_id:
                old = con.execute("SELECT original_filename FROM reference_documents WHERE id=?", (int(existing_id),)).fetchone()
                if not old:
                    raise RuntimeError('Reference document record not found.')
                con.execute("""UPDATE reference_documents SET category=?,title=?,original_filename=?,description=?,district=?,pdf_blob=?,pdf_sha256=?,full_text=?,updated_at=? WHERE id=?""",
                             (str(category).strip() or 'Other', str(title).strip() or filename, filename, str(description or '').strip(), district, sqlite3.Binary(blob), digest, full_text, now, int(existing_id)))
                doc_id = int(existing_id)
            else:
                con.execute("""INSERT INTO reference_documents(category,title,original_filename,description,district,pdf_blob,pdf_sha256,full_text,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)""",
                             (str(category).strip() or 'Other', str(title).strip() or filename, filename, str(description or '').strip(), district, sqlite3.Binary(blob), digest, full_text, now, now))
                doc_id = int(con.execute('SELECT last_insert_rowid()').fetchone()[0])
            con.commit()
        except Exception:
            con.rollback(); raise
        finally:
            con.close()

        # Put reference documents into the existing FTS index using a reserved
        # path. This lets normal application search find them without changing
        # the approval identity rules.
        try:
            self.index.upsert_document({
                'file_path': f'REFERENCE:{doc_id}',
                'file_name': filename,
                'file_hash': digest,
                'file_size': len(blob),
                'modified_time': pdf_path.stat().st_mtime,
                'page_count': len(pages),
                'approval_number': '', 'approval_number_numeric': 0,
                'approval_code': '', 'approval_date': '', 'approval_date_sort': '',
                'file_number': '', 'memo_number': '',
                'subject': f"[{category}] {title}",
                'full_text': full_text,
                'indexed_at': now,
            }, pages)
        except Exception:
            # The MASTER record remains valid; developer can re-index later.
            pass
        return doc_id

    def ensure_reference_documents_indexed(self):
        """Ensure embedded Map/Infra PDFs are present in the normal FTS index.

        This repair is deliberately safe for the USER application: it reads
        the reference PDFs from MASTER.db but writes only to index.db.  Older
        releases could have reference records with a PDF BLOB but no usable
        FTS text.  The current embedded BLOB is OCR'd when required and then
        indexed under REFERENCE:<id>.
        """
        con = self._master_connect(readonly=True)
        try:
            try:
                rows = [dict(r) for r in con.execute(
                    "SELECT id,category,title,original_filename,district,pdf_blob,pdf_sha256,full_text FROM reference_documents"
                ).fetchall()]
            except sqlite3.OperationalError as exc:
                if 'no such table: reference_documents' in str(exc).lower():
                    return 0
                raise
        finally:
            con.close()
        repaired = 0
        for r in rows:
            cat = str(r.get('category') or '').strip().lower()
            title = str(r.get('title') or '').strip().lower()
            fn = str(r.get('original_filename') or '').strip().lower()
            is_map = ('district map' in cat or 'power map' in title or '_map' in fn or fn.endswith('map.pdf'))
            is_infra = ('district infrastructure' in cat or 'district infra' in cat or 'infrastructure' in title or 'infra' in title or '_infra' in fn or '_infrastructure' in fn)
            if not (is_map or is_infra):
                continue
            blob = bytes(r.get('pdf_blob') or b'')
            if not blob:
                continue
            digest = hashlib.sha256(blob).hexdigest()
            idx_ok = False
            try:
                ic = self.index.connect()
                try:
                    ir = ic.execute(
                        "SELECT id,full_text,file_hash FROM documents WHERE file_path=? LIMIT 1",
                        (f"REFERENCE:{int(r['id'])}",)
                    ).fetchone()
                    idx_ok = bool(ir and str(ir['file_hash'] or '').lower() == digest.lower() and len(normalize_spaces(ir['full_text'] or '')) >= 3)
                finally:
                    ic.close()
            except Exception:
                idx_ok = False

            master_text_ok = len(normalize_spaces(r.get('full_text') or '')) >= 3
            needs_ocr_refresh = False
            if master_text_ok and idx_ok:
                try:
                    probe = fitz.open(stream=blob, filetype='pdf')
                    needs_ocr_refresh = any(len(normalize_spaces(pg.get_text('text') or '')) < 20 for pg in probe)
                    probe.close()
                except Exception:
                    pass

            if master_text_ok and idx_ok and not needs_ocr_refresh:
                continue

            try:
                pages, full_text, _meta = extract_pdf_bytes(blob)
            except Exception:
                continue
            now = datetime.now().isoformat(timespec='seconds')
            try:
                self.index.upsert_document({
                    'file_path': f"REFERENCE:{int(r['id'])}",
                    'file_name': r.get('original_filename') or r.get('title') or f"reference_{r['id']}.pdf",
                    'file_hash': digest,
                    'file_size': len(blob),
                    'modified_time': 0,
                    'page_count': len(pages),
                    'approval_number': '', 'approval_number_numeric': 0,
                    'approval_code': '', 'approval_date': '', 'approval_date_sort': '',
                    'file_number': '', 'memo_number': '',
                    'subject': f"[{r.get('category') or 'Reference'}] {r.get('title') or r.get('original_filename') or ''}",
                    'full_text': full_text,
                    'indexed_at': now,
                }, pages)
                repaired += 1
            except Exception:
                pass
        return repaired

    def delete_reference_document(self, doc_id):
        row = self.get_reference_document(doc_id)
        if not row: return False
        con = self._master_connect()
        try:
            con.execute('DELETE FROM reference_documents WHERE id=?', (int(doc_id),)); con.commit()
        finally:
            con.close()
        try:
            con = self.index.connect()
            try:
                r = con.execute("SELECT id FROM documents WHERE file_path=?", (f"REFERENCE:{int(doc_id)}",)).fetchone()
                if r:
                    did=int(r['id'])
                    con.execute('DELETE FROM pages WHERE document_id=?',(did,))
                    con.execute('DELETE FROM documents_fts WHERE rowid=?',(did,))
                    con.execute('DELETE FROM documents WHERE id=?',(did,))
                    con.commit()
            finally: con.close()
        except Exception: pass
        return True

    def list_substations(self):
        # V3: SSTN data is read exclusively from authoritative MASTER.db.
        """Return GIS-ready station rows from SSTN_MASTER/SSTN_INFRA in MASTER.db.

        IMPORTANT: SSTN_MASTER and SSTN_INFRA are part of the existing
        authoritative MASTER database.  They are NOT a separate SSTN database.
        Use the prepared runtime MASTER database through _master_connect() so
        this also works correctly with the application's encrypted-at-rest
        MASTER.db deployment.

        The established V50 GIS renderer expects the legacy keys (name,
        voltage_kv, latitude, longitude, etc.), so SSTN_MASTER/SSTN_INFRA are
        adapted to that interface here. One map marker is created per physical
        SSTN_MASTER record; multiple infrastructure stages are aggregated into
        the station's approval/capacity fields.
        """
        con = None
        try:
            # MASTER_DB_PATH is the prepared/decrypted runtime copy of the
            # authoritative MASTER.db. Do NOT search for SSTN_MASTER.db here.
            con = self._master_connect(readonly=True)
            master = con.execute(
                "SELECT * FROM SSTN_MASTER ORDER BY sstn_name"
            ).fetchall()
            infra_rows = con.execute(
                "SELECT * FROM SSTN_INFRA ORDER BY sstn_id, seq_no"
            ).fetchall()
        except sqlite3.OperationalError as exc:
            # Keep the GIS dialog graceful if an older MASTER.db has not yet
            # received the SSTN tables. Do not silently switch to another DB.
            if "no such table" in str(exc).lower():
                return []
            raise
        finally:
            if con is not None:
                con.close()

        infra_by = {}
        for ir in infra_rows:
            infra_by.setdefault(str(ir["sstn_id"]), []).append(dict(ir))

        def voltage_number(value):
            m = re.search(r"(765|400|220|132|66)", str(value or ""))
            return int(m.group(1)) if m else 0

        result = []
        for mr in master:
            r = dict(mr)
            sid = str(r.get("sstn_id") or "").strip()
            stages = infra_by.get(sid, [])
            stages.sort(key=lambda x: int(x.get("seq_no") or 0))
            existing = next((str(x.get("existing_capacity") or "").strip() for x in stages if str(x.get("existing_capacity") or "").strip()), "")
            approved = ""
            for x in stages:
                val = str(x.get("approved_capacity") or "").strip()
                if val:
                    approved = val
            rnos = []
            for x in stages:
                val = str(x.get("r_no") or "").strip().strip(",")
                if val and val not in rnos:
                    rnos.append(val)

            result.append({
                "id": sid,
                "sstn_id": sid,
                "name": str(r.get("sstn_name") or "").strip(),
                "voltage_kv": voltage_number(r.get("voltage_level")),
                "voltage_level": str(r.get("voltage_level") or "").strip(),
                "latitude": r.get("latitude"),
                "longitude": r.get("longitude"),
                "district": str(r.get("district") or "").strip(),
                "substation_type": str(r.get("substation_type") or "AIS").strip().upper(),
                "substation_status": str(r.get("substation_status") or "").strip(),
                "entity": str(r.get("entity") or "").strip(),
                "ts_division": str(r.get("ts_division") or "").strip(),
                "ts_circle": str(r.get("ts_circle") or "").strip(),
                "existing_capacity": existing,
                "approved_capacity": approved,
                "approved_rno": ", ".join(rnos),
                "remarks": str(r.get("master_remarks") or "").strip(),
                "master_remarks": str(r.get("master_remarks") or "").strip(),
                "infra_records": stages,
            })
        result.sort(key=lambda x: (-int(x.get("voltage_kv") or 0), str(x.get("name") or "").casefold()))
        return result

    def _ensure_sstn_tables(self):
        """Ensure the normalized SSTN tables exist in authoritative MASTER.db."""
        con=self._master_connect()
        try:
            con.execute("""CREATE TABLE IF NOT EXISTS SSTN_MASTER (
                sstn_id TEXT PRIMARY KEY, sstn_name TEXT NOT NULL UNIQUE,
                substation_status TEXT NOT NULL, substation_type TEXT NOT NULL,
                entity TEXT NOT NULL, voltage_level TEXT NOT NULL,
                ts_division TEXT NOT NULL DEFAULT '', ts_circle TEXT NOT NULL DEFAULT '',
                district TEXT NOT NULL DEFAULT '', latitude REAL, longitude REAL,
                gelo_pdf TEXT DEFAULT '', sld_pdf TEXT DEFAULT '', master_remarks TEXT DEFAULT ''
            )""")
            con.execute("""CREATE TABLE IF NOT EXISTS SSTN_INFRA (
                infra_id TEXT PRIMARY KEY, sstn_id TEXT NOT NULL, seq_no INTEGER NOT NULL,
                existing_capacity TEXT NOT NULL DEFAULT '', approved_capacity TEXT NOT NULL DEFAULT '',
                approved_fy TEXT DEFAULT '', r_no TEXT DEFAULT '', infra_remarks TEXT DEFAULT '',
                FOREIGN KEY(sstn_id) REFERENCES SSTN_MASTER(sstn_id) ON DELETE CASCADE,
                UNIQUE(sstn_id,seq_no)
            )""")
            con.execute("CREATE INDEX IF NOT EXISTS idx_sstn_master_name ON SSTN_MASTER(sstn_name)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_sstn_master_district ON SSTN_MASTER(district)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_sstn_infra_sstn ON SSTN_INFRA(sstn_id,seq_no)")
            con.commit()
        finally: con.close()

    def list_sstn_master(self):
        self._ensure_sstn_tables(); con=self._master_connect(readonly=True)
        try: return [dict(r) for r in con.execute("SELECT * FROM SSTN_MASTER ORDER BY voltage_level DESC,sstn_name COLLATE NOCASE").fetchall()]
        finally: con.close()

    def list_sstn_infra(self, sstn_id=None):
        self._ensure_sstn_tables(); con=self._master_connect(readonly=True)
        try:
            if sstn_id:
                q="SELECT * FROM SSTN_INFRA WHERE sstn_id=? ORDER BY seq_no"; args=(str(sstn_id),)
            else:
                q="SELECT * FROM SSTN_INFRA ORDER BY sstn_id,seq_no"; args=()
            return [dict(r) for r in con.execute(q,args).fetchall()]
        finally: con.close()

    def _ensure_substation_biography_tables(self):
        con=self._master_connect()
        try:
            con.execute("""CREATE TABLE IF NOT EXISTS TL_NETWORK_LAYOUT (
                sstn_id TEXT NOT NULL, node_sstn_id TEXT NOT NULL,
                pos_x REAL NOT NULL DEFAULT 0, pos_y REAL NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL, PRIMARY KEY(sstn_id,node_sstn_id),
                FOREIGN KEY(sstn_id) REFERENCES SSTN_MASTER(sstn_id) ON DELETE CASCADE,
                FOREIGN KEY(node_sstn_id) REFERENCES SSTN_MASTER(sstn_id) ON DELETE CASCADE
            )""")
            con.execute("""CREATE TABLE IF NOT EXISTS TL_NETWORK_CONNECTION (
                connection_id TEXT PRIMARY KEY, line_id TEXT NOT NULL,
                from_substation_id TEXT NOT NULL, to_substation_id TEXT NOT NULL,
                remarks TEXT DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
                UNIQUE(line_id,from_substation_id,to_substation_id),
                FOREIGN KEY(line_id) REFERENCES TL_LINE_MASTER(line_id) ON DELETE CASCADE,
                FOREIGN KEY(from_substation_id) REFERENCES SSTN_MASTER(sstn_id),
                FOREIGN KEY(to_substation_id) REFERENCES SSTN_MASTER(sstn_id)
            )""")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_network_layout_root ON TL_NETWORK_LAYOUT(sstn_id)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_network_conn_from ON TL_NETWORK_CONNECTION(from_substation_id)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_network_conn_to ON TL_NETWORK_CONNECTION(to_substation_id)")
            con.commit()
        finally: con.close()

    def list_saved_substation_network_connections(self, sstn_id):
        """Return ONLY explicitly saved Biography connectivity records for a station."""
        self._ensure_sstn_tables(); self._ensure_transmission_line_tables(); self._ensure_substation_biography_tables()
        sid=str(sstn_id or '').strip()
        if not sid: return []
        con=self._master_connect(readonly=True)
        try:
            rows=con.execute("""SELECT c.connection_id,c.line_id,c.from_substation_id,c.to_substation_id,
                          c.remarks AS connection_remarks,c.created_at,c.updated_at,
                          l.*
                   FROM TL_NETWORK_CONNECTION c
                   JOIN TL_LINE_MASTER l ON l.line_id=c.line_id
                   WHERE c.from_substation_id=? OR c.to_substation_id=?
                   ORDER BY l.line_voltage,l.line_name,c.connection_id""",(sid,sid)).fetchall()
            out=[]
            for x in rows:
                d=dict(x); d['direction']='OUTGOING' if str(d.get('from_substation_id'))==sid else 'INCOMING'
                d['conductor_records']=[dict(c) for c in con.execute('SELECT * FROM TL_LINE_CONDUCTOR WHERE line_id=? ORDER BY circuit_no',(d['line_id'],)).fetchall()]
                oid=d.get('to_substation_id') if d['direction']=='OUTGOING' else d.get('from_substation_id')
                other=con.execute('SELECT sstn_id,sstn_name,voltage_level,latitude,longitude,substation_status,substation_type,district FROM SSTN_MASTER WHERE sstn_id=?',(str(oid or ''),)).fetchone()
                d['connected_substation']=dict(other) if other else {'sstn_id':oid or '', 'sstn_name':d.get('to_substation') if d['direction']=='OUTGOING' else d.get('from_substation')}
                out.append(d)
            return out
        finally: con.close()

    def get_substation_biography(self, sstn_id):
        self._ensure_sstn_tables(); self._ensure_transmission_line_tables(); self._ensure_substation_biography_tables()
        sid=str(sstn_id or '').strip()
        if not sid: return None
        con=self._master_connect(readonly=True)
        try:
            r=con.execute('SELECT * FROM SSTN_MASTER WHERE sstn_id=?',(sid,)).fetchone()
            if not r: return None
            out=dict(r)
            out['infra']=[dict(x) for x in con.execute('SELECT * FROM SSTN_INFRA WHERE sstn_id=? ORDER BY seq_no',(sid,)).fetchall()]
            # V22.3.59: Connected Lines / Network Diagram use explicit saved connectivity.
            rows=con.execute("""SELECT c.connection_id,c.line_id,c.from_substation_id,c.to_substation_id,
                          c.remarks AS connection_remarks,c.created_at,c.updated_at,
                          l.*
                   FROM TL_NETWORK_CONNECTION c
                   JOIN TL_LINE_MASTER l ON l.line_id=c.line_id
                   WHERE c.from_substation_id=? OR c.to_substation_id=?
                   ORDER BY l.line_voltage,l.line_name,c.connection_id""",(sid,sid)).fetchall()
            out['lines']=[]
            for x in rows:
                d=dict(x); d['direction']='OUTGOING' if str(d.get('from_substation_id'))==sid else 'INCOMING'
                d['conductor_records']=[dict(c) for c in con.execute('SELECT * FROM TL_LINE_CONDUCTOR WHERE line_id=? ORDER BY circuit_no',(d['line_id'],)).fetchall()]
                oid=d.get('to_substation_id') if d['direction']=='OUTGOING' else d.get('from_substation_id')
                other=con.execute('SELECT sstn_id,sstn_name,voltage_level,latitude,longitude,substation_status,substation_type,district FROM SSTN_MASTER WHERE sstn_id=?',(str(oid or ''),)).fetchone()
                d['connected_substation']=dict(other) if other else {'sstn_id':oid or '', 'sstn_name':d.get('to_substation') if d['direction']=='OUTGOING' else d.get('from_substation')}
                out['lines'].append(d)
            out['layout']=[dict(x) for x in con.execute('SELECT * FROM TL_NETWORK_LAYOUT WHERE sstn_id=?',(sid,)).fetchall()]
            return out
        finally: con.close()

    def save_substation_biography_layout(self, root_sstn_id, positions):
        self._tl_require_developer('save Substation Biography network layout')
        self._ensure_substation_biography_tables(); root=str(root_sstn_id or '').strip()
        if not root: raise ValueError('Substation ID is required.')
        now=datetime.now().isoformat(timespec='seconds'); con=self._master_connect()
        try:
            for nid,pos in (positions or {}).items():
                con.execute('''INSERT INTO TL_NETWORK_LAYOUT(sstn_id,node_sstn_id,pos_x,pos_y,updated_at) VALUES (?,?,?,?,?)
                               ON CONFLICT(sstn_id,node_sstn_id) DO UPDATE SET pos_x=excluded.pos_x,pos_y=excluded.pos_y,updated_at=excluded.updated_at''',(root,str(nid),float(pos[0]),float(pos[1]),now))
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return True

    def save_substation_connectivity_line(self, data):
        """Create a Transmission Line connectivity record before GPS coordinates exist.

        This is intentionally separate from save_transmission_line(): a connectivity
        line may be created with a manually entered approved/known route length and
        Conductor Master selection, but zero tower/GPS records. Later the normal
        Transmission Line coordinate import can populate the same line_id with
        towers/segments without changing the substation connectivity identity.
        """
        self._tl_require_developer("add a Substation Connectivity Line")
        self._ensure_sstn_tables()
        self._ensure_transmission_line_tables()

        from_id = str(data.get("from_substation_id") or "").strip()
        to_id = str(data.get("to_substation_id") or "").strip()
        name = str(data.get("line_name") or "").strip()
        voltage = str(data.get("line_voltage") or "").strip()
        circuit = str(data.get("circuit_type") or "S/C").strip().upper()
        conductor_id = str(data.get("conductor_master_id") or "").strip()

        if not from_id or not to_id:
            raise ValueError("Both From Substation and To Substation are mandatory.")
        if from_id == to_id:
            raise ValueError("From Substation and To Substation cannot be the same.")
        if not name:
            raise ValueError("Line Name is mandatory.")
        if not voltage:
            raise ValueError("Line Voltage is mandatory.")
        if circuit not in {"S/C", "D/C"}:
            raise ValueError("Circuit type must be S/C or D/C.")
        if not conductor_id:
            raise ValueError("Conductor Master selection is mandatory.")

        try:
            route_km = float(data.get("line_length_km"))
        except Exception:
            raise ValueError("Line Length must be a valid number in km.")
        if route_km < 0:
            raise ValueError("Line Length cannot be negative.")

        con = self._master_connect()
        try:
            con.execute("PRAGMA foreign_keys=ON")
            f = con.execute(
                "SELECT sstn_id,sstn_name,voltage_level FROM SSTN_MASTER WHERE sstn_id=?",
                (from_id,)
            ).fetchone()
            to = con.execute(
                "SELECT sstn_id,sstn_name,voltage_level FROM SSTN_MASTER WHERE sstn_id=?",
                (to_id,)
            ).fetchone()
            if not f:
                raise ValueError("Selected From Substation is not present in SSTN_MASTER.")
            if not to:
                raise ValueError("Selected To Substation is not present in SSTN_MASTER.")

            cm = con.execute(
                "SELECT * FROM TL_CONDUCTOR_MASTER WHERE conductor_id=? AND active=1",
                (conductor_id,)
            ).fetchone()
            if not cm:
                raise ValueError("Selected Conductor Master record is invalid or inactive.")

            # Reuse an existing line with the same endpoint pair/name/voltage where
            # possible; otherwise allocate a fresh TLxxxxxx identifier.
            row = con.execute(
                """SELECT line_id FROM TL_LINE_MASTER
                   WHERE from_substation_id=? AND to_substation_id=?
                     AND line_name=? AND line_voltage=?
                   LIMIT 1""",
                (from_id, to_id, name, voltage)
            ).fetchone()
            if not row:
                row = con.execute(
                    """SELECT line_id FROM TL_LINE_MASTER
                       WHERE from_substation_id=? AND to_substation_id=?
                         AND line_name=? AND line_voltage=?
                       LIMIT 1""",
                    (to_id, from_id, name, voltage)
                ).fetchone()

            if row:
                line_id = str(row["line_id"])
            else:
                rows = con.execute(
                    "SELECT line_id FROM TL_LINE_MASTER WHERE line_id LIKE 'TL%'"
                ).fetchall()
                nums = []
                for r in rows:
                    m = re.fullmatch(r"TL(\d+)", str(r["line_id"]))
                    if m:
                        nums.append(int(m.group(1)))
                line_id = f"TL{(max(nums, default=0) + 1):06d}"

            now = datetime.now().isoformat(timespec="seconds")
            con.execute(
                """INSERT INTO TL_LINE_MASTER(
                    line_id,ts_division,line_voltage,line_name,doc_date,conductor_size,
                    from_substation,to_substation,from_substation_id,to_substation_id,
                    circuit,line_status,planning_status,total_towers,calculated_length_km,
                    max_span_m,max_span_from,max_span_to,min_span_m,min_span_from,min_span_to,
                    remarks,source_file,source_type,imported_at,updated_at
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(line_id) DO UPDATE SET
                    ts_division=excluded.ts_division,
                    line_voltage=excluded.line_voltage,
                    line_name=excluded.line_name,
                    conductor_size=excluded.conductor_size,
                    from_substation=excluded.from_substation,
                    to_substation=excluded.to_substation,
                    from_substation_id=excluded.from_substation_id,
                    to_substation_id=excluded.to_substation_id,
                    circuit=excluded.circuit,
                    line_status=excluded.line_status,
                    planning_status=excluded.planning_status,
                    calculated_length_km=excluded.calculated_length_km,
                    remarks=excluded.remarks,
                    source_type=excluded.source_type,
                    updated_at=excluded.updated_at""",
                (
                    line_id, str(data.get("ts_division") or f["sstn_name"] or "").strip(),
                    voltage, name, "", str(cm["conductor_size"] or "").strip(),
                    str(f["sstn_name"] or "").strip(), str(to["sstn_name"] or "").strip(),
                    from_id, to_id, circuit,
                    str(data.get("line_status") or "In Service").strip(),
                    str(data.get("planning_status") or "Existing").strip(),
                    0, route_km, None, "", "", None, "", "",
                    str(data.get("remarks") or "").strip(), "", "Connectivity", now, now
                )
            )

            # Replace only the connectivity-line conductor snapshot. No tower/GPS
            # data is created by this workflow.
            con.execute("DELETE FROM TL_LINE_CONDUCTOR WHERE line_id=?", (line_id,))
            con.execute(
                """INSERT INTO TL_LINE_CONDUCTOR(
                    line_id,circuit_no,conductor_master_id,conductor_size,conductor_type,
                    circuit_type,voltage_kv,thermal_current_a,thermal_capacity_mva,remarks
                ) VALUES (?,?,?,?,?,?,?,?,?,?)""",
                (
                    line_id, "1", conductor_id, cm["conductor_size"], cm["conductor_type"],
                    cm["circuit_type"], cm["voltage_kv"], float(cm["thermal_current_a"]),
                    float(cm["thermal_capacity_mva"]), cm["remarks"]
                )
            )

            # Keep the network connection table synchronized with the line master.
            con.execute(
                """INSERT INTO TL_NETWORK_CONNECTION(
                    connection_id,line_id,from_substation_id,to_substation_id,
                    remarks,created_at,updated_at
                ) VALUES (?,?,?,?,?,?,?)
                ON CONFLICT(line_id,from_substation_id,to_substation_id)
                DO UPDATE SET remarks=excluded.remarks,updated_at=excluded.updated_at""",
                (
                    f"NET{int(datetime.now().timestamp()*1000)%100000000:08d}",
                    line_id, from_id, to_id, str(data.get("remarks") or "").strip(),
                    now, now
                )
            )
            con.commit()
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()

        self._persist_master_after_developer_change()
        return line_id

    def add_substation_network_connection(self, line_id, remarks=''):
        self._tl_require_developer('add a Substation Biography network connection')
        self._ensure_transmission_line_tables(); self._ensure_substation_biography_tables(); lid=str(line_id or '').strip(); con=self._master_connect()
        try:
            row=con.execute('SELECT line_id,from_substation_id,to_substation_id FROM TL_LINE_MASTER WHERE line_id=?',(lid,)).fetchone()
            if not row: raise ValueError('Selected Transmission Line does not exist.')
            f=str(row['from_substation_id'] or '').strip(); t=str(row['to_substation_id'] or '').strip()
            if not f or not t: raise ValueError('Selected Transmission Line has no valid From/To Substation linkage.')
            cid=f"NET{int(datetime.now().timestamp()*1000)%100000000:08d}"
            con.execute('''INSERT INTO TL_NETWORK_CONNECTION(connection_id,line_id,from_substation_id,to_substation_id,remarks,created_at,updated_at)
                           VALUES (?,?,?,?,?,?,?) ON CONFLICT(line_id,from_substation_id,to_substation_id) DO UPDATE SET remarks=excluded.remarks,updated_at=excluded.updated_at''',(cid,lid,f,t,str(remarks or '').strip(),datetime.now().isoformat(timespec='seconds'),datetime.now().isoformat(timespec='seconds')))
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return True

    def delete_substation_network_connection(self, line_id):
        self._tl_require_developer('remove a Substation Biography network connection')
        self._ensure_substation_biography_tables(); con=self._master_connect()
        try: cur=con.execute('DELETE FROM TL_NETWORK_CONNECTION WHERE line_id=?',(str(line_id or '').strip(),)); con.commit()
        finally: con.close()
        if cur.rowcount: self._persist_master_after_developer_change()
        return bool(cur.rowcount)

    def delete_substation_network_connection_by_id(self, connection_id):
        """Delete exactly one saved connectivity record; never delete TL_LINE_MASTER."""
        self._tl_require_developer('remove a Substation Biography network connection')
        self._ensure_substation_biography_tables()
        cid=str(connection_id or '').strip()
        if not cid: raise ValueError('Connectivity record is required.')
        con=self._master_connect()
        try:
            cur=con.execute('DELETE FROM TL_NETWORK_CONNECTION WHERE connection_id=?',(cid,)); con.commit()
        finally: con.close()
        if cur.rowcount: self._persist_master_after_developer_change()
        return bool(cur.rowcount)

    def _persist_master_after_developer_change(self):
        """Persist an intentional Developer change to encrypted MASTER.db."""
        DB_STORE.sync_file(MASTER_DB_PATH, MASTER_STORAGE_PATH)
        DB_STORE.note_runtime_synced(MASTER_STORAGE_PATH, MASTER_DB_PATH)

    def _tl_require_developer(self, action="modify Transmission Line master data"):
        """Hard guard for all Transmission Line project-data mutations."""
        if not self.master_mode or str(globals().get("ACTIVE_LICENSE_ROLE", "")).upper() != "DEVELOPER":
            raise PermissionError(f"Developer access is required to {action}.")

    # ------------------------------------------------------------------
    # Transmission Line GIS master-data storage
    # ------------------------------------------------------------------
    def _ensure_transmission_line_tables(self):
        """Create/migrate Transmission Line GIS tables in authoritative MASTER.db.

        The common GIS opens this function frequently. Once the schema is complete,
        use a read-only metadata check and return immediately so the encrypted
        MASTER.db is NOT re-synchronised on every GIS launch.
        """
        required={'TL_LINE_MASTER','TL_TOWERS','TL_SEGMENTS','TL_IMPORT_LOG','TL_TOWER_INDEX','TL_SEGMENT_INDEX','TL_CONDUCTOR_MASTER','TL_LINE_CONDUCTOR'}
        try:
            ro=self._master_connect(readonly=True)
            try:
                found={r[0] for r in ro.execute("SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'TL_%'").fetchall()}
                if required.issubset(found):
                    cols={r[1] for r in ro.execute('PRAGMA table_info(TL_LINE_MASTER)').fetchall()}
                    tower_cols={r[1] for r in ro.execute('PRAGMA table_info(TL_TOWERS)').fetchall()}
                    required_tower_cols={'tower_by_user','tower_by_app','route_angle_deg','tower_type_status'}
                    if 'source_type' in cols and required_tower_cols.issubset(tower_cols):
                        return
            finally: ro.close()
        except Exception:
            pass
        con = self._master_connect()
        try:
            exists = con.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='TL_LINE_MASTER'"
            ).fetchone()
            if not exists:
                # The runtime MASTER.db is the writable decrypted database. Also
                # preserve the distributed encrypted MASTER.db before the first
                # transmission-line schema migration.
                stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
                try:
                    if Path(MASTER_STORAGE_PATH).exists():
                        shutil.copy2(
                            MASTER_STORAGE_PATH,
                            BASE_DIR / f'MASTER.db.TL_PRE_MIGRATION_{stamp}.bak'
                        )
                    if Path(MASTER_DB_PATH).exists():
                        shutil.copy2(
                            MASTER_DB_PATH,
                            BASE_DIR / f'MASTER_runtime.TL_PRE_MIGRATION_{stamp}.bak'
                        )
                except Exception as backup_exc:
                    raise RuntimeError(
                        f'Could not create the mandatory MASTER.db backup before '
                        f'Transmission Line GIS migration: {backup_exc}'
                    )

            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_LINE_MASTER (
                    line_id TEXT PRIMARY KEY,
                    ts_division TEXT NOT NULL DEFAULT '',
                    line_voltage TEXT NOT NULL DEFAULT '',
                    line_name TEXT NOT NULL,
                    doc_date TEXT DEFAULT '',
                    conductor_size TEXT DEFAULT '',
                    from_substation TEXT DEFAULT '',
                    to_substation TEXT DEFAULT '',
                    from_substation_id TEXT DEFAULT '',
                    to_substation_id TEXT DEFAULT '',
                    circuit TEXT DEFAULT '',
                    line_status TEXT DEFAULT 'In Service',
                    planning_status TEXT DEFAULT 'Existing',
                    total_towers INTEGER NOT NULL DEFAULT 0,
                    calculated_length_km REAL NOT NULL DEFAULT 0,
                    max_span_m REAL,
                    max_span_from TEXT DEFAULT '',
                    max_span_to TEXT DEFAULT '',
                    min_span_m REAL,
                    min_span_from TEXT DEFAULT '',
                    min_span_to TEXT DEFAULT '',
                    remarks TEXT DEFAULT '',
                    source_file TEXT DEFAULT '',
                    source_type TEXT DEFAULT 'Excel',
                    imported_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    UNIQUE(ts_division, line_voltage, line_name)
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_CONDUCTOR_MASTER (
                    conductor_id TEXT PRIMARY KEY,
                    conductor_size TEXT NOT NULL,
                    conductor_type TEXT NOT NULL DEFAULT '',
                    voltage_kv TEXT NOT NULL DEFAULT '',
                    circuit_type TEXT NOT NULL DEFAULT 'S/C',
                    thermal_current_a REAL NOT NULL,
                    thermal_capacity_mva REAL NOT NULL,
                    remarks TEXT DEFAULT '',
                    active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    UNIQUE(conductor_size,conductor_type,voltage_kv,circuit_type)
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_LINE_CONDUCTOR (
                    line_id TEXT NOT NULL,
                    circuit_no TEXT NOT NULL DEFAULT '1',
                    conductor_master_id TEXT NOT NULL,
                    conductor_size TEXT NOT NULL DEFAULT '',
                    conductor_type TEXT NOT NULL DEFAULT '',
                    circuit_type TEXT NOT NULL DEFAULT 'S/C',
                    voltage_kv TEXT NOT NULL DEFAULT '',
                    thermal_current_a REAL NOT NULL DEFAULT 0,
                    thermal_capacity_mva REAL NOT NULL DEFAULT 0,
                    remarks TEXT DEFAULT '',
                    PRIMARY KEY(line_id,circuit_no),
                    FOREIGN KEY(line_id) REFERENCES TL_LINE_MASTER(line_id) ON DELETE CASCADE,
                    FOREIGN KEY(conductor_master_id) REFERENCES TL_CONDUCTOR_MASTER(conductor_id)
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_TOWERS (
                    line_id TEXT NOT NULL,
                    tower_id TEXT NOT NULL,
                    sequence_no INTEGER NOT NULL,
                    latitude REAL NOT NULL,
                    longitude REAL NOT NULL,
                    tower_type TEXT DEFAULT '',
                    tower_by_user TEXT DEFAULT '',
                    tower_by_app TEXT DEFAULT '',
                    route_angle_deg REAL,
                    tower_type_status TEXT DEFAULT '',
                    remarks TEXT DEFAULT '',
                    PRIMARY KEY(line_id, tower_id),
                    FOREIGN KEY(line_id) REFERENCES TL_LINE_MASTER(line_id) ON DELETE CASCADE,
                    UNIQUE(line_id, sequence_no)
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_SEGMENTS (
                    line_id TEXT NOT NULL,
                    segment_no INTEGER NOT NULL,
                    from_tower TEXT NOT NULL,
                    to_tower TEXT NOT NULL,
                    length_m REAL NOT NULL,
                    from_lat REAL NOT NULL,
                    from_lon REAL NOT NULL,
                    to_lat REAL NOT NULL,
                    to_lon REAL NOT NULL,
                    min_lat REAL NOT NULL,
                    max_lat REAL NOT NULL,
                    min_lon REAL NOT NULL,
                    max_lon REAL NOT NULL,
                    PRIMARY KEY(line_id, segment_no),
                    FOREIGN KEY(line_id) REFERENCES TL_LINE_MASTER(line_id) ON DELETE CASCADE
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_IMPORT_LOG (
                    import_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source_file TEXT NOT NULL,
                    imported_at TEXT NOT NULL,
                    lines_imported INTEGER NOT NULL DEFAULT 0,
                    towers_imported INTEGER NOT NULL DEFAULT 0,
                    segments_imported INTEGER NOT NULL DEFAULT 0,
                    status TEXT NOT NULL,
                    remarks TEXT DEFAULT ''
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_TOWER_INDEX (
                    tower_index_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    line_id TEXT NOT NULL,
                    tower_id TEXT NOT NULL,
                    UNIQUE(line_id, tower_id),
                    FOREIGN KEY(line_id) REFERENCES TL_LINE_MASTER(line_id) ON DELETE CASCADE
                )
            """)
            con.execute("""
                CREATE TABLE IF NOT EXISTS TL_SEGMENT_INDEX (
                    segment_index_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    line_id TEXT NOT NULL,
                    segment_no INTEGER NOT NULL,
                    UNIQUE(line_id, segment_no),
                    FOREIGN KEY(line_id) REFERENCES TL_LINE_MASTER(line_id) ON DELETE CASCADE
                )
            """)
            # SQLite builds supplied with standard Python normally include RTree.
            # If unavailable, the ordinary index tables above still preserve the
            # data and can be used for a safe fallback search later.
            try:
                con.execute("""
                    CREATE VIRTUAL TABLE IF NOT EXISTS TL_TOWER_RTREE USING rtree(
                        tower_index_id, min_lat, max_lat, min_lon, max_lon
                    )
                """)
                con.execute("""
                    CREATE VIRTUAL TABLE IF NOT EXISTS TL_SEGMENT_RTREE USING rtree(
                        segment_index_id, min_lat, max_lat, min_lon, max_lon
                    )
                """)
            except sqlite3.DatabaseError:
                pass
            # Backward-compatible migration for databases created by V22.3.31.
            cols = [r[1] for r in con.execute("PRAGMA table_info(TL_LINE_MASTER)").fetchall()]
            if 'source_type' not in cols:
                con.execute("ALTER TABLE TL_LINE_MASTER ADD COLUMN source_type TEXT DEFAULT 'Excel'")
            for col, definition in (
                ('from_substation_id', "TEXT DEFAULT ''"),
                ('to_substation_id', "TEXT DEFAULT ''"),
                ('line_status', "TEXT DEFAULT 'In Service'"),
                ('planning_status', "TEXT DEFAULT 'Existing'"),
            ):
                if col not in cols:
                    con.execute(f"ALTER TABLE TL_LINE_MASTER ADD COLUMN {col} {definition}")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_line_from_sstn ON TL_LINE_MASTER(from_substation_id)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_line_to_sstn ON TL_LINE_MASTER(to_substation_id)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_line_conductor_master ON TL_LINE_CONDUCTOR(conductor_master_id)")
            tower_cols = [r[1] for r in con.execute("PRAGMA table_info(TL_TOWERS)").fetchall()]
            added_angle_columns = False
            for col, definition in (
                ('tower_by_user', "TEXT DEFAULT ''"),
                ('tower_by_app', "TEXT DEFAULT ''"),
                ('route_angle_deg', "REAL"),
                ('tower_type_status', "TEXT DEFAULT ''"),
            ):
                if col not in tower_cols:
                    con.execute(f"ALTER TABLE TL_TOWERS ADD COLUMN {col} {definition}")
                    added_angle_columns = True
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_line_voltage ON TL_LINE_MASTER(line_voltage)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_line_division ON TL_LINE_MASTER(ts_division)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_towers_line_seq ON TL_TOWERS(line_id, sequence_no)")
            con.execute("CREATE INDEX IF NOT EXISTS idx_tl_segments_line ON TL_SEGMENTS(line_id, segment_no)")

            # If this is an upgrade from V22.3.31-V22.3.35, populate the new
            # angle-analysis fields for every already-stored tower before the
            # schema migration is committed. Existing tower_type is treated as
            # the user/imported type and is never overwritten by the app result.
            if added_angle_columns:
                line_rows = con.execute("SELECT DISTINCT line_id FROM TL_TOWERS ORDER BY line_id").fetchall()
                for lr in line_rows:
                    lid = str(lr[0])
                    tower_rows = con.execute(
                        "SELECT tower_id,sequence_no,latitude,longitude,tower_type,tower_by_user FROM TL_TOWERS WHERE line_id=? ORDER BY sequence_no",
                        (lid,)
                    ).fetchall()
                    towers=[]
                    for tr in tower_rows:
                        user = str(tr['tower_by_user'] or tr['tower_type'] or '').strip()
                        towers.append({
                            'tower_id': str(tr['tower_id']), 'sequence_no': int(tr['sequence_no']),
                            'lat': float(tr['latitude']), 'lon': float(tr['longitude']),
                            'user': user
                        })
                    for i,t in enumerate(towers):
                        if 0 < i < len(towers)-1:
                            ang=self._tl_deflection_deg(
                                (towers[i-1]['lat'],towers[i-1]['lon']),
                                (t['lat'],t['lon']),
                                (towers[i+1]['lat'],towers[i+1]['lon'])
                            )
                            app=self._tl_predict_tower_type(ang)
                        else:
                            ang=None; app='END'
                        status=self._tl_type_status(t['user'],app,ang)
                        con.execute(
                            "UPDATE TL_TOWERS SET tower_by_user=?,tower_by_app=?,route_angle_deg=?,tower_type_status=? WHERE line_id=? AND tower_id=?",
                            (t['user'],app,ang,status,lid,t['tower_id'])
                        )
            con.commit()
        finally:
            con.close()
        self._persist_master_after_developer_change()

    @staticmethod
    def _tl_haversine_km(a, b):
        R = 6371.0088
        p1 = math.radians(float(a[0])); p2 = math.radians(float(b[0]))
        dp = math.radians(float(b[0]) - float(a[0]))
        dl = math.radians(float(b[1]) - float(a[1]))
        h = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
        return 2 * R * math.asin(min(1.0, math.sqrt(h)))

    @staticmethod
    def _tl_bearing_deg(a, b):
        """Initial great-circle bearing from coordinate a=(lat,lon) to b=(lat,lon)."""
        lat1=math.radians(float(a[0])); lat2=math.radians(float(b[0]))
        dlon=math.radians(float(b[1])-float(a[1]))
        y=math.sin(dlon)*math.cos(lat2)
        x=math.cos(lat1)*math.sin(lat2)-math.sin(lat1)*math.cos(lat2)*math.cos(dlon)
        return (math.degrees(math.atan2(y,x))+360.0)%360.0

    @classmethod
    def _tl_deflection_deg(cls, prev, current, nxt):
        """Route deviation angle at current tower, in degrees (0=straight)."""
        incoming=cls._tl_bearing_deg(prev,current)
        outgoing=cls._tl_bearing_deg(current,nxt)
        d=abs(outgoing-incoming)
        return d if d<=180.0 else 360.0-d

    @staticmethod
    def _tl_predict_tower_type(angle):
        if angle is None: return 'END'
        a=float(angle)
        if a < 0: return 'CHECK'
        if a <= 2.0: return 'A'
        if a <= 15.0: return 'B'
        if a <= 30.0: return 'C'
        if a <= 60.0: return 'D'
        return 'CHECK'

    @staticmethod
    def _tl_type_code(raw):
        u=str(raw or '').strip().upper()
        if not u: return ''
        m=re.search(r'\b([ABCD])(?:\s*[- ]?TYPE)?\b',u)
        if m: return m.group(1)
        if 'GANTRY' in u or u=='G': return 'GANTRY'
        if 'DEAD' in u or 'END' in u: return 'D'
        return u

    @classmethod
    def _tl_type_status(cls, user_type, app_type, angle):
        u=cls._tl_type_code(user_type); a=str(app_type or '').strip().upper()
        if not u and a=='END': return 'END / NO ANGLE'
        if not u: return 'APP ONLY'
        if a=='END': return 'USER ONLY / END'
        if u==a: return 'MATCH'
        if u=='GANTRY': return 'USER ONLY / GANTRY'
        return 'DIFFERENT'

    def save_transmission_line(self, line, source_file='', source_type='Excel', persist=True):
        self._tl_require_developer("save Transmission Line master data")
        """Insert or replace one complete validated transmission line."""
        self._ensure_transmission_line_tables()
        name = str(line.get('name', '')).strip()
        if not name:
            raise ValueError('Transmission line name is required.')
        towers = list(line.get('towers') or [])
        if not towers:
            raise ValueError(f'No tower coordinates found for {name}.')
        seen_ids = set()
        clean = []
        for seq, t in enumerate(towers, 1):
            tid = str(t.get('id', '')).strip()
            if not tid:
                raise ValueError(f'{name}: tower {seq} has no Tower ID.')
            if tid in seen_ids:
                raise ValueError(f'{name}: duplicate Tower ID {tid}.')
            seen_ids.add(tid)
            try:
                lat = float(t.get('lat')); lon = float(t.get('lon'))
            except Exception:
                raise ValueError(f'{name}: invalid coordinates for tower {tid}.')
            if not (-90 <= lat <= 90 and -180 <= lon <= 180):
                raise ValueError(f'{name}: coordinates out of range for tower {tid}.')
            user_type = str(t.get('tower_by_user', t.get('type', '')) or '').strip()
            clean.append({
                'id': tid, 'lat': lat, 'lon': lon,
                'type': user_type, 'tower_by_user': user_type,
                'remarks': str(t.get('remarks', '') or '').strip()
            })
        # Calculate the two-sided route deviation angle and predicted tower type
        # before anything is written to MASTER.db. End towers have no two-sided
        # deviation angle and are therefore marked END by the application.
        for i, t in enumerate(clean):
            if 0 < i < len(clean)-1:
                angle = self._tl_deflection_deg(clean[i-1], t, clean[i+1])
                t['route_angle_deg'] = angle
                t['tower_by_app'] = self._tl_predict_tower_type(angle)
            else:
                t['route_angle_deg'] = None
                t['tower_by_app'] = self._tl_predict_tower_type(None)
            t['tower_type_status'] = self._tl_type_status(t.get('tower_by_user',''), t.get('tower_by_app',''), t.get('route_angle_deg'))
        spans = []
        for i in range(len(clean) - 1):
            a, b = clean[i], clean[i + 1]
            m = self._tl_haversine_km((a['lat'], a['lon']), (b['lat'], b['lon'])) * 1000.0
            spans.append((i + 1, a, b, m))
        total_m = sum(x[3] for x in spans)
        max_s = max(spans, key=lambda x: x[3]) if spans else None
        min_s = min(spans, key=lambda x: x[3]) if spans else None
        line_id = str(line.get('line_id', '')).strip()
        now = datetime.now().isoformat(timespec='seconds')
        con = self._master_connect()
        try:
            if not line_id:
                row = con.execute(
                    'SELECT line_id FROM TL_LINE_MASTER WHERE ts_division=? AND line_voltage=? AND line_name=?',
                    (str(line.get('ts_division','')).strip(), str(line.get('voltage','')).strip(), name)
                ).fetchone()
                if row:
                    line_id = row[0]
                else:
                    row = con.execute("SELECT line_id FROM TL_LINE_MASTER WHERE line_id LIKE 'TL%'").fetchall()
                    nums = []
                    for r in row:
                        m = re.fullmatch(r'TL(\d+)', str(r[0]))
                        if m:
                            nums.append(int(m.group(1)))
                    line_id = f'TL{(max(nums, default=0) + 1):06d}'
            con.execute('PRAGMA foreign_keys=ON')
            con.execute('DELETE FROM TL_LINE_CONDUCTOR WHERE line_id=?', (line_id,))
            con.execute('DELETE FROM TL_TOWERS WHERE line_id=?', (line_id,))
            con.execute('DELETE FROM TL_SEGMENTS WHERE line_id=?', (line_id,))
            con.execute('DELETE FROM TL_TOWER_RTREE WHERE tower_index_id IN (SELECT tower_index_id FROM TL_TOWER_INDEX WHERE line_id=?)', (line_id,)) if self._tl_rtree_exists(con, 'TL_TOWER_RTREE') else None
            con.execute('DELETE FROM TL_SEGMENT_RTREE WHERE segment_index_id IN (SELECT segment_index_id FROM TL_SEGMENT_INDEX WHERE line_id=?)', (line_id,)) if self._tl_rtree_exists(con, 'TL_SEGMENT_RTREE') else None
            con.execute('DELETE FROM TL_TOWER_INDEX WHERE line_id=?', (line_id,))
            con.execute('DELETE FROM TL_SEGMENT_INDEX WHERE line_id=?', (line_id,))
            con.execute("""
                INSERT INTO TL_LINE_MASTER(
                    line_id,ts_division,line_voltage,line_name,doc_date,conductor_size,
                    from_substation,to_substation,from_substation_id,to_substation_id,circuit,line_status,planning_status,total_towers,calculated_length_km,
                    max_span_m,max_span_from,max_span_to,min_span_m,min_span_from,min_span_to,
                    remarks,source_file,source_type,imported_at,updated_at
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(line_id) DO UPDATE SET
                    ts_division=excluded.ts_division,line_voltage=excluded.line_voltage,
                    line_name=excluded.line_name,doc_date=excluded.doc_date,
                    conductor_size=excluded.conductor_size,from_substation=excluded.from_substation,
                    to_substation=excluded.to_substation,from_substation_id=excluded.from_substation_id,to_substation_id=excluded.to_substation_id,
                    circuit=excluded.circuit,line_status=excluded.line_status,planning_status=excluded.planning_status,
                    total_towers=excluded.total_towers,calculated_length_km=excluded.calculated_length_km,
                    max_span_m=excluded.max_span_m,max_span_from=excluded.max_span_from,max_span_to=excluded.max_span_to,
                    min_span_m=excluded.min_span_m,min_span_from=excluded.min_span_from,min_span_to=excluded.min_span_to,
                    remarks=excluded.remarks,source_file=excluded.source_file,source_type=excluded.source_type,updated_at=excluded.updated_at
            """, (
                line_id, str(line.get('ts_division','')).strip(), str(line.get('voltage','')).strip(), name,
                str(line.get('doc','')).strip(), str(line.get('conductor','')).strip(),
                str(line.get('from_substation','')).strip(), str(line.get('to_substation','')).strip(),
                str(line.get('from_substation_id','')).strip(), str(line.get('to_substation_id','')).strip(),
                str(line.get('circuit','')).strip(), str(line.get('line_status','In Service') or 'In Service').strip(), str(line.get('planning_status','Existing') or 'Existing').strip(), len(clean), total_m / 1000.0,
                max_s[3] if max_s else None, max_s[1]['id'] if max_s else '', max_s[2]['id'] if max_s else '',
                min_s[3] if min_s else None, min_s[1]['id'] if min_s else '', min_s[2]['id'] if min_s else '',
                str(line.get('remarks','')).strip(), str(source_file or line.get('source_file','')).strip(), str(source_type or line.get('source_type','Excel') or 'Excel'), now, now
            ))
            for seq, t in enumerate(clean, 1):
                con.execute(
                    'INSERT INTO TL_TOWERS(line_id,tower_id,sequence_no,latitude,longitude,tower_type,tower_by_user,tower_by_app,route_angle_deg,tower_type_status,remarks) VALUES (?,?,?,?,?,?,?,?,?,?,?)',
                    (line_id, t['id'], seq, t['lat'], t['lon'], t['type'], t['tower_by_user'], t['tower_by_app'], t['route_angle_deg'], t['tower_type_status'], t['remarks'])
                )
                cur = con.execute('INSERT INTO TL_TOWER_INDEX(line_id,tower_id) VALUES (?,?)', (line_id, t['id']))
                idx = cur.lastrowid
                if self._tl_rtree_exists(con, 'TL_TOWER_RTREE'):
                    con.execute('INSERT INTO TL_TOWER_RTREE VALUES (?,?,?,?,?)', (idx, t['lat'], t['lat'], t['lon'], t['lon']))
            for seg_no, a, b, m in spans:
                con.execute(
                    'INSERT INTO TL_SEGMENTS(line_id,segment_no,from_tower,to_tower,length_m,from_lat,from_lon,to_lat,to_lon,min_lat,max_lat,min_lon,max_lon) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
                    (line_id, seg_no, a['id'], b['id'], m, a['lat'], a['lon'], b['lat'], b['lon'],
                     min(a['lat'],b['lat']), max(a['lat'],b['lat']), min(a['lon'],b['lon']), max(a['lon'],b['lon']))
                )
                cur = con.execute('INSERT INTO TL_SEGMENT_INDEX(line_id,segment_no) VALUES (?,?)', (line_id, seg_no))
                idx = cur.lastrowid
                if self._tl_rtree_exists(con, 'TL_SEGMENT_RTREE'):
                    con.execute('INSERT INTO TL_SEGMENT_RTREE VALUES (?,?,?,?,?)', (idx, min(a['lat'],b['lat']), max(a['lat'],b['lat']), min(a['lon'],b['lon']), max(a['lon'],b['lon'])))
            # Save the selected engineering conductor as a line-specific snapshot.
            conductor_rows=line.get('conductor_records') or []
            if not conductor_rows and line.get('conductor_master_id'):
                conductor_rows=[line]
            for n,cr in enumerate(conductor_rows,1):
                cmid=str(cr.get('conductor_master_id','')).strip()
                if not cmid: raise ValueError(f'{name}: Conductor Master selection is mandatory.')
                master=con.execute('SELECT * FROM TL_CONDUCTOR_MASTER WHERE conductor_id=? AND active=1',(cmid,)).fetchone()
                if not master: raise ValueError(f'{name}: selected Conductor Master record is invalid or inactive.')
                con.execute('INSERT INTO TL_LINE_CONDUCTOR(line_id,circuit_no,conductor_master_id,conductor_size,conductor_type,circuit_type,voltage_kv,thermal_current_a,thermal_capacity_mva,remarks) VALUES (?,?,?,?,?,?,?,?,?,?)',(line_id,str(cr.get('circuit_no',n)),cmid,master['conductor_size'],master['conductor_type'],master['circuit_type'],master['voltage_kv'],float(master['thermal_current_a']),float(master['thermal_capacity_mva']),master['remarks']))
            con.commit()
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()
        if persist:
            self._persist_master_after_developer_change()
        return line_id, len(clean), len(spans), total_m / 1000.0

    @staticmethod
    def _tl_rtree_exists(con, name):
        try:
            return bool(con.execute("SELECT 1 FROM sqlite_master WHERE name=? AND type='table'", (name,)).fetchone())
        except Exception:
            return False

    def list_transmission_conductors(self, active_only=False):
        self._ensure_transmission_line_tables()
        con=self._master_connect(readonly=True)
        try:
            q="SELECT * FROM TL_CONDUCTOR_MASTER" + (" WHERE active=1" if active_only else "") + " ORDER BY voltage_kv,conductor_size,conductor_type,circuit_type"
            return [dict(r) for r in con.execute(q).fetchall()]
        finally: con.close()

    def save_transmission_conductor(self, data, conductor_id=None):
        self._tl_require_developer("save Conductor Master data")
        self._ensure_transmission_line_tables()
        size=str(data.get('conductor_size','')).strip()
        ctype=str(data.get('conductor_type','')).strip()
        voltage=str(data.get('voltage_kv','')).strip()
        circuit=str(data.get('circuit_type','S/C')).strip().upper() or 'S/C'
        if not size or not ctype or not voltage: raise ValueError('Conductor size, type and voltage are mandatory.')
        if circuit not in {'S/C','D/C'}: raise ValueError('Circuit type must be S/C or D/C.')
        try: amp=float(data.get('thermal_current_a'))
        except Exception: raise ValueError('Thermal current must be a valid number.')
        try: mva=float(data.get('thermal_capacity_mva'))
        except Exception: raise ValueError('Thermal capacity MVA must be a valid number.')
        if amp<=0 or mva<=0: raise ValueError('Thermal current and MVA capacity must be positive.')
        now=datetime.now().isoformat(timespec='seconds'); cid=str(conductor_id or data.get('conductor_id') or '').strip()
        con=self._master_connect()
        try:
            if cid:
                cur=con.execute("UPDATE TL_CONDUCTOR_MASTER SET conductor_size=?,conductor_type=?,voltage_kv=?,circuit_type=?,thermal_current_a=?,thermal_capacity_mva=?,remarks=?,active=?,updated_at=? WHERE conductor_id=?",(size,ctype,voltage,circuit,amp,mva,str(data.get('remarks','')).strip(),1 if data.get('active',1) else 0,now,cid))
                if cur.rowcount==0: raise ValueError(f'Conductor ID not found: {cid}')
            else:
                cid=f"COND{int(datetime.now().timestamp()*1000)%100000000:08d}"
                con.execute("INSERT INTO TL_CONDUCTOR_MASTER(conductor_id,conductor_size,conductor_type,voltage_kv,circuit_type,thermal_current_a,thermal_capacity_mva,remarks,active,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",(cid,size,ctype,voltage,circuit,amp,mva,str(data.get('remarks','')).strip(),1,now,now))
            con.commit()
        except Exception:
            con.rollback(); raise
        finally: con.close()
        self._persist_master_after_developer_change(); return cid

    def delete_transmission_conductor(self, conductor_id):
        self._tl_require_developer("delete Conductor Master data")
        cid=str(conductor_id or '').strip()
        if not cid: raise ValueError('Conductor ID is required.')
        con=self._master_connect()
        try:
            if con.execute("SELECT 1 FROM TL_LINE_CONDUCTOR WHERE conductor_master_id=? LIMIT 1",(cid,)).fetchone():
                raise ValueError('This conductor is already linked to a transmission line. Deactivate it instead of deleting it.')
            cur=con.execute("DELETE FROM TL_CONDUCTOR_MASTER WHERE conductor_id=?",(cid,))
            if cur.rowcount==0: raise ValueError('Conductor was not found.')
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return True

    def get_transmission_line_conductors(self, line_id):
        con=self._master_connect(readonly=True)
        try: return [dict(r) for r in con.execute("SELECT * FROM TL_LINE_CONDUCTOR WHERE line_id=? ORDER BY circuit_no",(str(line_id),)).fetchall()]
        finally: con.close()

    def list_transmission_lines(self):
        con = self._master_connect(readonly=True)
        try:
            return [dict(r) for r in con.execute('SELECT * FROM TL_LINE_MASTER ORDER BY ts_division,line_voltage,line_name').fetchall()]
        finally:
            con.close()

    def get_all_transmission_lines(self):
        """Bulk-load every stored line, tower and segment in one MASTER.db connection."""
        con=self._master_connect(readonly=True)
        try:
            lines={str(r['line_id']):dict(r) for r in con.execute('SELECT * FROM TL_LINE_MASTER ORDER BY ts_division,line_voltage,line_name').fetchall()}
            for L in lines.values():
                L['towers']=[]; L['name']=L.get('line_name',''); L['voltage']=L.get('line_voltage',''); L['conductor_records']=[]
            for r in con.execute('SELECT * FROM TL_LINE_CONDUCTOR ORDER BY line_id,circuit_no').fetchall():
                lid=str(r['line_id'])
                if lid in lines: lines[lid]['conductor_records'].append(dict(r))
            for r in con.execute('SELECT line_id,tower_id AS id,sequence_no,latitude AS lat,longitude AS lon,tower_type AS type,tower_by_user,tower_by_app,route_angle_deg,tower_type_status,remarks FROM TL_TOWERS ORDER BY line_id,sequence_no').fetchall():
                lid=str(r['line_id'])
                if lid in lines: lines[lid]['towers'].append(dict(r))
            segs={}
            for r in con.execute('SELECT line_id,segment_no,length_m FROM TL_SEGMENTS ORDER BY line_id,segment_no').fetchall():
                segs.setdefault(str(r['line_id']),{})[int(r['segment_no'])]=float(r['length_m'] or 0)
            for lid,L in lines.items():
                for t in L['towers']: t['span_m']=segs.get(lid,{}).get(int(t['sequence_no']))
            return list(lines.values())
        finally: con.close()

    def delete_transmission_line(self, line_id):
        self._tl_require_developer("delete Transmission Line master data")
        lid=str(line_id or '').strip()
        if not lid: raise ValueError('Transmission Line ID is required.')
        con=self._master_connect()
        try:
            if not con.execute('SELECT 1 FROM TL_LINE_MASTER WHERE line_id=?',(lid,)).fetchone(): raise ValueError(f'Transmission Line {lid} was not found.')
            con.execute('PRAGMA foreign_keys=ON')
            if self._tl_rtree_exists(con,'TL_TOWER_RTREE'): con.execute('DELETE FROM TL_TOWER_RTREE WHERE tower_index_id IN (SELECT tower_index_id FROM TL_TOWER_INDEX WHERE line_id=?)',(lid,))
            if self._tl_rtree_exists(con,'TL_SEGMENT_RTREE'): con.execute('DELETE FROM TL_SEGMENT_RTREE WHERE segment_index_id IN (SELECT segment_index_id FROM TL_SEGMENT_INDEX WHERE line_id=?)',(lid,))
            for tbl in ('TL_TOWER_INDEX','TL_SEGMENT_INDEX','TL_TOWERS','TL_SEGMENTS','TL_LINE_MASTER'):
                con.execute(f'DELETE FROM {tbl} WHERE line_id=?',(lid,))
            con.commit()
        except Exception: con.rollback(); raise
        finally: con.close()
        self._persist_master_after_developer_change()
        return lid

    def get_transmission_line(self, line_id):
        con = self._master_connect(readonly=True)
        try:
            row = con.execute('SELECT * FROM TL_LINE_MASTER WHERE line_id=?', (str(line_id),)).fetchone()
            if not row: return None
            out=dict(row); out['name']=out.get('line_name',''); out['voltage']=out.get('line_voltage','')
            out['towers']=[]
            out['conductor_records']=[dict(r) for r in con.execute('SELECT * FROM TL_LINE_CONDUCTOR WHERE line_id=? ORDER BY circuit_no',(str(line_id),)).fetchall()]
            for r in con.execute('SELECT tower_id AS id,sequence_no,latitude AS lat,longitude AS lon,tower_type AS type,tower_by_user,tower_by_app,route_angle_deg,tower_type_status,remarks FROM TL_TOWERS WHERE line_id=? ORDER BY sequence_no',(str(line_id),)).fetchall():
                out['towers'].append(dict(r))
            spans={int(r['segment_no']):float(r['length_m'] or 0) for r in con.execute('SELECT segment_no,length_m FROM TL_SEGMENTS WHERE line_id=? ORDER BY segment_no',(str(line_id),)).fetchall()}
            for t in out['towers']: t['span_m']=spans.get(int(t['sequence_no']))
            return out
        finally:
            con.close()
    def save_sstn_master(self, data, sstn_id=None):
        self._ensure_sstn_tables()
        name=str(data.get('sstn_name','')).strip()
        if not name: raise ValueError('Substation name is required.')
        status=str(data.get('substation_status','')).strip().title()
        if status.upper() not in {'EXISTING','NEW'}: raise ValueError('Status must be Existing or New.')
        stype=str(data.get('substation_type','')).strip().upper()
        if stype not in {'AIS','GIS','HYBRID'}: raise ValueError('Type must be AIS, GIS or HYBRID.')
        entity=str(data.get('entity','')).strip().upper()
        if entity not in {'HVPNL','BBMB','PGCIL','HSIIDC','GPTL','OTHERS'}: raise ValueError('Invalid entity.')
        voltage=str(data.get('voltage_level','')).strip().replace('KV','kV').replace('kv','kV')
        if voltage.upper() not in {'765KV','400KV','220KV','132KV','66KV'}: raise ValueError('Invalid voltage level.')
        division=str(data.get('ts_division','')).strip(); circle=str(data.get('ts_circle','')).strip(); district=str(data.get('district','')).strip()
        if not division or not circle or not district: raise ValueError('TS Division, TS Circle and District are mandatory.')
        try: lat=float(data.get('latitude')); lon=float(data.get('longitude'))
        except Exception: raise ValueError('Latitude and Longitude must be valid numbers.')
        if not (-90<=lat<=90 and -180<=lon<=180): raise ValueError('Invalid latitude/longitude.')
        sid=str(sstn_id or data.get('sstn_id') or '').strip()
        con=self._master_connect()
        try:
            if sid:
                con.execute("""UPDATE SSTN_MASTER SET sstn_name=?,substation_status=?,substation_type=?,entity=?,voltage_level=?,ts_division=?,ts_circle=?,district=?,latitude=?,longitude=?,gelo_pdf=?,sld_pdf=?,master_remarks=? WHERE sstn_id=?""",(name,status,stype,entity,voltage,division,circle,district,lat,lon,str(data.get('gelo_pdf','')).strip(),str(data.get('sld_pdf','')).strip(),str(data.get('master_remarks','')).strip(),sid))
                if con.total_changes==0: raise ValueError(f'Substation ID not found: {sid}')
            else:
                sid=f"SS{int(datetime.now().timestamp()*1000)%100000000:08d}"
                while con.execute("SELECT 1 FROM SSTN_MASTER WHERE sstn_id=?",(sid,)).fetchone(): sid=f"SS{int(datetime.now().timestamp()*1000)%100000000:08d}"
                con.execute("""INSERT INTO SSTN_MASTER(sstn_id,sstn_name,substation_status,substation_type,entity,voltage_level,ts_division,ts_circle,district,latitude,longitude,gelo_pdf,sld_pdf,master_remarks) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",(sid,name,status,stype,entity,voltage,division,circle,district,lat,lon,str(data.get('gelo_pdf','')).strip(),str(data.get('sld_pdf','')).strip(),str(data.get('master_remarks','')).strip()))
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return sid

    def save_sstn_infra(self, data, infra_id=None):
        self._ensure_sstn_tables()
        sid=str(data.get('sstn_id','')).strip()
        if not sid: raise ValueError('Substation ID is required.')
        try: seq=int(data.get('seq_no'))
        except Exception: raise ValueError('Seq No. must be a positive integer.')
        if seq<=0: raise ValueError('Seq No. must be a positive integer.')
        existing=str(data.get('existing_capacity','')).strip(); approved=str(data.get('approved_capacity','')).strip()
        if not existing or not approved: raise ValueError('Existing Capacity and Approved Capacity are mandatory.')
        con=self._master_connect()
        try:
            if not con.execute("SELECT 1 FROM SSTN_MASTER WHERE sstn_id=?",(sid,)).fetchone(): raise ValueError('Selected substation does not exist.')
            iid=str(infra_id or data.get('infra_id') or '').strip()
            if iid:
                con.execute("""UPDATE SSTN_INFRA SET sstn_id=?,seq_no=?,existing_capacity=?,approved_capacity=?,approved_fy=?,r_no=?,infra_remarks=? WHERE infra_id=?""",(sid,seq,existing,approved,str(data.get('approved_fy','')).strip(),str(data.get('r_no','')).strip(),str(data.get('infra_remarks','')).strip(),iid))
                if con.total_changes==0: raise ValueError(f'Infrastructure ID not found: {iid}')
            else:
                iid=f"INF{int(datetime.now().timestamp()*1000)%100000000:08d}"
                while con.execute("SELECT 1 FROM SSTN_INFRA WHERE infra_id=?",(iid,)).fetchone(): iid=f"INF{int(datetime.now().timestamp()*1000)%100000000:08d}"
                con.execute("""INSERT INTO SSTN_INFRA(infra_id,sstn_id,seq_no,existing_capacity,approved_capacity,approved_fy,r_no,infra_remarks) VALUES (?,?,?,?,?,?,?,?)""",(iid,sid,seq,existing,approved,str(data.get('approved_fy','')).strip(),str(data.get('r_no','')).strip(),str(data.get('infra_remarks','')).strip()))
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return iid

    def delete_sstn_master(self, sstn_id):
        self._ensure_sstn_tables(); con=self._master_connect()
        try:
            con.execute("PRAGMA foreign_keys=ON"); con.execute("DELETE FROM SSTN_MASTER WHERE sstn_id=?",(str(sstn_id),));
            if con.total_changes==0: return False
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return True

    def delete_sstn_infra(self, infra_id):
        self._ensure_sstn_tables(); con=self._master_connect()
        try:
            con.execute("DELETE FROM SSTN_INFRA WHERE infra_id=?",(str(infra_id),));
            if con.total_changes==0: return False
            con.commit()
        finally: con.close()
        self._persist_master_after_developer_change(); return True

    def upsert_substation(self, name, voltage_kv, latitude, longitude, district='', remarks='', existing_id=None, substation_type='AIS', existing_capacity='', approved_capacity='', approved_rno=''):
        name=str(name or '').strip()
        if not name: raise ValueError('Substation name is required.')
        v=int(voltage_kv)
        if v not in (765,400,220,132,66): raise ValueError('Voltage must be 765, 400, 220, 132 or 66 kV.')
        stype = str(substation_type or 'AIS').strip().upper()
        if stype not in ('AIS','GIS'): raise ValueError('Substation type must be AIS or GIS.')
        lat=float(latitude); lon=float(longitude)
        if not (-90 <= lat <= 90 and -180 <= lon <= 180): raise ValueError('Invalid latitude/longitude.')
        now=datetime.now().isoformat(timespec='seconds')
        con=self._master_connect()
        try:
            ecap=str(existing_capacity or '').strip()
            acap=str(approved_capacity or '').strip()
            arno=str(approved_rno or '').strip()
            if existing_id:
                con.execute("UPDATE substations SET name=?,voltage_kv=?,latitude=?,longitude=?,district=?,substation_type=?,existing_capacity=?,approved_capacity=?,approved_rno=?,remarks=?,updated_at=? WHERE id=?",(name,v,lat,lon,str(district or '').strip(),stype,ecap,acap,arno,str(remarks or '').strip(),now,int(existing_id)))
            else:
                con.execute("INSERT INTO substations(name,voltage_kv,latitude,longitude,district,substation_type,existing_capacity,approved_capacity,approved_rno,remarks,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",(name,v,lat,lon,str(district or '').strip(),stype,ecap,acap,arno,str(remarks or '').strip(),now))
            con.commit()
        finally: con.close()

    def delete_substation(self, substation_id):
        con=self._master_connect()
        try: con.execute('DELETE FROM substations WHERE id=?',(int(substation_id),)); con.commit()
        finally: con.close()

    def list_district_reference_documents(self, district):
        """Return developer reference PDFs associated with a district.

        Association is intentionally forgiving: it checks the district name
        against filename/title/category so existing records such as
        Rewari_Map.pdf and Rewari_Infra.pdf work without manual migration.
        """
        self._ensure_developer_auxiliary_tables()
        district = str(district or '').strip()
        if not district:
            return []
        con = self._master_connect(readonly=True)
        try:
            try:
                rows = [dict(r) for r in con.execute(
                    "SELECT id,category,title,original_filename,description,district,pdf_blob,pdf_sha256,created_at,updated_at FROM reference_documents ORDER BY category,title"
                ).fetchall()]
            except sqlite3.OperationalError as exc:
                if "no such table: reference_documents" in str(exc).lower():
                    return []
                raise
        finally:
            con.close()
        d = re.sub(r"[^a-z0-9]+", "", district.lower())
        out = []
        for r in rows:
            hay = " ".join(str(r.get(k) or '') for k in ('district','original_filename','title','description')).lower()
            compact = re.sub(r"[^a-z0-9]+", "", hay)
            if d and d in compact:
                out.append(r)
        return out

    def list_district_reference_districts(self, kind):
        """Return unique alphabetically sorted districts having Map/Infra PDFs.

        The explicit District field is preferred. Older records with a blank
        District field fall back to conventional filenames such as
        Faridabad_Infra.pdf or Faridabad_Map.pdf.
        """
        self._ensure_developer_auxiliary_tables()
        kind = str(kind or '').strip().lower()
        con = self._master_connect(readonly=True)
        try:
            rows = [dict(r) for r in con.execute(
                "SELECT category,title,original_filename,district FROM reference_documents ORDER BY title COLLATE NOCASE"
            ).fetchall()]
        except sqlite3.OperationalError as exc:
            if "no such table: reference_documents" in str(exc).lower():
                return []
            raise
        finally:
            con.close()

        found = {}
        for r in rows:
            cat = str(r.get('category') or '').strip().lower()
            title = str(r.get('title') or '').strip().lower()
            fn = str(r.get('original_filename') or '').strip().lower()
            if kind == 'map':
                matches = (cat == 'district map' or 'district map' in cat or
                           'power map' in title or '_map' in fn or fn.endswith('map.pdf'))
            elif kind == 'infra':
                matches = ('district infrastructure' in cat or 'district infra' in cat or
                           'infrastructure' in title or 'infra' in title or
                           '_infra' in fn or '_infrastructure' in fn)
            else:
                matches = False
            if not matches:
                continue
            district = str(r.get('district') or '').strip() or self._reference_district_from_filename(r.get('original_filename'))
            district = re.sub(r'\s+', ' ', district).strip()
            if district:
                found.setdefault(district.casefold(), district)
        return sorted(found.values(), key=lambda x: x.casefold())

    def get_reference_document_for_district(self, district, kind):
        """Pick the best matching District Map or District Infra PDF."""
        docs = self.list_district_reference_documents(district)
        kind = str(kind).lower()
        preferred = []
        for r in docs:
            fn = str(r.get('original_filename') or '').lower()
            title = str(r.get('title') or '').lower()
            cat = str(r.get('category') or '').lower()
            score = 0
            if kind == 'map':
                if 'district map' in cat: score += 100
                if '_map' in fn or fn.endswith('map.pdf') or 'power map' in title: score += 80
                if 'map' in title: score += 40
            else:
                if 'district infrastructure' in cat or 'infra' in cat: score += 100
                if '_infra' in fn or 'infra' in title or 'infrastructure' in title: score += 80
            if score:
                preferred.append((score, r))
        preferred.sort(key=lambda x: (-x[0], str(x[1].get('title') or '')))
        return preferred[0][1] if preferred else None

    def get_reference_blob_by_filename(self, file_name):
        key=self._canonical_pdf_filename(file_name)
        con=self._master_connect(readonly=True)
        try:
            r=con.execute("SELECT original_filename,pdf_blob FROM reference_documents WHERE LOWER(TRIM(original_filename))=? LIMIT 1",(key,)).fetchone()
            return (r['pdf_blob'], r['original_filename']) if r else (None,None)
        finally: con.close()

    def developer_import_pdf_to_master(self, pdf_path):
        """
        MASTER.db append-only rule.

        Indexing is NEVER allowed to UPDATE, DELETE or otherwise modify an
        existing MASTER.db approval. A PDF is imported only when its approval
        number is completely absent from MASTER.db.

        Identity is the numeric R.No. derived from the filename, e.g.
        2123.pdf -> R.No. 2123.

        New rows are intentionally created with only the immutable identity
        and PDF BLOB. Metadata remains blank/PENDING_REVIEW for later manual
        developer editing.
        """
        if not self.master_mode:
            raise RuntimeError("Developer import requires MASTER.db mode")

        pdf_path = Path(pdf_path)
        if not pdf_path.exists() or pdf_path.suffix.lower() != ".pdf":
            raise FileNotFoundError(f"PDF not found: {pdf_path}")

        filename = pdf_path.name
        rno = self._approval_number_from_filename(filename)
        mm = re.search(r"\d+", rno)
        numeric = int(mm.group()) if mm else 0

        if numeric <= 0:
            return False, "SKIPPED_INVALID_RNO", None

        blob = pdf_path.read_bytes()
        digest = hashlib.sha256(blob).hexdigest()

        con = self._master_connect()
        try:
            con.execute("BEGIN IMMEDIATE")

            # STRICT IMMUTABILITY:
            # If the R.No. already exists, absolutely nothing in MASTER.db is
            # changed — not the metadata, not the BLOB, not the filename, not
            # the hash. This remains true even during Force Full Re-index.
            existing = con.execute(
                """
                SELECT approval_id, approval_number
                FROM approvals
                WHERE approval_number_numeric=?
                   OR TRIM(approval_number)=?
                LIMIT 1
                """,
                (numeric, rno),
            ).fetchone()

            if existing:
                con.rollback()
                return False, "EXISTS_RNO_UNCHANGED", int(existing["approval_id"])

            # Extra safety for a duplicate filename linked to an existing row.
            existing_pdf = self._master_row_by_pdf_filename(con, filename)
            if existing_pdf:
                con.rollback()
                return False, "EXISTS_FILENAME_UNCHANGED", int(existing_pdf["approval_id"])

            now = datetime.now().isoformat(timespec="seconds")

            # Create only a NEW approval. Optional metadata fields are left
            # blank; no existing row is ever touched by this method.
            a_cols = {r[1] for r in con.execute("PRAGMA table_info(approvals)").fetchall()}
            values = {
                "approval_number": rno,
                "approval_number_numeric": numeric,
                "approval_code": rno,
                "memo_number": "",
                "file_number": "",
                "approval_date": "",
                "approval_date_sort": "",
                "subject": "",
                "metadata_status": "PENDING_REVIEW",
                "verified": 0,
                "metadata_updated_on": now,
            }
            cols = [k for k in values if k in a_cols]

            con.execute(
                f"INSERT INTO approvals ({','.join(cols)}) "
                f"VALUES ({','.join('?' for _ in cols)})",
                [values[k] for k in cols],
            )
            approval_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]

            # Attach the PDF only to this brand-new approval.
            p_cols = {r[1] for r in con.execute("PRAGMA table_info(pdf_documents)").fetchall()}
            p_values = {
                "approval_id": approval_id,
                "original_filename": filename,
                "pdf_blob": sqlite3.Binary(blob),
                "pdf_sha256": digest,
            }
            pcols = [k for k in p_values if k in p_cols]
            con.execute(
                f"INSERT INTO pdf_documents ({','.join(pcols)}) "
                f"VALUES ({','.join('?' for _ in pcols)})",
                [p_values[k] for k in pcols],
            )

            con.commit()
            DB_STORE.sync_file(MASTER_DB_PATH, MASTER_STORAGE_PATH)
            DB_STORE.note_runtime_synced(MASTER_STORAGE_PATH, MASTER_DB_PATH)
            return True, "APPENDED_NEW_RNO_ONLY", approval_id

        except Exception:
            con.rollback()
            raise
        finally:
            con.close()


    def add_new_master_pdf(self, pdf_path):
        """Manually append one new approval PDF to MASTER.db.

        The PDF filename supplies the immutable R.No. identity. Existing R.No.s
        are never overwritten by this method.
        """
        if not self.master_mode:
            raise RuntimeError("MASTER PDF maintenance requires MASTER.db mode")
        pdf_path=Path(pdf_path)
        if not pdf_path.exists() or pdf_path.suffix.lower() != '.pdf':
            raise FileNotFoundError(f"PDF not found: {pdf_path}")
        rno=self._approval_number_from_filename(pdf_path.name)
        if not rno or not re.search(r'\d+', rno):
            raise ValueError("The PDF filename must contain a numeric R.No., e.g. 2196.pdf")
        blob=pdf_path.read_bytes()
        if not blob.startswith(b'%PDF'):
            raise ValueError("The selected file does not appear to be a valid PDF.")
        digest=hashlib.sha256(blob).hexdigest()
        now=datetime.now().isoformat(timespec='seconds')
        m=re.search(r'\d+',rno); numeric=int(m.group()) if m else 0
        con=self._master_connect()
        try:
            con.execute('BEGIN IMMEDIATE')
            existing=con.execute("SELECT approval_id FROM approvals WHERE approval_number_numeric=? OR LOWER(TRIM(approval_number))=LOWER(TRIM(?)) LIMIT 1",(numeric,rno)).fetchone()
            if existing:
                con.rollback()
                raise ValueError(f"R.No. {rno} already exists in MASTER.db. Use Replace Embedded PDF for an amended PDF.")
            existing_pdf=con.execute("SELECT approval_id FROM pdf_documents WHERE LOWER(TRIM(original_filename))=LOWER(TRIM(?)) LIMIT 1",(pdf_path.name,)).fetchone()
            if existing_pdf:
                con.rollback(); raise ValueError(f"PDF {pdf_path.name} already exists in MASTER.db.")
            a_cols={r[1] for r in con.execute('PRAGMA table_info(approvals)').fetchall()}
            vals={'approval_number':rno,'approval_number_numeric':numeric,'approval_code':rno,'memo_number':'','file_number':'','approval_date':'','approval_date_sort':'','subject':'','metadata_status':'PENDING_REVIEW','verified':0,'created_at':now,'updated_at':now,'metadata_updated_on':now}
            cols=[k for k in vals if k in a_cols]
            con.execute(f"INSERT INTO approvals ({','.join(cols)}) VALUES ({','.join('?' for _ in cols)})",[vals[k] for k in cols])
            aid=int(con.execute('SELECT last_insert_rowid()').fetchone()[0])
            pcols={r[1] for r in con.execute('PRAGMA table_info(pdf_documents)').fetchall()}
            pvals={'approval_id':aid,'original_filename':pdf_path.name,'pdf_blob':sqlite3.Binary(blob),'pdf_sha256':digest,'sha256':digest,'file_size':len(blob),'pdf_size':len(blob),'imported_at':now,'imported_on':now,'page_count':0}
            pc=[k for k in pvals if k in pcols]
            # determine page count if schema supports it
            try:
                doc=fitz.open(stream=blob,filetype='pdf'); pages=len(doc); doc.close()
                if 'page_count' in pcols: pvals['page_count']=pages
            except Exception: pages=0
            con.execute(f"INSERT INTO pdf_documents ({','.join(pc)}) VALUES ({','.join('?' for _ in pc)})",[pvals[k] for k in pc])
            con.commit()
        except Exception:
            try: con.rollback()
            except Exception: pass
            raise
        finally: con.close()
        DB_STORE.sync_all()
        return {'approval_id':aid,'file_name':pdf_path.name,'rno':rno,'pdf_size':len(blob),'page_count':pages,'sha256':digest}

    def delete_master_record_by_filename(self, file_name):
        if not self.master_mode:
            raise RuntimeError("MASTER record deletion requires MASTER.db mode")
        file_name = str(file_name or "").strip()
        if not file_name:
            raise ValueError("PDF filename is required.")

        con = self._master_connect()
        try:
            con.execute("BEGIN IMMEDIATE")
            row = self._master_row_by_pdf_filename(con, file_name)
            if not row:
                raise RuntimeError(f"MASTER record for {file_name} was not found.")
            approval_id = int(row["approval_id"])
            con.execute("DELETE FROM pdf_documents WHERE approval_id=?", (approval_id,))
            con.execute("DELETE FROM approvals WHERE approval_id=?", (approval_id,))
            con.commit()
        except Exception:
            try:
                con.rollback()
            except Exception:
                pass
            raise
        finally:
            con.close()

        # Index ids are independent from MASTER approval ids.
        try:
            icon = self.index.connect()
            try:
                idx_rows = icon.execute(
                    "SELECT id FROM documents WHERE file_name=?", (file_name,)
                ).fetchall()
                for idx_row in idx_rows:
                    idx_id = int(idx_row["id"])
                    for table in ("semantic_chunks", "pages", "document_notes", "favorites"):
                        try:
                            icon.execute(
                                f"DELETE FROM {table} WHERE document_id=?", (idx_id,)
                            )
                        except Exception:
                            pass
                    icon.execute("DELETE FROM documents WHERE id=?", (idx_id,))
                icon.commit()
            finally:
                icon.close()
        except Exception:
            pass

        DB_STORE.sync_file(MASTER_DB_PATH, MASTER_STORAGE_PATH)
        DB_STORE.note_runtime_synced(MASTER_STORAGE_PATH, MASTER_DB_PATH)
        return approval_id

    # V22.3.43: PDF replacement is schema-compatible with legacy/current
    # MASTER.db layouts (sha256 vs pdf_sha256; file_size vs pdf_size).
    def replace_master_pdf_by_filename(self, file_name, pdf_path):
        if not self.master_mode:
            raise RuntimeError("MASTER PDF replacement requires MASTER.db mode")

        file_name = str(file_name or "").strip()
        pdf_path = Path(pdf_path)
        if not file_name:
            raise ValueError("Current MASTER PDF filename is required.")
        if not pdf_path.exists() or pdf_path.suffix.lower() != ".pdf":
            raise FileNotFoundError(f"Replacement PDF not found: {pdf_path}")

        current_rno = self._approval_number_from_filename(file_name)
        replacement_rno = self._approval_number_from_filename(pdf_path.name)
        if not current_rno or current_rno.casefold() != replacement_rno.casefold():
            raise ValueError(
                "Replacement PDF identity mismatch.\n\n"
                f"Current MASTER PDF: {file_name}\n"
                f"Current R.No.: {current_rno}\n\n"
                f"Selected PDF: {pdf_path.name}\n"
                f"Selected R.No.: {replacement_rno or 'not detected'}\n\n"
                "The replacement PDF must have the same R.No. filename."
            )

        blob = pdf_path.read_bytes()
        if not blob.startswith(b"%PDF"):
            raise ValueError("The selected file does not appear to be a valid PDF.")

        digest = hashlib.sha256(blob).hexdigest()
        try:
            doc = fitz.open(stream=blob, filetype="pdf")
            page_count = len(doc)
            doc.close()
        except Exception as exc:
            raise ValueError(f"Could not open the replacement PDF: {exc}")

        now = datetime.now().isoformat(timespec="seconds")
        con = self._master_connect()
        try:
            con.execute("BEGIN IMMEDIATE")
            row = self._master_row_by_pdf_filename(con, file_name)
            if not row:
                raise RuntimeError(f"MASTER record for {file_name} was not found.")
            approval_id = int(row["approval_id"])

            p_cols = {str(r[1]) for r in con.execute(
                "PRAGMA table_info(pdf_documents)"
            ).fetchall()}
            if "pdf_blob" not in p_cols:
                raise RuntimeError(
                    "MASTER.db pdf_documents has no pdf_blob column."
                )

            # MASTER generations use either sha256 or pdf_sha256, and either
            # file_size or pdf_size.  Resolve the physical column names once
            # rather than assuming the newest schema.
            hash_col = (
                "sha256" if "sha256" in p_cols
                else ("pdf_sha256" if "pdf_sha256" in p_cols else None)
            )
            size_col = (
                "file_size" if "file_size" in p_cols
                else ("pdf_size" if "pdf_size" in p_cols else None)
            )

            updates = {"pdf_blob": sqlite3.Binary(blob)}
            if hash_col:
                updates[hash_col] = digest
            if size_col:
                updates[size_col] = len(blob)
            if "page_count" in p_cols:
                updates["page_count"] = page_count
            if "imported_on" in p_cols:
                updates["imported_on"] = now
            elif "updated_at" in p_cols:
                updates["updated_at"] = now
            if not updates:
                raise RuntimeError("pdf_documents has no replaceable PDF fields.")

            con.execute(
                "UPDATE pdf_documents SET "
                + ", ".join(f"{k}=?" for k in updates)
                + " WHERE approval_id=?",
                list(updates.values()) + [approval_id],
            )
            con.commit()
        except Exception:
            try:
                con.rollback()
            except Exception:
                pass
            raise
        finally:
            con.close()

        # V22.3.43 CRITICAL FIX: sync_all() deliberately skips MASTER.db.
        # Replace-PDF therefore must explicitly persist the plaintext runtime
        # MASTER database back to the encrypted authoritative MASTER.db.
        DB_STORE.sync_file(MASTER_DB_PATH, MASTER_STORAGE_PATH)
        DB_STORE.note_runtime_synced(MASTER_STORAGE_PATH, MASTER_DB_PATH)

        # V22.3.43 FIX: _master_row_by_pdf_filename() now explicitly selects
        # pdf_blob/pdf_sha256 from pdf_documents.  Previously it selected only
        # a.* and p.original_filename; the subsequent verify_row["pdf_blob"]
        # therefore raised sqlite3.Row's "No item with that key" AFTER the
        # replacement had already been committed and synchronized.  That made
        # a successful replacement look like a failure.
        #
        # Verify the runtime BLOB after the transaction and persistence step.
        verify_con = self._master_connect(readonly=True)
        try:
            verify_row = self._master_row_by_pdf_filename(verify_con, file_name)
            if not verify_row:
                raise RuntimeError(
                    f"PDF replacement committed, but {file_name} could not be re-read from MASTER.db."
                )
            stored_blob = bytes(verify_row["pdf_blob"] or b"")
            stored_digest = hashlib.sha256(stored_blob).hexdigest() if stored_blob else ""
            if stored_digest != digest:
                raise RuntimeError(
                    "PDF replacement verification failed: the stored MASTER.db BLOB "
                    "does not match the replacement PDF."
                )
        finally:
            verify_con.close()

        return {
            "approval_id": approval_id,
            "file_name": file_name,
            "pdf_size": len(blob),
            "page_count": page_count,
            "sha256": digest,
            "persisted": True,
        }

    def master_approval_rows_for_index(self):
        """Return every approval PDF BLOB from MASTER.db for search indexing."""
        con = self._master_connect(readonly=True)
        try:
            # pdf_documents is the authoritative PDF-BLOB table. It does not
            # necessarily contain full_text; extracted/OCR text belongs in index.db.
            pcols={r[1] for r in con.execute("PRAGMA table_info(pdf_documents)").fetchall()}
            if "pdf_blob" not in pcols:
                raise RuntimeError("MASTER.db pdf_documents table has no pdf_blob column")
            hash_expr = "p.sha256" if "sha256" in pcols else ("p.pdf_sha256" if "pdf_sha256" in pcols else "''")
            size_expr = "p.file_size" if "file_size" in pcols else ("p.pdf_size" if "pdf_size" in pcols else "length(p.pdf_blob)")
            return [dict(r) for r in con.execute(
                "SELECT a.*, p.original_filename, p.pdf_blob, "
                f"COALESCE({size_expr}, length(p.pdf_blob), 0) AS pdf_size, "
                f"COALESCE({hash_expr}, '') AS pdf_hash "
                "FROM approvals a INNER JOIN pdf_documents p ON p.approval_id=a.approval_id "
                "WHERE length(COALESCE(p.pdf_blob, X'')) > 0 "
                "ORDER BY COALESCE(a.approval_number_numeric,0), a.approval_id"
            ).fetchall()]
        finally:
            con.close()

    def _rebuild_search_index_full(self, progress=None, log=None, cancel_event=None, force=False):
        """Build a completely isolated candidate index, validate it, then publish it.

        The live index.db is NEVER modified during the build. This is deliberate:
        if Windows/Python is killed or power is lost, the previous known-good
        index remains available. A candidate is published only after strict
        validation against MASTER.db.
        """
        if not self.master_mode:
            raise RuntimeError("MASTER-only indexing requires MASTER.db mode")
        cancel_event = cancel_event or threading.Event()

        # Read the complete MASTER source list first.
        mcon = self._master_connect(readonly=True)
        try:
            pcols = {r[1] for r in mcon.execute("PRAGMA table_info(pdf_documents)").fetchall()}
            acols = {r[1] for r in mcon.execute("PRAGMA table_info(approvals)").fetchall()}
            if "original_filename" not in pcols or "pdf_blob" not in pcols:
                raise RuntimeError("MASTER.db pdf_documents must contain original_filename and pdf_blob")

            hcol = "sha256" if "sha256" in pcols else ("pdf_sha256" if "pdf_sha256" in pcols else None)
            scol = "file_size" if "file_size" in pcols else ("pdf_size" if "pdf_size" in pcols else None)
            pgcol = "page_count" if "page_count" in pcols else None
            hexpr = f"COALESCE(p.{hcol}, '')" if hcol else "''"
            sexpr = f"COALESCE(p.{scol}, length(p.pdf_blob), 0)" if scol else "COALESCE(length(p.pdf_blob),0)"
            pexpr = f"COALESCE(p.{pgcol},0)" if pgcol else "0"
            fields = [
                "approval_number", "approval_number_numeric", "approval_code",
                "approval_date", "approval_date_sort", "file_number",
                "memo_number", "subject"
            ]
            ase = ", " + ", ".join(
                f"a.{c} AS a_{c}" for c in fields if c in acols
            ) if any(c in acols for c in fields) else ""
            rows = [dict(r) for r in mcon.execute(
                "SELECT p.rowid AS _pdf_rowid,p.approval_id,p.original_filename,p.pdf_blob,"
                f"{sexpr} AS _pdf_size,{hexpr} AS _pdf_hash,{pexpr} AS _pdf_page_count"
                f"{ase} FROM pdf_documents p "
                "LEFT JOIN approvals a ON a.approval_id=p.approval_id "
                "WHERE length(COALESCE(p.pdf_blob,X'')) > 0 "
                "ORDER BY p.rowid"
            ).fetchall()]
        finally:
            mcon.close()

        total = len(rows)
        blob_count = sum(bool(r.get("pdf_blob")) for r in rows)
        indexed = already_current = errors = 0
        native_pages = ocr_pages = unreadable_pages = 0
        semantic_created = semantic_skipped = 0

        if log:
            log(f"MASTER INDEX SOURCE: {total:,} approval PDF(s) with embedded BLOBs")
            log(f"Embedded PDF BLOBs available: {blob_count:,}")
            log("BUILD POLICY: live index.db is held unchanged until candidate validation succeeds.")
            log("If the application closes abruptly, the candidate is discarded on next startup.")

        # Candidate database lives separately from the live index.
        runtime_dir = Path(self.index.path).parent
        candidate = runtime_dir / f"index_BUILD_{os.getpid()}_{int(time.time())}.db"
        for suffix in ("", "-wal", "-shm", "-journal"):
            try:
                p = Path(str(candidate) + suffix)
                if p.exists():
                    p.unlink()
            except Exception:
                pass

        build_db = None
        published = False
        stopped = False
        try:
            build_db = IndexDatabase(candidate)

            for pos, row in enumerate(rows, 1):
                if cancel_event.is_set():
                    stopped = True
                    break

                filename = str(row.get("original_filename") or "").strip()
                if progress:
                    progress(pos, total, filename or f"MASTER row {pos}")

                if not filename:
                    errors += 1
                    if log:
                        log(f"[{pos}/{total}] ERROR: blank original_filename")
                    continue

                try:
                    aid = int(row.get("approval_id") or 0)
                    did = aid if aid > 0 else -int(row.get("_pdf_rowid") or pos)
                except Exception:
                    did = -int(row.get("_pdf_rowid") or pos)

                blob = bytes(row.get("pdf_blob") or b"")
                pdf_hash = str(row.get("_pdf_hash") or "").lower().strip()
                if not pdf_hash and blob:
                    pdf_hash = hashlib.sha256(blob).hexdigest()

                canonical = self._approval_number_from_filename(filename)
                mm = re.search(r"\d+", canonical)
                try:
                    numeric = int(mm.group()) if mm else int(row.get("a_approval_number_numeric") or 0)
                except Exception:
                    numeric = 0

                def aval(n):
                    v = row.get("a_" + n, "")
                    return "" if v is None else str(v)

                metadata = {
                    "approval_number": canonical or aval("approval_number"),
                    "approval_number_numeric": numeric,
                    "approval_code": aval("approval_code"),
                    "approval_date": aval("approval_date"),
                    "approval_date_sort": aval("approval_date_sort") or parse_date(aval("approval_date")),
                    "file_number": aval("file_number"),
                    "memo_number": aval("memo_number"),
                    "subject": aval("subject"),
                }

                pages = []
                full_text = ""
                try:
                    if blob:
                        if log:
                            log(f"[{pos}/{total}] {filename} — extracting embedded PDF")
                        pages, full_text, info = extract_pdf_bytes(blob, logger=log)
                        native_pages += int(info.get("native_pages", 0) or 0)
                        ocr_pages += int(info.get("ocr_pages", 0) or 0)
                        unreadable_pages += int(info.get("failed_pages", 0) or 0)
                        if len(normalize_spaces(full_text)) < 10:
                            full_text = "[SCANNED / IMAGE-ONLY PDF - OCR TEXT NOT AVAILABLE]"
                    else:
                        errors += 1
                        if log:
                            log(f"[{pos}/{total}] ERROR: empty pdf_blob")
                        continue

                    data = {
                        "file_path": f"MASTER:{did}",
                        "file_name": filename,
                        "file_hash": pdf_hash,
                        "file_size": int(row.get("_pdf_size") or len(blob)),
                        "modified_time": 0.0,
                        "page_count": int(row.get("_pdf_page_count") or len(pages) or 0),
                        **metadata,
                        "full_text": full_text,
                        "indexed_at": datetime.now().isoformat(timespec="seconds"),
                    }

                    con = build_db.connect()
                    try:
                        con.execute(
                            "INSERT INTO documents("
                            "id,file_path,file_name,file_hash,file_size,modified_time,page_count,"
                            "approval_number,approval_number_numeric,approval_code,approval_date,"
                            "approval_date_sort,file_number,memo_number,subject,full_text,indexed_at"
                            ") VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                            (
                                did, data["file_path"], filename, pdf_hash, data["file_size"], 0.0,
                                data["page_count"], data["approval_number"], data["approval_number_numeric"],
                                data["approval_code"], data["approval_date"], data["approval_date_sort"],
                                data["file_number"], data["memo_number"], data["subject"], full_text,
                                data["indexed_at"]
                            )
                        )
                        con.execute(
                            "INSERT INTO documents_fts("
                            "rowid,full_text,file_name,approval_number,approval_code,subject"
                            ") VALUES (?,?,?,?,?,?)",
                            (did, full_text, filename, data["approval_number"],
                             data["approval_code"], data["subject"])
                        )
                        if pages:
                            con.executemany(
                                "INSERT INTO pages(document_id,page_number,page_text) VALUES (?,?,?)",
                                [(did, n, t) for n, t in pages]
                            )
                        con.commit()
                    finally:
                        con.close()

                    indexed += 1
                    if log:
                        log(f"    Indexed successfully ({indexed:,}).")

                except Exception as exc:
                    errors += 1
                    if log:
                        log(f"[{pos}/{total}] INDEX ERROR: {filename}: {exc}")

            if stopped:
                if log:
                    log("BUILD STOPPED: candidate index was NOT published.")
                return {
                    "checked": total, "indexed": indexed,
                    "already_current": already_current, "errors": errors,
                    "native_pages": native_pages, "ocr_pages": ocr_pages,
                    "unreadable_pages": unreadable_pages,
                    "semantic_created": semantic_created,
                    "semantic_skipped": semantic_skipped,
                    "stopped": True, "total": total, "published": False,
                    "verified": False,
                }

            # Candidate uses a single durable SQLite main file in V21.  Close
            # any remaining connection before strict validation/publish.
            try:
                con = sqlite3.connect(str(candidate), timeout=60)
                con.execute("PRAGMA busy_timeout=60000")
                con.execute("PRAGMA journal_mode=DELETE")
                con.execute("PRAGMA synchronous=FULL")
                con.close()
            except Exception:
                pass

            ok, reason = self.validate_index_file_against_master(candidate)
            if not ok:
                errors += 1
                if log:
                    log(f"VALIDATION FAILED — candidate NOT published: {reason}")
                return {
                    "checked": total, "indexed": indexed,
                    "already_current": already_current, "errors": errors,
                    "native_pages": native_pages, "ocr_pages": ocr_pages,
                    "unreadable_pages": unreadable_pages,
                    "semantic_created": semantic_created,
                    "semantic_skipped": semantic_skipped,
                    "stopped": False, "total": total, "published": False,
                    "verified": False, "validation_error": reason,
                }

            if log:
                log(f"VALIDATION PASSED: {reason}")
                log("Writing persistent V21 verification marker…")
            # Stamp the candidate BEFORE encryption/persistence.  The marker
            # therefore travels inside the encrypted index.db and survives
            # every application restart.
            self.write_index_verification_marker(candidate)
            if log:
                log("Persistent V21 verification marker written successfully.")
                log("Publishing verified candidate index.db…")

            # Persist the validated candidate first. If encryption/storage fails,
            # the old live runtime index remains untouched.
            DB_STORE.sync_file(candidate, INDEX_STORAGE_PATH)

            # Replace the live runtime copy only after the encrypted storage copy
            # has been successfully created.
            live = Path(self.index.path)
            backup = live.with_name(live.name + ".PREVIOUS_GOOD")
            for p in (backup, Path(str(backup) + "-wal"), Path(str(backup) + "-shm")):
                try:
                    if p.exists():
                        p.unlink()
                except Exception:
                    pass

            if live.exists():
                os.replace(live, backup)

            os.replace(candidate, live)

            # Remove old live sidecars and keep the previous-good backup only
            # until the new live database has been opened and verified.
            for suffix in ("-wal", "-shm", "-journal"):
                try:
                    p = Path(str(live) + suffix)
                    if p.exists():
                        p.unlink()
                except Exception:
                    pass

            ok2, reason2 = self.validate_index_file_against_master(live)
            if not ok2:
                # Roll back immediately if the post-publish runtime verification fails.
                try:
                    if live.exists():
                        live.unlink()
                except Exception:
                    pass
                if backup.exists():
                    os.replace(backup, live)
                raise RuntimeError(f"post-publish index verification failed: {reason2}")

            try:
                if backup.exists():
                    backup.unlink()
            except Exception:
                pass

            # V29 CRITICAL FIX: publish the verified runtime index to the
            # encrypted persistent index.db BEFORE writing the restart proof.
            #
            # Previous V28 code only called DB_STORE.note_runtime_synced() here.
            # That function records a baseline hash; it does NOT copy/encrypt
            # the runtime database into BASE_DIR/index.db.  Consequently the
            # successful 1,584-document runtime index was lost when the temp
            # runtime directory was deleted, and the next launch decrypted the
            # old persistent index and rebuilt everything again.
            #
            # V29 makes persistence part of the successful indexing transaction.
            if log:
                log("Persisting verified index.db to encrypted storage before restart proof…")
            DB_STORE.sync_file(live, INDEX_STORAGE_PATH)
            if not INDEX_STORAGE_PATH.exists():
                raise RuntimeError("verified index was built but persistent index.db was not created")
            # Re-open the persisted artifact through the same decryption path and
            # verify its basic SQLite usability/count before declaring success.
            persisted_plain = live.with_name(live.name + ".persist_verify")
            try:
                persisted_plain.write_bytes(DB_STORE._decrypt_bytes(INDEX_STORAGE_PATH.read_bytes()))
                pcon = sqlite3.connect(str(persisted_plain), timeout=60)
                try:
                    pcon.execute("PRAGMA busy_timeout=60000")
                    pintegrity = str(pcon.execute("PRAGMA integrity_check").fetchone()[0]).strip().lower()
                    pcount = int(pcon.execute("SELECT COUNT(*) FROM documents").fetchone()[0])
                    if pintegrity != "ok":
                        raise RuntimeError(f"persistent index SQLite integrity_check failed: {pintegrity}")
                    if pcount != int(total):
                        raise RuntimeError(f"persistent index document count mismatch: expected={total} actual={pcount}")
                finally:
                    pcon.close()
            finally:
                try:
                    if persisted_plain.exists():
                        persisted_plain.unlink()
                except Exception:
                    pass
            if log:
                log(f"Persistent index.db write VERIFIED: {total:,} documents recoverable after restart.")

            # V34: FREEZE the exact persistent files produced by this successful
            # transaction.  Their exact SHA-256 values become the restart proof.
            master_storage_sha = _persistent_file_sha256(MASTER_STORAGE_PATH)
            index_storage_sha = _persistent_file_sha256(INDEX_STORAGE_PATH)
            _write_v34_registry_state(
                master_storage_sha, index_storage_sha, int(total), log=log
            )
            if log:
                log("V34 FREEZE COMMIT: successful MASTER.db + index.db are frozen until a data release.")

            published = True
            # V25 FIX: this code already runs on the Database instance.
            # The old V23 call used self.db._write_verified_state(), but this
            # object has no self.db attribute. That exception prevented the
            # persistent restart-proof file from ever being written, so every
            # subsequent application launch incorrectly rebuilt all PDFs.
            # Write the verified-state record only after BOTH the encrypted
            # storage copy and live runtime copy have passed verification.
            try:
                self._write_verified_state()
                if not INDEX_VERIFIED_STATE_PATH.exists():
                    raise RuntimeError("verified-state file was not created")
                state_ok, state_reason = self._verified_state_matches_files()
                if not state_ok:
                    raise RuntimeError(f"verified-state self-check failed: {state_reason}")
                if log:
                    log("Persistent V25 logical verified-state record written and self-checked successfully.")
                    log(f"Restart proof: {state_reason}")
            except Exception as exc:
                # A published index without a durable restart proof is not a
                # successful indexing transaction. Do not silently leave the
                # application in a state that will trigger an unexplained
                # full rebuild on the next launch.
                if log:
                    log(f"ERROR: could not finalize persistent verified-state record: {exc}")
                raise RuntimeError(f"index published but verified-state finalization failed: {exc}")
            DB_STORE.note_runtime_synced(INDEX_STORAGE_PATH, live)
            if log:
                log(f"INDEX PUBLISHED SUCCESSFULLY: {reason2}")
                log("V34 persistence commit complete — next restart will use the frozen persistent-file SHA registry gate.")

            return {
                "checked": total, "indexed": indexed,
                "already_current": already_current, "errors": errors,
                "native_pages": native_pages, "ocr_pages": ocr_pages,
                "unreadable_pages": unreadable_pages,
                "semantic_created": semantic_created,
                "semantic_skipped": semantic_skipped,
                "stopped": False, "total": total, "published": published,
                "verified": True, "validation_error": "",
            }

        finally:
            # Candidate is never allowed to survive as an ambiguous build artifact.
            try:
                if build_db is not None:
                    pass
            except Exception:
                pass
            if not published:
                for suffix in ("", "-wal", "-shm", "-journal"):
                    try:
                        p = Path(str(candidate) + suffix)
                        if p.exists():
                            p.unlink()
                    except Exception:
                        pass

    def master_index_change_plan(self):
        """Compare MASTER.db with the live index WITHOUT extracting/OCRing PDFs.

        Returns a compact plan identifying only approvals whose searchable
        representation is new, deleted, has a changed embedded PDF, or has
        changed metadata.  This scan is deliberately metadata/hash based; it
        never performs PDF extraction.
        """
        live = Path(self.index.path)
        if not live.exists():
            return {"usable": False, "reason": "index.db is missing", "changes": [], "total": 0}
        ok, reason = _basic_existing_index_check(live, expected_count=0)
        if not ok:
            return {"usable": False, "reason": reason, "changes": [], "total": 0}

        mrows = self.master_approval_rows_for_index()
        icon = self.index.connect()
        try:
            irows = [dict(r) for r in icon.execute(
                "SELECT id,file_name,file_hash,file_size,approval_number,approval_number_numeric,"
                "approval_code,approval_date,approval_date_sort,file_number,memo_number,subject,full_text,page_count "
                "FROM documents"
            ).fetchall()]
        finally:
            icon.close()

        master = {}
        for r in mrows:
            name = str(r.get("original_filename") or "").strip().casefold()
            if name:
                master[name] = r
        idx = {str(r.get("file_name") or "").strip().casefold(): r for r in irows if str(r.get("file_name") or "").strip()}

        changes = []
        for name, r in master.items():
            ir = idx.get(name)
            if ir is None:
                changes.append({"name": name, "kind": "new", "approval_id": int(r.get("approval_id") or 0)})
                continue
            mh = str(r.get("pdf_hash") or "").strip().lower()
            ih = str(ir.get("file_hash") or "").strip().lower()
            if mh and ih and mh != ih:
                changes.append({"name": name, "kind": "pdf_changed", "approval_id": int(r.get("approval_id") or 0)})
                continue
            if mh and not ih:
                changes.append({"name": name, "kind": "pdf_changed", "approval_id": int(r.get("approval_id") or 0)})
                continue
            metadata_pairs = (
                ("approval_number", r.get("a_approval_number"), ir.get("approval_number")),
                ("approval_number_numeric", r.get("a_approval_number_numeric"), ir.get("approval_number_numeric")),
                ("approval_code", r.get("a_approval_code"), ir.get("approval_code")),
                ("approval_date", r.get("a_approval_date"), ir.get("approval_date")),
                ("approval_date_sort", r.get("a_approval_date_sort"), ir.get("approval_date_sort")),
                ("file_number", r.get("a_file_number"), ir.get("file_number")),
                ("memo_number", r.get("a_memo_number"), ir.get("memo_number")),
                ("subject", r.get("a_subject"), ir.get("subject")),
            )
            different = False
            for _field, a, b in metadata_pairs:
                aa = "" if a is None else str(a).strip()
                bb = "" if b is None else str(b).strip()
                if _field == "approval_number_numeric":
                    try:
                        if int(a or 0) != int(b or 0): different = True
                    except Exception:
                        if aa != bb: different = True
                elif aa != bb:
                    different = True
                if different:
                    break
            if different:
                changes.append({"name": name, "kind": "metadata_changed", "approval_id": int(r.get("approval_id") or 0)})

        # Only documents previously sourced from MASTER approval BLOBs belong to the
        # approval search index.  Older releases could leave SSTN infrastructure/map
        # or other folder-based reference PDFs in index.db.  They are NOT approvals
        # and must never be presented as approval changes or indexed again.
        legacy_nonapproval = []
        for name, ir in idx.items():
            if name not in master:
                fp = str(ir.get("file_path") or "")
                if fp.upper().startswith("MASTER:"):
                    changes.append({"name": name, "kind": "deleted", "approval_id": int(ir.get("id") or 0)})
                else:
                    legacy_nonapproval.append({"name": name, "kind": "legacy_nonapproval", "approval_id": int(ir.get("id") or 0)})

        return {"usable": True, "reason": "incremental comparison complete", "changes": changes,
                "legacy_nonapproval": legacy_nonapproval, "total": len(master)}

    def _publish_index_candidate(self, candidate, total, log=None):
        """Publish and persist a validated candidate index using the existing V34/V25 safety protocol."""
        ok, reason = self.validate_index_file_against_master(candidate)
        if not ok:
            raise RuntimeError(f"VALIDATION FAILED — candidate NOT published: {reason}")
        if log: log(f"VALIDATION PASSED: {reason}")
        self.write_index_verification_marker(candidate)
        if log: log("Persistent verification marker written; publishing candidate index.db…")
        DB_STORE.sync_file(candidate, INDEX_STORAGE_PATH)
        live = Path(self.index.path)
        backup = live.with_name(live.name + ".PREVIOUS_GOOD")
        for q in (backup, Path(str(backup)+"-wal"), Path(str(backup)+"-shm")):
            try:
                if q.exists(): q.unlink()
            except Exception: pass
        if live.exists(): os.replace(live, backup)
        os.replace(candidate, live)
        for suffix in ("-wal", "-shm", "-journal"):
            try:
                q=Path(str(live)+suffix)
                if q.exists(): q.unlink()
            except Exception: pass
        ok2, reason2 = self.validate_index_file_against_master(live)
        if not ok2:
            try:
                if live.exists(): live.unlink()
            except Exception: pass
            if backup.exists(): os.replace(backup, live)
            raise RuntimeError(f"post-publish index verification failed: {reason2}")
        try:
            if backup.exists(): backup.unlink()
        except Exception: pass
        DB_STORE.sync_file(live, INDEX_STORAGE_PATH)
        persisted_plain = live.with_name(live.name + ".persist_verify")
        try:
            persisted_plain.write_bytes(DB_STORE._decrypt_bytes(INDEX_STORAGE_PATH.read_bytes()))
            pcon=sqlite3.connect(str(persisted_plain), timeout=60)
            try:
                pcon.execute("PRAGMA busy_timeout=60000")
                if str(pcon.execute("PRAGMA integrity_check").fetchone()[0]).strip().lower() != "ok":
                    raise RuntimeError("persistent index SQLite integrity_check failed")
                pcount=int(pcon.execute("SELECT COUNT(*) FROM documents").fetchone()[0])
                if pcount != int(total):
                    raise RuntimeError(f"persistent index document count mismatch: expected={total} actual={pcount}")
            finally: pcon.close()
        finally:
            try:
                if persisted_plain.exists(): persisted_plain.unlink()
            except Exception: pass
        master_storage_sha=_persistent_file_sha256(MASTER_STORAGE_PATH)
        index_storage_sha=_persistent_file_sha256(INDEX_STORAGE_PATH)
        _write_v34_registry_state(master_storage_sha,index_storage_sha,int(total),log=log)
        self._write_verified_state()
        state_ok,state_reason=self._verified_state_matches_files()
        if not state_ok:
            raise RuntimeError(f"verified-state self-check failed: {state_reason}")
        DB_STORE.note_runtime_synced(INDEX_STORAGE_PATH, live)
        return reason2

    def rebuild_search_index_from_master(self, progress=None, log=None, cancel_event=None, force=False):
        """Incrementally update only MASTER approvals whose search content changed.

        A full rebuild is retained for missing/corrupt/incompatible indexes or
        when the Developer explicitly requests Force Full Search Re-index.
        """
        cancel_event = cancel_event or threading.Event()
        if force:
            if log: log("FORCE FULL RE-INDEX requested — all MASTER approval PDFs will be processed.")
            return self._rebuild_search_index_full(progress, log, cancel_event, force=True)

        plan = self.master_index_change_plan()
        if not plan.get("usable"):
            if log: log(f"Incremental index unavailable: {plan.get('reason')}. Falling back to full rebuild.")
            return self._rebuild_search_index_full(progress, log, cancel_event, force=False)
        changes = plan.get("changes", [])
        legacy_nonapproval = plan.get("legacy_nonapproval", []) or []
        total = int(plan.get("total") or 0)
        if legacy_nonapproval and log:
            log(f"APPROVAL INDEX SOURCE ISOLATION: {len(legacy_nonapproval):,} legacy non-approval index record(s) found; SSTN infrastructure/maps/reference PDFs are excluded.")
        if not changes:
            if legacy_nonapproval:
                # Remove obsolete folder/reference records from the disposable index
                # without treating them as approval PDFs or doing any extraction.
                live = Path(self.index.path)
                tmp = live.parent / f"index_CLEANUP_{os.getpid()}_{int(time.time())}.db"
                try:
                    shutil.copy2(live, tmp)
                    clean = IndexDatabase(tmp)
                    c = clean.connect()
                    try:
                        for rec in legacy_nonapproval:
                            did = int(rec.get("approval_id") or 0)
                            if did:
                                c.execute("DELETE FROM documents_fts WHERE rowid=?", (did,))
                                c.execute("DELETE FROM pages WHERE document_id=?", (did,))
                                c.execute("DELETE FROM semantic_chunks WHERE document_id=?", (did,))
                                c.execute("DELETE FROM documents WHERE id=?", (did,))
                        c.commit()
                    finally:
                        c.close()
                        clean.close()
                    self._publish_index_candidate(tmp, total, log=log)
                    if log: log(f"Removed {len(legacy_nonapproval):,} legacy non-approval record(s) from approval index; no PDFs were extracted.")
                finally:
                    for suffix in ("", "-wal", "-shm", "-journal"):
                        try:
                            q=Path(str(tmp)+suffix)
                            if q.exists(): q.unlink()
                        except Exception: pass
            if log: log(f"INCREMENTAL INDEX: no approval changes detected; {total:,} indexed approvals remain unchanged.")
            # Registry may be stale because of an old migration; safely refresh
            # the restart proof without extracting any PDFs.
            live=Path(self.index.path)
            try:
                self.write_index_verification_marker(live)
                DB_STORE.sync_file(live, INDEX_STORAGE_PATH)
                _write_v34_registry_state(_persistent_file_sha256(MASTER_STORAGE_PATH), _persistent_file_sha256(INDEX_STORAGE_PATH), total, log=log)
                self._write_verified_state()
            except Exception:
                pass
            return {"checked": total,"indexed":0,"already_current":total,"errors":0,"native_pages":0,"ocr_pages":0,"unreadable_pages":0,"semantic_created":0,"semantic_skipped":0,"stopped":False,"total":total,"published":True,"verified":True,"incremental":True,"changed_count":0}

        live=Path(self.index.path)
        runtime_dir=live.parent
        candidate=runtime_dir / f"index_BUILD_INC_{os.getpid()}_{int(time.time())}.db"
        for suffix in ("","-wal","-shm","-journal"):
            try:
                q=Path(str(candidate)+suffix)
                if q.exists(): q.unlink()
            except Exception: pass
        shutil.copy2(live,candidate)
        published=False
        indexed=0; errors=0; native_pages=0; ocr_pages=0; unreadable_pages=0; semantic_created=0; semantic_skipped=0
        if log:
            log(f"INCREMENTAL INDEX STARTED: {len(changes):,} approval change(s) out of {total:,} MASTER PDFs.")
            kinds={}
            for c in changes: kinds[c["kind"]]=kinds.get(c["kind"],0)+1
            log("Change plan: " + ", ".join(f"{k}={v}" for k,v in sorted(kinds.items())))
            log("Unchanged approvals are copied forward without PDF extraction/OCR.")
        try:
            build=IndexDatabase(candidate)
            mrows={str(r.get("original_filename") or "").strip().casefold():r for r in self.master_approval_rows_for_index()}
            icon=build.connect()
            try:
                # Purge legacy non-approval documents from the candidate before
                # processing the actual approval change set. They never enter the
                # progress count and are never extracted/OCR'd.
                for rec in legacy_nonapproval:
                    did=int(rec.get("approval_id") or 0)
                    if did:
                        icon.execute("DELETE FROM documents_fts WHERE rowid=?",(did,))
                        icon.execute("DELETE FROM pages WHERE document_id=?",(did,))
                        icon.execute("DELETE FROM semantic_chunks WHERE document_id=?",(did,))
                        icon.execute("DELETE FROM documents WHERE id=?",(did,))
                if legacy_nonapproval:
                    icon.commit()

                for pos,ch in enumerate(changes,1):
                    if cancel_event.is_set():
                        return {"checked":len(changes),"indexed":indexed,"already_current":0,"errors":errors,"native_pages":native_pages,"ocr_pages":ocr_pages,"unreadable_pages":unreadable_pages,"semantic_created":semantic_created,"semantic_skipped":semantic_skipped,"stopped":True,"total":total,"published":False,"verified":False,"incremental":True,"changed_count":len(changes)}
                    name=ch["name"]; kind=ch["kind"]
                    row=mrows.get(name)
                    filename=(str(row.get("original_filename") or "") if row else name)
                    if progress: progress(pos,len(changes),filename)
                    if log: log(f"[{pos}/{len(changes)}] {kind}: {filename}")
                    if kind=="deleted":
                        did=int(ch.get("approval_id") or 0)
                        if did<=0:
                            rr=icon.execute("SELECT id FROM documents WHERE lower(file_name)=lower(?) LIMIT 1",(filename,)).fetchone()
                            did=int(rr[0]) if rr else 0
                        if did:
                            icon.execute("DELETE FROM documents_fts WHERE rowid=?",(did,))
                            icon.execute("DELETE FROM pages WHERE document_id=?",(did,))
                            icon.execute("DELETE FROM semantic_chunks WHERE document_id=?",(did,))
                            icon.execute("DELETE FROM documents WHERE id=?",(did,))
                        indexed += 1
                        continue

                    aid=int(row.get("approval_id") or 0)
                    blob=bytes(row.get("pdf_blob") or b"")
                    pdf_hash=str(row.get("pdf_hash") or "").strip().lower() or (hashlib.sha256(blob).hexdigest() if blob else "")
                    if kind=="metadata_changed":
                        ir=icon.execute("SELECT full_text,page_count,file_size FROM documents WHERE id=?",(aid,)).fetchone()
                        if not ir:
                            kind="pdf_changed"
                        else:
                            full_text=str(ir[0] or "")
                            page_count=int(ir[1] or 0)
                            size=int(ir[2] or len(blob))
                            mm=re.search(r"\d+",self._approval_number_from_filename(filename))
                            numeric=int(mm.group()) if mm else int(row.get("a_approval_number_numeric") or 0)
                            def av(n): return "" if row.get("a_"+n) is None else str(row.get("a_"+n))
                            vals=(self._approval_number_from_filename(filename) or av("approval_number"),numeric,av("approval_code"),av("approval_date"),av("approval_date_sort") or parse_date(av("approval_date")),av("file_number"),av("memo_number"),av("subject"),datetime.now().isoformat(timespec="seconds"))
                            icon.execute("UPDATE documents SET file_path=?,file_name=?,file_hash=?,file_size=?,modified_time=?,page_count=?,approval_number=?,approval_number_numeric=?,approval_code=?,approval_date=?,approval_date_sort=?,file_number=?,memo_number=?,subject=?,indexed_at=? WHERE id=?", (f"MASTER:{aid}",filename,pdf_hash,size,0.0,page_count,vals[0],vals[1],vals[2],vals[3],vals[4],vals[5],vals[6],vals[7],vals[8],aid))
                            icon.execute("DELETE FROM documents_fts WHERE rowid=?",(aid,))
                            icon.execute("INSERT INTO documents_fts(rowid,full_text,file_name,approval_number,approval_code,subject) VALUES(?,?,?,?,?,?)",(aid,full_text,filename,vals[0],vals[2],vals[7]))
                            indexed += 1
                            continue

                    if not blob:
                        raise RuntimeError("MASTER pdf_blob is empty")
                    pages,full_text,info=extract_pdf_bytes(blob,logger=log)
                    native_pages += int(info.get("native_pages",0) or 0); ocr_pages += int(info.get("ocr_pages",0) or 0); unreadable_pages += int(info.get("failed_pages",0) or 0)
                    if len(normalize_spaces(full_text))<10: full_text="[SCANNED / IMAGE-ONLY PDF - OCR TEXT NOT AVAILABLE]"
                    semantic_chunks=[]
                    if ensure_semantic_available() and len(normalize_spaces(full_text))>=30 and "OCR TEXT NOT AVAILABLE" not in full_text:
                        try: semantic_chunks=embed_chunks(pages); semantic_created += 1
                        except Exception as exc:
                            semantic_skipped += 1
                            if log: log(f"    Semantic indexing skipped: {exc}")
                    mm=re.search(r"\d+",self._approval_number_from_filename(filename)); numeric=int(mm.group()) if mm else int(row.get("a_approval_number_numeric") or 0)
                    def av(n): return "" if row.get("a_"+n) is None else str(row.get("a_"+n))
                    approval_num=self._approval_number_from_filename(filename) or av("approval_number")
                    vals=(approval_num,numeric,av("approval_code"),av("approval_date"),av("approval_date_sort") or parse_date(av("approval_date")),av("file_number"),av("memo_number"),av("subject"),datetime.now().isoformat(timespec="seconds"))
                    existing=icon.execute("SELECT id FROM documents WHERE id=?",(aid,)).fetchone()
                    if existing:
                        icon.execute("UPDATE documents SET file_path=?,file_name=?,file_hash=?,file_size=?,modified_time=?,page_count=?,approval_number=?,approval_number_numeric=?,approval_code=?,approval_date=?,approval_date_sort=?,file_number=?,memo_number=?,subject=?,full_text=?,indexed_at=? WHERE id=?",(f"MASTER:{aid}",filename,pdf_hash,len(blob),0.0,len(pages),*vals,full_text,aid))
                    else:
                        icon.execute("INSERT INTO documents(id,file_path,file_name,file_hash,file_size,modified_time,page_count,approval_number,approval_number_numeric,approval_code,approval_date,approval_date_sort,file_number,memo_number,subject,full_text,indexed_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",(aid,f"MASTER:{aid}",filename,pdf_hash,len(blob),0.0,len(pages),vals[0],vals[1],vals[2],vals[3],vals[4],vals[5],vals[6],vals[7],full_text,vals[8]))
                    icon.execute("DELETE FROM pages WHERE document_id=?",(aid,)); icon.execute("DELETE FROM documents_fts WHERE rowid=?",(aid,)); icon.execute("DELETE FROM semantic_chunks WHERE document_id=?",(aid,))
                    icon.execute("INSERT INTO documents_fts(rowid,full_text,file_name,approval_number,approval_code,subject) VALUES(?,?,?,?,?,?)",(aid,full_text,filename,approval_num,av("approval_code"),av("subject")))
                    if pages: icon.executemany("INSERT INTO pages(document_id,page_number,page_text) VALUES(?,?,?)",[(aid,n,t) for n,t in pages])
                    if semantic_chunks:
                        icon.executemany("INSERT INTO semantic_chunks(document_id,page_number,chunk_text,embedding,embedding_dim) VALUES(?,?,?,?,?)",[(aid,pg,txt,emb.tobytes(),int(len(emb))) for pg,txt,emb in semantic_chunks])
                    indexed += 1
                    if log: log(f"    Indexed successfully: {filename}")
                icon.commit()
            finally:
                icon.close()

            if cancel_event.is_set():
                return {"checked":len(changes),"indexed":indexed,"already_current":0,"errors":errors,"native_pages":native_pages,"ocr_pages":ocr_pages,"unreadable_pages":unreadable_pages,"semantic_created":semantic_created,"semantic_skipped":semantic_skipped,"stopped":True,"total":total,"published":False,"verified":False,"incremental":True,"changed_count":len(changes)}
            reason=self._publish_index_candidate(candidate,total,log=log)
            published=True
            if log: log(f"INCREMENTAL INDEX PUBLISHED: {indexed:,} changed approval(s) processed; {total-indexed:,} unchanged approval(s) copied forward.")
            return {"checked":len(changes),"indexed":indexed,"already_current":max(0,total-indexed),"errors":errors,"native_pages":native_pages,"ocr_pages":ocr_pages,"unreadable_pages":unreadable_pages,"semantic_created":semantic_created,"semantic_skipped":semantic_skipped,"stopped":False,"total":total,"published":published,"verified":True,"validation_error":"","incremental":True,"changed_count":len(changes)}
        except Exception as exc:
            errors += 1
            if log: log(f"INCREMENTAL INDEX ERROR: {exc}")
            return {"checked":len(changes),"indexed":indexed,"already_current":max(0,total-indexed),"errors":errors,"native_pages":native_pages,"ocr_pages":ocr_pages,"unreadable_pages":unreadable_pages,"semantic_created":semantic_created,"semantic_skipped":semantic_skipped,"stopped":False,"total":total,"published":False,"verified":False,"validation_error":str(exc),"incremental":True,"changed_count":len(changes)}
        finally:
            if not published:
                for suffix in ("","-wal","-shm","-journal"):
                    try:
                        q=Path(str(candidate)+suffix)
                        if q.exists(): q.unlink()
                    except Exception: pass

    def validate_index_file_against_master(self, index_path=None):
        """Strictly validate an index before it can become the live index.

        The live index is considered READY only when:
          * SQLite integrity is OK;
          * required schema/FTS exists;
          * document IDs, filenames and hashes exactly match MASTER's
            embedded approval PDFs;
          * document and FTS counts agree;
          * there are no duplicate document IDs or filenames.
        """
        index_path = Path(index_path or self.index_path)
        if not index_path.exists():
            return False, "index database file does not exist"

        try:
            icon = sqlite3.connect(str(index_path), timeout=60)
            icon.row_factory = sqlite3.Row
            icon.execute("PRAGMA busy_timeout=60000")
            integrity = str(icon.execute("PRAGMA integrity_check").fetchone()[0]).strip().lower()
            if integrity != "ok":
                icon.close()
                return False, f"SQLite integrity_check failed: {integrity}"

            tables = {str(r[0]) for r in icon.execute(
                "SELECT name FROM sqlite_master WHERE type IN ('table','view')"
            ).fetchall()}
            required = {"documents", "documents_fts", "pages"}
            if not required.issubset(tables):
                missing = ", ".join(sorted(required - tables))
                icon.close()
                return False, f"required index tables missing: {missing}"

            cols = {r[1] for r in icon.execute("PRAGMA table_info(documents)").fetchall()}
            required_cols = {
                "id", "file_path", "file_name", "file_hash", "file_size",
                "page_count", "approval_number", "approval_number_numeric",
                "approval_code", "approval_date", "approval_date_sort",
                "file_number", "memo_number", "subject", "full_text", "indexed_at"
            }
            if not required_cols.issubset(cols):
                missing = ", ".join(sorted(required_cols - cols))
                icon.close()
                return False, f"documents schema incomplete: {missing}"

            idx_rows = icon.execute(
                "SELECT id,file_name,file_hash FROM documents ORDER BY id"
            ).fetchall()
            fts_count = int(icon.execute("SELECT COUNT(*) FROM documents_fts").fetchone()[0])
            doc_count = len(idx_rows)

            # FTS5 has its own integrity checker.  Count equality alone can
            # miss a stale/misaligned FTS row set after an interrupted build.
            try:
                icon.execute("INSERT INTO documents_fts(documents_fts) VALUES('integrity-check')")
            except Exception as exc:
                icon.close()
                return False, f"FTS integrity check failed: {exc}"

            missing_fts_rows = int(icon.execute(
                "SELECT COUNT(*) FROM documents d LEFT JOIN documents_fts f ON f.rowid=d.id WHERE f.rowid IS NULL"
            ).fetchone()[0])
            if missing_fts_rows:
                icon.close()
                return False, f"FTS row coverage mismatch: {missing_fts_rows} document(s) have no FTS row"

            bad_page_refs = int(icon.execute(
                "SELECT COUNT(*) FROM pages p LEFT JOIN documents d ON d.id=p.document_id WHERE d.id IS NULL"
            ).fetchone()[0])
            if bad_page_refs:
                icon.close()
                return False, f"orphan page references detected: {bad_page_refs}"

            # Duplicate identity checks.
            if int(icon.execute(
                "SELECT COUNT(*) - COUNT(DISTINCT id) FROM documents"
            ).fetchone()[0]) != 0:
                icon.close()
                return False, "duplicate document IDs detected"
            if int(icon.execute(
                "SELECT COUNT(*) - COUNT(DISTINCT lower(file_name)) FROM documents"
            ).fetchone()[0]) != 0:
                icon.close()
                return False, "duplicate filenames detected"

            icon.close()

            mcon = self._master_connect(readonly=True)
            pcols = {r[1] for r in mcon.execute("PRAGMA table_info(pdf_documents)").fetchall()}
            hcol = "sha256" if "sha256" in pcols else ("pdf_sha256" if "pdf_sha256" in pcols else None)
            hash_expr = f"COALESCE(p.{hcol}, '')" if hcol else "''"
            master_rows = mcon.execute(
                "SELECT p.approval_id, p.original_filename, "
                f"{hash_expr} AS pdf_hash, length(COALESCE(p.pdf_blob,X'')) AS pdf_size "
                "FROM pdf_documents p "
                "WHERE length(COALESCE(p.pdf_blob,X'')) > 0 "
                "ORDER BY p.rowid"
            ).fetchall()
            mcon.close()

            master = {}
            master_ids = set()
            for r in master_rows:
                name = str(r["original_filename"] or "").casefold()
                if not name:
                    return False, "MASTER contains a blank PDF filename"
                if name in master:
                    return False, f"duplicate MASTER filename: {r['original_filename']}"
                aid = int(r["approval_id"])
                if aid in master_ids:
                    return False, f"duplicate MASTER approval_id: {aid}"
                master_ids.add(aid)
                master[name] = (aid, str(r["pdf_hash"] or "").lower(), int(r["pdf_size"] or 0))

            if doc_count != len(master):
                return False, f"document count mismatch: MASTER={len(master)} INDEX={doc_count}"
            if fts_count != doc_count:
                return False, f"FTS count mismatch: documents={doc_count} FTS={fts_count}"

            idx = {}
            for r in idx_rows:
                name = str(r["file_name"] or "").casefold()
                if name in idx:
                    return False, f"duplicate index filename: {r['file_name']}"
                idx[name] = (int(r["id"]), str(r["file_hash"] or "").lower())

            if set(master) != set(idx):
                missing = sorted(set(master) - set(idx))
                extra = sorted(set(idx) - set(master))
                return False, (
                    f"filename set mismatch: missing={len(missing)} extra={len(extra)}"
                )

            if {v[0] for v in master.values()} != {v[0] for v in idx.values()}:
                return False, "approval ID set mismatch"

            for name, (aid, mh, msize) in master.items():
                iid, ih = idx[name]
                if aid != iid:
                    return False, f"approval ID mismatch for {name}: MASTER={aid} INDEX={iid}"
                if mh and ih and mh != ih:
                    return False, f"PDF hash mismatch for {name}"

            return True, f"verified {doc_count:,} approval PDFs; FTS={fts_count:,}; SQLite integrity=OK"

        except Exception as exc:
            try:
                icon.close()
            except Exception:
                pass
            return False, str(exc)

    def master_index_validation_status(self):
        """Return (ok, reason) for the persistent runtime index state."""
        if not self.master_mode:
            return False, "MASTER-only mode is not active"
        return self.validate_index_file_against_master(self.index.path)

    def _master_verification_fingerprint(self):
        """Stable logical fingerprint of MASTER's embedded approval PDFs."""
        con = self._master_connect(readonly=True)
        try:
            pcols = {r[1] for r in con.execute("PRAGMA table_info(pdf_documents)").fetchall()}
            hcol = "sha256" if "sha256" in pcols else ("pdf_sha256" if "pdf_sha256" in pcols else None)
            hash_expr = f"COALESCE(p.{hcol}, '')" if hcol else "''"
            rows = con.execute(
                "SELECT p.approval_id, p.original_filename, "
                f"{hash_expr} AS pdf_hash, length(COALESCE(p.pdf_blob,X'')) AS pdf_size "
                "FROM pdf_documents p "
                "WHERE length(COALESCE(p.pdf_blob,X'')) > 0 "
                "ORDER BY p.approval_id, lower(p.original_filename), p.rowid"
            ).fetchall()
        finally:
            con.close()
        h = hashlib.sha256()
        for r in rows:
            h.update((f"{int(r[0])}\x1f{str(r[1] or '').casefold()}\x1f"
                      f"{str(r[2] or '').lower()}\x1f{int(r[3] or 0)}\n").encode("utf-8"))
        return h.hexdigest(), len(rows)

    def _index_verification_fingerprint(self, index_path=None):
        """Stable logical fingerprint of indexed documents + searchable FTS rows."""
        path = str(index_path or self.index.path)
        con = sqlite3.connect(path, timeout=60)
        try:
            rows = con.execute(
                "SELECT id,file_name,file_hash,file_size,approval_number,approval_number_numeric,"
                "approval_code,approval_date,approval_date_sort,file_number,memo_number,subject,"
                "length(COALESCE(full_text,'')), hex(sha256_text) FROM ("
                "SELECT id,file_name,file_hash,file_size,approval_number,approval_number_numeric,"
                "approval_code,approval_date,approval_date_sort,file_number,memo_number,subject,"
                "full_text, NULL AS sha256_text FROM documents) ORDER BY id"
            ).fetchall()
        except Exception:
            # SQLite builds normally do not expose sha256().  Keep the
            # fingerprint deterministic without relying on optional extensions.
            rows = con.execute(
                "SELECT id,file_name,file_hash,file_size,approval_number,approval_number_numeric,"
                "approval_code,approval_date,approval_date_sort,file_number,memo_number,subject,"
                "full_text FROM documents ORDER BY id"
            ).fetchall()
        try:
            fts_rows = con.execute(
                "SELECT rowid,full_text,file_name,approval_number,approval_code,subject "
                "FROM documents_fts ORDER BY rowid"
            ).fetchall()
        finally:
            con.close()
        h = hashlib.sha256()
        for r in rows:
            vals = list(r)
            if len(vals) >= 13:
                vals[12] = hashlib.sha256(str(vals[12] or '').encode('utf-8')).hexdigest()
            h.update(("\x1f".join(str(v if v is not None else '') for v in vals) + "\n").encode('utf-8'))
        h.update(b"--FTS--\n")
        for r in fts_rows:
            h.update(("\x1f".join(str(v if v is not None else '') for v in r) + "\n").encode('utf-8'))
        return h.hexdigest(), len(rows), len(fts_rows)

    def write_index_verification_marker(self, index_path=None):
        """Write a persistent V21 marker only after a verified index exists."""
        path = str(index_path or self.index.path)
        master_fp, master_count = self._master_verification_fingerprint()
        index_fp, index_count, fts_count = self._index_verification_fingerprint(path)
        if master_count != index_count or index_count != fts_count:
            raise RuntimeError(
                f"Cannot mark index verified: MASTER={master_count} INDEX={index_count} FTS={fts_count}"
            )
        con = sqlite3.connect(path, timeout=60)
        try:
            con.execute(
                "INSERT INTO index_verification(id,verification_version,master_fingerprint,index_fingerprint,document_count,verified_at) "
                "VALUES(1,1,?,?,?,?) "
                "ON CONFLICT(id) DO UPDATE SET verification_version=excluded.verification_version, "
                "master_fingerprint=excluded.master_fingerprint,index_fingerprint=excluded.index_fingerprint, "
                "document_count=excluded.document_count,verified_at=excluded.verified_at",
                (master_fp, index_fp, index_count, datetime.now().isoformat(timespec='seconds'))
            )
            con.commit()
        finally:
            con.close()

    def _persistent_index_marker_is_current(self):
        """Fast restart check using the marker embedded in index.db."""
        try:
            path = Path(self.index.path)
            if not path.exists():
                return False, "index database file does not exist"
            con = sqlite3.connect(str(path), timeout=60)
            try:
                con.execute("PRAGMA busy_timeout=60000")
                integrity = str(con.execute("PRAGMA integrity_check").fetchone()[0]).strip().lower()
                if integrity != 'ok':
                    return False, f"SQLite integrity_check failed: {integrity}"
                row = con.execute(
                    "SELECT verification_version,master_fingerprint,index_fingerprint,document_count FROM index_verification WHERE id=1"
                ).fetchone()
                if not row:
                    return False, "no persistent V21 verification marker"
                doc_count = int(con.execute("SELECT COUNT(*) FROM documents").fetchone()[0])
                fts_count = int(con.execute("SELECT COUNT(*) FROM documents_fts").fetchone()[0])
                missing_fts = int(con.execute(
                    "SELECT COUNT(*) FROM documents d LEFT JOIN documents_fts f ON f.rowid=d.id WHERE f.rowid IS NULL"
                ).fetchone()[0])
                if doc_count != int(row[3]) or fts_count != doc_count or missing_fts:
                    return False, f"persistent marker count/FTS mismatch: marker={row[3]} index={doc_count} fts={fts_count} missing_fts={missing_fts}"
            finally:
                con.close()

            master_fp, master_count = self._master_verification_fingerprint()
            index_fp, index_count, fts_count = self._index_verification_fingerprint(path)
            if master_count != int(row[3]):
                return False, f"MASTER approval count changed: marker={row[3]} current={master_count}"
            if master_fp != str(row[1]):
                return False, "MASTER PDF fingerprint changed"
            if index_count != int(row[3]) or fts_count != index_count:
                return False, f"index fingerprint count mismatch: INDEX={index_count} FTS={fts_count}"
            if index_fp != str(row[2]):
                return False, "index logical fingerprint changed"
            return True, f"persistent V21 marker verified: {index_count:,} PDFs"
        except Exception as exc:
            return False, f"persistent marker check failed: {exc}"

    def _write_verified_state(self):
        """Persist a small durable TRUSTED verification record for restart.

        V28 strategy change: the restart gate is based on the authoritative
        MASTER logical fingerprint + count and basic SQLite usability.  It does
        NOT compare the complete index logical fingerprint, raw SQLite bytes,
        encrypted bytes, PDF hashes, filenames, IDs or file sizes on restart.
        Those forensic checks are appropriate for a newly-built candidate, but
        they are too strict for a restart gate and can cause false rebuilds.
        """
        if not INDEX_STORAGE_PATH.exists() or not MASTER_STORAGE_PATH.exists():
            return
        try:
            master_fp, master_count = self._master_verification_fingerprint()
            # Only capture lightweight index facts needed for diagnostics.
            con = sqlite3.connect(str(self.index.path), timeout=60)
            try:
                con.execute("PRAGMA busy_timeout=60000")
                index_count = int(con.execute("SELECT COUNT(*) FROM documents").fetchone()[0])
                fts_count = int(con.execute("SELECT COUNT(*) FROM documents_fts").fetchone()[0])
            finally:
                con.close()
            state = {
                "state_version": 28,
                "master_fingerprint": master_fp,
                "master_count": int(master_count),
                "verified_document_count": int(index_count),
                "verified_fts_count": int(fts_count),
                "verified_at": datetime.now().isoformat(timespec="seconds"),
                "gate_policy": "TRUST_MASTER_FINGERPRINT_PLUS_SQLITE_INTEGRITY",
            }
            tmp = INDEX_VERIFIED_STATE_PATH.with_suffix(".json.tmp")
            tmp.write_text(json.dumps(state, indent=2), encoding="utf-8")
            os.replace(tmp, INDEX_VERIFIED_STATE_PATH)
        except Exception as exc:
            raise RuntimeError(f"could not write V28 trusted verified-state: {exc}")

    def _verified_state_matches_files(self):
        """V28 compatibility helper: validate only the authoritative MASTER state.

        This intentionally does not compare the index logical fingerprint.
        """
        try:
            if not INDEX_VERIFIED_STATE_PATH.exists():
                return False, "no persistent V28 verified-state record"
            state = json.loads(INDEX_VERIFIED_STATE_PATH.read_text(encoding="utf-8"))
            if int(state.get("state_version", 0)) != 28:
                return False, "verified-state record is from an older build"
            master_fp, master_count = self._master_verification_fingerprint()
            if master_fp != str(state.get("master_fingerprint", "")):
                return False, "MASTER logical fingerprint changed"
            if int(master_count) != int(state.get("master_count", -1)):
                return False, "MASTER PDF count changed"
            return True, "V28 trusted MASTER state unchanged"
        except Exception as exc:
            return False, f"trusted-state check failed: {exc}"

    def validate_index_startup_trusted(self, index_path=None):
        """V34 startup gate: exact persistent MASTER/index SHA-256 only."""
        return v34_registry_index_gate()

    def validate_index_startup_soft(self, index_path=None):
        return self.validate_index_startup_trusted(index_path)

    def master_index_current_status(self):
        """V34: only frozen persistent-file SHA values decide whether to rebuild."""
        try:
            ok, reason = v34_registry_index_gate()
        except Exception as exc:
            return False, f"V34 registry gate exception: {exc}"
        if ok:
            return True, reason

        # Existing installations may already have a good index but no V34
        # registry record.  Bootstrap the registry without rebuilding PDFs.
        if reason == "V34 registry record is missing or invalid":
            try:
                con = sqlite3.connect(str(self.index.path), timeout=30)
                con.execute("PRAGMA busy_timeout=30000")
                integrity = str(con.execute("PRAGMA integrity_check").fetchone()[0]).strip().lower()
                count = int(con.execute("SELECT COUNT(*) FROM documents").fetchone()[0])
                con.close()
                if integrity == "ok":
                    msha = _persistent_file_sha256(MASTER_STORAGE_PATH)
                    isha = _persistent_file_sha256(INDEX_STORAGE_PATH)
                    _write_v34_registry_state(msha, isha, count)
                    return True, f"V34 registry bootstrapped from existing index ({count:,} PDFs) — NO REINDEX"
            except Exception as exc:
                return False, f"V34 registry bootstrap failed: {exc}"

        return False, f"V34 registry gate FAILED — {reason}"

    def master_index_is_current(self):
        ok, _reason = self.master_index_current_status()
        return bool(ok)

    def developer_stats(self):
        icon = self.index.connect()
        try:
            indexed = int(icon.execute("SELECT COUNT(*) FROM documents").fetchone()[0])
            indexed_names = {str(r[0]).casefold() for r in icon.execute("SELECT file_name FROM documents").fetchall()}
        finally:
            icon.close()
        con = self._master_connect(readonly=True)
        try:
            master_names = {str(r[0]).casefold() for r in con.execute("SELECT original_filename FROM pdf_documents").fetchall()}
            max_r = con.execute("SELECT MAX(approval_number_numeric) FROM approvals").fetchone()[0] or 0
        finally:
            con.close()
        return {"master": len(master_names), "indexed": indexed, "missing_index": len(master_names-indexed_names),
                "missing_master": len(indexed_names-master_names), "max_rno": max_r}

    # Local per-PC user data -------------------------------------------------
    def add_search_history(self, query):
        query=normalize_spaces(query or "")
        if not query: return
        con=self._user_connect()
        try:
            con.execute("INSERT INTO search_history(query,searched_at,use_count) VALUES (?,?,1) ON CONFLICT(query) DO UPDATE SET searched_at=excluded.searched_at,use_count=use_count+1", (query,datetime.now().isoformat(timespec="seconds")))
            con.commit()
        finally: con.close()
    def get_search_history(self, limit=30):
        con=self._user_connect()
        try: return [dict(r) for r in con.execute("SELECT query,searched_at,use_count FROM search_history ORDER BY searched_at DESC LIMIT ?",(int(limit),)).fetchall()]
        finally: con.close()
    def clear_search_history(self):
        con=self._user_connect();
        try: con.execute("DELETE FROM search_history"); con.commit()
        finally: con.close()
    def is_favorite(self, document_id):
        con=self._user_connect()
        try: return bool(con.execute("SELECT 1 FROM favorites WHERE document_id=?",(int(document_id),)).fetchone())
        finally: con.close()
    def set_favorite(self, document_id, enabled):
        con=self._user_connect()
        try:
            if enabled: con.execute("INSERT OR IGNORE INTO favorites(document_id,created_at) VALUES (?,?)",(int(document_id),datetime.now().isoformat(timespec="seconds")))
            else: con.execute("DELETE FROM favorites WHERE document_id=?",(int(document_id),))
            con.commit()
        finally: con.close()
    def favorite_documents(self):
        con=self._user_connect()
        try: ids=[r[0] for r in con.execute("SELECT document_id FROM favorites ORDER BY created_at DESC").fetchall()]
        finally: con.close()
        if not ids: return []
        idx_con=self.index.connect()
        try:
            marks=','.join('?' for _ in ids); rows=idx_con.execute(f"SELECT * FROM documents WHERE id IN ({marks})",ids).fetchall()
        finally: idx_con.close()
        order={v:i for i,v in enumerate(ids)}; out=self._merge_rows(rows); out.sort(key=lambda r:order.get(r['id'],999999)); return out
    def get_note(self, document_id):
        con=self._user_connect()
        try:
            r=con.execute("SELECT note FROM document_notes WHERE document_id=?",(int(document_id),)).fetchone(); return r['note'] if r else ''
        finally: con.close()
    def save_note(self, document_id, note):
        note=(note or '').strip(); con=self._user_connect()
        try:
            if note: con.execute("INSERT INTO document_notes(document_id,note,updated_at) VALUES (?,?,?) ON CONFLICT(document_id) DO UPDATE SET note=excluded.note,updated_at=excluded.updated_at",(int(document_id),note,datetime.now().isoformat(timespec='seconds')))
            else: con.execute("DELETE FROM document_notes WHERE document_id=?",(int(document_id),))
            con.commit()
        finally: con.close()
    def document_note_ids(self, document_ids):
        ids=[int(x) for x in document_ids if x is not None]
        if not ids:return set()
        con=self._user_connect()
        try:
            marks=','.join('?' for _ in ids); rows=con.execute(f"SELECT document_id FROM document_notes WHERE document_id IN ({marks}) AND TRIM(note)<>''",ids).fetchall(); return {int(r['document_id']) for r in rows}
        finally: con.close()
    def noted_documents(self):
        con=self._user_connect()
        try: notes={int(r['document_id']):(r['note'],r['updated_at']) for r in con.execute("SELECT document_id,note,updated_at FROM document_notes WHERE TRIM(note)<>'' ORDER BY updated_at DESC").fetchall()}
        finally: con.close()
        if not notes:return []
        idx_con=self.index.connect()
        try:
            ids=list(notes); marks=','.join('?' for _ in ids); rows=idx_con.execute(f"SELECT * FROM documents WHERE id IN ({marks})",ids).fetchall()
        finally: idx_con.close()
        out=self._merge_rows(rows)
        for r in out: r['note'],r['note_updated_at']=notes[r['id']]
        out.sort(key=lambda r:notes[r['id']][1],reverse=True); return out

    # Suggestions are intentionally disabled in the GUI, but keep API intact.
    def smart_suggestions(self, prefix, limit=12): return []

    # Developer indexing architecture:
    # MASTER.db and index.db are independent.
    # MASTER.db is append-only during indexing (handled by developer_import_pdf_to_master).
    # index.db may be checked, updated and rebuilt independently.
    def document_is_current(self,*a,**k):
        return self.index.document_is_current(*a,**k)

    def upsert_document(self,*a,**k):
        return self.index.upsert_document(*a,**k)

    def delete_path(self,*a,**k):
        return self.index.delete_path(*a,**k)

    def reset_database_file(self,*a,**k):
        return self.index.reset_database_file(*a,**k)



# ============================================================
# SEMANTIC SEARCH
# ============================================================

_semantic_model = None

def get_semantic_model():
    global _semantic_model
    if not ensure_semantic_available():
        return None
    if _semantic_model is None:
        # Small, fast local model. Downloads automatically on first use.
        _semantic_model = SentenceTransformer("all-MiniLM-L6-v2")
    return _semantic_model

def make_semantic_chunks(pages, chunk_words=220, overlap_words=45):
    chunks = []
    for page_no, text in pages:
        words = normalize_spaces(text).split()
        if not words:
            continue
        step = max(1, chunk_words - overlap_words)
        for start in range(0, len(words), step):
            chunk = " ".join(words[start:start + chunk_words])
            if len(chunk) >= 30:
                chunks.append((page_no, chunk))
            if start + chunk_words >= len(words):
                break
    return chunks

def embed_chunks(pages):
    model = get_semantic_model()
    if model is None:
        return []
    raw = make_semantic_chunks(pages)
    if not raw:
        return []
    texts = [x[1] for x in raw]
    vectors = model.encode(texts, normalize_embeddings=True, show_progress_bar=False)
    return [(raw[i][0], raw[i][1], np.asarray(vectors[i], dtype=np.float32)) for i in range(len(raw))]

# ============================================================
# OCR DIAGNOSTICS
# ============================================================

def ocr_status_message():
    ready, message = configure_tesseract()
    return message



def normalize_spaces(text):
    """Normalize extracted/OCR text without losing searchable words."""
    if text is None:
        return ""
    text = str(text).replace("\x00", " ")
    text = re.sub(r"[\t\r\f\v]+", " ", text)
    text = re.sub(r"[ ]{2,}", " ", text)
    text = re.sub(r"\n[ ]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()

def sha256_file(path, chunk_size=1024 * 1024):
    """Return a SHA-256 digest without loading the whole PDF into memory."""
    digest = hashlib.sha256()
    with open(path, "rb") as fh:
        while True:
            chunk = fh.read(chunk_size)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()



# ============================================================
# PDF EXTRACTION / OCR
# ============================================================

def preprocess_for_ocr(image):
    """Improve typical low-quality HVPNL approval scans before OCR."""
    gray = ImageOps.grayscale(image)
    gray = ImageOps.autocontrast(gray, cutoff=1)
    gray = ImageEnhance.Contrast(gray).enhance(2.0)
    gray = ImageEnhance.Sharpness(gray).enhance(1.5)

    # Light median filtering reduces scanner specks without destroying letters.
    gray = gray.filter(ImageFilter.MedianFilter(size=3))

    # Upscale very small pages/images before Tesseract.
    if gray.width < 1800:
        scale = 1800 / max(1, gray.width)
        gray = gray.resize(
            (int(gray.width * scale), int(gray.height * scale)),
            Image.Resampling.LANCZOS,
        )

    return gray


def run_tesseract_best(image):
    """Try more than one page segmentation mode and retain the best result."""
    candidates = []
    last_error = None

    for config in ("--oem 3 --psm 6", "--oem 3 --psm 3", "--oem 3 --psm 11"):
        try:
            text = pytesseract.image_to_string(image, config=config) or ""
            text = normalize_spaces(text)
            candidates.append(text)
        except Exception as e:
            last_error = e

    if not candidates:
        if last_error:
            raise RuntimeError(str(last_error))
        return ""

    # Longer output is normally preferable for these full-page official scans.
    return max(candidates, key=len)


def ocr_single_page(page, dpi=300):
    """Render one PDF page with PyMuPDF and OCR it using Tesseract."""
    zoom = max(1.0, dpi / 72.0)
    pix = page.get_pixmap(
        matrix=fitz.Matrix(zoom, zoom),
        colorspace=fitz.csRGB,
        alpha=False,
    )
    image = Image.frombytes(
        "RGB",
        [pix.width, pix.height],
        pix.samples,
    )
    prepared = preprocess_for_ocr(image)
    return run_tesseract_best(prepared)


def extract_pdf_bytes(pdf_bytes, logger=None):
    """Extract searchable text from an embedded PDF BLOB.

    Reference documents are stored inside MASTER.db, so they cannot rely on
    the original source filename/path. Native PDF text is used where useful;
    scanned/image pages are OCR'd with the same OCR pipeline used by the main
    approval indexer.
    """
    ready, ocr_message = configure_tesseract()
    pages = []
    native_count = 0
    ocr_count = 0
    failed_ocr_pages = 0
    errors = []
    doc = fitz.open(stream=bytes(pdf_bytes or b""), filetype="pdf")
    try:
        total_pages = doc.page_count
        for i, page in enumerate(doc):
            native_text = page.get_text("text") or ""
            clean_native = normalize_spaces(native_text)
            if len(clean_native) >= 20:
                pages.append((i, native_text)); native_count += 1
                continue
            if ready:
                try:
                    if logger:
                        logger(f"    OCR reference page {i + 1}/{total_pages}...")
                    ocr_text = ocr_single_page(page, dpi=300)
                    if len(normalize_spaces(ocr_text)) >= 3:
                        pages.append((i, ocr_text)); ocr_count += 1
                    else:
                        pages.append((i, native_text)); failed_ocr_pages += 1
                except Exception as e:
                    pages.append((i, native_text)); failed_ocr_pages += 1
                    errors.append(f"page {i + 1}: {e}")
            else:
                pages.append((i, native_text)); failed_ocr_pages += 1
    finally:
        doc.close()
    full_text = "\n".join(text for _, text in pages)
    if logger:
        logger(f"    Reference extraction: {native_count} native, {ocr_count} OCR, {failed_ocr_pages} failed page(s).")
        if errors: logger(f"    OCR detail: {errors[0]}")
    return pages, full_text, {
        "native_pages": native_count,
        "ocr_pages": ocr_count,
        "failed_pages": failed_ocr_pages,
        "ocr_ready": ready,
        "ocr_message": ocr_message,
    }

def extract_pdf(path, logger=None):
    """
    Extract native PDF text first. Every page with insufficient native text is
    OCR'd individually. This is important for mixed PDFs containing both
    searchable pages and scanned pages.
    """
    path = Path(path)
    ready, ocr_message = configure_tesseract()

    pages = []
    native_count = 0
    ocr_count = 0
    failed_ocr_pages = 0
    errors = []

    doc = fitz.open(str(path))
    try:
        total_pages = len(doc)

        for i, page in enumerate(doc):
            native_text = page.get_text("text") or ""
            clean_native = normalize_spaces(native_text)

            # Use native text when meaningful; otherwise OCR THIS page.
            if len(clean_native) >= 20:
                pages.append((i, native_text))
                native_count += 1
                continue

            if ready:
                try:
                    if logger:
                        logger(
                            f"    OCR page {i + 1}/{total_pages} "
                            f"(scanned/image page)..."
                        )
                    ocr_text = ocr_single_page(page, dpi=300)
                    if len(normalize_spaces(ocr_text)) >= 3:
                        pages.append((i, ocr_text))
                        ocr_count += 1
                    else:
                        pages.append((i, native_text))
                        failed_ocr_pages += 1
                except Exception as e:
                    pages.append((i, native_text))
                    failed_ocr_pages += 1
                    errors.append(f"page {i + 1}: {e}")
            else:
                pages.append((i, native_text))
                failed_ocr_pages += 1
    finally:
        doc.close()

    full_text = "\n".join(text for _, text in pages)

    if logger:
        logger(
            f"    Text extraction: {native_count} native page(s), "
            f"{ocr_count} OCR page(s), {failed_ocr_pages} unreadable page(s)."
        )
        if ocr_count == 0 and native_count == 0:
            logger(f"    OCR status: {ocr_message}")
        if errors:
            logger(f"    OCR detail: {errors[0]}")

    return pages, full_text, {
        "native_pages": native_count,
        "ocr_pages": ocr_count,
        "failed_pages": failed_ocr_pages,
        "ocr_ready": ready,
        "ocr_message": ocr_message,
    }


def extract_pdf_bytes(pdf_bytes, logger=None):
    """Extract native text/OCR directly from a PDF BLOB stored in MASTER.db.

    This is the core of the MASTER-only architecture: no approval PDF is read
    from the documents folder.  The BLOB is opened directly by PyMuPDF.
    """
    ready, ocr_message = configure_tesseract()
    pages = []
    native_count = 0
    ocr_count = 0
    failed_ocr_pages = 0
    errors = []
    doc = fitz.open(stream=bytes(pdf_bytes or b""), filetype="pdf")
    try:
        total_pages = len(doc)
        for i, page in enumerate(doc):
            native_text = page.get_text("text") or ""
            clean_native = normalize_spaces(native_text)
            if len(clean_native) >= 20:
                pages.append((i, native_text))
                native_count += 1
                continue
            if ready:
                try:
                    if logger:
                        logger(f"    OCR page {i + 1}/{total_pages} (scanned/image page)...")
                    ocr_text = ocr_single_page(page, dpi=300)
                    if len(normalize_spaces(ocr_text)) >= 3:
                        pages.append((i, ocr_text))
                        ocr_count += 1
                    else:
                        pages.append((i, native_text))
                        failed_ocr_pages += 1
                except Exception as e:
                    pages.append((i, native_text))
                    failed_ocr_pages += 1
                    errors.append(f"page {i + 1}: {e}")
            else:
                pages.append((i, native_text))
                failed_ocr_pages += 1
    finally:
        doc.close()
    full_text = "\n".join(text for _, text in pages)
    if logger:
        logger(f"    Text extraction: {native_count} native page(s), {ocr_count} OCR page(s), {failed_ocr_pages} unreadable page(s).")
        if errors:
            logger(f"    OCR detail: {errors[0]}")
    return pages, full_text, {
        "native_pages": native_count,
        "ocr_pages": ocr_count,
        "failed_pages": failed_ocr_pages,
        "ocr_ready": ready,
        "ocr_message": ocr_message,
    }

def first_match(patterns, text, flags=re.I | re.S):
    for p in patterns:
        m = re.search(p, text, flags)
        if m:
            return normalize_spaces(m.group(1))
    return ""



def parse_date(value):
    """Return YYYYMMDD for sorting; blank/invalid values sort safely."""
    if not value:
        return ""

    raw = normalize_spaces(value)
    raw = raw.replace(".", "/").replace("-", "/")

    for fmt in ("%d/%m/%Y", "%d/%m/%y", "%Y/%m/%d"):
        try:
            return datetime.strptime(raw, fmt).strftime("%Y%m%d")
        except ValueError:
            pass

    m = re.search(r"(\d{1,4})/(\d{1,2})/(\d{1,4})", raw)
    if not m:
        return ""

    a, b, c = m.groups()
    try:
        if len(a) == 4:
            return datetime(int(a), int(b), int(c)).strftime("%Y%m%d")
        year = int(c)
        if year < 100:
            year += 2000
        return datetime(year, int(b), int(a)).strftime("%Y%m%d")
    except ValueError:
        return ""


def normalize_display_date(value):
    """Normalize dates for display/storage as DD.MM.YYYY."""
    raw = normalize_spaces(value or "")
    if not raw:
        return ""
    iso_candidate = raw.replace("T", " ").strip()
    for fmt in (
        "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
        "%Y/%m/%d %H:%M:%S", "%Y/%m/%d %H:%M",
        "%Y-%m-%d", "%Y/%m/%d",
        "%d-%m-%Y", "%d/%m/%Y", "%d.%m.%Y",
        "%d-%m-%y", "%d/%m/%y", "%d.%m.%y",
    ):
        try:
            return datetime.strptime(iso_candidate, fmt).strftime("%d.%m.%Y")
        except ValueError:
            pass
    m = re.search(r"(?<!\d)(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?!\d)", raw)
    if m:
        try:
            return datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))).strftime("%d.%m.%Y")
        except ValueError:
            pass
    m = re.search(r"(?<!\d)(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})(?!\d)", raw)
    if m:
        try:
            yy = int(m.group(3))
            if yy < 100:
                yy += 2000
            return datetime(yy, int(m.group(2)), int(m.group(1))).strftime("%d.%m.%Y")
        except ValueError:
            pass
    return raw


def extract_metadata(text, filename):
    # Approval number: file name is deliberately also considered.
    approval_number = first_match([
        r"\b(?:R\.?\s*No\.?|R\.?\s*No|Approval\s*(?:No\.?|Number)?|Memo\s*No\.?)\s*[:\-]?\s*(\d{2,7})\b",
        r"\bR\s*[-.]?\s*(\d{2,7})\b",
    ], text[:15000])

    if not approval_number:
        m = re.search(r"(\d{2,7})", Path(filename).stem)
        approval_number = m.group(1) if m else ""

    try:
        approval_number_numeric = int(re.search(r"\d+", approval_number).group()) if approval_number else 0
    except Exception:
        approval_number_numeric = 0

    approval_code = first_match([
        r"\b(?:Approval\s*)?(?:Code|R\.?\s*No\.?|Memo\s*No\.?)\s*[:\-]\s*([A-Z0-9][A-Z0-9\/\-. ]{3,80})",
        r"\b([A-Z]{1,5}[-\/][A-Z0-9\/\-.]{2,50})\b",
    ], text[:12000])

    date_value = first_match([
        r"\b(?:Dated|Date)\s*[:.\-]?\s*(\d{1,2}[./\-]\d{1,2}[./\-]\d{2,4})",
        r"\b(\d{1,2}[./\-]\d{1,2}[./\-]20\d{2})\b",
    ], text[:12000])

    file_number = first_match([
        r"\bFile\s*(?:No\.?|Number)?\s*[:\-]?\s*([A-Z0-9\/\-. ]{3,100})",
    ], text[:12000])

    memo_number = first_match([
        r"\bMemo\s*(?:No\.?|Number)?\s*[:\-]?\s*([A-Z0-9\/\-. ]{3,100})",
    ], text[:12000])

    subject = first_match([
        r"\bSubject\s*[:\-]?\s*(.{10,600}?)(?=\s{2,}|\b(?:Ref\.?|Reference|Memo|Date|Dated)\b|$)",
    ], text[:20000])

    date_value = normalize_display_date(date_value)
    return {
        "approval_number": approval_number,
        "approval_number_numeric": approval_number_numeric,
        "approval_code": approval_code,
        "approval_date": date_value,
        "approval_date_sort": parse_date(date_value),
        "file_number": file_number,
        "memo_number": memo_number,
        "subject": subject,
    }

# ============================================================
# SEARCH / SNIPPETS
# ============================================================

def parse_search_shortcuts(query):
    """Extract @ shortcuts from the search box.

    Examples:
      Suzuki @within 1 year
      Suzuki @within 4 years
      Suzuki @within 30 days
      Suzuki @last 12 months
    """
    raw = (query or "").strip()
    filters = {"within_days": None}
    patterns = [
        r"@within\s+(\d+)\s*(year|years|yr|yrs)\b",
        r"@within\s+(\d+)\s*(month|months|mo|mos)\b",
        r"@within\s+(\d+)\s*(day|days|d)\b",
        r"@last\s+(\d+)\s*(year|years|yr|yrs|month|months|mo|mos|day|days|d)\b",
    ]
    def repl(m):
        n = max(1, int(m.group(1)))
        unit = m.group(2).lower()
        if unit.startswith(("year", "yr")):
            days = n * 365
        elif unit.startswith(("month", "mo")):
            days = n * 30
        else:
            days = n
        filters["within_days"] = days if filters["within_days"] is None else min(filters["within_days"], days)
        return " "
    for pattern in patterns:
        raw = re.sub(pattern, repl, raw, flags=re.I)
    return normalize_spaces(raw), filters


def parse_query(query):
    """
    sec 5 gur    -> normal broad AND search
    sec+5+gur    -> close/proximity search
    """
    query, _filters = parse_search_shortcuts(query)
    query = query.strip()
    if not query:
        return [], None, False

    phrases = re.findall(r'"([^"]+)"', query)
    exact_phrase = " ".join(phrases).strip() if phrases else None
    remaining = re.sub(r'"[^"]+"', " ", query).strip()

    close_mode = "+" in remaining
    if close_mode:
        terms = [x.strip() for x in re.split(r"\s*\+\s*", remaining) if x.strip()]
    else:
        terms = [x.strip() for x in re.split(r"\s+", remaining) if x.strip()]

    if not terms and exact_phrase:
        return [], exact_phrase, False
    return terms, exact_phrase, close_mode


def _close_term_pattern(term):
    """Prefix matching for text shorthand; whole-number matching for numbers."""
    term = (term or "").strip()
    if not term:
        return ""
    escaped = re.escape(term)
    if re.fullmatch(r"\d+", term):
        return rf"(?<!\w){escaped}(?!\w)"
    return rf"(?<!\w){escaped}\w*"


def text_has_close_terms(text, terms, max_gap=10):
    """
    Match all + terms in one compact cluster, in ANY order.

    Therefore gur+75a and 75a+gur are symmetric.
    """
    terms = [t.strip() for t in terms if t and t.strip()]
    if not text or not terms:
        return False

    max_gap = max(0, int(max_gap))
    flags = re.I | re.S

    if len(terms) == 1:
        return re.search(_close_term_pattern(terms[0]), text, flags) is not None

    occurrences = []
    for idx, term in enumerate(terms):
        spans = [(m.start(), m.end(), idx)
                 for m in re.finditer(_close_term_pattern(term), text, flags)]
        if not spans:
            return False
        occurrences.append(spans[:250])

    # Two-term search is directly symmetric.
    if len(occurrences) == 2:
        for a_start, a_end, _ in occurrences[0]:
            for b_start, b_end, _ in occurrences[1]:
                if a_end <= b_start:
                    gap = b_start - a_end
                elif b_end <= a_start:
                    gap = a_start - b_end
                else:
                    gap = 0
                if gap <= max_gap:
                    return True
        return False

    # 3+ terms: compact sliding windows + bounded combination test.
    all_hits = sorted(hit for group in occurrences for hit in group)
    counts = [0] * len(terms)
    left = 0
    max_span = sum(max(1, len(t)) for t in terms) + max_gap * (len(terms)-1) + 20

    for right, hit in enumerate(all_hits):
        counts[hit[2]] += 1
        while left <= right and all_hits[right][1] - all_hits[left][0] > max_span:
            counts[all_hits[left][2]] -= 1
            left += 1

        if all(c > 0 for c in counts):
            window = all_hits[left:right+1]
            by_term = [[] for _ in terms]
            for item in window:
                by_term[item[2]].append(item)

            chosen = []
            def pick(i=0):
                if i == len(by_term):
                    ordered = sorted(chosen, key=lambda x: x[0])
                    return all(
                        ordered[j+1][0] - ordered[j][1] <= max_gap
                        for j in range(len(ordered)-1)
                    )
                for item in by_term[i]:
                    chosen.append(item)
                    if pick(i+1):
                        return True
                    chosen.pop()
                return False

            if pick():
                return True

    return False


def word_highlight_html(text, terms, color):
    safe = (text
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;"))
    if not terms:
        return safe
    pattern = "(" + "|".join(re.escape(t) for t in sorted(set(terms), key=len, reverse=True) if t) + ")"
    if pattern == "()":
        return safe
    return re.sub(
        pattern,
        lambda m: f'<span style="background:{color}; color:#111; font-weight:700; padding:1px 2px; border-radius:2px;">{m.group(0)}</span>',
        safe,
        flags=re.I
    )


def snippets_for_document(text, terms, before_words, after_words, max_snippets):
    """
    Produces a snippet around each occurrence. Nearby occurrences are de-duplicated.
    """
    if not text or not terms:
        return []

    words = re.findall(r"\S+", text)
    lower_words = [w.lower() for w in words]
    snippets = []
    used_ranges = []

    for term in terms:
        term_l = term.lower()
        for i, w in enumerate(lower_words):
            clean = re.sub(r"^\W+|\W+$", "", w)
            if term_l in clean or term_l in w:
                start = max(0, i - before_words)
                end = min(len(words), i + after_words + 1)

                # avoid almost identical snippets
                if any(not (end < a or start > b) for a, b in used_ranges):
                    continue

                snippet = " ".join(words[start:end])
                if start > 0:
                    snippet = "... " + snippet
                if end < len(words):
                    snippet += " ..."

                snippets.append(snippet)
                used_ranges.append((start, end))

                if len(snippets) >= max_snippets:
                    return snippets

    return snippets


def _clean_table_entry(lines):
    """Join one Description-column row into one clean paragraph.

    This is display-only cleanup. It does not change the OCR stored in the DB.
    """
    cleaned = []
    for raw in lines:
        line = normalize_spaces(raw)
        if not line:
            continue
        # Remove only a leading table serial number, e.g. "2." or "2 -".
        line = re.sub(r"^\s*\d{1,3}\s*[.)\-:]\s*", "", line)
        # Ignore obvious Code-column-only values such as 1A2053* / A2052*.
        if re.fullmatch(r"[A-Za-z]{0,3}\d{2,}[A-Za-z0-9*./\-]*", line) and " " not in line:
            continue
        cleaned.append(line)

    text = normalize_spaces(" ".join(cleaned))
    if not text:
        return ""

    # Some OCR engines append a short Code-column token to the end of a
    # Description line. Remove only such an isolated trailing token.
    text = re.sub(r"\s+(?:[A-Za-z]{0,3}\d{2,}[A-Za-z0-9*./\-]*)\s*$", "", text)
    return normalize_spaces(text)


def _looks_like_table_code(line):
    line = normalize_spaces(line)
    if not line or " " in line:
        return False
    return bool(re.fullmatch(r"[A-Za-z]{0,4}\d{2,}[A-Za-z0-9*./\-]*", line))


def _looks_like_table_end(line):
    """Recognise text that normally starts after an approval table."""
    low = normalize_spaces(line).lower()
    return bool(re.match(
        r"^(?:copy\s+to|copy:|to\s+the\s+chief|chief\s+(?:general\s+)?engineer|"
        r"chief\s+manager|general\s+manager|this\s+issues|issued\s+with|"
        r"sd/?-|secretary|office\s+order|encl(?:osure)?[:\-])\b", low))


def _extract_boxed_table_entries(raw_lines, max_entries=6):
    """Extract complete Description cells from the first boxed Sr.No. table.

    OCR from scanned tables is linear: the Sr.No., multi-line Description and
    Code column can appear as separate text lines. We therefore collect text
    only between consecutive serial numbers and deliberately discard Code-column
    tokens and post-table correspondence text.
    """
    if not raw_lines:
        return []

    # Find a genuine table header. Requiring Description plus Sr.No./S.No. avoids
    # treating ordinary numbered body paragraphs as approval-table entries.
    header_at = None
    for i in range(len(raw_lines)):
        probe = " ".join(normalize_spaces(x) for x in raw_lines[i:i+5]).lower()
        if "description" in probe and re.search(r"\b(?:sr\.?\s*no\.?|s\.?\s*no\.?|sno\.?|serial\s+no\.?|sr\.?)\b", probe):
            header_at = min(len(raw_lines), i + 5)
            break
    if header_at is None:
        return []

    entries = []
    current = []
    current_no = None
    expected_min = 1
    seen_first_row = False

    for raw in raw_lines[header_at:]:
        line = normalize_spaces(raw)
        if not line:
            continue

        # Once a table has begun, correspondence/address text means the table is
        # over. Do not absorb the rest of the letter into the last table row.
        if seen_first_row and _looks_like_table_end(line):
            break

        # Ignore repeated table headers and isolated Code-column values.
        low = line.lower()
        if low in {"description", "code", "approval code", "sr. no.", "s.no."}:
            continue
        if seen_first_row and _looks_like_table_code(line):
            continue

        # Serial number may be "2.", "2 - text", or an isolated "2" line.
        m = re.match(r"^(\d{1,3})\s*(?:[.)\-:]\s*)?(.*)$", line)
        is_new_row = False
        marker_no = None
        marker_text = ""
        if m:
            candidate = int(m.group(1))
            rest = normalize_spaces(m.group(2))
            # Tables normally start 1, 2, 3...; reject dates, voltages, memo nos.
            if candidate <= 100 and (not seen_first_row and candidate <= 3 or seen_first_row and candidate >= expected_min and candidate <= (current_no or candidate) + 3):
                # A marker is trusted when isolated, punctuated, or followed by
                # ordinary description text rather than a date/code/voltage token.
                if (line == str(candidate) or re.match(r"^\d{1,3}\s*[.)\-:]", line) or
                        (rest and not re.match(r"^(?:\d{4}|\d{1,3}(?:/\d+)+|[A-Za-z]{0,3}\d{2,}[A-Za-z0-9*./\-]*)$", rest))):
                    is_new_row = True
                    marker_no, marker_text = candidate, rest

        if is_new_row:
            if current:
                entry = _clean_table_entry(current)
                if entry and len(entry.split()) >= 3:
                    entries.append(entry)
                    if len(entries) >= max_entries:
                        break
            current = [marker_text] if marker_text else []
            current_no = marker_no
            expected_min = marker_no + 1
            seen_first_row = True
            continue

        if seen_first_row:
            current.append(line)

    if current and len(entries) < max_entries:
        entry = _clean_table_entry(current)
        if entry and len(entry.split()) >= 3:
            entries.append(entry)

    # A single detected row can still be a false positive. The table in the
    # screenshot normally has at least two rows, so require two complete cells.
    return entries if len(entries) >= 2 else []


def approval_overview_lines(text, terms=None, min_lines=12, words_per_line=14):
    """Return a clean exact-approval overview for the result card.

    When a boxed Sr.No./Description table exists, each Description cell is shown
    as one separate paragraph. The visual convention is "... text ..." rather
    than bullets, matching the user's preferred card style.
    """
    text = (text or "").strip()
    if not text:
        return []

    raw_lines = [normalize_spaces(x) for x in text.splitlines() if normalize_spaces(x)]
    if not raw_lines:
        return []

    table_entries = _extract_boxed_table_entries(raw_lines, max_entries=6)
    if table_entries:
        return ["... " + entry + " ..." for entry in table_entries]

    # FALLBACK for documents without a reliably detectable table: begin from Subject.
    start = 0
    for i, line in enumerate(raw_lines):
        if re.match(r"^\s*(?:subject|sub\.?\s*ject)\s*[:\-]", line, re.I):
            start = i
            break
    else:
        joined = " ".join(raw_lines)
        m = re.search(r"\bsubject\s*[:\-]?", joined, re.I)
        if m:
            raw_lines = [joined[m.start():]]
            start = 0

    selected = normalize_spaces(" ".join(raw_lines[start:]))
    if not selected:
        return []

    # The card already has a dedicated Subject line, so do not repeat a short subject.
    if re.match(r"^subject\s*[:\-]", selected, re.I):
        subject_end = re.search(r"(?:\.|\n)\s+", selected)
        if subject_end and subject_end.end() < len(selected):
            possible = selected[:subject_end.end()].strip()
            if len(possible.split()) <= 120:
                selected = selected[subject_end.end():].strip()

    if not selected:
        return []

    chunks = re.split(
        r"(?<=[.!?])\s+(?=[A-Z0-9])|(?<=;)\s+|"
        r"(?=\b(?:This|The|It|Accordingly|Therefore|Further|However|Meanwhile|Reference|Memo|Letter|Approval|Proposal|WTDs|DHBVN|HVPNL)\b)",
        selected,
        flags=re.I,
    )
    chunks = [normalize_spaces(c) for c in chunks if normalize_spaces(c)]

    paragraphs, current, current_words = [], [], 0
    soft_limit, hard_limit = 38, 62
    for chunk in chunks:
        wc = len(chunk.split())
        if current and (current_words + wc > hard_limit or current_words >= soft_limit):
            paragraphs.append(normalize_spaces(" ".join(current)))
            current, current_words = [], 0
        current.append(chunk)
        current_words += wc
    if current:
        paragraphs.append(normalize_spaces(" ".join(current)))

    result = []
    word_budget = max(190, min_lines * max(14, words_per_line))
    used_words = 0
    for para in paragraphs:
        if not para or (result and used_words >= word_budget):
            break
        result.append("... " + para + " ...")
        used_words += len(para.split())
        if len(result) >= 8:
            break
    if result and len(paragraphs) > len(result):
        result[-1] = result[-1].rstrip(" .") + " ..."
    return result

# ============================================================
# BACKGROUND INDEXER
# ============================================================

class WorkerSignals(QObject):
    progress = Signal(int, int, str)
    finished = Signal(int, int, bool)  # indexed, total, stopped
    summary = Signal(dict)             # complete indexing summary
    error = Signal(str)
    log = Signal(str)


class IndexWorker(QRunnable):
    def __init__(self, folder, force=False, cancel_event=None):
        super().__init__()
        self.folder = Path(folder)
        self.force = force
        self.cancel_event = cancel_event or threading.Event()
        self.signals = WorkerSignals()

    def cancelled(self):
        return self.cancel_event.is_set()

    def run(self):
        indexed = 0
        total = 0
        stopped = False
        summary = {
            "checked": 0,
            "indexed": 0,
            "already_current": 0,
            "errors": 0,
            "master_appended": 0,
            "master_existing": 0,
            "master_invalid": 0,
            "native_pages": 0,
            "ocr_pages": 0,
            "unreadable_pages": 0,
            "semantic_created": 0,
            "semantic_skipped": 0,
        }

        if not INDEX_LOCK.acquire(blocking=False):
            self.signals.log.emit("Another indexing operation is already running.")
            self.signals.finished.emit(0, 0, False)
            return

        try:
            db = Database()
            ocr_ok, ocr_status = configure_tesseract()
            self.signals.log.emit(f"OCR STATUS: {ocr_status}")
            if not ocr_ok:
                self.signals.log.emit(
                    "OCR WARNING: scanned PDFs cannot be indexed until Tesseract is installed."
                )

            pdfs = sorted(self.folder.rglob("*.pdf"))
            total = len(pdfs)
            recovered_once = False

            self.signals.log.emit(
                f"Indexing started: {total} PDF file(s) found in {self.folder}"
            )

            for n, path in enumerate(pdfs, 1):
                if self.cancelled():
                    stopped = True
                    self.signals.log.emit(
                        "INDEX STOPPED by user. Existing indexed files are retained."
                    )
                    break

                try:
                    stat = path.stat()
                    summary["checked"] += 1
                    self.signals.progress.emit(n, total, path.name)
                    self.signals.log.emit(f"[{n}/{total}] Checking: {path.name}")

                    # Incremental check first. Do not hash every PDF unnecessarily.
                    # This is important because a normal "Index New / Changed"
                    # run should not reprocess unchanged approvals.
                    current_hash = None

                    # MASTER.db is APPEND-ONLY during indexing.
                    # Existing R.No. records are never updated or replaced.
                    imported, import_status, _approval_id = db.developer_import_pdf_to_master(path)
                    if imported:
                        summary["master_appended"] += 1
                        self.signals.log.emit(
                            f"    MASTER.db: NEW approval appended: {path.name} "
                            f"(R.No. missing earlier)"
                        )
                    elif import_status.startswith("EXISTS"):
                        summary["master_existing"] += 1
                        self.signals.log.emit(
                            f"    MASTER.db: existing approval retained unchanged "
                            f"({import_status})"
                        )
                    elif import_status == "SKIPPED_INVALID_RNO":
                        summary["master_invalid"] += 1
                        self.signals.log.emit(
                            f"    MASTER.db: skipped — filename does not provide a valid R.No."
                        )
                    if not self.force:
                        # Fast check: same path/filename + same size + same timestamp.
                        if db.document_is_current(
                            str(path), stat.st_size, stat.st_mtime, None
                        ):
                            summary["already_current"] += 1
                            self.signals.log.emit(
                                f"    Already current: {path.name} "
                                f"(metadata unchanged — no hash/OCR needed)"
                            )
                            continue

                        # Only ambiguous/new/changed candidates need a SHA-256
                        # content comparison. If the content hash matches the
                        # previous index, skip extraction/OCR as well.
                        current_hash = sha256_file(path)
                        if db.document_is_current(
                            str(path), stat.st_size, stat.st_mtime, current_hash
                        ):
                            summary["already_current"] += 1
                            self.signals.log.emit(
                                f"    Already current: {path.name} "
                                f"(content hash unchanged — no OCR needed)"
                            )
                            continue
                    else:
                        # Force Full Re-index intentionally re-extracts every PDF.
                        current_hash = sha256_file(path)

                    self.signals.log.emit(f"    Extracting native text + OCR fallback: {path.name}")
                    pages, full_text, extraction_info = extract_pdf(
                        path,
                        logger=self.signals.log.emit,
                    )
                    # Keep a concise extraction summary for the developer.
                    summary["native_pages"] += int(extraction_info.get("native_pages", 0) or 0)
                    summary["ocr_pages"] += int(extraction_info.get("ocr_pages", 0) or 0)
                    summary["unreadable_pages"] += int(extraction_info.get("failed_pages", 0) or 0)

                    # Stop after the current extraction operation, before DB write.
                    if self.cancelled():
                        stopped = True
                        self.signals.log.emit(
                            "Stop requested. Current extraction finished; stopping safely."
                        )
                        break

                    if len(normalize_spaces(full_text)) < 10:
                        self.signals.log.emit(
                            "    WARNING: no readable text was extracted. "
                            f"OCR status: {extraction_info.get('ocr_message', 'unknown')}"
                        )
                        full_text = (
                            "[SCANNED / IMAGE-ONLY PDF - OCR TEXT NOT AVAILABLE]\n"
                        )

                    metadata = extract_metadata(full_text, path.name)

                    semantic_chunks = []
                    if (
                        ensure_semantic_available()
                        and len(normalize_spaces(full_text)) >= 30
                        and "OCR TEXT NOT AVAILABLE" not in full_text
                    ):
                        try:
                            self.signals.log.emit("    Creating semantic index...")
                            semantic_chunks = embed_chunks(pages)
                            summary["semantic_created"] += 1
                        except Exception as sem_error:
                            summary["semantic_skipped"] += 1
                            self.signals.log.emit(
                                f"    Semantic indexing skipped: {sem_error}"
                            )

                    if self.cancelled():
                        stopped = True
                        self.signals.log.emit(
                            "Stop requested. Current processing finished; stopping before next database write."
                        )
                        break

                    if not current_hash:
                        current_hash = sha256_file(path)

                    data = {
                        "file_path": str(path),
                        "file_name": path.name,
                        "file_hash": current_hash,
                        "file_size": stat.st_size,
                        "modified_time": stat.st_mtime,
                        "page_count": len(pages),
                        **metadata,
                        "full_text": full_text,
                        "indexed_at": datetime.now().isoformat(timespec="seconds"),
                    }

                    try:
                        db.upsert_document(data, pages, semantic_chunks)
                    except Exception as db_error:
                        if (
                            Database.is_corruption_error(db_error)
                            and not recovered_once
                        ):
                            recovered_once = True
                            self.signals.log.emit(
                                "    DATABASE CORRUPTION DETECTED. "
                                "Automatically rebuilding a clean index..."
                            )
                            db.reset_database_file(str(db_error))
                            db = Database()
                            self.signals.log.emit(
                                "    Database rebuilt. Retrying current PDF..."
                            )
                            db.upsert_document(data, pages, semantic_chunks)
                        else:
                            raise

                    indexed += 1
                    summary["indexed"] = indexed
                    self.signals.log.emit(
                        f"    Indexed successfully ({indexed} updated)."
                    )

                except Exception as e:
                    summary["errors"] += 1
                    self.signals.error.emit(f"INDEX ERROR: {path.name}: {e}")

            summary["indexed"] = indexed
            summary["total"] = total
            summary["stopped"] = stopped
            self.signals.summary.emit(summary)
            self.signals.finished.emit(indexed, total, stopped)

        except Exception as e:
            summary["errors"] += 1
            summary["indexed"] = indexed
            summary["total"] = total
            summary["stopped"] = stopped
            self.signals.error.emit(f"INDEX ERROR: {e}")
            self.signals.summary.emit(summary)
            self.signals.finished.emit(indexed, total, stopped)

        finally:
            INDEX_LOCK.release()


# ============================================================
# MASTER-ONLY SEARCH INDEX WORKER
# ============================================================
class MasterIndexWorker(QRunnable):
    def __init__(self, cancel_event=None, force=False):
        super().__init__()
        self.cancel_event = cancel_event or threading.Event()
        self.force = bool(force)
        self.signals = WorkerSignals()
    def run(self):
        try:
            db = Database()
            result = db.rebuild_search_index_from_master(
                progress=self.signals.progress.emit,
                log=self.signals.log.emit,
                cancel_event=self.cancel_event,
                force=self.force,
            )
            self.signals.summary.emit(result)
            self.signals.finished.emit(int(result.get("indexed",0)), int(result.get("total",0)), bool(result.get("stopped")))
        except Exception as e:
            self.signals.error.emit(f"MASTER INDEX ERROR: {e}")
            self.signals.summary.emit({"checked":0,"indexed":0,"errors":1,"total":0,"stopped":False})
            self.signals.finished.emit(0,0,False)

# ============================================================
# FOLDER WATCHER
# ============================================================

class FolderChangeHandler(FileSystemEventHandler):
    def __init__(self, callback):
        self.callback = callback
        self.pending = {}

    def _queue(self, path):
        if str(path).lower().endswith(".pdf"):
            self.pending[str(path)] = time.time()
            self.callback()

    def on_created(self, event):
        if not event.is_directory:
            self._queue(event.src_path)

    def on_modified(self, event):
        if not event.is_directory:
            self._queue(event.src_path)

    def on_moved(self, event):
        if not event.is_directory:
            self._queue(event.dest_path)


def normalize_screen_ocr_text(text):
    """Clean screen-OCR output for natural clipboard pasting.

    Tesseract commonly inserts a newline at the end of every visual line.
    Those are layout line-wraps, not real paragraph breaks, and they force the
    user to press Backspace/Delete after pasting.  For clipboard OCR we flatten
    layout line-wraps into normal spaces while also repairing words split at a
    line boundary (for example ``trans-\nmission`` -> ``transmission``).

    This cleanup is deliberately limited to Screen OCR output; indexed/native
    PDF text and stored OCR are not modified.
    """
    if text is None:
        return ""

    text = str(text).replace("\x00", " ").replace("\r\n", "\n").replace("\r", "\n")

    # Remove trailing spaces from each OCR line first.
    lines = [re.sub(r"[ \t]+$", "", ln) for ln in text.split("\n")]

    # Repair OCR word splits at a line boundary.  Only remove the hyphen when
    # the next line starts with a lowercase letter, which avoids changing
    # normal terms such as "self-execution" or "U.O.".
    repaired = []
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if i + 1 < len(lines):
            nxt = lines[i + 1].strip()
            if line and nxt and re.search(r"[A-Za-z]-$", line) and re.match(r"^[a-z]", nxt):
                line = line[:-1] + nxt
                i += 1
        repaired.append(line)
        i += 1

    # Treat every OCR newline as a visual wrap.  Blank lines are also flattened
    # because they are frequently introduced by page/layout detection and
    # should not create unwanted gaps in pasted text.
    text = " ".join(x for x in repaired if x)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def run_screen_ocr_on_pil_image(pil_image):
    """Run the same high-accuracy OCR pipeline used by the PDF Screen OCR button.

    Both the dedicated PDF selector and the project-wide Ctrl+Q selector call
    this function so they cannot silently drift into different OCR behaviour.
    The returned clipboard text is cleaned for natural continuous pasting.
    """
    if not OCR_AVAILABLE:
        raise RuntimeError("Screen OCR is unavailable. Install pytesseract and Pillow.")
    if pil_image is None:
        raise RuntimeError("No image was supplied for OCR")
    pil = pil_image.convert("RGB")
    if pil.width < 1800:
        scale = min(3, max(1, int(1800 / max(1, pil.width))))
        if scale > 1:
            pil = pil.resize((pil.width * scale, pil.height * scale))
    text = normalize_screen_ocr_text(pytesseract.image_to_string(pil, config="--psm 6"))
    if not text:
        text = normalize_screen_ocr_text(pytesseract.image_to_string(pil, config="--psm 3"))
    return text


