class OcrSelectablePageLabel(QLabel):
    """PDF page image with drag-to-select OCR and hand-tool panning."""
    region_selected = Signal(QRect)
    def __init__(self,*a,**kw):
        super().__init__(*a,**kw)
        self.ocr_mode=False; self._origin=None; self._rect=QRect()
        self.pan_area=None; self._pan_global=None; self._pan_h=0; self._pan_v=0
        self.setMouseTracking(True)

    def set_pan_area(self, area):
        self.pan_area = area

    def set_ocr_mode(self,enabled):
        self.ocr_mode=bool(enabled); self._origin=None; self._rect=QRect(); self._pan_global=None
        self.setCursor(Qt.CursorShape.CrossCursor if self.ocr_mode else Qt.CursorShape.OpenHandCursor); self.update()

    def mousePressEvent(self,e):
        if self.ocr_mode and e.button()==Qt.MouseButton.LeftButton:
            self._origin=e.position().toPoint(); self._rect=QRect(self._origin,QSize()); self.update(); e.accept(); return
        if (not self.ocr_mode) and e.button()==Qt.MouseButton.LeftButton and self.pan_area is not None:
            self._pan_global=e.globalPosition().toPoint(); self._pan_h=self.pan_area.horizontalScrollBar().value(); self._pan_v=self.pan_area.verticalScrollBar().value()
            self.setCursor(Qt.CursorShape.ClosedHandCursor); e.accept(); return
        super().mousePressEvent(e)

    def mouseMoveEvent(self,e):
        if self.ocr_mode and self._origin is not None:
            self._rect=QRect(self._origin,e.position().toPoint()).normalized(); self.update(); e.accept(); return
        if (not self.ocr_mode) and self._pan_global is not None and self.pan_area is not None:
            now=e.globalPosition().toPoint(); delta=now-self._pan_global
            self.pan_area.horizontalScrollBar().setValue(self._pan_h-delta.x())
            self.pan_area.verticalScrollBar().setValue(self._pan_v-delta.y())
            e.accept(); return
        super().mouseMoveEvent(e)

    def mouseReleaseEvent(self,e):
        if self.ocr_mode and self._origin is not None and e.button()==Qt.MouseButton.LeftButton:
            r=QRect(self._origin,e.position().toPoint()).normalized(); self._origin=None; self._rect=QRect(); self.update()
            if r.width()>=6 and r.height()>=6: self.region_selected.emit(r)
            e.accept(); return
        if (not self.ocr_mode) and self._pan_global is not None and e.button()==Qt.MouseButton.LeftButton:
            self._pan_global=None; self.setCursor(Qt.CursorShape.OpenHandCursor); e.accept(); return
        super().mouseReleaseEvent(e)

    def paintEvent(self,e):
        super().paintEvent(e)
        if self.ocr_mode and not self._rect.isNull():
            # The PDF OCR selector deliberately uses the same visual treatment
            # as the project-wide capture overlay.  The colour is configurable
            # from Settings > Screen OCR Capture.
            c = QColor(getattr(self, "ocr_selection_color", "#FFD54F"))
            fill = QColor(c); fill.setAlpha(55)
            pen = QColor(c); pen.setAlpha(235)
            p=QPainter(self); p.setPen(QPen(pen,2,Qt.PenStyle.DashLine)); p.setBrush(fill); p.drawRect(self._rect); p.end()


class PdfFindWorkerSignals(QObject):
    """Retained only for compatibility with older saved code paths."""
    finished = Signal(int, object, object)
    error = Signal(int, str)


class PdfFindWorker(QRunnable):
    """Fast native PDF-text search only.

    Reference Map/Infra PDFs are expected to be OCRed before they are added to
    the application. Therefore searching must use the PDF's existing text
    layer, exactly like the Approval PDF viewer, and must NEVER invoke
    Tesseract, render pages for OCR, or maintain an OCR cache.
    """
    def __init__(self, generation, pdf_bytes, file_path, query, cached_ocr_words=None):
        super().__init__()
        self.setAutoDelete(True)
        self.generation = int(generation)
        self.pdf_bytes = bytes(pdf_bytes or b"")
        self.file_path = str(file_path or "")
        self.query = str(query or "").strip()
        self.signals = PdfFindWorkerSignals()

    def run(self):
        # This class is deliberately unused by PdfViewer for normal Find
        # operations. It is retained so external/legacy code does not fail if
        # it references the class.
        try:
            self.signals.finished.emit(self.generation, [], {})
        except Exception as exc:
            self.signals.error.emit(self.generation, str(exc))



class PdfViewer(QWidget):
    """Continuous, mouse-scrollable PDF preview using PyMuPDF raster pages."""
    def __init__(self):
        super().__init__()
        self.doc = None
        self.file_path = None
        self.pdf_bytes = None
        self.page_no = 0
        self.search_terms = []
        self.highlight_color = QColor(SEARCH_HIGHLIGHT_DEFAULT)
        self.zoom = 0.5
        self.find_text = ""
        self.find_hits = []
        self.find_index = -1
        # Find uses the PDF text layer only. No OCR is performed here.
        self._find_generation = 0
        self._find_pending_text = ""
        self.page_labels = []
        self.ocr_selection_mode = False
        self.ocr_selection_color = "#FFD54F"
        self._find_timer = QTimer(self)
        self._find_timer.setSingleShot(True)
        self._find_timer.setInterval(120)
        self._find_timer.timeout.connect(lambda: self._start_find_worker())

        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        toolbar = QFrame(); toolbar.setObjectName("toolbar")
        tb = QHBoxLayout(toolbar); tb.setContentsMargins(10, 7, 10, 7); tb.setSpacing(7)
        self.file_label = QLabel("No PDF selected")
        self.file_label.setStyleSheet(f"font-size:15px; font-weight:600; color:{TEXT};")
        tb.addWidget(self.file_label, 1)
        self.zoom_out_btn = QPushButton("−"); self.zoom_out_btn.setFixedWidth(42); self.zoom_out_btn.clicked.connect(lambda: self.change_zoom(-0.15))
        self.zoom_label = QLabel("50%"); self.zoom_label.setMinimumWidth(50); self.zoom_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.zoom_in_btn = QPushButton("+"); self.zoom_in_btn.setFixedWidth(42); self.zoom_in_btn.clicked.connect(lambda: self.change_zoom(0.15))
        self.print_btn = QPushButton("🖨 Print"); self.print_btn.clicked.connect(self.print_pdf)
        self.pan_btn = QPushButton("✋ Pan"); self.pan_btn.setCheckable(True); self.pan_btn.setChecked(True)
        self.pan_btn.setToolTip("Hand tool: drag the PDF with the left mouse button to pan")
        self.pan_btn.toggled.connect(self.set_pan_mode)
        self.screen_ocr_btn = QPushButton("🔎 Screen OCR"); self.screen_ocr_btn.setCheckable(True)
        self.screen_ocr_btn.setToolTip("Click, then drag a rectangle over the PDF. OCR text is copied to the clipboard.")
        self.screen_ocr_btn.toggled.connect(self.set_ocr_selection_mode)
        for w in (self.zoom_out_btn, self.zoom_label, self.zoom_in_btn, self.pan_btn, self.screen_ocr_btn, self.print_btn):
            tb.addWidget(w)
        root.addWidget(toolbar)

        findbar = QFrame(); findbar.setObjectName("toolbar")
        fb = QHBoxLayout(findbar); fb.setContentsMargins(10, 5, 10, 5); fb.setSpacing(7)
        self.find_edit = QLineEdit(); self.find_edit.setPlaceholderText("Find in this PDF..."); self.find_edit.setClearButtonEnabled(True); self.find_edit.setFixedHeight(32)
        self.find_edit.returnPressed.connect(self.find_next)
        self.find_edit.textChanged.connect(self._schedule_find)
        self.find_prev_btn = QPushButton("‹"); self.find_next_btn = QPushButton("›"); self.find_count_label = QLabel("")
        self.find_prev_btn.clicked.connect(self.find_previous); self.find_next_btn.clicked.connect(self.find_next)
        fb.addWidget(self.find_edit, 1); fb.addWidget(self.find_prev_btn); fb.addWidget(self.find_next_btn); fb.addWidget(self.find_count_label)
        root.addWidget(findbar)

        self.scroll = QScrollArea(); self.scroll.setWidgetResizable(False); self.scroll.setAlignment(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setStyleSheet(f"background:{DARKER}; border:none;")
        self.scroll.viewport().installEventFilter(self)
        self._set_placeholder("Select a search result to preview the PDF")
        root.addWidget(self.scroll, 1)

    def _set_placeholder(self, text):
        holder = QLabel(text)
        holder.setAlignment(Qt.AlignmentFlag.AlignCenter)
        holder.setStyleSheet(f"color:{MUTED}; font-size:16px; padding:30px;")
        holder.setMinimumSize(500, 650)
        self.image_label = holder  # compatibility with existing error/loading code
        old = self.scroll.takeWidget() if hasattr(self, 'scroll') else None
        if hasattr(self, 'scroll'):
            self.scroll.setWidget(holder)
        if old and old is not holder:
            old.deleteLater()
        self.page_labels = []

    def set_ocr_selection_color(self, color):
        self.ocr_selection_color = str(color or "#FFD54F")
        for label in self.page_labels:
            if isinstance(label, OcrSelectablePageLabel):
                label.ocr_selection_color = self.ocr_selection_color
                label.update()

    def set_pan_mode(self, enabled):
        # Pan is the normal mode; OCR temporarily switches to crosshair mode.
        if enabled and self.ocr_selection_mode:
            self.screen_ocr_btn.setChecked(False)
        for label in self.page_labels:
            if isinstance(label, OcrSelectablePageLabel):
                label.set_ocr_mode(self.ocr_selection_mode)

    def set_ocr_selection_mode(self, enabled):
        self.ocr_selection_mode=bool(enabled)
        if self.ocr_selection_mode:
            self.pan_btn.setChecked(False)
        elif not self.pan_btn.isChecked():
            self.pan_btn.setChecked(True)
        for label in self.page_labels:
            if isinstance(label,OcrSelectablePageLabel): label.set_ocr_mode(self.ocr_selection_mode)
        self.screen_ocr_btn.setText("✥ Select OCR Area" if self.ocr_selection_mode else "🔎 Screen OCR")

    def _ocr_selected_region(self,label,rect):
        if not OCR_AVAILABLE:
            QMessageBox.warning(self,APP_NAME,"Screen OCR is unavailable. Install pytesseract and Pillow."); self.screen_ocr_btn.setChecked(False); return
        ready,message=configure_tesseract()
        if not ready:
            QMessageBox.warning(self,APP_NAME,"Screen OCR is not ready:\n"+str(message)); self.screen_ocr_btn.setChecked(False); return
        try:
            pm=label.pixmap()
            if pm is None or pm.isNull(): raise RuntimeError("No rendered PDF image is available for OCR")
            img=pm.toImage().convertToFormat(QImage.Format.Format_RGBA8888)
            x=max(0,min(rect.x(),img.width()-1)); y=max(0,min(rect.y(),img.height()-1)); w=max(1,min(rect.width(),img.width()-x)); h=max(1,min(rect.height(),img.height()-y))
            crop=img.copy(x,y,w,h); pil=Image.frombytes("RGBA",(crop.width(),crop.height()),bytes(crop.bits()),"raw","RGBA",0,1).convert("RGB")
            text = run_screen_ocr_on_pil_image(pil)
            if text: QApplication.clipboard().setText(text); self.screen_ocr_btn.setToolTip("✓ OCR text copied to clipboard")
            else: self.screen_ocr_btn.setToolTip("No readable text detected in selected area")
        except Exception as e: QMessageBox.warning(self,APP_NAME,f"Screen OCR failed:\n{e}")
        finally: self.screen_ocr_btn.setChecked(False)

    def eventFilter(self, obj, event):
        if obj is self.scroll.viewport() and event.type() == QEvent.Type.Wheel and (event.modifiers() & Qt.KeyboardModifier.ControlModifier):
            self.change_zoom(0.12 if event.angleDelta().y() > 0 else -0.12)
            return True
        return super().eventFilter(obj, event)

    def _clear_preview_widget(self):
        old = self.scroll.takeWidget()
        if old:
            old.deleteLater()
        self.page_labels = []

    def _render_page_pixmap(self, page_no, highlight_rects=None):
        page = self.doc.load_page(int(page_no))
        zoom = 1.55 * self.zoom
        pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
        image = QImage(pix.samples, pix.width, pix.height, pix.stride, QImage.Format.Format_RGB888).copy()
        if highlight_rects:
            painter = QPainter(image)
            painter.setPen(QPen(QColor("#8a7200"), 1))
            highlight = QColor(self.highlight_color); highlight.setAlpha(120); painter.setBrush(highlight)
            for rect in highlight_rects:
                x = rect.x0 * zoom; y = rect.y0 * zoom
                w = (rect.x1 - rect.x0) * zoom; h = (rect.y1 - rect.y0) * zoom
                painter.drawRect(int(x), int(y), max(2, int(w)), max(2, int(h)))
            painter.end()
        return QPixmap.fromImage(image)

    def _render_page_with_hits(self, page_no, rects):
        """Re-render only a page affected by the current/previous search."""
        pixmap = self._render_page_pixmap(page_no, rects)
        if 0 <= int(page_no) < len(self.page_labels):
            self.page_labels[int(page_no)].setPixmap(pixmap)

    def _refresh_find_highlights(self, old_hits=None):
        """Update only pages whose highlights changed.

        This deliberately does NOT keep a second copy of every rendered page.
        It also does not run OCR. Pages are rendered again only when they are
        affected by the old or new search results.
        """
        if not self.doc or not self.page_labels:
            return
        affected = set(int(p) for p, _ in (old_hits or []))
        affected.update(int(p) for p, _ in self.find_hits)
        by_page = {}
        for pno, rect in self.find_hits:
            by_page.setdefault(int(pno), []).append(fitz.Rect(rect))
        for pno in sorted(affected):
            if 0 <= pno < len(self.page_labels):
                self._render_page_with_hits(pno, by_page.get(pno, []))

    def render_all_pages(self, scroll_target=None):
        if not self.doc:
            return
        self._clear_preview_widget()
        container = QWidget()
        container.setStyleSheet(f"background:{DARKER};")
        layout = QVBoxLayout(container)
        layout.setContentsMargins(12, 12, 12, 12)
        layout.setSpacing(12)
        layout.setAlignment(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop)
        self.page_labels = []
        for pno in range(self.doc.page_count):
            try:
                pixmap = self._render_page_pixmap(pno)
                label = OcrSelectablePageLabel()
                label.ocr_selection_color = self.ocr_selection_color
                label.setAlignment(Qt.AlignmentFlag.AlignCenter)
                label.setPixmap(pixmap)
                label.setPanArea = getattr(label, "set_pan_area", None)
                if label.setPanArea:
                    label.setPanArea(self.scroll)
                label.setObjectName(f"pdf_page_{pno}")
                label.set_ocr_mode(self.ocr_selection_mode)
                label.region_selected.connect(lambda rect, lbl=label: self._ocr_selected_region(lbl,rect))
                layout.addWidget(label, 0, Qt.AlignmentFlag.AlignHCenter)
                self.page_labels.append(label)
            except Exception as e:
                label = QLabel(f"Cannot render page {pno + 1}: {e}")
                label.setStyleSheet(f"color:{MUTED}; padding:20px;")
                layout.addWidget(label)
                self.page_labels.append(label)
        self.scroll.setWidget(container)
        self.image_label = self.page_labels[0] if self.page_labels else QLabel()
        QApplication.processEvents()
        if scroll_target is not None:
            pno, y = scroll_target
            if 0 <= pno < len(self.page_labels):
                target = self.page_labels[pno]
                pos_y = target.pos().y() + int(y)
                self.scroll.verticalScrollBar().setValue(max(0, pos_y - 80))

    def load_pdf(self, path, terms, highlight_color):
        self.close_doc(); self.file_path = path; self.pdf_bytes = None; self.search_terms = terms or []; self.highlight_color = QColor(highlight_color)
        self._set_placeholder("Loading PDF...")
        try:
            self.doc = fitz.open(path); self.file_label.setText(Path(path).name); self.zoom = 0.5; self.zoom_label.setText("50%")
            self.find_text = ""; self.find_hits = []; self.find_index = -1
            self.render_all_pages()
            self.prepare_find(self.find_edit.text())
        except Exception as e:
            self._set_placeholder(f"Cannot open PDF:\n{e}")

    def load_pdf_bytes(self, pdf_bytes, filename, terms, highlight_color):
        """Hard-refresh the continuous preview from the exact selected MASTER BLOB."""
        import hashlib
        self.close_doc()
        self.file_path = None
        self.pdf_bytes = bytes(pdf_bytes or b"")
        self.search_terms = list(terms or [])
        self.highlight_color = QColor(highlight_color)
        self.file_label.setText(filename or "Embedded approval.pdf")
        self._set_placeholder("Loading embedded PDF...")
        QApplication.processEvents()
        try:
            if not self.pdf_bytes:
                raise RuntimeError("Embedded PDF data is empty")
            self._loaded_pdf_filename = str(filename or "")
            self._loaded_pdf_sha256 = hashlib.sha256(self.pdf_bytes).hexdigest()
            new_doc = fitz.open(stream=self.pdf_bytes, filetype="pdf")
            if new_doc.page_count < 1:
                new_doc.close(); raise RuntimeError("Embedded PDF contains no pages")
            self.doc = new_doc
            self.zoom = 0.5; self.zoom_label.setText("50%")
            self.find_text = (self.find_edit.text() or "").strip()
            self.find_hits = []; self.find_index = -1
            self._find_pending_text = self.find_text
            self.render_all_pages()
            if self.find_text:
                self._start_find_worker()
        except Exception as e:
            self.close_doc(); self._set_placeholder(f"Cannot open embedded PDF:\n{e}")

    def close_doc(self):
        if self.doc:
            try: self.doc.close()
            except Exception: pass
        self._find_generation += 1
        self.doc = None; self.pdf_bytes = None; self.find_hits = []; self.find_index = -1
        self._loaded_pdf_filename = ""; self._loaded_pdf_sha256 = ""

    def find_first_matching_page(self):
        if not self.doc: return 0
        for i, page in enumerate(self.doc):
            text = page.get_text("text") or ""
            if any(t.lower() in text.lower() for t in self.search_terms): return i
        return 0

    def change_zoom(self, delta):
        self.zoom = max(0.35, min(3.0, round(self.zoom + delta, 2)))
        self.zoom_label.setText(f"{int(self.zoom * 100)}%")
        if self.doc:
            target = None
            if self.find_index >= 0 and self.find_index < len(self.find_hits):
                pno, rect = self.find_hits[self.find_index]
                target = (pno, rect.y0 * 1.55 * self.zoom)
            self.render_all_pages(target)

    def _find_query(self, query):
        """Use PyMuPDF's native text layer exactly as the Approval PDF viewer."""
        if not self.doc or not query:
            return []
        hits = []
        for pno in range(self.doc.page_count):
            try:
                page = self.doc.load_page(pno)
                # This is the same fast native PDF search used by the approval
                # preview. It searches the embedded/OCR text layer and returns
                # the exact PDF coordinates needed for highlighting.
                for rect in page.search_for(query, quads=False):
                    hits.append((pno, fitz.Rect(rect)))
            except Exception:
                continue
        return hits

    def _schedule_find(self, text=""):
        self._find_pending_text = (text or "").strip()
        self._find_timer.stop()
        self._find_timer.start()

    def _start_find_worker(self):
        # Compatibility name. Search is intentionally synchronous/native and
        # extremely light now that OCR is guaranteed to have been done before
        # upload. No Tesseract, rendering or worker thread is involved.
        text = self._find_pending_text
        self._find_generation += 1
        old_hits = list(self.find_hits)
        self.find_text = text
        self.find_hits = self._find_query(text) if text else []
        self.find_index = -1
        self.find_count_label.setText(
            f"{len(self.find_hits)} matching text found" if self.find_hits
            else ("No matching text found" if text else "")
        )
        self._refresh_find_highlights(old_hits)
        if self.find_hits:
            self.find_next()

    def prepare_find(self, text):
        self._find_pending_text = (text or "").strip()
        self._find_timer.stop()
        self._find_timer.start()

    def _scroll_to_hit(self):
        if self.find_index < 0 or self.find_index >= len(self.find_hits):
            return
        pno, rect = self.find_hits[self.find_index]
        self.page_no = pno
        self.find_count_label.setText(
            f"{self.find_index + 1} / {len(self.find_hits)} matching text found"
        )
        if not self.page_labels:
            self.render_all_pages((pno, rect.y0 * 1.55 * self.zoom))
            return
        if 0 <= pno < len(self.page_labels):
            label = self.page_labels[pno]
            y = label.pos().y() + int(rect.y0 * 1.55 * self.zoom)
            self.scroll.verticalScrollBar().setValue(max(0, y - 80))

    def find_next(self):
        if not self.find_hits:
            return
        self.find_index = (self.find_index + 1) % len(self.find_hits)
        self._scroll_to_hit()

    def find_previous(self):
        if not self.find_hits:
            return
        self.find_index = (self.find_index - 1) % len(self.find_hits)
        self._scroll_to_hit()

    def render_page(self):
        self.render_all_pages()

    def print_pdf(self):
        path = self.file_path
        try:
            if self.pdf_bytes:
                name = self.file_label.text() or "approval.pdf"
                safe = re.sub(r'[^A-Za-z0-9._-]+', '_', Path(name).name)
                path = str(Path(tempfile.gettempdir()) / f"HVPNL_Print_{safe}")
                Path(path).write_bytes(self.pdf_bytes)
            if not path or not Path(path).exists():
                QMessageBox.information(self, APP_NAME, "Open a PDF first."); return
            if sys.platform.startswith("win"): os.startfile(str(path), "print")
            else:
                import subprocess; subprocess.Popen(["lp", str(path)])
        except Exception as e: QMessageBox.warning(self, APP_NAME, f"Could not start printing:\n{e}")


