def format_display_date(value):
    """Return dates for the UI as dd.mm.yyyy, while leaving unknown text intact."""
    if value is None:
        return ""
    raw = str(value).strip()
    if not raw:
        return ""

    # Common values stored in MASTER.db / Excel imports.
    candidates = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
        "%d.%m.%Y",
        "%d-%m-%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%Y.%m.%d",
    ]
    for fmt in candidates:
        try:
            return datetime.strptime(raw, fmt).strftime("%d.%m.%Y")
        except ValueError:
            pass

    # ISO strings with timezone/fractional seconds.
    try:
        iso = raw.replace("Z", "+00:00")
        return datetime.fromisoformat(iso).strftime("%d.%m.%Y")
    except Exception:
        return raw


def approval_age_text(value):
    """Return a compact age label from the stored approval date."""
    sort_value = parse_date(value or "")
    if not sort_value:
        return ""
    try:
        approved = datetime.strptime(sort_value, "%Y%m%d").date()
        today = date.today()
        if approved > today:
            return ""
        days = (today - approved).days
        if days < 31:
            return f"{days} day{'s' if days != 1 else ''} old"
        months = (today.year - approved.year) * 12 + today.month - approved.month
        if today.day < approved.day:
            months -= 1
        if months < 12:
            months = max(1, months)
            return f"{months} month{'s' if months != 1 else ''} old"
        years = months // 12
        return f"{years} year{'s' if years != 1 else ''} old"
    except Exception:
        return ""

class JustifiedTextWidget(QWidget):
    """A lightweight rich-text widget that genuinely justifies both edges.

    QLabel accepts rich text, but its layout can retain an old size hint and
    often leaves the last visual geometry looking ragged when the splitter is
    moved. QTextDocument performs real paragraph justification against the
    widget's current width, so every result card reflows cleanly.
    """
    def __init__(self, html_text="", color="#e7eaf0", font_size=14, parent=None):
        super().__init__(parent)
        self._doc = QTextDocument(self)
        self._doc.setDocumentMargin(0)
        self._doc.setDefaultStyleSheet(
            f"body, div, p {{ color:{color}; font-size:{font_size}px; margin:0; padding:0; }}"
        )
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        sp = QSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        sp.setHeightForWidth(True)
        self.setSizePolicy(sp)
        self.setMinimumWidth(0)
        self.setHtml(html_text)

    def setHtml(self, html_text):
        self._doc.setHtml(html_text or "")
        self._update_text_width()
        self.updateGeometry()
        self.update()

    def _update_text_width(self):
        # QTextDocument must be told the CURRENT card width. This is what makes
        # the left and right edges stay aligned when the PDF pane is resized.
        self._doc.setTextWidth(max(1, self.contentsRect().width()))

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._update_text_width()
        self.updateGeometry()

    def heightForWidth(self, width):
        if width <= 1:
            return 0
        self._doc.setTextWidth(max(1, width - self.contentsMargins().left() - self.contentsMargins().right()))
        return max(1, int(self._doc.size().height() + 1))

    def sizeHint(self):
        width = max(220, self.width() or 500)
        return QSize(width, self.heightForWidth(width))

    def minimumSizeHint(self):
        return QSize(0, 1)

    def paintEvent(self, event):
        painter = QPainter(self)
        ctx = QAbstractTextDocumentLayout.PaintContext()
        self._doc.documentLayout().draw(painter, ctx)


class ResultCard(QWidget):
    clicked = Signal(object)
    favorite_toggled = Signal(object)
    note_requested = Signal(object)

    def __init__(self, row, snippets, terms, highlight_color, has_note=False, is_favorite=False):
        super().__init__()
        self.row = row
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setObjectName("resultCard")
        # The centre results pane must be allowed to become narrow when the PDF
        # splitter is expanded.  Without an Ignored horizontal policy, long OCR
        # snippets can keep their old size hint and visually run underneath the
        # PDF pane instead of reflowing.
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)

        # IMPORTANT:
        # QLabel children normally consume mouse events. In a result card this can
        # make clicking directly on "1639.pdf", its subject, or its OCR snippet do
        # nothing, leaving the PREVIOUS PDF (e.g. 1638.pdf) on screen. All display
        # labels are therefore transparent to mouse events so the click always
        # reaches this ResultCard. Real buttons remain clickable.
        def display_label(*args):
            w = QLabel(*args)
            w.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
            # Force text to use the width actually available in the centre pane.
            # This makes labels wrap/reflow instead of preserving a wide size hint.
            w.setMinimumWidth(0)
            w.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
            return w

        layout = QVBoxLayout(self)
        layout.setContentsMargins(16, 13, 16, 13)
        layout.setSpacing(7)
        top = QHBoxLayout()

        icon = display_label("PDF")
        icon.setFixedSize(38, 38)
        icon.setMinimumWidth(38)
        icon.setMaximumWidth(38)
        icon.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        icon.setAlignment(Qt.AlignmentFlag.AlignCenter)
        icon.setStyleSheet("background:#d83535; color:white; border-radius:4px; font-weight:800; font-size:10px;")

        # Keep the PDF icon and the text in two real, non-overlapping columns.
        # A bare QVBoxLayout inside the QHBoxLayout can get an invalid/negative
        # width when the centre splitter is made very narrow, which allowed the
        # title to paint over the fixed PDF icon.  A dedicated QWidget gives the
        # text column its own geometry.
        title_container = QWidget(self)
        title_container.setMinimumWidth(0)
        title_container.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        title_box = QVBoxLayout(title_container)
        title_box.setContentsMargins(0, 0, 0, 0)
        title_box.setSpacing(2)

        title = display_label(row["file_name"])
        title.setMinimumWidth(0)
        title.setStyleSheet(f"font-size:20px; font-weight:600; color:{RESULT_TEXT};")
        title.setWordWrap(True)
        title_box.addWidget(title)

        details = []
        if row["approval_number"]:
            details.append(f"Approval: {row['approval_number']}")
        display_file_no = (
            row.get("file_number")
            or row.get("memo_number")
            or row.get("approval_code")
            or ""
        )
        if display_file_no:
            details.append(f"File: {display_file_no[:70]}")
        if row["approval_date"]:
            details.append(format_display_date(row["approval_date"]))
        age = approval_age_text(row["approval_date"] or "")
        if age:
            details.append(age)
        try:
            if "semantic_score" in row and row["semantic_score"] is not None:
                details.append(f"AI match: {row['semantic_score']:.2f}")
        except Exception:
            pass

        sub = display_label("  •  ".join(details) if details else "Indexed HVPNL approval")
        sub.setStyleSheet(f"color:{MUTED}; font-size:12px;")
        sub.setWordWrap(True)
        title_box.addWidget(sub)

        top.setContentsMargins(0, 0, 0, 0)
        top.setSpacing(12)
        top.addWidget(icon, 0, Qt.AlignmentFlag.AlignTop)
        top.addWidget(title_container, 1, Qt.AlignmentFlag.AlignTop)

        # Note is always visible, just like the favourite star. Its appearance
        # clearly distinguishes an approval which already has a saved note from
        # one which has no note yet. Clicking either state opens the note editor.
        self.note_icon = QPushButton("📝" if has_note else "🗒")
        self.note_icon.setToolTip("Edit saved note" if has_note else "Add note")
        self.note_icon.setFixedSize(32, 30)
        self.note_icon.setStyleSheet(
            f"font-size:16px; color:{BLUE if has_note else MUTED}; "
            f"background:{'#303844' if has_note else 'transparent'}; "
            "padding:2px; text-align:center;"
        )
        self.note_icon.clicked.connect(lambda: self.note_requested.emit(self.row))
        top.addWidget(self.note_icon, 0, Qt.AlignmentFlag.AlignTop)

        self.star_btn = QPushButton("★" if is_favorite else "☆")
        self.star_btn.setToolTip("Remove from favourites" if is_favorite else "Add to favourites")
        self.star_btn.setFixedSize(32, 30)
        self.star_btn.setStyleSheet(
            f"font-size:21px; color:{'#e0a400' if is_favorite else MUTED}; "
            "padding:0; text-align:center;"
        )
        self.star_btn.clicked.connect(lambda: self.favorite_toggled.emit(self.row))
        top.addWidget(self.star_btn, 0, Qt.AlignmentFlag.AlignTop)
        layout.addLayout(top)

        # Everything BELOW the approval header uses real paragraph justification.
        # This includes the Subject and every OCR/table overview entry, so all result
        # cards have clean left and right edges irrespective of card width.
        if row["subject"]:
            # Show the COMPLETE subject. Do not truncate it to a fixed character
            # count; the QTextDocument widget wraps it to the actual card width.
            subject_html = word_highlight_html("Subject: " + row["subject"], terms, highlight_color)
            subject = JustifiedTextWidget(
                f'<div style="text-align:justify; text-justify:inter-word; line-height:140%; font-weight:600;">{subject_html}</div>',
                color=SUBJECT_TEXT,
                font_size=13,
                parent=self,
            )
            subject.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.MinimumExpanding)
            layout.addWidget(subject)

        for snippet in snippets:
            snippet_html = word_highlight_html(snippet, terms, highlight_color)
            # Real QTextDocument justification, rather than QLabel's approximate
            # rich-text layout. The paragraph reflows whenever the splitter moves.
            lbl = JustifiedTextWidget(
                f'<div style="text-align:justify; text-justify:inter-word; margin:0; padding:0 4px; line-height:145%;">{snippet_html}</div>',
                color=RESULT_TEXT,
                font_size=14,
                parent=self,
            )
            layout.addWidget(lbl)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit(self.row)
            event.accept()
            return
        super().mousePressEvent(event)

