class SearchSignals(QObject):
    finished = Signal(int, object, object, bool, str)
    error = Signal(int, str)

class SearchWorker(QRunnable):
    def __init__(self, db_path, token, terms, exact_phrase, close_mode, max_gap, semantic_mode, query):
        super().__init__()
        self.db_path = db_path; self.token = token; self.terms = terms; self.exact_phrase = exact_phrase
        self.close_mode = close_mode; self.max_gap = max_gap; self.semantic_mode = semantic_mode; self.query = query
        self.signals = SearchSignals()
    def run(self):
        try:
            db = Database(self.db_path)
            if self.semantic_mode:
                if not ensure_semantic_available(): raise RuntimeError("Semantic search requires sentence-transformers and numpy")
                model = get_semantic_model()
                vector = model.encode(self.query, normalize_embeddings=True)
                rows = db.semantic_search(vector)
            else:
                rows = db.search(self.terms, self.exact_phrase, close_search=self.close_mode, max_gap=self.max_gap)
            self.signals.finished.emit(self.token, list(rows), self.terms, self.close_mode, "")
        except Exception as e:
            self.signals.error.emit(self.token, str(e))

class AutoUpdateSignals(QObject):
    finished = Signal(object, str)  # (update_info_or_none, error)


class AutoUpdateWorker(QRunnable):
    """Small background GitHub release check; never blocks the GUI thread."""
    def __init__(self):
        super().__init__()
        self.setAutoDelete(True)
        self.signals = AutoUpdateSignals()

    def run(self):
        try:
            info, error = hvpnl_read_update_info()
            if error:
                self.signals.finished.emit(None, str(error))
                return

            versions = hvpnl_get_installed_component_versions()
            local_app = versions["app_version"]
            local_master = versions["master_version"]
            app_remote = str((info.get("app") or {}).get("version") or "").strip()
            if not app_remote:
                app_remote = str(info.get("app_version") or info.get("version") or "").strip()
            app_plan = None
            if app_remote and hvpnl_version_tuple(app_remote) > hvpnl_version_tuple(local_app):
                app_asset = str((info.get("app") or {}).get("asset") or "").strip()
                if app_asset:
                    app_plan = {"mode": "app", "asset": app_asset, "from_version": local_app, "to_version": app_remote}

            master_plan = hvpnl_select_component(info, "master", local_master)
            if not app_plan and not master_plan:
                self.signals.finished.emit(None, "")
                return

            tag = str(info.get("_github_release_tag") or "")
            signature = "|".join([
                tag,
                str(app_plan.get("to_version") if app_plan else ""),
                str(master_plan.get("to_version") if master_plan else ""),
            ])
            payload = {
                "info": info, "app_plan": app_plan,
                "master_plan": master_plan,
                "versions": versions, "signature": signature,
            }
            self.signals.finished.emit(payload, "")
        except Exception as exc:
            self.signals.finished.emit(None, str(exc))


