def apply_project_tooltips(root):
    """Give every visible QPushButton a concise purpose tooltip. Explicit tooltips are preserved."""
    mapping = {
        "search": "Search the approval database using the entered words.",
        "settings": "Open application display, theme and search settings.",
        "developer": "Open developer controls for indexing, data releases, metadata and licences.",
        "favourite": "Show or manage favourite approvals.",
        "notes": "Show approvals that have saved notes.",
        "history": "Show recent search history.",
        "load": "Load the selected approval or document into the current view.",
        "screen ocr": "Select a rectangle on the PDF and copy OCR text to the clipboard.",
        "pan": "Hand tool: drag the PDF to move around without scrollbars.",
        "print": "Print the currently displayed approval PDF.",
        "save": "Save the current changes or corrections.",
        "close": "Close this window without changing other records.",
        "previous": "Go to the previous approval record.",
        "next": "Go to the next approval record.",
        "select documents folder": "Select the source folder containing approval PDF files for indexing.",
        "index new / changed": "Index only PDFs whose searchable-index fingerprint is new or changed. Existing MASTER records are retained.",
        "force full": "Rebuild the complete searchable/OCR index for every PDF. Existing MASTER metadata is not overwritten.",
        "edit master metadata": "Review and manually correct approval metadata stored in MASTER.db.",
        "create data": "Publish a GitHub release containing only the application EXE and MASTER.db; index.db is local-only.",
        "licence": "Add users and generate, renew or review machine-specific activation licences.",
        "refresh": "Recalculate and refresh database and indexing statistics.",
        "stop indexing": "Request a safe stop after the current indexing operation reaches a safe point.",
        "copy index log": "Copy the complete Index Log to the Windows clipboard.",
        "copy": "Copy the displayed value to the clipboard.",
        "about": "Show application version, data version, database information and legal-use notice.",
        "generate": "Generate a machine-specific signed activation code using the selected licence duration.",
        "activate": "Validate and save the activation code for this PC.",
    }
    for btn in root.findChildren(QPushButton):
        if btn.toolTip().strip():
            continue
        text = (btn.text() or "").lower()
        for key, tip in mapping.items():
            if key in text:
                btn.setToolTip(tip)
                break
        else:
            btn.setToolTip(f"Action: {(btn.text() or 'button').strip()}")





# ============================================================
# SINGLE-EXE UPDATE ENGINE
# ============================================================
# The distributed application remains ONE EXE.  During an update the same
# EXE is started a second time with --hvpnl-self-update.  The temporary child
# process waits for the main process to exit, replaces the EXE/database files,
# then starts the new EXE and removes the temporary update files.
#
# SECURITY MODEL
# ----------------
# The SAME EXE serves both USER and DEVELOPER modes. The credentials are
# deliberately separate:
#   USER       -> dedicated READ-ONLY update credential
#   DEVELOPER  -> separate WRITE/PUBLISH credential
# The developer credential is preferred in Windows Credential Manager and is
# only consumed by the Developer Control Centre publishing workflow.
# The user credential may be provisioned in Credential Manager or supplied as
# an encrypted build-time value for zero-touch user deployment.
#
# IMPORTANT: any credential shipped inside a client EXE can ultimately be
# recovered by a determined local attacker. A server-side update gateway is
# stronger because the GitHub credential never reaches user PCs.

HVPNL_GITHUB_API = "https://api.github.com"
HVPNL_UPDATE_MANIFEST_NAME = "update.json"
HVPNL_UPDATE_CRED_TARGET = "HVPNL-Approval-Search-GitHub-Read"
HVPNL_DEVELOPER_CRED_TARGET = "HVPNL-Approval-Search-GitHub-Developer"

# Optional encrypted updater PAT for zero-touch user deployment.
# This is NOT the developer/write PAT. It must be a dedicated fine-grained
# GitHub PAT restricted to this repository with Contents: Read-only.
# The blob is generated locally with: --embed-user-update-pat
HVPNL_EMBEDDED_UPDATE_PAT_B64 = ""
HVPNL_EMBEDDED_UPDATE_KEY_MATERIAL = (
    b"HVPNL-Approval-Search|UserUpdateCredential|v1|"
    b"9f1b6d3a-7d8c-4c75-a2a8-4a9d8c7f6e31"
)


def _hvpnl_read_windows_credential(target):
    """Read a generic credential from Windows Credential Manager."""
    if os.name != "nt":
        return ""
    try:
        import ctypes
        from ctypes import wintypes

        advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)

        class CREDENTIALW(ctypes.Structure):
            _fields_ = [
                ("Flags", wintypes.DWORD),
                ("Type", wintypes.DWORD),
                ("TargetName", wintypes.LPWSTR),
                ("Comment", wintypes.LPWSTR),
                ("LastWritten", wintypes.FILETIME),
                ("CredentialBlobSize", wintypes.DWORD),
                ("CredentialBlob", ctypes.POINTER(ctypes.c_ubyte)),
                ("Persist", wintypes.DWORD),
                ("AttributeCount", wintypes.DWORD),
                ("Attributes", ctypes.c_void_p),
                ("TargetAlias", wintypes.LPWSTR),
                ("UserName", wintypes.LPWSTR),
            ]

        CredReadW = advapi32.CredReadW
        CredReadW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD,
                              ctypes.POINTER(ctypes.POINTER(CREDENTIALW))]
        CredReadW.restype = wintypes.BOOL
        CredFree = advapi32.CredFree
        CredFree.argtypes = [ctypes.c_void_p]
        CredFree.restype = wintypes.BOOL

        cred_ptr = ctypes.POINTER(CREDENTIALW)()
        # CRED_TYPE_GENERIC = 1
        if not CredReadW(str(target), 1, 0, ctypes.byref(cred_ptr)):
            return ""
        try:
            cred = cred_ptr.contents
            size = int(cred.CredentialBlobSize or 0)
            if size <= 0 or not cred.CredentialBlob:
                return ""
            raw = ctypes.string_at(cred.CredentialBlob, size)
            try:
                return raw.decode("utf-8").strip()
            except UnicodeDecodeError:
                return raw.decode("utf-16-le").strip()
        finally:
            CredFree(cred_ptr)
    except Exception:
        return ""


def hvpnl_get_github_token():
    """Developer publishing credential only.

    This is deliberately separate from the end-user update credential.
    Preferred storage is Windows Credential Manager. Environment/file fallbacks
    are retained for backward compatibility on the developer machine only.
    """
    token = _hvpnl_read_windows_credential(HVPNL_DEVELOPER_CRED_TARGET)
    if token:
        return token

    token = str(os.environ.get("HVPNL_GITHUB_TOKEN", "") or "").strip()
    if token:
        return token

    env_path = str(os.environ.get("HVPNL_GITHUB_TOKEN_FILE", "") or "").strip()
    if env_path:
        try:
            path = Path(env_path).expanduser()
            if path.exists():
                token = path.read_text(encoding="utf-8").strip()
                if token:
                    return token
        except Exception:
            pass

    # Backward-compatible developer-only file fallback. Never used by users.
    legacy = BASE_DIR / "hvpnl_github_token.txt"
    try:
        if legacy.exists():
            token = legacy.read_text(encoding="utf-8").strip()
            if token:
                return token
    except Exception:
        pass
    return ""


def hvpnl_store_developer_github_token(token):
    """Store the developer WRITE/PUBLISH PAT in Windows Credential Manager."""
    if os.name != "nt":
        raise OSError("Windows Credential Manager is available only on Windows.")
    token = str(token or "").strip()
    if not token:
        raise ValueError("A non-empty developer GitHub token is required.")

    import ctypes
    from ctypes import wintypes
    advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)

    class CREDENTIALW(ctypes.Structure):
        _fields_ = [
            ("Flags", wintypes.DWORD),
            ("Type", wintypes.DWORD),
            ("TargetName", wintypes.LPWSTR),
            ("Comment", wintypes.LPWSTR),
            ("LastWritten", wintypes.FILETIME),
            ("CredentialBlobSize", wintypes.DWORD),
            ("CredentialBlob", ctypes.POINTER(ctypes.c_ubyte)),
            ("Persist", wintypes.DWORD),
            ("AttributeCount", wintypes.DWORD),
            ("Attributes", ctypes.c_void_p),
            ("TargetAlias", wintypes.LPWSTR),
            ("UserName", wintypes.LPWSTR),
        ]

    CredWriteW = advapi32.CredWriteW
    CredWriteW.argtypes = [ctypes.POINTER(CREDENTIALW), wintypes.DWORD]
    CredWriteW.restype = wintypes.BOOL

    raw = token.encode("utf-8")
    blob = (ctypes.c_ubyte * len(raw)).from_buffer_copy(raw)
    cred = CREDENTIALW()
    cred.Flags = 0
    cred.Type = 1
    cred.TargetName = HVPNL_DEVELOPER_CRED_TARGET
    cred.Comment = "HVPNL Approval Search: Developer GitHub publish credential"
    cred.CredentialBlobSize = len(raw)
    cred.CredentialBlob = ctypes.cast(blob, ctypes.POINTER(ctypes.c_ubyte))
    cred.Persist = 2  # CRED_PERSIST_LOCAL_MACHINE
    cred.AttributeCount = 0
    cred.Attributes = None
    cred.TargetAlias = None
    cred.UserName = "HVPNL-developer-publisher"

    if not CredWriteW(ctypes.byref(cred), 0):
        err = ctypes.get_last_error()
        raise OSError(err, f"CredWriteW failed with Windows error {err}")
    return True


def _hvpnl_embedded_update_key(salt):
    if not CRYPTO_AVAILABLE:
        return None
    kdf = PBKDF2HMAC(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=200_000)
    return kdf.derive(HVPNL_EMBEDDED_UPDATE_KEY_MATERIAL)


def hvpnl_decrypt_embedded_update_token():
    blob_text = str(HVPNL_EMBEDDED_UPDATE_PAT_B64 or "").strip()
    if not blob_text or not CRYPTO_AVAILABLE:
        return ""
    try:
        raw = base64.b64decode(blob_text.encode("ascii"), validate=True)
        magic = b"HVPNL-EMBED-UPDATE\x01"
        if not raw.startswith(magic) or len(raw) < len(magic) + 16 + 12 + 16:
            return ""
        pos = len(magic)
        salt = raw[pos:pos+16]; pos += 16
        nonce = raw[pos:pos+12]; pos += 12
        key = _hvpnl_embedded_update_key(salt)
        token = AESGCM(key).decrypt(nonce, raw[pos:], magic).decode("utf-8").strip()
        if token:
            try:
                hvpnl_store_user_update_token(token)
            except Exception:
                pass
        return token
    except Exception:
        return ""


def hvpnl_get_user_update_token():
    """Return the end-user READ-ONLY GitHub update credential.

    Order: Windows Credential Manager, then the encrypted read-only credential
    embedded in the distributed EXE. The developer publishing credential is
    never consulted here.
    """
    token = _hvpnl_read_windows_credential(HVPNL_UPDATE_CRED_TARGET)
    if token:
        return token
    return hvpnl_decrypt_embedded_update_token()


# ---------------------------------------------------------------------------
# Remote user blocking / access revocation
# ---------------------------------------------------------------------------
# Only explicitly blocked machines are stored in this private GitHub JSON.
# Normal activation remains offline-capable. A successful online lookup clears
# a previously cached block; until then a cached block is enforced locally.
HVPNL_BLOCKED_USERS_PATH = "license/blocked_users.json"
HVPNL_BLOCKED_USERS_VERSION = 1
HVPNL_LOCAL_SECURITY_REG_PATH = r"Software\HVPNL Approval Search\AccessControl"


def _hvpnl_local_block_set(blocked=True, fingerprint="", reason=""):
    """Persist the last-known remote block in Windows Registry.

    This is an enforcement cache, not the authority. A remote unblock clears it.
    Non-Windows fallback uses a protected application-data file for development.
    """
    try:
        if os.name == "nt":
            import winreg
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER, HVPNL_LOCAL_SECURITY_REG_PATH) as key:
                winreg.SetValueEx(key, "Blocked", 0, winreg.REG_DWORD, 1 if blocked else 0)
                if blocked:
                    winreg.SetValueEx(key, "Fingerprint", 0, winreg.REG_SZ, str(fingerprint or "").upper())
                    winreg.SetValueEx(key, "BlockedAt", 0, winreg.REG_SZ, datetime.now().isoformat(timespec="seconds"))
                    winreg.SetValueEx(key, "Reason", 0, winreg.REG_SZ, str(reason or ""))
                else:
                    for name in ("Fingerprint", "BlockedAt", "Reason"):
                        try: winreg.DeleteValue(key, name)
                        except OSError: pass
            return True
        path = _activation_storage_dir() / "security_state.dat"
        if blocked:
            path.write_text(json.dumps({"blocked": True, "fingerprint": str(fingerprint or "").upper(), "reason": str(reason or "")}), encoding="utf-8")
        else:
            path.unlink(missing_ok=True)
        return True
    except Exception:
        return False


def _hvpnl_local_block_get():
    try:
        if os.name == "nt":
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, HVPNL_LOCAL_SECURITY_REG_PATH) as key:
                blocked = int(winreg.QueryValueEx(key, "Blocked")[0] or 0) == 1
                fp = str(winreg.QueryValueEx(key, "Fingerprint")[0] or "").upper() if blocked else ""
                reason = str(winreg.QueryValueEx(key, "Reason")[0] or "") if blocked else ""
                return blocked, fp, reason
        path = _activation_storage_dir() / "security_state.dat"
        if path.exists():
            d=json.loads(path.read_text(encoding="utf-8")); return bool(d.get("blocked")), str(d.get("fingerprint","")).upper(), str(d.get("reason",""))
    except Exception:
        pass
    return False, "", ""


def hvpnl_github_get_blocked_users(owner, repo, token):
    """Read license/blocked_users.json from the private repository."""
    try:
        data = hvpnl_github_api_json(owner, repo, token, f"contents/{urllib.parse.quote(HVPNL_BLOCKED_USERS_PATH, safe='/')}")
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            return {"version": HVPNL_BLOCKED_USERS_VERSION, "updated_at": "", "blocked_users": []}, None
        raise
    encoded = str(data.get("content", "") or "").replace("\\n", "").strip()
    try:
        registry = json.loads(base64.b64decode(encoded).decode("utf-8")) if encoded else {}
    except Exception as exc:
        raise RuntimeError(f"GitHub blocked_users.json is not valid JSON: {exc}")
    if not isinstance(registry, dict): raise RuntimeError("blocked_users.json must contain a JSON object.")
    users = registry.get("blocked_users", [])
    if not isinstance(users, list): raise RuntimeError("blocked_users must be a JSON array.")
    registry["blocked_users"] = users
    return registry, data.get("sha")


def hvpnl_github_save_blocked_users(users, message="Update HVPNL blocked users"):
    """Replace blocked_users.json using the developer-only GitHub credential."""
    token = hvpnl_get_github_token()
    if not token: raise RuntimeError("Developer GitHub write credential is not configured in Windows Credential Manager.")
    owner, repo = str(HVPNL_GITHUB_OWNER).strip(), str(HVPNL_GITHUB_REPO).strip()
    registry, sha = hvpnl_github_get_blocked_users(owner, repo, token)
    clean=[]; seen=set()
    for u in users:
        if not isinstance(u, dict): continue
        fp=str(u.get("fingerprint","")).strip().upper()
        if len(fp)!=64 or fp in seen: continue
        seen.add(fp)
        clean.append({
            "fingerprint": fp,
            "blocked_at": str(u.get("blocked_at") or datetime.now().isoformat(timespec="seconds")),
            "reason": str(u.get("reason") or "")
        })
    registry={"version":HVPNL_BLOCKED_USERS_VERSION,"updated_at":datetime.now().isoformat(timespec="seconds"),"blocked_users":clean}
    content=json.dumps(registry,indent=2,ensure_ascii=False)+"\n"
    payload={"message":message,"content":base64.b64encode(content.encode("utf-8")).decode("ascii")}
    if sha: payload["sha"]=sha
    result=hvpnl_github_api_json(owner,repo,token,f"contents/{urllib.parse.quote(HVPNL_BLOCKED_USERS_PATH,safe='/')}",method="PUT",payload=payload)
    return {"path":HVPNL_BLOCKED_USERS_PATH,"record_count":len(clean),"commit_sha":str(result.get("commit",{}).get("sha","") or ""),"blocked_users":clean}


def hvpnl_github_block_machine(fingerprint, reason=""):
    fp=str(fingerprint or "").strip().upper()
    if len(fp)!=64: raise ValueError("Machine fingerprint must be exactly 64 hexadecimal characters.")
    token=hvpnl_get_github_token()
    if not token: raise RuntimeError("Developer GitHub write credential is not configured.")
    registry, _ = hvpnl_github_get_blocked_users(HVPNL_GITHUB_OWNER,HVPNL_GITHUB_REPO,token)
    users=list(registry.get("blocked_users",[]))
    now=datetime.now().isoformat(timespec="seconds")
    found=False
    for u in users:
        if isinstance(u,dict) and str(u.get("fingerprint","")).upper()==fp:
            u["reason"]=str(reason or ""); u["blocked_at"]=str(u.get("blocked_at") or now); found=True; break
    if not found: users.append({"fingerprint":fp,"blocked_at":now,"reason":str(reason or "")})
    result=hvpnl_github_save_blocked_users(users, f"Block HVPNL machine {fp[:12]}")
    _hvpnl_local_block_set(True,fp,reason)
    return result


def hvpnl_github_unblock_machine(fingerprint):
    fp=str(fingerprint or "").strip().upper()
    token=hvpnl_get_github_token()
    if not token: raise RuntimeError("Developer GitHub write credential is not configured.")
    registry,_=hvpnl_github_get_blocked_users(HVPNL_GITHUB_OWNER,HVPNL_GITHUB_REPO,token)
    users=[u for u in registry.get("blocked_users",[]) if not (isinstance(u,dict) and str(u.get("fingerprint","")).upper()==fp)]
    result=hvpnl_github_save_blocked_users(users, f"Unblock HVPNL machine {fp[:12]}")
    if str(get_device_fingerprint()).upper()==fp: _hvpnl_local_block_set(False)
    return result


def hvpnl_remote_block_check(fingerprint=None):
    """Return (status, reason): True=blocked, False=not blocked, None=unknown/offline."""
    fp=str(fingerprint or get_device_fingerprint()).strip().upper()
    local_blocked, local_fp, local_reason = _hvpnl_local_block_get()
    if local_blocked and local_fp and local_fp==fp:
        # Fail closed until a successful online check proves the machine was unblocked.
        pass
    try:
        token=hvpnl_get_user_update_token()
        if not token: return (True if local_blocked else None, local_reason)
        registry,_=hvpnl_github_get_blocked_users(HVPNL_GITHUB_OWNER,HVPNL_GITHUB_REPO,token)
        for u in registry.get("blocked_users",[]):
            if isinstance(u,dict) and str(u.get("fingerprint","")).strip().upper()==fp:
                reason=str(u.get("reason") or "Licence revoked")
                _hvpnl_local_block_set(True,fp,reason)
                return True,reason
        # Successful online lookup and fingerprint absent = clear local block.
        _hvpnl_local_block_set(False)
        return False,""
    except Exception:
        return (True if local_blocked else None, local_reason)


class BlockedAccessDialog(QDialog):
    """Shown after a remote block. Developer/Admin access remains available."""
    def __init__(self, fingerprint, reason="", parent=None):
        super().__init__(parent); self.choice=None; self.fingerprint=fingerprint
        self.setWindowTitle("🔒 HVPNL Approval Search — Access Revoked"); self.setModal(True); self.setMinimumWidth(620)
        lay=QVBoxLayout(self); lay.setContentsMargins(24,24,24,24); lay.setSpacing(12)
        title=QLabel("🔒 Access Revoked"); title.setStyleSheet("font-size:24px;font-weight:800;"); lay.addWidget(title)
        msg=QLabel("Your access to this application has been revoked by the administrator.\n\nPlease contact the administrator if you believe this is an error.")
        msg.setWordWrap(True); lay.addWidget(msg)
        if reason: lay.addWidget(QLabel(f"Reason: {html.escape(reason)}"))
        retry=QPushButton("🔄 Retry"); retry.setMinimumHeight(42); retry.setToolTip("Check GitHub again. Access is restored only when the administrator has removed this machine from the block list.")
        dev=QPushButton("🛠 Developer / Admin"); dev.setMinimumHeight(42); dev.setToolTip("Administrator TOTP access is still available so the developer can unblock this PC.")
        exitb=QPushButton("Exit");
        lay.addWidget(retry); lay.addWidget(dev); lay.addWidget(exitb)
        retry.clicked.connect(self._retry); dev.clicked.connect(self._developer); exitb.clicked.connect(self.reject)
    def _retry(self):
        status,reason=hvpnl_remote_block_check(self.fingerprint)
        if status is False:
            self.choice="RETRY_OK"; QMessageBox.information(self,"Access Restored","Your access has been restored. The application will continue normally.",parent=self); self.accept()
        elif status is True:
            QMessageBox.warning(self,"Access Still Revoked",f"Your access is still blocked.\n\n{reason or 'Please contact the administrator.'}",parent=self)
        else:
            QMessageBox.warning(self,"Unable to Check","Could not connect to the licence block list. Internet access is required to verify whether the administrator has unblocked this PC.",parent=self)
    def _developer(self):
        dlg=DeveloperTOTPDialog(self)
        if dlg.exec()==QDialog.DialogCode.Accepted:
            self.choice="DEVELOPER"; self.accept()

def hvpnl_store_user_update_token(token):
    """Provision a READ-ONLY update PAT into Windows Credential Manager.

    This helper is intended for one-time administrative provisioning. It is
    not called automatically by the application and never writes a token file.
    """
    if os.name != "nt":
        raise OSError("Windows Credential Manager is available only on Windows.")
    token = str(token or "").strip()
    if not token:
        raise ValueError("A non-empty GitHub read-only token is required.")

    import ctypes
    from ctypes import wintypes
    advapi32 = ctypes.WinDLL("advapi32", use_last_error=True)

    class CREDENTIALW(ctypes.Structure):
        _fields_ = [
            ("Flags", wintypes.DWORD),
            ("Type", wintypes.DWORD),
            ("TargetName", wintypes.LPWSTR),
            ("Comment", wintypes.LPWSTR),
            ("LastWritten", wintypes.FILETIME),
            ("CredentialBlobSize", wintypes.DWORD),
            ("CredentialBlob", ctypes.POINTER(ctypes.c_ubyte)),
            ("Persist", wintypes.DWORD),
            ("AttributeCount", wintypes.DWORD),
            ("Attributes", ctypes.c_void_p),
            ("TargetAlias", wintypes.LPWSTR),
            ("UserName", wintypes.LPWSTR),
        ]

    CredWriteW = advapi32.CredWriteW
    CredWriteW.argtypes = [ctypes.POINTER(CREDENTIALW), wintypes.DWORD]
    CredWriteW.restype = wintypes.BOOL

    raw = token.encode("utf-8")
    blob = (ctypes.c_ubyte * len(raw)).from_buffer_copy(raw)
    cred = CREDENTIALW()
    cred.Flags = 0
    cred.Type = 1  # CRED_TYPE_GENERIC
    cred.TargetName = HVPNL_UPDATE_CRED_TARGET
    cred.Comment = "HVPNL Approval Search: GitHub read-only update credential"
    cred.CredentialBlobSize = len(raw)
    cred.CredentialBlob = ctypes.cast(blob, ctypes.POINTER(ctypes.c_ubyte))
    cred.Persist = 2  # CRED_PERSIST_LOCAL_MACHINE
    cred.AttributeCount = 0
    cred.Attributes = None
    cred.TargetAlias = None
    cred.UserName = "HVPNL-update-read-only"

    if not CredWriteW(ctypes.byref(cred), 0):
        err = ctypes.get_last_error()
        raise OSError(err, f"Windows Credential Manager CredWrite failed (WinError {err}).")
    return True


def hvpnl_github_request(owner, repo, token, endpoint, accept="application/vnd.github+json"):
    url = f"{HVPNL_GITHUB_API}/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/{endpoint.lstrip('/')}"
    req = urllib.request.Request(
        url,
        headers={
            "Accept": accept,
            "Authorization": f"Bearer {token}",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "HVPNL-Approval-Search-Updater",
        },
        method="GET",
    )
    with urllib.request.urlopen(req, timeout=45) as response:
        return response.read()


def hvpnl_github_json(owner, repo, token, endpoint):
    return json.loads(hvpnl_github_request(owner, repo, token, endpoint).decode("utf-8"))


def hvpnl_github_api_json(owner, repo, token, endpoint, method="GET", payload=None):
    """Call a GitHub JSON API endpoint for developer publishing."""
    url = f"{HVPNL_GITHUB_API}/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/{endpoint.lstrip('/')}"
    data = None if payload is None else json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=data,
        headers={
            "Accept": "application/vnd.github+json",
            "Authorization": f"Bearer {token}",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "HVPNL-Approval-Search-Developer",
            "Content-Type": "application/json",
        },
        method=method,
    )
    with urllib.request.urlopen(req, timeout=60) as response:
        raw = response.read()
    return json.loads(raw.decode("utf-8")) if raw else {}



# ---------------------------------------------------------------------------
# Developer licence registry on the private GitHub repository
# ---------------------------------------------------------------------------
# The developer application may explicitly publish an activation record to a
# single JSON file in the private repository.  The GitHub WRITE credential is
# obtained only from the developer machine's Windows Credential Manager (or
# the existing developer-only environment/file fallbacks).  It is never
# embedded in the distributed user application.
HVPNL_LICENSE_REGISTRY_PATH = "license/users.json"
HVPNL_LICENSE_REGISTRY_VERSION = 1


def hvpnl_github_get_license_registry(owner, repo, token):
    """Read the single developer-managed licence registry JSON.

    Returns (registry, sha).  A missing file is treated as an empty registry.
    """
    try:
        data = hvpnl_github_api_json(
            owner, repo, token,
            f"contents/{urllib.parse.quote(HVPNL_LICENSE_REGISTRY_PATH, safe='/')}"
        )
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            return {
                "version": HVPNL_LICENSE_REGISTRY_VERSION,
                "updated_at": "",
                "users": [],
            }, None
        raise

    encoded = str(data.get("content", "") or "").replace("\\n", "").strip()
    if not encoded:
        registry = {"version": HVPNL_LICENSE_REGISTRY_VERSION, "updated_at": "", "users": []}
    else:
        try:
            raw = base64.b64decode(encoded).decode("utf-8")
            registry = json.loads(raw)
        except Exception as exc:
            raise RuntimeError(f"GitHub licence registry is not valid JSON: {exc}")

    if not isinstance(registry, dict):
        raise RuntimeError("GitHub licence registry must contain a JSON object.")
    users = registry.get("users", [])
    if not isinstance(users, list):
        raise RuntimeError("GitHub licence registry field 'users' must be a JSON array.")
    registry["version"] = int(registry.get("version", HVPNL_LICENSE_REGISTRY_VERSION) or HVPNL_LICENSE_REGISTRY_VERSION)
    registry["users"] = users
    return registry, data.get("sha")


def hvpnl_github_post_activation(payload, activation_code, remarks="", status="Activated"):
    """Add/update one activation record in the private GitHub users.json.

    One machine fingerprint represents one current licence entry.  Renewing or
    re-issuing a licence for the same PC updates that record instead of creating
    duplicate rows.  The complete signed activation code is retained because
    this is a private administrator-only registry.
    """
    token = hvpnl_get_github_token()
    if not token:
        raise RuntimeError(
            "Developer GitHub credential is not configured.\n\n"
            "Configure the developer GitHub write token in Windows Credential "
            "Manager using the existing developer publishing setup."
        )

    owner = str(HVPNL_GITHUB_OWNER or "").strip()
    repo = str(HVPNL_GITHUB_REPO or "").strip()
    if not owner or not repo:
        raise RuntimeError("GitHub owner/repository is not configured.")

    fp = str(payload.get("fingerprint", "") or "").strip().upper()
    licence_id = str(payload.get("licence_id", "") or "").strip()
    if len(fp) != 64:
        raise ValueError("The activation payload does not contain a valid 64-character fingerprint.")
    if not licence_id:
        raise ValueError("The activation payload does not contain a licence ID.")

    registry, sha = hvpnl_github_get_license_registry(owner, repo, token)
    users = list(registry.get("users", []))

    record = {
        "licence_id": licence_id,
        "user_name": str(payload.get("user_name", "") or ""),
        "organisation": str(payload.get("organisation", "") or ""),
        "fingerprint": fp,
        "activation_code": "".join(str(activation_code or "").split()),
        "status": str(status or "Activated").strip() or "Activated",
        "issued_at": str(payload.get("issued_at", "") or ""),
        "expires_on": str(payload.get("expires_on", "") or ""),
        "days": int(payload.get("days", 0) or 0),
        "role": str(payload.get("role", "USER") or "USER"),
        "remarks": str(remarks or ""),
        "updated_at": datetime.now().isoformat(timespec="seconds"),
    }

    # Match by fingerprint first (same physical installation), then licence ID.
    existing_index = None
    for i, old in enumerate(users):
        if not isinstance(old, dict):
            continue
        old_fp = str(old.get("fingerprint", "") or "").strip().upper()
        old_id = str(old.get("licence_id", "") or "").strip()
        if old_fp == fp or old_id == licence_id:
            existing_index = i
            break

    if existing_index is None:
        users.append(record)
        action = "added"
    else:
        users[existing_index] = record
        action = "updated"

    registry["version"] = HVPNL_LICENSE_REGISTRY_VERSION
    registry["updated_at"] = datetime.now().isoformat(timespec="seconds")
    registry["users"] = users

    content = json.dumps(registry, indent=2, ensure_ascii=False, sort_keys=False) + "\n"
    encoded = base64.b64encode(content.encode("utf-8")).decode("ascii")
    payload_api = {
        "message": f"Register HVPNL activation {licence_id}",
        "content": encoded,
    }
    if sha:
        payload_api["sha"] = sha

    result = hvpnl_github_api_json(
        owner, repo, token,
        f"contents/{urllib.parse.quote(HVPNL_LICENSE_REGISTRY_PATH, safe='/')}",
        method="PUT",
        payload=payload_api,
    )
    return {
        "action": action,
        "licence_id": licence_id,
        "path": HVPNL_LICENSE_REGISTRY_PATH,
        "commit_sha": str(result.get("commit", {}).get("sha", "") or ""),
        "record_count": len(users),
    }

class _HVPNLProgressFile:
    """Stream a local file while reporting upload progress."""
    def __init__(self, path, callback=None):
        self.path = Path(path)
        self.fp = self.path.open("rb")
        self.total = self.path.stat().st_size
        self.sent = 0
        self.callback = callback
        self._last_emit = -1

    def read(self, size=-1):
        data = self.fp.read(size)
        if data:
            self.sent += len(data)
            if self.callback:
                pct = int((self.sent * 100) / self.total) if self.total else 100
                if pct != self._last_emit or self.sent == self.total:
                    self._last_emit = pct
                    self.callback(self.sent, self.total)
        return data

    def close(self):
        try:
            self.fp.close()
        except Exception:
            pass


def hvpnl_github_upload_asset(owner, repo, token, release_id, path, progress_callback=None):
    """Stream one release asset to GitHub with byte-level progress reporting."""
    path = Path(path)
    parsed = urllib.parse.urlsplit(
        f"https://uploads.github.com/repos/{urllib.parse.quote(owner)}/"
        f"{urllib.parse.quote(repo)}/releases/{int(release_id)}/assets"
        f"?name={urllib.parse.quote(path.name)}"
    )
    request_path = parsed.path + (("?" + parsed.query) if parsed.query else "")

    conn = http.client.HTTPSConnection(
        parsed.hostname, parsed.port or 443, timeout=600
    )
    pf = _HVPNLProgressFile(path, progress_callback)
    try:
        conn.putrequest("POST", request_path)
        conn.putheader("Accept", "application/vnd.github+json")
        conn.putheader("Authorization", f"Bearer {token}")
        conn.putheader("X-GitHub-Api-Version", "2022-11-28")
        conn.putheader("User-Agent", "HVPNL-Approval-Search-Developer")
        conn.putheader("Content-Type", "application/octet-stream")
        conn.putheader("Content-Length", str(pf.total))
        conn.endheaders()

        while True:
            chunk = pf.read(1024 * 1024)
            if not chunk:
                break
            conn.send(chunk)

        response = conn.getresponse()
        raw = response.read()
        if response.status < 200 or response.status >= 300:
            detail = raw.decode("utf-8", errors="replace")[:1500]
            raise RuntimeError(
                f"GitHub asset upload failed (HTTP {response.status}). {detail}"
            )
        return json.loads(raw.decode("utf-8")) if raw else {}
    finally:
        pf.close()
        conn.close()



# V41 GitHub distribution policy: only these three release assets are valid.
# index.db (and the old hvpnl_index.db name) are explicitly local-only and
# must never be uploaded, displayed as managed update assets, or referenced
# by the published update manifest.
HVPNL_GITHUB_ALLOWED_ASSETS = {
    "HVPNL-Approval-Search.exe",
    "MASTER.db",
    HVPNL_UPDATE_MANIFEST_NAME,
}
HVPNL_GITHUB_LOCAL_ONLY_ASSETS = {"index.db", "hvpnl_index.db"}

def hvpnl_sanitize_github_manifest(obj):
    """Return a GitHub update manifest with all index.db distribution data removed.

    This also makes the updater tolerant of older releases whose update.json
    still contains an obsolete 'index' section. The returned manifest never
    exposes that section to update-selection logic.
    """
    if not isinstance(obj, dict):
        return {}
    cleaned = dict(obj)
    cleaned.pop("index", None)
    cleaned.pop("index_version", None)
    cleaned.pop("index_sha256", None)
    cleaned.pop("index_asset", None)
    cleaned.pop("index_db", None)
    assets = cleaned.get("_github_release_assets")
    if isinstance(assets, dict):
        cleaned["_github_release_assets"] = {
            str(name): asset for name, asset in assets.items()
            if str(name).strip().lower() not in HVPNL_GITHUB_LOCAL_ONLY_ASSETS
        }
    notes = str(cleaned.get("release_notes") or "").strip()
    if notes:
        # Remove legacy wording from manifests generated by pre-V41 builds.
        notes = re.sub(r"\s*index\.db(?:\s+(?:updated|published|uploaded))?[^.]*\.?", " ", notes, flags=re.I)
        notes = re.sub(r"\s+", " ", notes).strip()
        cleaned["release_notes"] = notes
    return cleaned


def hvpnl_github_publish_preview(owner, repo, token, current):
    """Read-only preview for the GitHub release model.

    V41 architecture:
      * GitHub manages ONLY the application EXE and MASTER.db.
      * index.db is a disposable local search cache and is NEVER published.
      * A MASTER.db update is enough to make the user rebuild index.db locally.
    """
    latest = hvpnl_github_latest_managed_release(owner, repo, token)
    next_tag = hvpnl_github_next_release_tag(owner, repo, token)

    latest_manifest = {}
    if latest:
        manifest_asset = next(
            (a for a in latest.get("assets", [])
             if a.get("name") == HVPNL_UPDATE_MANIFEST_NAME), None
        )
        if manifest_asset:
            raw = hvpnl_download_github_asset(owner, repo, token, manifest_asset)
            latest_manifest = json.loads(raw.decode("utf-8-sig"))
            if not isinstance(latest_manifest, dict):
                latest_manifest = {}
            latest_manifest = hvpnl_sanitize_github_manifest(latest_manifest)

    def plain_hash(runtime_path):
        p = Path(runtime_path)
        if not p.exists():
            return ""
        return hashlib.sha256(p.read_bytes()).hexdigest()

    current_master_hash = plain_hash(MASTER_DB_PATH)
    old_master = (latest_manifest.get("master") or {}) if latest_manifest else {}
    old_app = (latest_manifest.get("app") or {}) if latest_manifest else {}

    first_release = latest is None
    master_changed = (
        first_release or
        current_master_hash.lower() !=
        str(old_master.get("plain_sha256") or "").strip().lower()
    )
    old_app_version = str(old_app.get("version") or "v0.0")
    app_changed = (
        first_release or
        hvpnl_version_tuple(current["app_version"]) >
        hvpnl_version_tuple(old_app_version)
    )

    current_master = str(current["master_version"])
    # V43: NEVER invent or silently bump the MASTER.db version. The Developer
    # explicitly chooses the release version at publish time. The preview
    # therefore shows the currently embedded version only.
    proposed_master = current_master
    proposed_app = current["app_version"]
    any_changed = app_changed or master_changed
    if not any_changed:
        next_tag = latest.get("tag_name") if latest else "v0.1"

    return {
        "latest_tag": latest.get("tag_name") if latest else "none",
        "next_tag": next_tag,
        "app_current": current["app_version"],
        "master_current": current_master,
        "app_proposed": proposed_app,
        "master_proposed": proposed_master,
        "app_changed": app_changed,
        "master_changed": master_changed,
        "any_changed": any_changed,
    }


class HVPNLGitHubPublishWorker(QObject):
    """Runs GitHub publishing outside the GUI thread."""
    status = Signal(str)
    progress = Signal(int, int, str)
    finished = Signal(object)
    failed = Signal(str)

    def __init__(self, job):
        super().__init__()
        self.job = job

    def run(self):
        try:
            result = self.job(self.status.emit, self.progress.emit)
            self.finished.emit(result)
        except Exception as exc:
            self.failed.emit(str(exc))



def hvpnl_github_managed_releases(owner, repo, token):
    """Return releases using the new two-part v0.1/v0.2... scheme only."""
    releases = []
    for page in range(1, 6):
        data = hvpnl_github_api_json(owner, repo, token, f"releases?per_page=100&page={page}")
        if not data:
            break
        releases.extend(data)
        if len(data) < 100:
            break
    managed=[]
    for rel in releases:
        tag=str(rel.get("tag_name") or "").strip()
        if re.fullmatch(r"v\d+\.\d+", tag) and not rel.get("draft") and not rel.get("prerelease"):
            managed.append(rel)
    managed.sort(key=lambda r: hvpnl_version_tuple(r.get("tag_name")), reverse=True)
    return managed


def hvpnl_github_list_release_assets(owner, repo, token):
    """Return the assets published in the latest managed GitHub release.

    Used only by the Developer Control Centre. It is read-only and does not
    expose or modify repository contents.
    """
    release = hvpnl_github_latest_managed_release(owner, repo, token)
    if not release:
        return None, []
    assets = []
    for asset in release.get("assets", []) or []:
        name = str(asset.get("name") or "").strip()
        if not name:
            continue
        if name.lower() in HVPNL_GITHUB_LOCAL_ONLY_ASSETS:
            continue
        if name not in HVPNL_GITHUB_ALLOWED_ASSETS:
            # Keep the developer asset viewer focused on the current managed
            # distribution model; unrelated release attachments are ignored.
            continue
        assets.append({
            "name": name,
            "size": int(asset.get("size") or 0),
            "download_count": int(asset.get("download_count") or 0),
            "created_at": str(asset.get("created_at") or ""),
            "updated_at": str(asset.get("updated_at") or ""),
            "content_type": str(asset.get("content_type") or ""),
            "browser_download_url": str(asset.get("browser_download_url") or ""),
        })
    return release, assets


def hvpnl_github_latest_managed_release(owner, repo, token):
    releases = hvpnl_github_managed_releases(owner, repo, token)
    return releases[0] if releases else None


def hvpnl_github_next_release_tag(owner, repo, token):
    latest = hvpnl_github_latest_managed_release(owner, repo, token)
    if not latest:
        return "v0.1"
    ver=hvpnl_version_tuple(latest.get("tag_name"))
    major, minor = (list(ver)+[0,0])[:2]
    return f"v{major}.{minor+1}"


def hvpnl_bump_component_version(value):
    ver=hvpnl_version_tuple(value)
    major, minor=(list(ver)+[0,0])[:2]
    return f"v{major}.{minor+1}"


def hvpnl_github_asset_request(owner, repo, token, asset):
    asset_id = asset.get("id")
    if not asset_id:
        raise ValueError("GitHub release asset has no asset ID.")
    url = f"{HVPNL_GITHUB_API}/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/releases/assets/{int(asset_id)}"
    return urllib.request.Request(
        url,
        headers={
            "Accept": "application/octet-stream",
            "Authorization": f"Bearer {token}",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "HVPNL-Approval-Search-Updater",
        },
        method="GET",
    )


def hvpnl_download_github_asset(owner, repo, token, asset):
    """Download a small GitHub release asset into memory (e.g. update.json)."""
    req = hvpnl_github_asset_request(owner, repo, token, asset)
    with urllib.request.urlopen(req, timeout=180) as response:
        return response.read()


def hvpnl_download_github_asset_to_file(owner, repo, token, asset, target,
                                        progress_callback=None, cancel_event=None):
    """Stream a GitHub release asset directly to disk.

    This function is intended for large EXE/DB update assets. It never keeps
    the complete file in RAM and reports progress while downloading.
    """
    req = hvpnl_github_asset_request(owner, repo, token, asset)
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    temp_target = target.with_name(target.name + ".part")
    expected_size = int(asset.get("size") or 0)
    downloaded = 0
    started = time.monotonic()
    last_emit = 0.0

    try:
        with urllib.request.urlopen(req, timeout=180) as response, open(temp_target, "wb") as out:
            while True:
                if cancel_event is not None and cancel_event.is_set():
                    raise InterruptedError("Update download cancelled by user.")
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                out.write(chunk)
                downloaded += len(chunk)
                now = time.monotonic()
                if progress_callback and (now - last_emit >= 0.08 or (expected_size and downloaded >= expected_size)):
                    elapsed = max(now - started, 0.001)
                    speed = downloaded / elapsed
                    eta = ((expected_size - downloaded) / speed) if expected_size and speed > 0 else None
                    progress_callback(downloaded, expected_size, speed, eta)
                    last_emit = now

        if expected_size and temp_target.stat().st_size != expected_size:
            raise IOError(
                f"Downloaded asset size mismatch: {asset.get('name', target.name)} "
                f"({temp_target.stat().st_size} of {expected_size} bytes)."
            )
        temp_target.replace(target)
        if progress_callback:
            elapsed = max(time.monotonic() - started, 0.001)
            speed = downloaded / elapsed
            progress_callback(downloaded, expected_size or downloaded, speed, 0.0)
        return target
    except Exception:
        try:
            temp_target.unlink(missing_ok=True)
        except Exception:
            pass
        raise


def hvpnl_sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def hvpnl_sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def hvpnl_wait_for_pid_exit(pid, timeout=90):
    if not pid:
        return True
    if os.name != "nt":
        deadline = time.time() + timeout
        while time.time() < deadline:
            try:
                os.kill(int(pid), 0)
                time.sleep(0.25)
            except OSError:
                return True
        return False
    import ctypes
    SYNCHRONIZE = 0x00100000
    WAIT_OBJECT_0 = 0x00000000
    WAIT_TIMEOUT = 0x00000102
    handle = ctypes.windll.kernel32.OpenProcess(SYNCHRONIZE, False, int(pid))
    if not handle:
        return True
    try:
        result = ctypes.windll.kernel32.WaitForSingleObject(handle, int(timeout * 1000))
        return result == WAIT_OBJECT_0
    finally:
        ctypes.windll.kernel32.CloseHandle(handle)


def hvpnl_encrypt_database_plain(plain):
    # Keep this format identical to EncryptedDatabaseStore.
    if not CRYPTO_AVAILABLE:
        raise RuntimeError("cryptography is required for database updates.")
    magic = b"HVPNLDB1"
    version = b"\x01"
    salt = secrets.token_bytes(16)
    nonce = secrets.token_bytes(12)
    key = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=250000,
    ).derive(EncryptedDatabaseStore.APP_SECRET)
    cipher = AESGCM(key).encrypt(nonce, plain, magic + version)
    return magic + version + salt + nonce + cipher


def hvpnl_decrypt_database_raw(raw):
    if raw.startswith(b"SQLite format 3\x00"):
        return raw
    magic = b"HVPNLDB1"
    version = b"\x01"
    if not raw.startswith(magic + version):
        raise RuntimeError("Unsupported HVPNL database format.")
    pos = len(magic) + 1
    salt, nonce, cipher = raw[pos:pos+16], raw[pos+16:pos+28], raw[pos+28:]
    key = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=250000,
    ).derive(EncryptedDatabaseStore.APP_SECRET)
    return AESGCM(key).decrypt(nonce, cipher, magic + version)


def hvpnl_apply_sqlite_patch(storage_path, patch_path, expected_from_version=""):
    storage_path = Path(storage_path)
    patch = json.loads(Path(patch_path).read_text(encoding="utf-8"))
    raw = storage_path.read_bytes()
    plain = hvpnl_decrypt_database_raw(raw)
    base_hash = hashlib.sha256(plain).hexdigest().lower()
    expected_base = str(patch.get("base_plain_sha256") or "").lower()
    if expected_base and base_hash != expected_base:
        raise RuntimeError("Database does not match the patch base version.")
    if expected_from_version and str(patch.get("from_version")) != str(expected_from_version):
        raise RuntimeError("Patch source version does not match the installed database version.")

    work = Path(tempfile.mkstemp(prefix="hvpnl_patch_", suffix=".db")[1])
    try:
        work.write_bytes(plain)
        con = sqlite3.connect(str(work))
        con.execute("PRAGMA foreign_keys=ON")
        try:
            con.execute("BEGIN IMMEDIATE")
            for op in patch.get("operations", []):
                typ = op.get("op")
                if typ in ("fts_delete", "fts_upsert"):
                    if typ == "fts_delete":
                        con.execute("DELETE FROM documents_fts WHERE rowid=?", (op["document_id"],))
                    else:
                        row = [hvpnl_restore_patch_value(x) for x in op["row"]]
                        fcols = [r[1] for r in con.execute('PRAGMA table_info("documents_fts")').fetchall()]
                        con.execute("DELETE FROM documents_fts WHERE rowid=?", (row[0],))
                        cols_sql = ",".join(["rowid"] + [f'"{c}"' for c in fcols])
                        placeholders = ",".join("?" for _ in row)
                        con.execute(f"INSERT INTO documents_fts({cols_sql}) VALUES ({placeholders})", row)
                    continue

                table = str(op.get("table") or "")
                if not table:
                    raise RuntimeError("Patch contains an operation without a table.")
                info = con.execute(f'PRAGMA table_info("{table}")').fetchall()
                cols = [r[1] for r in info]
                pkcols = [r[1] for r in sorted(info, key=lambda r: r[5]) if r[5]]
                if not pkcols:
                    raise RuntimeError(f"Patch table has no primary key: {table}")
                where = " AND ".join(f'"{c}"=?' for c in pkcols)

                if typ == "delete":
                    pk = [hvpnl_restore_patch_value(x) for x in op["pk"]]
                    con.execute(f'DELETE FROM "{table}" WHERE {where}', pk)
                elif typ == "insert":
                    vals = [hvpnl_restore_patch_value(x) for x in op["row"]]
                    colsql = ",".join(f'"{c}"' for c in cols)
                    placeholders = ",".join("?" for _ in cols)
                    con.execute(f'INSERT INTO "{table}" ({colsql}) VALUES ({placeholders})', vals)
                elif typ == "update":
                    vals = [hvpnl_restore_patch_value(x) for x in op["row"]]
                    pk = [hvpnl_restore_patch_value(x) for x in op["pk"]]
                    assignments = ",".join(f'"{c}"=?' for c in cols)
                    con.execute(f'UPDATE "{table}" SET {assignments} WHERE {where}', vals + pk)
                else:
                    raise RuntimeError(f"Unsupported patch operation: {typ}")

            con.commit()
            try:
                con.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            except Exception:
                pass
            integrity = con.execute("PRAGMA integrity_check").fetchone()[0]
            if str(integrity).lower() != "ok":
                raise RuntimeError(f"SQLite integrity check failed: {integrity}")
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()

        result_plain = work.read_bytes()
        target_hash = str(patch.get("target_plain_sha256") or "").lower()
        if target_hash and hashlib.sha256(result_plain).hexdigest().lower() != target_hash:
            raise RuntimeError("Patched database failed target hash verification.")

        encrypted = hvpnl_encrypt_database_plain(result_plain)
        temp_target = storage_path.with_suffix(storage_path.suffix + ".update.tmp")
        backup = storage_path.with_suffix(storage_path.suffix + ".update.bak")
        temp_target.write_bytes(encrypted)

        # Keep a rollback copy until the complete update succeeds.
        shutil.copy2(storage_path, backup)
        os.replace(temp_target, storage_path)
        backup.unlink(missing_ok=True)
    finally:
        work.unlink(missing_ok=True)


def hvpnl_restore_patch_value(value):
    if isinstance(value, dict) and "__bytes__" in value:
        return base64.b64decode(value["__bytes__"])
    return value


def hvpnl_install_full_database(storage_path, downloaded_path, expected_sha256="", expected_component_version=""):
    storage_path = Path(storage_path)
    downloaded_path = Path(downloaded_path)
    if expected_sha256 and hvpnl_sha256_file(downloaded_path).lower() != expected_sha256.lower():
        raise RuntimeError(f"SHA-256 verification failed for {storage_path.name}.")
    # Validate both encrypted format and SQLite contents before replacing.
    raw = downloaded_path.read_bytes()
    plain = hvpnl_decrypt_database_raw(raw)
    test = Path(tempfile.mkstemp(prefix="hvpnl_verify_", suffix=".db")[1])
    try:
        test.write_bytes(plain)
        con = sqlite3.connect(str(test))
        try:
            result = con.execute("PRAGMA integrity_check").fetchone()[0]
            if str(result).lower() != "ok":
                raise RuntimeError(f"SQLite integrity check failed: {result}")
            if expected_component_version:
                row = con.execute("SELECT version FROM hvpnl_component_metadata WHERE component='master'").fetchone()
                actual_version = str(row[0]).strip() if row and row[0] is not None else ""
                if actual_version != str(expected_component_version).strip():
                    raise RuntimeError(
                        f"MASTER.db internal version mismatch: expected {expected_component_version}, "
                        f"downloaded database contains {actual_version or 'no master version'}"
                    )
        finally:
            con.close()
    finally:
        test.unlink(missing_ok=True)

    temp_target = storage_path.with_suffix(storage_path.suffix + ".update.tmp")
    backup = storage_path.with_suffix(storage_path.suffix + ".update.bak")
    shutil.copy2(downloaded_path, temp_target)
    shutil.copy2(storage_path, backup)
    os.replace(temp_target, storage_path)
    backup.unlink(missing_ok=True)


def hvpnl_atomic_replace_exe(current_exe, new_exe):
    current_exe = Path(current_exe)
    new_exe = Path(new_exe)
    backup = current_exe.with_suffix(current_exe.suffix + ".old")
    shutil.copy2(current_exe, backup)
    try:
        os.replace(new_exe, current_exe)
        backup.unlink(missing_ok=True)
    except Exception:
        if backup.exists():
            try:
                os.replace(backup, current_exe)
            except Exception:
                pass
        raise


def hvpnl_run_self_update(plan_path, parent_pid):
    plan_path = Path(plan_path)
    plan = json.loads(plan_path.read_text(encoding="utf-8"))
    base_dir = Path(plan.get("base_dir") or Path(sys.executable).resolve().parent)
    current_exe = Path(plan.get("current_exe") or sys.executable).resolve()
    updater_exe = Path(plan.get("updater_exe") or sys.executable).resolve()
    temp_dir = Path(plan.get("temp_dir") or plan_path.parent)
    log_path = temp_dir / "update.log"

    def log(message):
        try:
            with log_path.open("a", encoding="utf-8") as f:
                f.write(datetime.now().isoformat(timespec="seconds") + " " + str(message) + "\n")
        except Exception:
            pass

    try:
        log("Waiting for main application to exit.")
        if not hvpnl_wait_for_pid_exit(parent_pid, timeout=120):
            raise RuntimeError("The main application did not close in time.")
        time.sleep(0.8)

        # Apply database components first. The main application has already
        # synchronized its encrypted runtime databases in closeEvent().
        for item in plan.get("components", []):
            kind = item.get("kind")
            storage = base_dir / str(item["storage"])
            payload = Path(item["asset_path"])
            log(f"Applying {item.get('component')} ({kind}).")
            if kind == "db_patch":
                hvpnl_apply_sqlite_patch(storage, payload, item.get("from_version", ""))
            elif kind == "db_full":
                hvpnl_install_full_database(
                    storage, payload, item.get("sha256", ""),
                    item.get("to_version", "") if item.get("component") == "master" else ""
                )
            elif kind == "app":
                hvpnl_atomic_replace_exe(current_exe, payload)
            else:
                raise RuntimeError(f"Unknown update component: {kind}")

        log("Update completed. Restarting application.")
        restart_command = plan.get("restart_command")
        if not restart_command:
            restart_command = [str(current_exe)]
        subprocess.Popen(restart_command, cwd=str(base_dir), close_fds=True)
        # The temporary helper EXE is still running, so schedule its deletion
        # after this updater process exits. This is only a transient process;
        # nothing extra is installed with the application.
        try:
            if os.name == "nt" and updater_exe.exists():
                subprocess.Popen(
                    ["cmd.exe", "/d", "/c", f'ping 127.0.0.1 -n 3 >nul & del /f /q "{updater_exe}"'],
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                    close_fds=True,
                )
        except Exception:
            pass
        return 0
    except Exception as exc:
        log("UPDATE FAILED: " + repr(exc))
        # Try to start the existing application so a failed update does not
        # leave the user without the program.
        try:
            restart_command = plan.get("restart_command")
            if not restart_command:
                restart_command = [str(current_exe)]
            subprocess.Popen(restart_command, cwd=str(base_dir), close_fds=True)
        except Exception:
            pass
        return 1
    finally:
        try:
            # Delay cleanup because this process may still need the files.
            cleanup = [Path(x) for x in (plan.get("cleanup") or [])]
            cleanup.append(plan_path)
            for p in cleanup:
                try:
                    if p.exists():
                        p.unlink()
                except Exception:
                    pass
        except Exception:
            pass

def hvpnl_version_tuple(value):
    return tuple(int(x) for x in re.findall(r"\d+", str(value or ""))[:8]) or (0,)



def hvpnl_read_component_metadata_version(db_path, component, fallback):
    """Read the version from the actual runtime SQLite database."""
    try:
        path = Path(db_path)
        if not path.exists():
            return str(fallback)

        con = sqlite3.connect(str(path), timeout=10)
        try:
            tables = {
                str(r[0]) for r in con.execute(
                    "SELECT name FROM sqlite_master "
                    "WHERE type='table' AND name NOT LIKE 'sqlite_%'"
                ).fetchall()
            }

            if "hvpnl_component_metadata" in tables:
                row = con.execute(
                    "SELECT version FROM hvpnl_component_metadata "
                    "WHERE component=?",
                    (str(component),),
                ).fetchone()
                if row and row[0] is not None and str(row[0]).strip():
                    return str(row[0]).strip()

        finally:
            con.close()
    except Exception:
        pass

    return str(fallback)


def hvpnl_set_component_version(db_path, component, version):
    """Store a component version inside the runtime SQLite database."""
    version = str(version or "").strip()
    if not re.fullmatch(r"v\d+\.\d+", version):
        raise ValueError(f"Invalid {component} version: {version}")

    con = sqlite3.connect(str(db_path), timeout=30)
    try:
        con.execute(
            "CREATE TABLE IF NOT EXISTS hvpnl_component_metadata ("
            "component TEXT PRIMARY KEY, version TEXT NOT NULL)"
        )
        con.execute(
            "INSERT INTO hvpnl_component_metadata(component, version) "
            "VALUES (?, ?) "
            "ON CONFLICT(component) DO UPDATE SET version=excluded.version",
            (str(component), version),
        )
        con.commit()
    finally:
        con.close()


def hvpnl_initialize_component_versions():
    """Initialize missing metadata without changing an existing version."""
    if MASTER_STORAGE_AVAILABLE and Path(MASTER_DB_PATH).exists():
        current = hvpnl_read_component_metadata_version(
            MASTER_DB_PATH, "master", ""
        )
        if not current:
            hvpnl_set_component_version(
                MASTER_DB_PATH, "master", MASTER_DB_VERSION
            )

    if Path(INDEX_DB_PATH).exists():
        current = hvpnl_read_component_metadata_version(
            INDEX_DB_PATH, "index", ""
        )
        if not current:
            hvpnl_set_component_version(
                INDEX_DB_PATH, "index", INDEX_DB_VERSION
            )


def hvpnl_get_installed_component_versions():
    """Return the authoritative versions of the running components."""
    return {
        "app_version": str(APP_BUILD_VERSION),
        "master_version": hvpnl_read_component_metadata_version(
            MASTER_DB_PATH, "master", MASTER_DB_VERSION
        ),
        "index_version": hvpnl_read_component_metadata_version(
            INDEX_DB_PATH, "index", INDEX_DB_VERSION
        ),
    }



def hvpnl_read_update_info():

    """Read update.json from the latest release of a private GitHub repo.

    The repository name is harmless to embed; the GitHub credential is NOT.
    The end-user update token is read from Windows Credential Manager. The
    token should be a separate fine-grained PAT with only read access to this
    repository; the developer publishing PAT is never used here.
    """
    owner = str(globals().get("HVPNL_GITHUB_OWNER", "") or "").strip()
    repo = str(globals().get("HVPNL_GITHUB_REPO", "") or "").strip()
    if not owner or not repo:
        return None, "Private GitHub update repository is not configured."
    try:
        token = hvpnl_get_user_update_token()
        if not token:
            return None, (
                "GitHub update credential is not configured on this PC.\n\n"
                "A READ-ONLY GitHub PAT must be provisioned in Windows Credential Manager "
                f"under: {HVPNL_UPDATE_CRED_TARGET}"
            )
        release = hvpnl_github_latest_managed_release(owner, repo, token)
        if not release:
            return None, "No v0.x GitHub release is published yet."
        manifest_asset = next((a for a in release.get("assets", []) if a.get("name") == "update.json"), None)
        if not manifest_asset:
            return None, "Latest GitHub release does not contain update.json."
        raw = hvpnl_download_github_asset(owner, repo, token, manifest_asset)
        obj = json.loads(raw.decode("utf-8-sig"))
        if not isinstance(obj, dict):
            return None, "update.json must contain a JSON object."
        obj["_github_release_assets"] = {
            str(a.get("name")): a for a in release.get("assets", [])
            if a.get("name") and str(a.get("name")).strip().lower() not in HVPNL_GITHUB_LOCAL_ONLY_ASSETS
        }
        obj["_github_release_tag"] = release.get("tag_name", "")
        obj = hvpnl_sanitize_github_manifest(obj)
        return obj, None
    except urllib.error.HTTPError as exc:
        if exc.code in (401, 403): return None, f"GitHub returned HTTP {exc.code} (access denied)."
        if exc.code == 404: return None, "GitHub repository or latest release was not found."
        return None, f"GitHub returned HTTP {exc.code}."
    except Exception as exc:
        return None, f"Could not read GitHub update information: {exc}"


def hvpnl_download_update_asset(info, asset_name, folder, expected_sha256="",
                                progress_callback=None, cancel_event=None):
    owner = str(globals().get("HVPNL_GITHUB_OWNER", "") or "").strip()
    repo = str(globals().get("HVPNL_GITHUB_REPO", "") or "").strip()
    token = hvpnl_get_user_update_token()
    if not token:
        raise RuntimeError(
            "GitHub update credential is not configured in Windows Credential Manager."
        )
    assets = info.get("_github_release_assets") or {}
    if str(asset_name).strip().lower() in HVPNL_GITHUB_LOCAL_ONLY_ASSETS:
        raise FileNotFoundError(f"Local-only asset is not downloadable from GitHub: {asset_name}")
    asset = assets.get(str(asset_name))
    if not asset:
        raise FileNotFoundError(f"GitHub release asset not found: {asset_name}")
    target = Path(folder) / str(asset_name)
    hvpnl_download_github_asset_to_file(
        owner, repo, token, asset, target,
        progress_callback=progress_callback,
        cancel_event=cancel_event,
    )
    if expected_sha256:
        actual = hvpnl_sha256_file(target)
        if actual.lower() != str(expected_sha256).strip().lower():
            target.unlink(missing_ok=True)
            raise IOError(f"SHA-256 verification failed: {asset_name}")
    return target

def hvpnl_select_component(info, component, local_version):
    remote = info.get(component) or {}
    # Also accept the simple top-level version field for compatibility.
    # V41 has no remotely distributed index component.
    remote_version = str(
        remote.get("version")
        or info.get(f"{component}_version")
        or ""
    ).strip()
    if not remote_version or hvpnl_version_tuple(remote_version) <= hvpnl_version_tuple(local_version):
        return None
    patches = remote.get("patches") or {}
    patch = patches.get(str(local_version)) if isinstance(patches, dict) else None
    if isinstance(patch, dict) and patch.get("asset") and not patch.get("disabled"):
        return {"mode": "patch", "asset": patch["asset"], "from_version": str(local_version), "to_version": remote_version}
    full = remote.get("full") or {}
    if not full.get("asset"):
        raise ValueError(f"No full update asset is available for {component} {remote_version}.")
    return {"mode": "full", "asset": full["asset"], "from_version": str(local_version), "to_version": remote_version}

class HVPNLUpdateDownloadSignals(QObject):
    progress = Signal(int, int, int, int, float, object)
    # current_bytes, total_bytes, overall_bytes, overall_total, speed, eta
    status = Signal(str)
    finished = Signal(object)
    failed = Signal(str)


class HVPNLUpdateDownloadWorker(QRunnable):
    """Background downloader so the Qt GUI thread remains responsive."""
    def __init__(self, info, download_specs, plan_dir):
        super().__init__()
        self.setAutoDelete(True)
        self.info = info
        self.download_specs = list(download_specs)
        self.plan_dir = Path(plan_dir)
        self.signals = HVPNLUpdateDownloadSignals()
        self.cancel_event = threading.Event()

    def cancel(self):
        self.cancel_event.set()

    @staticmethod
    def _fmt_size(value):
        value = float(max(value or 0, 0))
        units = ("B", "KB", "MB", "GB")
        for unit in units:
            if value < 1024 or unit == units[-1]:
                return f"{value:.1f} {unit}" if unit != "B" else f"{int(value)} B"
            value /= 1024.0
        return "0 B"

    @staticmethod
    def _fmt_eta(seconds):
        if seconds is None or seconds < 0 or seconds == float("inf"):
            return "Calculating…"
        seconds = int(max(seconds, 0))
        h, rem = divmod(seconds, 3600)
        m, s = divmod(rem, 60)
        if h:
            return f"{h}h {m:02d}m {s:02d}s"
        if m:
            return f"{m}m {s:02d}s"
        return f"{s}s"

    def run(self):
        started = time.monotonic()
        overall_total = sum(int(x.get("size") or 0) for x in self.download_specs)
        overall_done = 0
        results = []
        try:
            if not self.download_specs:
                self.signals.finished.emit(results)
                return

            for spec in self.download_specs:
                if self.cancel_event.is_set():
                    raise InterruptedError("Update download cancelled by user.")

                name = str(spec["asset_name"])
                self.signals.status.emit(f"Downloading {name}")
                local_start_done = overall_done

                def on_progress(current, total, speed, eta,
                                _name=name, _local_start=local_start_done):
                    overall_current = _local_start + current
                    elapsed = max(time.monotonic() - started, 0.001)
                    overall_speed = overall_current / elapsed
                    overall_eta = ((overall_total - overall_current) / overall_speed) if overall_total and overall_speed > 0 else eta
                    self.signals.progress.emit(
                        int(current), int(total), int(overall_current),
                        int(overall_total), float(overall_speed),
                        self._fmt_eta(overall_eta),
                    )

                path = hvpnl_download_update_asset(
                    self.info, name, self.plan_dir,
                    str(spec.get("sha256") or ""),
                    progress_callback=on_progress,
                    cancel_event=self.cancel_event,
                )
                size = path.stat().st_size
                overall_done += size
                self.signals.progress.emit(
                    int(size), int(size), int(overall_done), int(overall_total or overall_done),
                    float(overall_done / max(time.monotonic() - started, 0.001)), "0s"
                )
                results.append((spec, path))

            self.signals.status.emit("Download complete — verifying update files…")
            self.signals.finished.emit(results)
        except Exception as exc:
            self.signals.failed.emit(str(exc))


class ScreenOCROverlay(QDialog):
    """Full-screen OCR capture overlay.

    The selection rectangle is painted by this widget itself rather than by
    QRubberBand.  QRubberBand can be rendered with the platform's native
    blue/grey palette on Windows, which ignored the configured OCR colour.
    Painting it directly guarantees that the Settings colour is used for both
    the fill and the dotted border, exactly like the PDF OCR selector.
    """
    region_selected = Signal(QRect, QImage)

    def __init__(self, parent=None, selection_color="#FFD54F"):
        super().__init__(parent)
        self.selection_color = str(selection_color or "#FFD54F")
        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint |
            Qt.WindowType.WindowStaysOnTopHint |
            Qt.WindowType.Tool
        )
        self.setModal(True)
        self.setCursor(Qt.CursorShape.CrossCursor)
        screen = QApplication.primaryScreen()
        if screen is None:
            raise RuntimeError("No screen is available for OCR capture.")

        self._screen_geometry = screen.geometry()
        pix = screen.grabWindow(0)
        self._image = pix.toImage().convertToFormat(QImage.Format.Format_RGBA8888)
        self._origin = None
        self._rect = QRect()

        # Keep the captured desktop as the widget background.  Everything,
        # including the dim layer and selection rectangle, is painted in one
        # place so Windows native widget styles cannot replace our colour.
        pix.setDevicePixelRatio(1.0)
        self._pixmap = pix.scaled(
            self._screen_geometry.size(),
            Qt.AspectRatioMode.IgnoreAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
        self.setGeometry(self._screen_geometry)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, False)

        self._instruction = QLabel(
            "SCREEN OCR  •  Drag over text  •  Esc to cancel", self
        )
        self._instruction.setStyleSheet(
            "background:rgba(15,23,42,225);color:white;padding:9px 14px;"
            "border-radius:8px;font:600 13px 'Segoe UI';"
        )
        self._instruction.adjustSize()
        self._instruction.move(18, 18)
        self._instruction.raise_()

    def _colour(self):
        c = QColor(self.selection_color)
        return c if c.isValid() else QColor("#FFD54F")

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.drawPixmap(0, 0, self._pixmap)

        # Neutral darkened desktop, then a brighter configured selection area.
        p.fillRect(self.rect(), QColor(10, 20, 35, 72))

        if not self._rect.isNull():
            c = self._colour()
            # The selected area gets the configured translucent colour.
            fill = QColor(c)
            fill.setAlpha(62)
            p.fillRect(self._rect, fill)

            # Beautiful dashed border matching the PDF OCR selector.
            pen_colour = QColor(c)
            pen_colour.setAlpha(245)
            pen = QPen(pen_colour, 2, Qt.PenStyle.DashLine)
            pen.setDashPattern([7, 5])
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(self._rect.adjusted(1, 1, -1, -1))

        p.end()

    def mousePressEvent(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            return
        self._origin = event.position().toPoint()
        self._rect = QRect(self._origin, QSize())
        self.update()
        event.accept()

    def mouseMoveEvent(self, event):
        if self._origin is None:
            return
        self._rect = QRect(
            self._origin, event.position().toPoint()
        ).normalized()
        self.update()
        event.accept()

    def mouseReleaseEvent(self, event):
        if self._origin is None or event.button() != Qt.MouseButton.LeftButton:
            return
        rect = QRect(
            self._origin, event.position().toPoint()
        ).normalized()
        self._origin = None
        self.update()

        if rect.width() < 8 or rect.height() < 8:
            self.reject()
            return

        sx = self._image.width() / max(1, self._screen_geometry.width())
        sy = self._image.height() / max(1, self._screen_geometry.height())
        px = max(0, min(self._image.width() - 1, int(round(rect.x() * sx))))
        py = max(0, min(self._image.height() - 1, int(round(rect.y() * sy))))
        pw = max(1, min(self._image.width() - px, int(round(rect.width() * sx))))
        ph = max(1, min(self._image.height() - py, int(round(rect.height() * sy))))
        crop = self._image.copy(px, py, pw, ph)
        self.region_selected.emit(rect, crop)
        self.accept()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key.Key_Escape:
            self.reject()
            return
        super().keyPressEvent(event)



