# Public Cloudflare Worker endpoint. No Supabase secret is stored here.
HVPNL_ISSUE_API_URL = os.environ.get(
    "HVPNL_ISSUE_API_URL",
    "https://hvpnl-issue-api.sandeep-hvpnl.workers.dev"
).strip().rstrip("/")

def hvpnl_issue_api_url():
    return str(
        globals().get("HVPNL_ISSUE_API_URL", "") or ""
    ).strip().rstrip("/")

def hvpnl_issue_client_id():
    try:
        fp = str(get_device_fingerprint() or "").strip()
    except Exception:
        fp = ""
    return hashlib.sha256(
        ("HVPNL-ISSUE-CLIENT|" + fp).encode()
    ).hexdigest() if fp else ""

def hvpnl_issue_identity():
    p = ACTIVE_LICENSE_PAYLOAD if isinstance(
        ACTIVE_LICENSE_PAYLOAD, dict
    ) else {}
    try:
        v = hvpnl_get_installed_component_versions()
    except Exception:
        v = {}
    return {
        "client_id": hvpnl_issue_client_id(),
        "licence_id": str(p.get("licence_id") or ""),
        "user_name": str(p.get("user_name") or ""),
        "organisation": str(p.get("organisation") or ""),
        "app_version": str(
            globals().get("APP_BUILD_VERSION") or ""
        ),
        "master_version": str(
            v.get("master_version") or ""
        ),
    }

def _hvpnl_issue_response_body(exc):
    """Read an HTTP error body without hiding the Worker diagnostic."""
    try:
        raw = exc.read()
    except Exception:
        raw = b""
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8-sig", errors="replace")
    raw = str(raw or "").strip()
    if len(raw) > 4000:
        raw = raw[:4000] + "\n...[truncated]"
    return raw

def hvpnl_issue_request(method, path, payload=None, developer=False):
    base = hvpnl_issue_api_url()
    if not base:
        raise RuntimeError(
            "Raise an Issue service is not configured."
        )

    body = None
    headers = {
        "Accept": "application/json",
        "User-Agent": "HVPNL-Approval-Search-Issue/1.1",
    }

    if developer:
        key = str(
            globals().get("HVPNL_ISSUE_API_KEY") or ""
        ).strip()
        if not key:
            raise RuntimeError(
                "Developer Issue API key is not configured."
            )
        headers["X-API-Key"] = key

    if payload is not None:
        body = json.dumps(
            payload, ensure_ascii=False
        ).encode("utf-8")
        headers["Content-Type"] = "application/json"

    req = urllib.request.Request(
        base + "/" + str(path).lstrip("/"),
        data=body,
        headers=headers,
        method=str(method).upper(),
    )

    try:
        with urllib.request.urlopen(
            req, timeout=HVPNL_ISSUE_API_TIMEOUT
        ) as r:
            raw = r.read()
            if not raw:
                return {}
            return json.loads(
                raw.decode("utf-8-sig")
            )
    except urllib.error.HTTPError as e:
        detail = _hvpnl_issue_response_body(e)
        raise RuntimeError(
            f"Issue server returned HTTP {e.code}.\n"
            + (detail or "(empty response body)")
        )
    except urllib.error.URLError as e:
        raise RuntimeError(
            "Could not connect to Issue server.\n"
            f"{getattr(e, 'reason', e)}"
        )


HVPNL_ISSUE_ALLOWED_EXTENSIONS = {
    ".pdf", ".doc", ".docx", ".txt", ".xls", ".xlsx", ".xlss"
}
HVPNL_ISSUE_MAX_ATTACHMENT_BYTES = 25 * 1024 * 1024


def hvpnl_issue_upload(issue_id, path):
    # Upload one generic issue attachment.
    p = Path(path)
    if not p.exists() or not p.is_file():
        raise RuntimeError(f"Selected attachment was not found:\n{p}")

    ext = p.suffix.lower()
    if ext not in HVPNL_ISSUE_ALLOWED_EXTENSIONS:
        raise RuntimeError(
            "Unsupported attachment type.\n\n"
            "Allowed: PDF, DOC, DOCX, TXT, XLS, XLSX and XLSS."
        )

    data = p.read_bytes()
    if len(data) > HVPNL_ISSUE_MAX_ATTACHMENT_BYTES:
        raise RuntimeError("Attachment exceeds the 25 MB limit.")

    import mimetypes
    content_type = mimetypes.guess_type(p.name)[0] or "application/octet-stream"
    boundary = "----HVPNLIssue" + secrets.token_hex(12)

    parts = [
        (
            f'--{boundary}\r\n'
            'Content-Disposition: form-data; name="client_id"\r\n\r\n'
            f'{hvpnl_issue_client_id()}\r\n'
        ).encode("utf-8"),
        (
            f'--{boundary}\r\n'
            f'Content-Disposition: form-data; name="file"; filename="{p.name.replace(chr(34), "_")}"\r\n'
            f'Content-Type: {content_type}\r\n\r\n'
        ).encode("utf-8"),
        data,
        f"\r\n--{boundary}--\r\n".encode("utf-8"),
    ]

    req = urllib.request.Request(
        hvpnl_issue_api_url()
        + f'/v1/issues/{urllib.parse.quote(str(issue_id))}/attachment',
        data=b"".join(parts),
        headers={
            "Content-Type": f"multipart/form-data; boundary={boundary}",
            "Accept": "application/json",
            "User-Agent": "HVPNL-Approval-Search-Issue/1.2",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(req, timeout=120) as r:
            raw = r.read()
            return json.loads(raw.decode("utf-8-sig")) if raw else {}
    except urllib.error.HTTPError as e:
        detail = _hvpnl_issue_response_body(e)
        raise RuntimeError(
            f"Attachment upload returned HTTP {e.code}.\n"
            + (detail or "(empty response body)")
        )


def hvpnl_issue_list_attachments(issue_id):
    r = hvpnl_issue_request(
        "GET",
        "/v1/issues/"
        + urllib.parse.quote(str(issue_id))
        + "/attachments?client_id="
        + urllib.parse.quote(hvpnl_issue_client_id()),
    )
    return r.get("attachments", []) or []


def hvpnl_issue_download_attachment(issue_id, attachment, target_path):
    filename = str(
        attachment.get("filename")
        or attachment.get("name")
        or attachment.get("original_name")
        or "attachment"
    )
    object_key = str(
        attachment.get("object_key")
        or attachment.get("key")
        or ""
    ).strip()
    if not object_key:
        raise RuntimeError("Attachment has no object key.")

    url = (
        hvpnl_issue_api_url()
        + "/v1/issues/"
        + urllib.parse.quote(str(issue_id))
        + "/attachments/"
        + urllib.parse.quote(object_key, safe="")
        + "?client_id="
        + urllib.parse.quote(hvpnl_issue_client_id())
    )
    req = urllib.request.Request(
        url,
        headers={
            "Accept": "*/*",
            "User-Agent": "HVPNL-Approval-Search-Issue/1.2",
        },
        method="GET",
    )
    target = Path(target_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    with urllib.request.urlopen(req, timeout=120) as r:
        target.write_bytes(r.read())
    return target



