def hvpnl_issue_busy_operation(message="Processing…"):
    # Shows a visible modal progress dialog before a synchronous
    # Issue API operation and disables the parent dialog.
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            parent = self if isinstance(self, QDialog) else None
            progress = QProgressDialog(str(message), "", 0, 0, parent)
            progress.setWindowTitle("HVPNL Issue")
            progress.setCancelButton(None)
            progress.setMinimumDuration(0)
            progress.setWindowModality(Qt.WindowModality.ApplicationModal)
            progress.setAutoClose(False)
            progress.setAutoReset(False)

            try:
                progress.show()
                QApplication.processEvents()
                if parent is not None:
                    parent.setEnabled(False)
                    QApplication.processEvents()
                return func(self, *args, **kwargs)
            finally:
                if parent is not None:
                    parent.setEnabled(True)
                progress.close()
                progress.deleteLater()
                QApplication.processEvents()
        return wrapper
    return decorator


