        self.raise_issue_btn.setToolTip("Raise an Issue — report a problem or upload a new approval PDF")
        self.raise_issue_btn.clicked.connect(self.open_raise_issue_dialog)
        h.addWidget(self.raise_issue_btn)

        self.hvpnl_about_btn = QPushButton("ⓘ")
        self.hvpnl_about_btn.setFixedSize(42, 36)
