        self.sort_combo = QComboBox(); self.sort_combo.addItems(['Approval No. ↓','Approval No. ↑','File Name A-Z','Recently Indexed']); self.sort_combo.currentIndexChanged.connect(self.perform_search); info_row.addWidget(QLabel('Sort:')); info_row.addWidget(self.sort_combo); ml.addLayout(info_row)
        self.results_scroll = QScrollArea(); self.results_scroll.setWidgetResizable(True); self.results_scroll.setMinimumWidth(0); self.results_scroll.setSizePolicy(QSizePolicy.Policy.Ignored,QSizePolicy.Policy.Expanding); self.results_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff); self.results_scroll.setStyleSheet('border:none; background:transparent;')
        self.results_container = QWidget(); self.results_container.setMinimumWidth(0); self.results_container.setSizePolicy(QSizePolicy.Policy.Ignored,QSizePolicy.Policy.Preferred); self.results_layout = QVBoxLayout(self.results_container); self.results_layout.setContentsMargins(0,0,0,0); self.results_layout.setSpacing(10); self.results_layout.addStretch(); self.results_scroll.setWidget(self.results_container); ml.addWidget(self.results_scroll,1)
