        right_tabs=QTabWidget(); right_tabs.setDocumentMode(True); right_tabs.setMinimumWidth(520); self.right_preview_tabs=right_tabs

        approval_tab=QWidget(); al=QVBoxLayout(approval_tab); al.setContentsMargins(0,0,0,0); self.pdf_viewer=PdfViewer(); al.addWidget(self.pdf_viewer); right_tabs.addTab(approval_tab,'📄 Approval PDF')
        self.approval_tab=approval_tab

        def build_district_tab(kind, empty_text):
            tab=QWidget()
            lay=QVBoxLayout(tab); lay.setContentsMargins(0,0,0,0); lay.setSpacing(0)

            # District names are link-like controls ABOVE the PDF viewer.
            # A horizontal scroll strip prevents them from being hidden when
            # the archive contains many districts.
            bar=QScrollArea(); bar.setWidgetResizable(True); bar.setFixedHeight(54)
            bar.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
            bar.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
            bar.setFrameShape(QFrame.Shape.NoFrame)
            host=QWidget(); row=QHBoxLayout(host); row.setContentsMargins(10,6,10,6); row.setSpacing(2); bar.setWidget(host)
            lay.addWidget(bar)

            viewer=PdfViewer(); lay.addWidget(viewer,1)
            if kind == 'map':
                self.district_map_viewer=viewer; self.district_map_district_bar=bar
            else:
                self.district_infra_viewer=viewer; self.district_infra_district_bar=bar

            def load_district(district):
                try:
                    rec=self.db.get_reference_document_for_district(district,kind)
                    if not rec:
                        raise RuntimeError(f'No {kind} document is available for {district}.')
                    raw=bytes(rec.get('pdf_blob') or b'')
                    if not raw:
                        raise RuntimeError('The selected reference document contains no embedded PDF data.')
                    viewer.load_pdf_bytes(raw, rec.get('original_filename') or rec.get('title') or 'Reference.pdf', [], self.settings.get('highlight_color', SEARCH_HIGHLIGHT_DEFAULT))
                    self.status_label.setText(f"Viewing {kind.title()} reference: {rec.get('title') or rec.get('original_filename')} • District: {district}")
                except Exception as e:
                    viewer.close_doc(); viewer.image_label.setPixmap(QPixmap()); viewer.image_label.setText(f'Could not display PDF:\n{e}'); viewer.file_label.setText('Reference PDF error')

            def refresh_links():
                while row.count():
                    item=row.takeAt(0)
                    if item.widget(): item.widget().deleteLater()
                districts=self.db.list_district_reference_districts(kind)
                if not districts:
                    msg=QLabel('No districts available')
                    msg.setStyleSheet(f'color:{MUTED}; padding:8px 12px;')
                    row.addWidget(msg); row.addStretch(1)
                    viewer.close_doc(); viewer.image_label.setPixmap(QPixmap()); viewer.image_label.setText(empty_text); viewer.file_label.setText('No PDF selected')
                    return
                for district in districts:
                    btn=QPushButton(district)
                    btn.setFlat(True); btn.setCursor(Qt.CursorShape.PointingHandCursor); btn.setProperty('districtLink',True)
                    btn.setToolTip(f'Open {district} {"power map" if kind == "map" else "infrastructure"} PDF')
                    btn.clicked.connect(lambda checked=False,d=district: load_district(d))
                    row.addWidget(btn)
                row.addStretch(1)

            tab._refresh_district_links=refresh_links
            return tab

        map_tab=build_district_tab('map','Select a district above to preview its power map.')
        infra_tab=build_district_tab('infra','Select a district above to preview its infrastructure document.')
        self.district_map_tab=map_tab; self.district_infra_tab=infra_tab
        right_tabs.addTab(map_tab,'🗺 District Power Map')
        right_tabs.addTab(infra_tab,'🏗 District Infra')
        splitter.addWidget(right_tabs)
        splitter.setChildrenCollapsible(False); splitter.setCollapsible(0,False); splitter.setCollapsible(1,False)
        splitter.setStretchFactor(0,1); splitter.setStretchFactor(1,1)
        splitter.setSizes([760,980])

        self.live_search_timer = QTimer(self)
        self.live_search_timer.setSingleShot(True)
        self.live_search_timer.setInterval(600)
        self.live_search_timer.timeout.connect(self.perform_search)

        # District links are sourced from MASTER.db reference_documents.
        QTimer.singleShot(0, self.refresh_district_reference_links)

        # Persistent lower footer: operational status at left, update state,
