            act_row=QHBoxLayout(); generate_btn=QPushButton("🔑 Generate Activation Code"); copy_btn=QPushButton("📋 Copy Activation Code"); save_btn=QPushButton("💾 Save Activation Code"); post_btn=QPushButton("☁ Post Activation to GitHub"); post_btn.setEnabled(False); post_btn.setToolTip("Add/update this activation in the private GitHub licence registry."); act_row.addWidget(generate_btn); act_row.addWidget(copy_btn); act_row.addWidget(save_btn); act_row.addWidget(post_btn); act_row.addStretch(1); lay.addLayout(act_row)
            table=QTableWidget(0,8); table.setHorizontalHeaderLabels(["User","Organisation","Fingerprint","Issued","Expires","Days","Status","Licence ID"]); table.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows); table.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers); table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch); lay.addWidget(QLabel("ISSUED / RENEWABLE LICENCES")); lay.addWidget(table,1)
