        def open_sstn_statistics():
            """Developer-only district-wise SSTN statistics dashboard."""
            if ACTIVE_LICENSE_ROLE != "DEVELOPER":
                QMessageBox.warning(dlg, APP_NAME, "Developer access is required."); return
            try:
                masters=self.db.list_sstn_master(); infras=self.db.list_sstn_infra()
            except Exception as e:
                QMessageBox.critical(dlg, APP_NAME, f"Could not read SSTN data from MASTER.db:\n\n{e}"); return
            by_sid={str(r.get('sstn_id')):[] for r in masters}
            for r in infras: by_sid.setdefault(str(r.get('sstn_id')),[]).append(dict(r))
            for sid in by_sid: by_sid[sid].sort(key=lambda x:int(x.get('seq_no') or 0))

            def state_totals(text): return _sstn_transformer_totals(text)
            def filtered_records(district="All Districts", voltage="All Voltages"):
                out=[]
                for m in masters:
                    if district!='All Districts' and str(m.get('district') or '').strip()!=district: continue
                    mv=str(m.get('voltage_level') or '').replace(' ','').upper()
                    if voltage!='All Voltages' and mv!=voltage.upper(): continue
                    sid=str(m.get('sstn_id')); stages=by_sid.get(sid,[])
                    if not stages: continue
                    first=next((x for x in stages if str(x.get('existing_capacity') or '').strip()), stages[0])
                    last=stages[-1]
                    ex=state_totals(first.get('existing_capacity','')); ap=state_totals(last.get('approved_capacity',''))
                    # Sequential approved-stage deltas for FY growth.
                    growth=[]; prev=ex
                    for st in stages:
                        cur=state_totals(st.get('approved_capacity',''))
                        fy=str(st.get('approved_fy') or '').strip()
                        if fy:
                            growth.append((fy, max(0.0,cur['mva']-prev['mva']), max(0,cur['tf_count']-prev['tf_count']), cur['mva']-prev['mva'], cur['tf_count']-prev['tf_count']))
                        prev=cur
                    out.append({'master':m,'stages':stages,'existing':ex,'approved':ap,'growth':growth})
                return out

