            district_box=QComboBox(); districts=sorted({str(m.get('district') or '').strip() for m in masters if str(m.get('district') or '').strip()}, key=str.casefold); district_box.addItems(['All Districts']+districts); head.addWidget(district_box)
            head.addWidget(QLabel('Voltage:')); voltage_box=QComboBox(); voltage_box.addItems(['All Voltages','765KV','400KV','220KV','132KV','66KV']); head.addWidget(voltage_box); root.addLayout(head)
            # V22.3.12 — compact summary area above the graphs.
