    def schedule_live_search(self):
        query = self.search_edit.text().strip()
        if len(re.sub(r"\s+", "", query)) < 3:
            self.live_search_timer.stop()
            if query: self.result_count_label.setText("Type at least 3 characters to search")
            return
        self.live_search_timer.start()

    def update_suggestions(self, query):
        # Intentionally disabled: no automatic text/suggestion popup in the search box.
        return

    def clear_results(self):
        self._card_batch_timer.stop(); self._pending_cards=[]
        while self.results_layout.count():
            item = self.results_layout.takeAt(0)
            if item.widget(): item.widget().deleteLater()

    def perform_search(self, force=False):
        query = self.search_edit.text().strip()
        self.live_search_timer.stop()
        self.search_generation += 1
        token = self.search_generation
        self.clear_results()
        if not query:
            self.result_count_label.setText("Enter at least 3 characters to search"); self.results_layout.addStretch(); return
        self.showing_favorites=False; self.showing_notes=False
        terms, exact_phrase, close_mode = parse_query(query)
        semantic_mode = False
        self.result_count_label.setText("Searching...")
        self.search_in_progress=True
        self.db.add_search_history(query)
        worker = SearchWorker(self.db.path, token, terms, exact_phrase, close_mode, self.close_gap_spin.value(), semantic_mode, query)
        worker.signals.finished.connect(self._search_finished)
        worker.signals.error.connect(self._search_error)
        self.thread_pool.start(worker)

    def _search_error(self, token, message):
        if token != self.search_generation: return
        self.search_in_progress=False
        self.result_count_label.setText("Search error")
        empty=QLabel(f"Search error: {message}"); empty.setWordWrap(True); empty.setStyleSheet(f"color:{MUTED}; padding:30px;")
        self.results_layout.addWidget(empty); self.results_layout.addStretch()

    def _search_finished(self, token, rows, worker_terms, close_mode, _message):
        if token != self.search_generation: return
        self.search_in_progress=False
        query=self.search_edit.text().strip()
        terms, exact_phrase, _ = parse_query(query)
        highlight_terms = terms[:] if terms else (exact_phrase.split() if exact_phrase else [])
        rows=list(rows)
        _clean_query, _shortcut_filters = parse_search_shortcuts(query)
        within_days = _shortcut_filters.get("within_days")
        if within_days:
            cutoff = date.today() - timedelta(days=int(within_days))
            filtered_rows = []
            for _row in rows:
                _sort_date = parse_date(_row.get("approval_date") or "")
                try:
                    _dt = datetime.strptime(_sort_date, "%Y%m%d").date() if _sort_date else None
                except Exception:
                    _dt = None
                if _dt is not None and _dt >= cutoff:
                    filtered_rows.append(_row)
            rows = filtered_rows
        mode = self.sort_combo.currentText()

        # IMPORTANT: search results must not retain SQLite/FTS relevance order.
        # Default mode is Approval No. DESC, i.e. highest R.No./Approval No. first.
        # approval_number_numeric is the canonical numeric identity derived from
        # the PDF filename / R.No.; file_name is only used as a stable tie-breaker.
        if mode == "Approval No. ↓":
            rows.sort(
                key=lambda r: (
                    r.get("approval_number_numeric") or 0,
                    str(r.get("approval_number") or r.get("file_name") or "").casefold(),
                    str(r.get("file_name") or "").casefold(),
                ),
                reverse=True,
            )
        elif mode == "Approval No. ↑":
            rows.sort(
                key=lambda r: (
                    r.get("approval_number_numeric") or 0,
                    str(r.get("approval_number") or r.get("file_name") or "").casefold(),
                    str(r.get("file_name") or "").casefold(),
                )
            )
        elif mode == "File Name A-Z":
            rows.sort(key=lambda r: str(r.get("file_name") or "").casefold())
        elif mode == "Recently Indexed":
            rows.sort(key=lambda r: r.get("indexed_at") or "", reverse=True)
        self.current_rows=rows
        semantic_mode=False
        search_label=f"Close search (+, ≤{self.close_gap_spin.value()} chars gap)" if close_mode else "All Words (AND)"
        self.result_count_label.setText(f"{len(rows):,} result(s) • {search_label}")
        if not rows:
            empty=QLabel("No approval found containing all searched terms."); empty.setAlignment(Qt.AlignmentFlag.AlignCenter); empty.setStyleSheet(f"color:{MUTED}; padding:50px;")
            self.results_layout.addWidget(empty); self.results_layout.addStretch(); return
        note_ids=self.db.document_note_ids([row["id"] for row in rows])
        favorite_ids=set()
        try: favorite_ids={r["id"] for r in self.db.favorite_documents()}
        except Exception: pass
        # A direct numeric search (for example 1036) is special: for the exact
        # approval itself, show a substantial OCR overview so the user can see
        # what the proposal is about. Other approvals that merely mention 1036
        # continue to use normal match snippets.
        exact_numeric_query = None
        if len(terms) == 1 and re.fullmatch(r"\d+", (terms[0] or "").strip()) and not exact_phrase and not close_mode:
            exact_numeric_query = terms[0].strip()

        self._pending_cards=[
            (row, highlight_terms, row["id"] in note_ids, row["id"] in favorite_ids,
             exact_numeric_query is not None and str(row.get("approval_number") or "").strip() == exact_numeric_query)
            for row in rows
        ]
        self._card_context=(self.before_spin.value(), self.after_spin.value(), self.max_snippets_spin.value())
        self._add_next_card_batch()

    def _add_next_card_batch(self):
        if not self._pending_cards:
            if self.results_layout.count()==0 or self.results_layout.itemAt(self.results_layout.count()-1).spacerItem() is None: self.results_layout.addStretch()
            return
        batch=self._pending_cards[:10]; self._pending_cards=self._pending_cards[10:]
        before, after, max_snippets = self._card_context
        for row, terms, has_note, is_favorite, is_exact_approval in batch:
            if is_exact_approval:
                # Always provide roughly 12 visible lines for the exact approval
                # number searched, rather than only one occurrence snippet.
                snippets=approval_overview_lines(row.get("full_text") or "", terms, min_lines=12, words_per_line=14)
                if not snippets:
                    snippets=snippets_for_document(row.get("full_text") or "", terms, before, after, max(max_snippets, 12))
            else:
                snippets=snippets_for_document(row.get("full_text") or "", terms, before, after, max_snippets)
            card=ResultCard(row,snippets,terms,self.settings["highlight_color"],has_note=has_note,is_favorite=is_favorite)
            card.clicked.connect(lambda r,t=terms:self.open_result(r,t))
            card.favorite_toggled.connect(self.toggle_card_favorite)
            card.note_requested.connect(self.show_card_note)
            self.results_layout.addWidget(card)
        if self._pending_cards: self._card_batch_timer.start(0)
        else: self.results_layout.addStretch()

    def toggle_card_favorite(self, row):
        enabled=not self.db.is_favorite(row["id"]); self.db.set_favorite(row["id"],enabled)
        self.status_label.setText("Added to favourites" if enabled else "Removed from favourites")
        if self.showing_favorites: self.show_favorites()
        else: self.perform_search(force=True)

    def show_card_note(self, row):
        """Open the note editor directly from a result-card note icon."""
        self.current_row = row
        dlg = QDialog(self)
        dlg.setWindowTitle(f"Notes - {row['file_name']}")
        dlg.resize(650, 420)
        layout = QVBoxLayout(dlg)

        info = QLabel(
            f"Approval: {row['approval_number'] or 'Not detected'}   •   {row['file_name']}"
        )
        info.setWordWrap(True)
        layout.addWidget(info)

        editor = QPlainTextEdit(self.db.get_note(row["id"]))
        editor.setPlaceholderText("Write your personal/office notes for this approval...")
        layout.addWidget(editor, 1)

        buttons = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel
        )
        buttons.accepted.connect(dlg.accept)
        buttons.rejected.connect(dlg.reject)
        layout.addWidget(buttons)

        if dlg.exec() == QDialog.DialogCode.Accepted:
            saved_note = editor.toPlainText().strip()
            self.db.save_note(row["id"], saved_note)
            self.status_label.setText(
                "Note saved for selected approval" if saved_note else "Note removed from selected approval"
            )
            # Refresh the visible list so the note icon state changes immediately.
            if self.showing_notes:
                self.show_noted_approvals()
            elif self.search_edit.text().strip():
                self.perform_search()


    def open_result(self, row, terms):
        # A result card can contain OCR text mentioning another approval number.
        # Never use that text as identity. The clicked card's file_name is the
        # sole canonical identity: 1639.pdf must load the BLOB 1639.pdf.
        selected_filename = str(row["file_name"] or "").strip()
        self.current_row = row

        # Every approval-card click opens the Approval PDF tab.
        if hasattr(self,'right_preview_tabs') and hasattr(self,'approval_tab'):
            self.right_preview_tabs.setCurrentWidget(self.approval_tab)

        # Immediately clear the old PDF. This prevents a stale 1638.pdf from
        # remaining visible if the new selection cannot be loaded.
        self.pdf_viewer.close_doc()
        self.pdf_viewer.image_label.setPixmap(QPixmap())
        self.pdf_viewer.image_label.setText("Loading selected approval...")
        self.pdf_viewer.file_label.setText(selected_filename or "Loading...")
        QApplication.processEvents()

        # Fetch strictly by the clicked card's filename.  Do not pass the search/index
        # document id into the preview path: ids from merged search results may belong
        # to different database tables, whereas 1639.pdf is an unambiguous identity.
        pdf_bytes, original_filename = self.db.get_pdf_blob_by_filename(selected_filename)

        if not pdf_bytes:
            self.pdf_viewer.file_label.setText("Embedded PDF not found")
            self.pdf_viewer.image_label.setText(
                f"No embedded PDF BLOB found for the selected result: {selected_filename}"
            )
            self.status_label.setText(
                f"ERROR: {selected_filename} selected, but its exact embedded BLOB was not found."
            )
            return

        # Defensive identity check. Never silently display a different PDF.
        try:
            expected_key = self.db._canonical_pdf_filename(selected_filename)
            actual_key = self.db._canonical_pdf_filename(original_filename)
        except Exception:
            expected_key = selected_filename.casefold().strip()
            actual_key = str(original_filename or "").casefold().strip()

        if actual_key != expected_key:
            self.pdf_viewer.file_label.setText("PDF identity mismatch")
            self.pdf_viewer.image_label.setText(
                f"REFUSED TO DISPLAY MISMATCHED PDF\n\n"
                f"Selected: {selected_filename}\nReturned: {original_filename or 'unknown'}"
            )
            self.status_label.setText(
                f"ERROR: selected {selected_filename}, but database returned {original_filename or 'unknown'}."
            )
            return

        self.pdf_viewer.load_pdf_bytes(
            pdf_bytes,
            original_filename,
            terms,
            self.settings["highlight_color"],
        )
        self.status_label.setText(
            f"Viewing exact embedded PDF: {original_filename}  |  "
            f"Approval No.: {row['approval_number'] or 'Not detected'}"
        )
        if hasattr(self,'right_preview_tabs') and hasattr(self,'approval_tab'):
            self.right_preview_tabs.setCurrentWidget(self.approval_tab)

    def toggle_current_favorite(self):
        if not self.current_row:
            return
        enabled = not self.db.is_favorite(self.current_row["id"])
        self.db.set_favorite(self.current_row["id"], enabled)
        self.status_label.setText(
            "Added to favourites" if enabled else "Removed from favourites"
        )
        if self.showing_favorites:
            self.show_favorites()
    def _add_result_cards(self, rows, snippets_by_row=None, terms=None):
        rows=list(rows or []); terms=terms or []
        note_ids=self.db.document_note_ids([r["id"] for r in rows])
        for row in rows:
            snippets=snippets_by_row(row) if callable(snippets_by_row) else ([row["subject"]] if row["subject"] else [])
            is_favorite=self.db.is_favorite(row["id"])
            card=ResultCard(row,snippets or [],terms,self.settings["highlight_color"],has_note=row["id"] in note_ids,is_favorite=is_favorite)
            card.clicked.connect(lambda r,t=terms: self.open_result(r,t))
            card.favorite_toggled.connect(self.toggle_card_favorite)
            card.note_requested.connect(self.show_card_note)
            self.results_layout.addWidget(card)
        self.results_layout.addStretch()

    def show_favorites(self):
        self.clear_results(); rows=list(self.db.favorite_documents()); self.current_rows=rows; self.showing_favorites=True; self.showing_notes=False; self.result_count_label.setText(f"{len(rows):,} favourite approval(s)")
        if not rows:
            empty=QLabel("No favourite approvals yet."); empty.setAlignment(Qt.AlignmentFlag.AlignCenter); empty.setStyleSheet(f"color:{MUTED}; padding:50px;"); self.results_layout.addWidget(empty); self.results_layout.addStretch(); return
        self._add_result_cards(rows,terms=[])

    def show_noted_approvals(self):
        self.clear_results(); rows=list(self.db.noted_documents()); self.current_rows=rows; self.showing_favorites=False; self.showing_notes=True
        self.result_count_label.setText(f"{len(rows):,} approval(s) with saved notes")
        if not rows:
            empty=QLabel("No approvals have saved notes yet."); empty.setAlignment(Qt.AlignmentFlag.AlignCenter); empty.setStyleSheet(f"color:{MUTED}; padding:50px;"); self.results_layout.addWidget(empty); self.results_layout.addStretch(); return
        def note_snippet(row):
            parts=[]
            if (row["subject"] or "").strip(): parts.append(row["subject"])
            if (row["note"] or "").strip(): parts.append("📝 Note: " + row["note"][:300])
            return parts
        self._add_result_cards(rows,note_snippet,terms=[])

    def show_search_history(self):
        dlg=QDialog(self); dlg.setWindowTitle("Search History"); dlg.resize(520,420); layout=QVBoxLayout(dlg)
        lst=QListWidget(); rows=self.db.get_search_history(int(self.settings.get("search_history_limit",30)))
        for row in rows:
            item=QListWidgetItem(f"{row['query']}   —   {row['searched_at']}"); item.setData(Qt.ItemDataRole.UserRole,row['query']); lst.addItem(item)
        layout.addWidget(lst,1)
        buttons=QDialogButtonBox(); use=buttons.addButton("Search Selected",QDialogButtonBox.ButtonRole.AcceptRole); clear=buttons.addButton("Clear History",QDialogButtonBox.ButtonRole.DestructiveRole); close=buttons.addButton(QDialogButtonBox.StandardButton.Close); layout.addWidget(buttons)
        def use_selected():
            item=lst.currentItem()
            if item:
                self.search_edit.setText(item.data(Qt.ItemDataRole.UserRole)); self.perform_search(); dlg.accept()
        def clear_all():
            if QMessageBox.question(dlg,APP_NAME,"Clear all search history?",QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No)==QMessageBox.StandardButton.Yes:
                self.db.clear_search_history(); lst.clear()
        use.clicked.connect(use_selected); clear.clicked.connect(clear_all); close.clicked.connect(dlg.reject); dlg.exec()

