    def ask_database(self):
        dlg=QDialog(self); dlg.setWindowTitle("✨ AI-Assisted Ask the Database"); dlg.resize(760,540); layout=QVBoxLayout(dlg); layout.addWidget(QLabel("Ask a natural-language question about indexed HVPNL approvals. Results remain grounded in your local database.")); question=QPlainTextEdit(); question.setFixedHeight(90); question.setPlaceholderText("Example: Which approvals relate to creation of 220 kV GIS substations in Gurugram?"); layout.addWidget(question); answer=QPlainTextEdit(); answer.setReadOnly(True); layout.addWidget(answer,1); buttons=QDialogButtonBox(); ask=buttons.addButton("Ask",QDialogButtonBox.ButtonRole.AcceptRole); close=buttons.addButton(QDialogButtonBox.StandardButton.Close); layout.addWidget(buttons); close.clicked.connect(dlg.reject)
        def run_question():
            q=normalize_spaces(question.toPlainText())
            if not q: return
            QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
            try:
                if ensure_semantic_available():
                    rows=self.db.semantic_search(get_semantic_model().encode(q,normalize_embeddings=True),limit=8); mode="AI semantic retrieval"
                else:
                    terms=[w for w in re.findall(r"[A-Za-z0-9]{3,}",q.lower()) if w not in {"which","about","approval","approvals","the","and","for","with","from","that","this","are","was"}]; rows=self.db.search(terms[:8]) if terms else []; mode="keyword retrieval (install sentence-transformers for semantic AI search)"
                if not rows: answer.setPlainText("No sufficiently relevant approval was found. Try a location, voltage level, company name, approval number, or distinctive technical phrase."); return
                lines=[f"Mode: {mode}","",f"Found {len(rows)} relevant approval(s):",""]
                for i,row in enumerate(rows[:8],1):
                    lines.append(f"{i}. Approval {row['approval_number'] or '—'} | {row['file_name']}")
                    if row['subject']: lines.append(f"   Subject: {row['subject']}")
                    snippets=snippets_for_document(row['full_text'] or '',re.findall(r"[A-Za-z0-9]{3,}",q)[:4],18,28,1)
                    if snippets: lines.append(f"   Evidence: {snippets[0]}")
                    lines.append("")
                answer.setPlainText("\n".join(lines))
            except Exception as e: answer.setPlainText(f"Ask the Database error: {e}")
            finally: QApplication.restoreOverrideCursor()
        ask.clicked.connect(run_question); dlg.exec()

    def change_theme(self, theme):
        self.settings["theme"] = str(theme).upper()
        # Theme switching always returns result/subject text to automatic theme colours.
        self.settings["result_text_color"] = ""
        self.settings["subject_text_color"] = ""
        save_settings(self.settings)
        self.apply_styles()
        self.refresh_visible_cards()

    def _mark_master_index_pending(self, count=1):
        """Mark the disposable search index stale without rebuilding it."""
        try:
            self._pending_master_index_updates = int(getattr(self, "_pending_master_index_updates", 0)) + max(1, int(count))
        except Exception:
            self._pending_master_index_updates = 1
        self._master_index_ready = False
        self._index_verification_failed = False
        try:
            self.status_label.setText(
                f"MASTER PDF changed • {self._pending_master_index_updates} change(s) pending • index update deferred"
            )
        except Exception:
            pass
        self.add_index_log(
            f"MASTER PDF CHANGE QUEUED FOR SEARCH INDEX | pending={self._pending_master_index_updates} | no automatic re-index started"
        )

    def _offer_pending_master_index_rebuild(self, parent=None):
        """Offer one consolidated rebuild after a batch of MASTER PDF edits."""
        pending = int(getattr(self, "_pending_master_index_updates", 0) or 0)
        if pending <= 0 or self.indexing:
            return
        answer = QMessageBox.question(
            parent or self, APP_NAME,
            f"{pending} MASTER PDF replacement/change(s) are pending search-index update.\n\n"
            "Re-index the searchable index now?\n\n"
            "Yes = rebuild now (only changed PDFs will normally require re-extraction).\n"
            "No = skip for now. The index will be rebuilt automatically the next time the application starts.\n\n"
            "MASTER.db is already saved and will not be changed by the indexing operation.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if answer == QMessageBox.StandardButton.Yes:
            self._pending_master_index_updates = 0
            self.add_index_log(
                f"USER REQUESTED INDEX UPDATE NOW | consolidated MASTER changes={pending}"
            )
            self.start_indexing(False)
        else:
            self.add_index_log(
                f"USER SKIPPED INDEX UPDATE | pending MASTER changes={pending} | next application start will detect stale MASTER/index state"
            )
            try:
                self.status_label.setText(
                    f"Index update deferred • {pending} MASTER PDF change(s) pending • will update next app start"
                )
            except Exception:
                pass

    def add_or_replace_master_pdf(self):
        """Developer-only one-at-a-time MASTER PDF maintenance."""
        if not TEMP_DEVELOPER_MODE:
            if not self.activate_developer_mode(): return
        dlg=QDialog(self); dlg.setWindowTitle('MASTER.db — Add New / Replace Approval PDF'); dlg.resize(760,360)
        lay=QVBoxLayout(dlg)
        info=QLabel('Select a PDF. If its numeric R.No. is already in MASTER.db, the operation will replace that PDF only. Otherwise a new approval record will be appended. Existing metadata is preserved on replacement.')
        info.setWordWrap(True); lay.addWidget(info)
        path_edit=QLineEdit(); path_edit.setPlaceholderText('Select approval PDF, e.g. 2196.pdf or replacement 1812.pdf'); lay.addWidget(path_edit)
        browse=QPushButton('📄 Select PDF'); lay.addWidget(browse)
        status=QLabel(''); status.setWordWrap(True); lay.addWidget(status)
        row=QHBoxLayout(); row.addStretch(1); save=QPushButton('Save to MASTER.db'); close=QPushButton('Close'); row.addWidget(save); row.addWidget(close); lay.addLayout(row)
        def choose():
            fn,_=QFileDialog.getOpenFileName(dlg,'Select Approval PDF','','PDF Files (*.pdf)')
            if fn: path_edit.setText(fn)
        browse.clicked.connect(choose); close.clicked.connect(dlg.reject)
        def commit():
            path=Path(path_edit.text().strip())
            if not path.exists(): status.setText('Please select a valid PDF.'); return
            rno=self.db._approval_number_from_filename(path.name)
            if not rno or not re.search(r'\d+',rno): status.setText('Filename must contain a numeric R.No.'); return
            try:
                con=self.db._master_connect(readonly=True)
                exists=con.execute("SELECT approval_id FROM approvals WHERE approval_number_numeric=? OR LOWER(TRIM(approval_number))=LOWER(TRIM(?)) LIMIT 1",(int(re.search(r'\d+',rno).group()),rno)).fetchone()
                con.close()
                if exists:
                    result=self.db.replace_master_pdf_by_filename(f'{rno}.pdf',path)
                    self._mark_master_index_pending(1)
                    status.setText(f"✓ Replaced embedded PDF for R.No. {rno}. Search-index update deferred until you choose Re-index Now.")
                else:
                    result=self.db.add_new_master_pdf(path)
                    self._mark_master_index_pending(1)
                    status.setText(f"✓ Added new R.No. {rno} to MASTER.db. Search-index update deferred until you choose Re-index Now.")
                self.refresh_status(); self.refresh_developer_stats();
            except Exception as e:
                status.setText(f'❌ {e}'); return
        save.clicked.connect(commit)
        dlg.exec()
        # One consolidated prompt after a batch of maintenance operations.
        self._offer_pending_master_index_rebuild(self)

    def edit_master_metadata(self):
        """Review MASTER metadata by direct R.No. lookup or sequential navigation while previewing the exact embedded PDF.

        Canonical identity is the PDF filename stem: 1223.pdf means R.No. 1223
        and 1223A.pdf means R.No. 1223A. Lookup therefore uses filename identity.
        """
        rows = self.db.get_editable_documents()
        if not rows:
            QMessageBox.information(self, APP_NAME, "No approval records are available for editing.")
            return

        current_id = None
        if self.current_row:
            try:
                current_id = int(self.current_row.get("id"))
            except Exception:
                current_id = None

        pos = 0
        if current_id is not None:
            for i, r in enumerate(rows):
                if int(r.get("id") or -1) == current_id:
                    pos = i
                    break

        dlg = QDialog(self)
        dlg.setWindowTitle("✎ Edit MASTER Approval Metadata")
        dlg.resize(1450, 860)
        dlg.setMinimumSize(1080, 650)

        outer = QVBoxLayout(dlg)
        outer.setContentsMargins(16, 16, 16, 16)
        outer.setSpacing(10)

        title = QLabel("MASTER METADATA REVIEW & PDF VERIFICATION")
        title.setStyleSheet("font-size:18px; font-weight:800;")
        outer.addWidget(title)

        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        outer.addWidget(splitter, 1)

        # ---------------- Left: metadata ----------------
        editor_panel = QWidget()
        editor_layout = QVBoxLayout(editor_panel)
        editor_layout.setContentsMargins(8, 8, 8, 8)
        editor_layout.setSpacing(10)

        # Direct approval-number lookup. This is useful during manual master-data
        # verification: type an exact R.No. such as 1234 or 1234A and load that
        # approval immediately, instead of navigating sequentially from another row.
        lookup_row = QHBoxLayout()
        lookup_label = QLabel("Go to R.No.")
        lookup_input = QLineEdit()
        lookup_input.setPlaceholderText("Enter exact R.No., e.g. 1234 or 1234A")
        lookup_input.setClearButtonEnabled(True)
        lookup_input.setToolTip("Enter the R.No.; the editor loads the exact same-named PDF, e.g. 1236 -> 1236.pdf.")
        lookup_btn = QPushButton("🔎  Load")
        lookup_btn.setToolTip("Load this approval from MASTER.db")
        lookup_row.addWidget(lookup_label)
        lookup_row.addWidget(lookup_input, 1)
        lookup_row.addWidget(lookup_btn)
        editor_layout.addLayout(lookup_row)

        position_label = QLabel()
        position_label.setStyleSheet(f"color:{MUTED}; font-weight:600;")
        editor_layout.addWidget(position_label)

        source_label = QLabel()
        source_label.setWordWrap(True)
        source_label.setStyleSheet(f"color:{MUTED}; font-size:11px;")
        editor_layout.addWidget(source_label)

        verify_label = QLabel("PDF Preview: loading embedded approval from MASTER.db...")
        verify_label.setWordWrap(True)
        verify_label.setStyleSheet(f"color:{BLUE}; font-size:11px; font-weight:600;")
        editor_layout.addWidget(verify_label)

        form = QFormLayout()
        form.setLabelAlignment(Qt.AlignmentFlag.AlignRight)
        form.setSpacing(12)

        approval = QLineEdit()
        approval.setReadOnly(True)
        approval.setPlaceholderText("Derived automatically from PDF filename")
        approval.setToolTip("R.No./Approval No. is the PDF filename without .pdf and is not edited separately.")
        file_no = QLineEdit()
        date = QLineEdit()
        subject = QPlainTextEdit()
        subject.setMinimumHeight(220)
        subject_ocr_hint = QLabel("Use Screen OCR in the PDF preview: select the Subject area, then paste the copied OCR text here.")
        subject_ocr_hint.setWordWrap(True)
        subject_ocr_hint.setStyleSheet(f"color:{MUTED}; font-size:11px;")

        form.addRow("Approval No. / R.No. (PDF identity)", approval)
        form.addRow("File / Memo No.", file_no)
        form.addRow("Date", date)
        form.addRow("Subject", subject)
        editor_layout.addLayout(form, 1)
        editor_layout.addWidget(subject_ocr_hint)

        status = QLabel("")
        status.setWordWrap(True)
        editor_layout.addWidget(status)

        splitter.addWidget(editor_panel)

        # ---------------- Right: exact PDF being verified ----------------
        preview_panel = QWidget()
        preview_layout = QVBoxLayout(preview_panel)
        preview_layout.setContentsMargins(4, 4, 4, 4)
        preview_layout.setSpacing(6)

        preview_title = QLabel("EMBEDDED APPROVAL PDF PREVIEW")
        preview_title.setStyleSheet("font-size:13px; font-weight:800;")
        preview_layout.addWidget(preview_title)

        preview = PdfViewer()
        preview.setMinimumWidth(520)
        preview_layout.addWidget(preview, 1)
        splitter.addWidget(preview_panel)
        splitter.setStretchFactor(0, 0)
        splitter.setStretchFactor(1, 1)
        splitter.setSizes([430, 900])

        # Navigation remains below the split view so it is always available.
        nav = QHBoxLayout()
        previous_btn = QPushButton("◀  Previous")

        delete_btn = QPushButton("🗑  Delete Record")
        delete_btn.setToolTip(
            "Delete the current MASTER record, embedded PDF and search-index entry."
        )

        replace_pdf_btn = QPushButton("📄  Replace PDF")
        replace_pdf_btn.setToolTip(
            "Replace the embedded PDF while keeping R.No. and metadata unchanged."
        )

        save_btn = QPushButton("💾  Save Corrections")
        next_btn = QPushButton("Next  ▶")
        close_btn = QPushButton("Close")

        nav.addWidget(previous_btn)
        nav.addWidget(delete_btn)
        nav.addWidget(replace_pdf_btn)
        nav.addStretch()
        nav.addWidget(save_btn)
        nav.addWidget(next_btn)
        nav.addWidget(close_btn)
        outer.addLayout(nav)

        dirty = {"value": False}
        loading = {"value": False}
        pos_holder = {"value": pos}

        def normalized_rno(value):
            # Case-insensitive exact lookup while preserving the actual stored text.
            return re.sub(r"\s+", "", (value or "")).casefold()

        def mark_dirty(*_):
            if not loading["value"]:
                dirty["value"] = True

        approval.textChanged.connect(mark_dirty)
        file_no.textChanged.connect(mark_dirty)
        date.textChanged.connect(mark_dirty)
        subject.textChanged.connect(mark_dirty)

        def approval_display(value):
            value = (value or "").strip()
            return value if value else "—"

        def load_embedded_pdf(r):
            verify_label.setText("PDF Preview: loading exact embedded PDF from MASTER.db...")
            QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
            try:
                pdf_bytes, filename = self.db.get_pdf_blob_by_filename(r.get("file_name"))
                if not pdf_bytes:
                    preview.close_doc()
                    preview.file_label.setText("Embedded PDF not found")
                    preview.image_label.setPixmap(QPixmap())
                    preview.image_label.setText(
                        "No embedded PDF BLOB was found for this approval in MASTER.db."
                    )
                    verify_label.setText("✗ PDF verification failed: embedded BLOB not found.")
                    verify_label.setStyleSheet("color:#e57373; font-size:11px; font-weight:700;")
                    return
                preview.load_pdf_bytes(
                    pdf_bytes,
                    filename or r.get("file_name") or "Embedded approval.pdf",
                    [],
                    self.settings.get("highlight_color", SEARCH_HIGHLIGHT_DEFAULT),
                )
                verify_label.setText(
                    f"✓ PDF verification: previewing embedded BLOB • "
                    f"{filename or r.get('file_name') or 'approval.pdf'}"
                )
                verify_label.setStyleSheet("color:#52ba8a; font-size:11px; font-weight:700;")
            except Exception as e:
                preview.close_doc()
                preview.image_label.setPixmap(QPixmap())
                preview.image_label.setText(f"Cannot load embedded PDF:\n{e}")
                verify_label.setText(f"✗ PDF verification failed: {e}")
                verify_label.setStyleSheet("color:#e57373; font-size:11px; font-weight:700;")
            finally:
                QApplication.restoreOverrideCursor()

        def load_row(index):
            loading["value"] = True
            try:
                r = rows[index]
                canonical_rno = self.db._approval_number_from_filename(r.get("file_name"))
                r["approval_number"] = canonical_rno
                mm = re.search(r"\d+", canonical_rno)
                r["approval_number_numeric"] = int(mm.group()) if mm else 0
                current_number = approval_display(canonical_rno)
                position_label.setText(
                    f"Approval {index + 1} of {len(rows)}   •   "
                    f"Current Approval No. / R.No.: {current_number}"
                )
                source_label.setText(
                    f"Source PDF: {r.get('file_name') or '—'}   •   "
                    f"Document ID: {r.get('id') or '—'}   •   Canonical match: {current_number}.pdf"
                )
                approval.setText(canonical_rno)
                lookup_input.setText(canonical_rno)
                file_no.setText(r.get("file_number") or r.get("memo_number") or "")
                date.setText(normalize_display_date(r.get("approval_date") or ""))
                subject.setPlainText(r.get("subject") or "")
                previous_btn.setEnabled(index > 0)
                next_btn.setEnabled(index < len(rows) - 1)
                dirty["value"] = False
                status.setText("")
            finally:
                loading["value"] = False

            # Preview only after form data is loaded. This PDF comes from the
            # exact BLOB linked to this source document ID.
            load_embedded_pdf(r)

        def save_current(show_message=True):
            r = rows[pos_holder["value"]]
            approval_value = self.db._approval_number_from_filename(r.get("file_name"))
            if not approval_value:
                QMessageBox.warning(dlg, APP_NAME, "Cannot derive R.No. from the PDF filename.")
                return False
            try:
                corrected_date = normalize_display_date(date.text())
                date.setText(corrected_date)
                self.db.update_metadata(
                    r["id"], approval_value, file_no.text(), corrected_date, subject.toPlainText()
                )
                r["approval_number"] = approval_value
                lookup_input.setText(approval_value)
                r["file_number"] = file_no.text().strip()
                r["memo_number"] = file_no.text().strip()
                r["approval_date"] = normalize_display_date(date.text())
                r["subject"] = subject.toPlainText().strip()
                m = re.search(r"\d+", approval_value)
                r["approval_number_numeric"] = int(m.group()) if m else 0
                dirty["value"] = False
                position_label.setText(
                    f"Approval {pos_holder['value'] + 1} of {len(rows)}   •   "
                    f"Current Approval No. / R.No.: {approval_display(approval_value)}"
                )
                status.setText("✓ Saved to MASTER.db and synchronized with the searchable index.")
                self.current_row = r
                if show_message:
                    QMessageBox.information(dlg, APP_NAME, "Metadata saved successfully.")
                return True
            except Exception as e:
                QMessageBox.warning(dlg, APP_NAME, f"Could not update metadata:\n{e}")
                return False


        def delete_current_record():
            index = pos_holder["value"]
            r = rows[index]
            filename = str(r.get("file_name") or "").strip()
            rno = self.db._approval_number_from_filename(filename)

            if dirty["value"]:
                answer = QMessageBox.question(
                    dlg, APP_NAME,
                    "There are unsaved metadata changes.\n\n"
                    "Discard them and continue with deletion?",
                    QMessageBox.StandardButton.Discard
                    | QMessageBox.StandardButton.Cancel,
                    QMessageBox.StandardButton.Cancel,
                )
                if answer != QMessageBox.StandardButton.Discard:
                    return

            answer = QMessageBox.warning(
                dlg, APP_NAME,
                f"DELETE MASTER RECORD?\n\n"
                f"R.No.: {rno or '—'}\n"
                f"PDF: {filename or '—'}\n\n"
                "This permanently removes the MASTER metadata, embedded PDF "
                "and corresponding searchable-index entry.\n\n"
                "This action cannot be undone.",
                QMessageBox.StandardButton.Yes
                | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if answer != QMessageBox.StandardButton.Yes:
                return

            QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
            try:
                self.db.delete_master_record_by_filename(filename)
                rows.pop(index)

                if not rows:
                    dlg.accept()
                    try:
                        self.refresh_status()
                    except Exception:
                        pass
                    return

                new_index = min(index, len(rows) - 1)
                pos_holder["value"] = new_index
                dirty["value"] = False
                self.current_row = rows[new_index]
                load_row(new_index)

                status.setText(
                    f"✓ MASTER record {rno or filename} deleted successfully."
                )
                status.setStyleSheet(
                    "color:#52ba8a; font-size:11px; font-weight:700;"
                )
                QMessageBox.information(
                    dlg, APP_NAME,
                    f"MASTER record {rno or filename} was deleted successfully."
                )
            except Exception as e:
                QMessageBox.warning(
                    dlg, APP_NAME,
                    f"Could not delete MASTER record:\n{e}"
                )
            finally:
                QApplication.restoreOverrideCursor()

        def replace_current_pdf():
            r = rows[pos_holder["value"]]
            filename = str(r.get("file_name") or "").strip()
            rno = self.db._approval_number_from_filename(filename)

            if not filename:
                QMessageBox.warning(
                    dlg, APP_NAME, "The current MASTER record has no PDF filename."
                )
                return

            selected, _ = QFileDialog.getOpenFileName(
                dlg,
                f"Replace PDF for R.No. {rno}",
                "",
                "PDF files (*.pdf)",
            )
            if not selected:
                return

            selected_path = Path(selected)
            replacement_rno = self.db._approval_number_from_filename(
                selected_path.name
            )

            if not replacement_rno or replacement_rno.casefold() != rno.casefold():
                QMessageBox.warning(
                    dlg, APP_NAME,
                    "Replacement rejected.\n\n"
                    f"Current R.No.: {rno}\n"
                    f"Selected PDF: {selected_path.name}\n"
                    f"Selected R.No.: {replacement_rno or 'not detected'}\n\n"
                    "The replacement PDF must have the same R.No. filename."
                )
                return

            answer = QMessageBox.question(
                dlg, APP_NAME,
                f"REPLACE EMBEDDED PDF?\n\n"
                f"R.No.: {rno}\n"
                f"Current PDF: {filename}\n"
                f"New PDF: {selected_path.name}\n\n"
                "File/Memo No., Date and Subject will remain unchanged.\n"
                "Only the embedded PDF BLOB will be replaced.",
                QMessageBox.StandardButton.Yes
                | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if answer != QMessageBox.StandardButton.Yes:
                return

            QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
            try:
                result = self.db.replace_master_pdf_by_filename(
                    filename, selected_path
                )
                load_embedded_pdf(r)
                # V22.3.43: do NOT start indexing here. MASTER.db is already
                # permanently updated and the disposable search index is allowed
                # to remain stale until the user explicitly chooses Re-index Now.
                # This lets 10/20/100 PDF replacements be batched into one index run.
                self._mark_master_index_pending(1)
                dirty["value"] = False

                status.setText(
                    f"✓ PDF replaced successfully • "
                    f"{result['page_count']} page(s) • "
                    f"{result['pdf_size']:,} bytes"
                )
                status.setStyleSheet(
                    "color:#52ba8a; font-size:11px; font-weight:700;"
                )
                QMessageBox.information(
                    dlg, APP_NAME,
                    f"Embedded PDF for R.No. {rno} was replaced successfully.\n\n"
                    f"Pages: {result['page_count']}\n"
                    f"Size: {result['pdf_size']:,} bytes"
                )
            except Exception as e:
                QMessageBox.warning(
                    dlg, APP_NAME,
                    f"Could not replace the embedded PDF:\n{e}"
                )
            finally:
                QApplication.restoreOverrideCursor()

        def maybe_save_before_move(move_to):
            if dirty["value"]:
                answer = QMessageBox.question(
                    dlg, APP_NAME,
                    "Save changes to the current approval before moving?",
                    QMessageBox.StandardButton.Save | QMessageBox.StandardButton.Discard | QMessageBox.StandardButton.Cancel,
                    QMessageBox.StandardButton.Save,
                )
                if answer == QMessageBox.StandardButton.Cancel:
                    return False
                if answer == QMessageBox.StandardButton.Save and not save_current(False):
                    return False
            pos_holder["value"] = move_to
            load_row(move_to)
            return True

        def go_to_rno():
            requested = lookup_input.text().strip()
            if not requested:
                QMessageBox.information(dlg, APP_NAME, "Enter an Approval No. / R.No. first.")
                lookup_input.setFocus()
                return

            key = normalized_rno(requested)
            match_index = None
            # Canonical lookup: 1236 means exact file 1236.pdf.
            for i, candidate in enumerate(rows):
                canonical = normalized_rno(self.db._approval_number_from_filename(candidate.get("file_name")))
                if canonical == key:
                    match_index = i
                    break

            if match_index is None:
                QMessageBox.warning(
                    dlg, APP_NAME,
                    f"Approval No. / R.No. '{requested}' was not found in MASTER.db.\n\n"
                    "The exact PDF identity was not found. 1234 requires 1234.pdf; 1234A requires 1234A.pdf."
                )
                lookup_input.selectAll()
                lookup_input.setFocus()
                return

            if match_index == pos_holder["value"]:
                load_row(match_index)
                return

            maybe_save_before_move(match_index)

        def go_previous():
            i = pos_holder["value"]
            if i > 0:
                maybe_save_before_move(i - 1)

        def go_next():
            i = pos_holder["value"]
            if i < len(rows) - 1:
                maybe_save_before_move(i + 1)

        def close_editor():
            if dirty["value"]:
                answer = QMessageBox.question(
                    dlg, APP_NAME,
                    "Save changes before closing?",
                    QMessageBox.StandardButton.Save | QMessageBox.StandardButton.Discard | QMessageBox.StandardButton.Cancel,
                    QMessageBox.StandardButton.Save,
                )
                if answer == QMessageBox.StandardButton.Cancel:
                    return
                if answer == QMessageBox.StandardButton.Save and not save_current(False):
                    return
            preview.close_doc()
            dlg.accept()

        lookup_btn.clicked.connect(go_to_rno)
        lookup_input.returnPressed.connect(go_to_rno)
        delete_btn.clicked.connect(delete_current_record)
        replace_pdf_btn.clicked.connect(replace_current_pdf)
        previous_btn.clicked.connect(go_previous)
        next_btn.clicked.connect(go_next)
        save_btn.clicked.connect(lambda: save_current(True))
        close_btn.clicked.connect(close_editor)
        load_row(pos)
        dlg.exec()
        preview.close_doc()

        # V22.3.43: consolidate all PDF replacements made during this editor
        # session into one explicit re-index decision. If skipped, next startup
        # will detect the stale MASTER/index registry pair and rebuild then.
        self._offer_pending_master_index_rebuild(self)

        try:
            self.perform_search()
        except Exception:
            pass

    def edit_selected_metadata(self):
        """Compatibility entry point: open the new sequential MASTER editor."""
        self.edit_master_metadata()


