    def open_sstn_statistics(self, parent=None):
        """Interactive read-only SSTN Statistics dashboard.

        V22.3.5 enhancement:
          * Main abstract includes a filter-aware voltage/rating-wise Existing vs Approved
            transformer TF/MVA capacity summary with a TOTAL row.

        V19 rules:
          * Voltage-wise totals are based on the transformer HIGH-SIDE voltage
            parsed from each voltage ratio, not the SSTN_MASTER voltage label.
          * 765/400 -> 765 kV; 400/220 -> 400 kV; 220/132, 220/66,
            220/33 -> 220 kV; 132/66 -> 132 kV; 66/11 -> 66 kV.
          * No FY is invented: only non-blank approved_fy values stored in
            SSTN_INFRA are used.
          * All chart values are permanently displayed; clicks open details.
        """
        host = parent if parent is not None else self
        try:
            masters = self.db.list_sstn_master()
            infras = self.db.list_sstn_infra()
        except Exception as e:
            QMessageBox.critical(host, APP_NAME, f"Could not read SSTN data from MASTER.db:\n\n{e}")
            return

        by_sid = {str(r.get('sstn_id')): [] for r in masters}
        for r in infras:
            by_sid.setdefault(str(r.get('sstn_id')), []).append(dict(r))
        for sid in by_sid:
            by_sid[sid].sort(key=lambda x: int(x.get('seq_no') or 0))

        voltage_levels = [765.0, 400.0, 220.0, 132.0, 66.0]
        voltage_labels = {765.0: '765 kV', 400.0: '400 kV', 220.0: '220 kV', 132.0: '132 kV', 66.0: '66 kV'}
        voltage_keys = {v: f'{v:g}KV' for v in voltage_levels}

        def state_totals(text):
            return _sstn_transformer_totals(text)

        # V22.3.13 filter state: actual stored voltage ratio + actual upper MVA rating.
        active_ratio_filter = 'All Ratios'
        active_capacity_filter = 'All Capacities'

        def transformer_filter_match(x):
            ratio_ok = (active_ratio_filter == 'All Ratios' or
                        str(x.get('ratio') or '').strip() == active_ratio_filter)
            try:
                rating = float(x.get('high_mva') or 0)
            except Exception:
                rating = 0.0
            if active_capacity_filter == 'All Capacities':
                cap_ok = True
            else:
                try:
                    wanted = float(str(active_capacity_filter).replace(' MVA', '').strip())
                    cap_ok = abs(rating - wanted) < 0.01
                except Exception:
                    cap_ok = False
            return ratio_ok and cap_ok

        def state_totals_filtered(text):
            if active_ratio_filter == 'All Ratios' and active_capacity_filter == 'All Capacities':
                return _sstn_transformer_totals(text)
            tf = 0
            mva = 0.0
            for x in _sstn_parse_transformers(text):
                if not transformer_filter_match(x):
                    continue
                cnt = int(x.get('count') or 0)
                rating = float(x.get('high_mva') or 0)
                tf += cnt
                mva += cnt * rating
            return {'tf_count': tf, 'mva': mva}

        def stats_filter_options():
            ratios = set()
            capacities = set()
            for rec in infras:
                for field in ('existing_capacity', 'approved_capacity'):
                    for x in _sstn_parse_transformers(rec.get(field, '')):
                        ratio = str(x.get('ratio') or '').strip()
                        if ratio:
                            ratios.add(ratio)
                        try:
                            rating = float(x.get('high_mva') or 0)
                            if rating > 0:
                                capacities.add(rating)
                        except Exception:
                            pass
            def _rk(s):
                nums = [float(v) for v in re.findall(r'\d+(?:\.\d+)?', s)]
                return (nums[0] if nums else 0, nums[1] if len(nums) > 1 else 0)
            return sorted(ratios, key=lambda s: (-_rk(s)[0], -_rk(s)[1], s)), sorted(capacities)

        def normalized_master_voltage(m):
            return str(m.get('voltage_level') or '').replace(' ', '').upper()

        def filtered_records(district='All Districts', voltage='All Voltages', ratio_filter='All Ratios', capacity_filter='All Capacities'):
            out = []
            for m in masters:
                if district != 'All Districts' and str(m.get('district') or '').strip() != district:
                    continue
                mv = normalized_master_voltage(m)
                if voltage != 'All Voltages' and mv != voltage.upper():
                    continue
                stages = by_sid.get(str(m.get('sstn_id')), [])
                if not stages:
                    continue
                first = next((x for x in stages if str(x.get('existing_capacity') or '').strip()), stages[0])
                last = stages[-1]
                ex = state_totals_filtered(first.get('existing_capacity', ''))
                ap = state_totals_filtered(last.get('approved_capacity', ''))

                # When a transformer Ratio and/or Capacity filter is selected,
                # a station is part of the filtered dataset ONLY when that
                # transformer filter actually matches at least one transformer
                # in its existing or approved state.  Previously the station
                # itself was retained even when the selected ratio/capacity
                # matched nothing, producing phantom rows such as a 400 kV
                # station with 0 TF / 0 MVA under a 132/33 kV filter.
                if active_ratio_filter != 'All Ratios' or active_capacity_filter != 'All Capacities':
                    _has_matching_transformer = False
                    for _txt in (
                        first.get('existing_capacity', ''),
                        last.get('approved_capacity', '')
                    ):
                        for _x in _sstn_parse_transformers(_txt):
                            if transformer_filter_match(_x):
                                _has_matching_transformer = True
                                break
                        if _has_matching_transformer:
                            break
                    if not _has_matching_transformer:
                        continue

                out.append({'master': m, 'stages': stages, 'existing': ex, 'approved': ap})
            return out

        def setrow(table, row, vals):
            # QTableWidget sorting MUST be disabled while a row is being built.
            # With sorting enabled, inserting the first cell can immediately
            # reorder the row, causing the remaining cells to be written into
            # the wrong/empty rows.  This was the cause of blank detail rows in
            # Required Transformer drill-down windows.
            sorting_was_enabled = table.isSortingEnabled()
            if sorting_was_enabled:
                table.setSortingEnabled(False)
            try:
                table.insertRow(row)
                for j, v in enumerate(vals):
                    if j >= table.columnCount():
                        break
                    table.setItem(row, j, QTableWidgetItem(str(v)))
            finally:
                if sorting_was_enabled:
                    table.setSortingEnabled(True)


        # V22.3 table helpers.
        stats_tables = []

        def apply_stats_row_style(table):
            try:
                mode = row_style_box.currentText()
            except Exception:
                mode = str(self.settings.get('stats_row_style', 'Blue / Dark'))
            if mode == 'No Alternating':
                table.setAlternatingRowColors(False)
                table.setStyleSheet('')
            elif mode == 'Grey / Dark':
                table.setAlternatingRowColors(True)
                table.setStyleSheet('QTableWidget { alternate-background-color: #30343b; }')
            else:
                table.setAlternatingRowColors(True)
                table.setStyleSheet('QTableWidget { alternate-background-color: #06256f; }')

        def add_total_row(table, values):
            table.setSortingEnabled(False)
            row = table.rowCount()
            table.insertRow(row)
            for col, value in enumerate(values):
                if col >= table.columnCount():
                    break
                item = QTableWidgetItem(str(value))
                f = item.font(); f.setBold(True); item.setFont(f)
                table.setItem(row, col, item)
            apply_stats_row_style(table)

        def finish_stats_table(table, values):
            add_total_row(table, values)
            table.setSortingEnabled(False)
            apply_stats_row_style(table)

        def on_row_style_changed(mode):
            self.settings['stats_row_style'] = str(mode)
            try:
                save_settings(self.settings)
            except Exception:
                pass
            for _table in stats_tables:
                try:
                    apply_stats_row_style(_table)
                except Exception:
                    pass

        def make_table(headers):
            table = QTableWidget(0, len(headers))
            table.setHorizontalHeaderLabels(headers)
            table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.ResizeToContents)
            if headers:
                table.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
            table.setAlternatingRowColors(True)
            table.setSortingEnabled(True)
            stats_tables.append(table)
            apply_stats_row_style(table)
            table.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            table.customContextMenuRequested.connect(lambda pos, t=table: _stats_export_menu(t, pos))
            return table

        def _stats_matrix(table):
            headers = [(table.horizontalHeaderItem(c).text() if table.horizontalHeaderItem(c) else f'Column {c+1}')
                       for c in range(table.columnCount())]
            rows = [[table.item(r,c).text() if table.item(r,c) else '' for c in range(table.columnCount())]
                    for r in range(table.rowCount())]
            return headers, rows

        def _stats_export_xlsx(table):
            fn, _ = QFileDialog.getSaveFileName(sd, 'Export Statistics Table to Excel',
                                                'Statistics.xlsx', 'Excel Workbook (*.xlsx)')
            if not fn: return
            if not fn.lower().endswith('.xlsx'): fn += '.xlsx'
            try:
                headers, rows = _stats_matrix(table)
                def esc(v): return escape(str(v or ''))
                body = [f'<row r="1">' + ''.join(f'<c t="inlineStr"><is><t>{esc(h)}</t></is></c>' for h in headers) + '</row>']
                for ri,row in enumerate(rows,2):
                    body.append(f'<row r="{ri}">' + ''.join(f'<c t="inlineStr"><is><t>{esc(v)}</t></is></c>' for v in row) + '</row>')
                sheet = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                         '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'
                         + ''.join(body) + '</sheetData></worksheet>')
                workbook = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                            '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
                            '<sheets><sheet name="Statistics" sheetId="1" r:id="rId1"/></sheets></workbook>')
                rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>')
                rootrels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
                types = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                         '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                         '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                         '<Default Extension="xml" ContentType="application/xml"/>'
                         '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
                         '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                         '</Types>')
                with zipfile.ZipFile(fn,'w',zipfile.ZIP_DEFLATED) as z:
                    z.writestr('[Content_Types].xml',types); z.writestr('_rels/.rels',rootrels)
                    z.writestr('xl/workbook.xml',workbook); z.writestr('xl/_rels/workbook.xml.rels',rels)
                    z.writestr('xl/worksheets/sheet1.xml',sheet)
                QMessageBox.information(sd, APP_NAME, f'Excel export completed.\n\n{fn}')
            except Exception as e:
                QMessageBox.critical(sd, APP_NAME, f'Excel export failed.\n\n{e}')

        def _stats_export_word(table):
            fn, _ = QFileDialog.getSaveFileName(sd, 'Export Statistics Table to Word',
                                                'Statistics.docx', 'Word Document (*.docx)')
            if not fn: return
            if not fn.lower().endswith('.docx'): fn += '.docx'
            try:
                headers, rows = _stats_matrix(table)
                def tc(v,b=False):
                    rp='<w:rPr><w:b/></w:rPr>' if b else ''
                    return f'<w:tc><w:p><w:r>{rp}<w:t xml:space="preserve">{escape(str(v or ""))}</w:t></w:r></w:p></w:tc>'
                trs=['<w:tr>'+''.join(tc(h,True) for h in headers)+'</w:tr>']
                trs += ['<w:tr>'+''.join(tc(v) for v in row)+'</w:tr>' for row in rows]
                doc=('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                     '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'
                     '<w:p><w:r><w:rPr><w:b/></w:rPr><w:t>HVPNL Substation Statistics</w:t></w:r></w:p>'
                     '<w:tbl><w:tblPr><w:tblBorders><w:top w:val="single"/><w:left w:val="single"/><w:bottom w:val="single"/><w:right w:val="single"/><w:insideH w:val="single"/><w:insideV w:val="single"/></w:tblBorders></w:tblPr>'
                     + ''.join(trs) + '</w:tbl><w:sectPr/></w:body></w:document>')
                types=('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                       '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                       '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                       '<Default Extension="xml" ContentType="application/xml"/>'
                       '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
                       '</Types>')
                rootrels=('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                          '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>')
                with zipfile.ZipFile(fn,'w',zipfile.ZIP_DEFLATED) as z:
                    z.writestr('[Content_Types].xml',types); z.writestr('_rels/.rels',rootrels)
                    z.writestr('word/document.xml',doc)
                    z.writestr('word/_rels/document.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>')
                QMessageBox.information(sd, APP_NAME, f'Word export completed.\n\n{fn}')
            except Exception as e:
                QMessageBox.critical(sd, APP_NAME, f'Word export failed.\n\n{e}')

        def _stats_export_pdf(table):
            fn, _ = QFileDialog.getSaveFileName(
                sd, 'Export Statistics Table to PDF', 'Statistics.pdf', 'PDF Document (*.pdf)'
            )
            if not fn:
                return
            if not fn.lower().endswith('.pdf'):
                fn += '.pdf'
            try:
                headers, rows = _stats_matrix(table)
                # Use QTextDocument + QPrinter so PDF export does not require
                # any additional third-party package on the user's PC.
                html_parts = [
                    '<html><head><meta charset="utf-8"><style>'
                    'body{font-family:Arial;font-size:9pt;}'
                    'h2{font-size:14pt;} table{border-collapse:collapse;width:100%;}'
                    'th,td{border:1px solid #888;padding:4px;} th{font-weight:bold;}'
                    '</style></head><body><h2>HVPNL Substation Statistics</h2><table><tr>'
                ]
                html_parts += [f'<th>{escape(str(h))}</th>' for h in headers]
                html_parts.append('</tr>')
                for row in rows:
                    html_parts.append('<tr>')
                    html_parts += [f'<td>{escape(str(v or ""))}</td>' for v in row]
                    html_parts.append('</tr>')
                html_parts.append('</table></body></html>')

                doc = QTextDocument()
                doc.setHtml(''.join(html_parts))
                printer = QPrinter(QPrinter.PrinterMode.HighResolution)
                printer.setOutputFormat(QPrinter.OutputFormat.PdfFormat)
                printer.setOutputFileName(fn)
                doc.print_(printer)
                QMessageBox.information(sd, APP_NAME, f'PDF export completed.\n\n{fn}')
            except Exception as e:
                QMessageBox.critical(sd, APP_NAME, f'PDF export failed.\n\n{e}')

        def _stats_export_menu(table, pos):
            menu = QMenu(table)
            menu.addAction('Export to Excel (.xlsx)', lambda: _stats_export_xlsx(table))
            menu.addAction('Export to Word (.docx)', lambda: _stats_export_word(table))
            menu.addAction('Export to PDF (.pdf)', lambda: _stats_export_pdf(table))
            menu.exec(table.viewport().mapToGlobal(pos))

        def add_stats_export_bar(layout, table):
            # Every Statistics detail list gets both the existing right-click
            # export menu and a visible Export button for discoverability.
            bar = QHBoxLayout()
            btn = QPushButton('Export')
            menu = QMenu(btn)
            menu.addAction('Export to Excel (.xlsx)', lambda: _stats_export_xlsx(table))
            menu.addAction('Export to Word (.docx)', lambda: _stats_export_word(table))
            menu.addAction('Export to PDF (.pdf)', lambda: _stats_export_pdf(table))
            btn.setMenu(menu)
            bar.addWidget(btn)
            bar.addStretch(1)
            layout.addLayout(bar)

        def scroll_page(widget):
            scroll = QScrollArea()
            scroll.setWidgetResizable(True)
            scroll.setFrameShape(QFrame.Shape.NoFrame)
            scroll.setWidget(widget)
            return scroll

        def aggregate_by_high_voltage(recs, state_name):
            result = {v: {'tf': 0, 'mva': 0.0} for v in voltage_levels}
            for r in recs:
                textv = next((x.get('existing_capacity', '') for x in r['stages'] if str(x.get('existing_capacity') or '').strip()), '') if state_name == 'existing' else r['stages'][-1].get('approved_capacity', '')
                for x in _sstn_parse_transformers(textv):
                    if not transformer_filter_match(x):
                        continue
                    hv = float(x.get('hv') or 0)
                    match = next((v for v in voltage_levels if abs(hv - v) < 0.01), None)
                    if match is None:
                        continue
                    result[match]['tf'] += int(x['count'])
                    result[match]['mva'] += int(x['count']) * float(x['high_mva'])
            return result

        def aggregate_ratio(recs, state_name):
            result = {}
            for r in recs:
                textv = next((x.get('existing_capacity', '') for x in r['stages'] if str(x.get('existing_capacity') or '').strip()), '') if state_name == 'existing' else r['stages'][-1].get('approved_capacity', '')
                for x in _sstn_parse_transformers(textv):
                    if not transformer_filter_match(x):
                        continue
                    ratio = str(x['ratio'])
                    d = result.setdefault(ratio, {'tf': 0, 'mva': 0.0})
                    d['tf'] += int(x['count'])
                    d['mva'] += int(x['count']) * float(x['high_mva'])
            return result

        def aggregate_voltage_rating(recs, state_name):
            # Summary List key MUST be the actual transformer voltage ratio
            # plus MVA rating.  Do not derive the LV voltage from the MVA
            # rating or from the parent SSTN voltage.
            result = {}
            for r in recs:
                textv = (next((x.get('existing_capacity', '') for x in r['stages']
                               if str(x.get('existing_capacity') or '').strip()), '')
                         if state_name == 'existing' else
                         (r['stages'][-1].get('approved_capacity', '') if r['stages'] else ''))
                for x in _sstn_parse_transformers(textv):
                    if not transformer_filter_match(x):
                        continue
                    ratio = str(x.get('ratio') or '').strip()
                    rating = float(x.get('high_mva') or 0)
                    if not ratio or rating <= 0:
                        continue
                    key = (ratio, rating)
                    d = result.setdefault(key, {'tf': 0, 'mva': 0.0})
                    d['tf'] += int(x.get('count') or 0)
                    d['mva'] += int(x.get('count') or 0) * rating
            return result

