        def _kpi_ratio_rows(recs):
            """Build one detail row per SUBSTATION + exact transformer voltage ratio.

            Only the first recorded existing state and the final approved state
            are used.  Intermediate Seq./planning stages are never added to
            transformer capacity, preventing the same station capacity from
            being counted more than once.
            """
            rows = []
            for r in recs:
                m = r['master']
                stages = r['stages']
                if not stages:
                    continue

                existing_stage = next(
                    (x for x in stages if str(x.get('existing_capacity') or '').strip()), None
                )
                existing_text = existing_stage.get('existing_capacity', '') if existing_stage else ''
                approved_stage = next(
                    (x for x in reversed(stages) if str(x.get('approved_capacity') or '').strip()), None
                )
                approved_text = approved_stage.get('approved_capacity', '') if approved_stage else ''

                ex_by = {}
                for x in _sstn_parse_transformers(existing_text):
                    if not transformer_filter_match(x):
                        continue
                    ratio = str(x.get('ratio') or '').strip()
                    if not ratio:
                        continue
                    d = ex_by.setdefault(ratio, {'tf': 0, 'mva': 0.0, 'ratings': set()})
                    cnt = int(x.get('count') or 0)
                    rating = float(x.get('high_mva') or 0)
                    d['tf'] += cnt
                    d['mva'] += cnt * rating
                    if rating > 0:
                        d['ratings'].add(rating)

                ap_by = {}
                for x in _sstn_parse_transformers(approved_text):
                    if not transformer_filter_match(x):
                        continue
                    ratio = str(x.get('ratio') or '').strip()
                    if not ratio:
                        continue
                    d = ap_by.setdefault(ratio, {'tf': 0, 'mva': 0.0, 'ratings': set()})
                    cnt = int(x.get('count') or 0)
                    rating = float(x.get('high_mva') or 0)
                    d['tf'] += cnt
                    d['mva'] += cnt * rating
                    if rating > 0:
                        d['ratings'].add(rating)

                ratios = sorted(set(ex_by) | set(ap_by), key=_ratio_sort_key)
                for ratio in ratios:
                    ex = ex_by.get(ratio, {'tf': 0, 'mva': 0.0, 'ratings': set()})
                    ap = ap_by.get(ratio, {'tf': 0, 'mva': 0.0, 'ratings': set()})
                    ex_tf, ap_tf = int(ex['tf']), int(ap['tf'])
                    ex_mva, ap_mva = float(ex['mva']), float(ap['mva'])
                    needed = max(0, ap_tf - ex_tf)
                    spare = max(0, ex_tf - ap_tf)
                    ratings = sorted(ex['ratings'] | ap['ratings'])
                    rating_text = ', '.join(f'{v:g}' for v in ratings) + ' MVA' if ratings else '—'
                    rows.append({
                        'substation': m.get('sstn_name', ''),
                        'district': m.get('district', ''),
                        'sstn_voltage': m.get('voltage_level', ''),
                        'ratio': ratio,
                        'existing_tf': ex_tf,
                        'existing_mva': ex_mva,
                        'approved_tf': ap_tf,
                        'approved_mva': ap_mva,
                        'needed_tf': needed,
                        'spare': spare,
                        'stage_count': len(stages),
                        'rating': rating_text,
                    })
            return rows

        def show_kpi_detail(kind):
            dlg = QDialog(sd)
            dlg.setWindowTitle(f'Statistics Details — {kind}')
            dlg.resize(1550, 820)
            lay = QVBoxLayout(dlg)
            lay.addWidget(QLabel(
                f'{kind} details under current District / Voltage / Voltage Ratio / Transformer Capacity filters. '
                f'Each transformer row is one substation + exact voltage ratio; intermediate Seq./planning stages '
                f'are not added to transformer capacity totals.'
            ))

            table = make_table([
                'Substation', 'District', 'SSTN Voltage', 'Voltage Ratio',
                'Existing TFs', 'Existing MVA', 'Approved TFs', 'Approved MVA',
                'Needed TFs', 'Spare / Plan Surplus', 'Infra Stages'
            ])
            lay.addWidget(table, 1)
            add_stats_export_bar(lay, table)

            recs = filtered_records(
                district_box.currentText(), voltage_box.currentText(),
                ratio_box.currentText(), capacity_box.currentText()
            )

            # Infra Stages is a stage/event list, not a transformer-capacity
            # aggregation.  It is therefore intentionally handled separately.
            if kind == 'Infra Stages':
                table.setColumnCount(9)
                table.setHorizontalHeaderLabels([
                    'Substation', 'District', 'Seq.', 'Voltage Ratio',
                    'Existing Capacity', 'Approved Capacity',
                    'Approved FY', 'Approval R.No.', 'Status'
                ])
                rr = 0
                unique_stage_total = 0
                for r in recs:
                    m = r['master']
                    stages = r['stages']
                    for st in stages:
                        # Show ratios represented by this stage, but never
                        # repeat the stage as multiple capacity rows.
                        ratios = []
                        for field in ('existing_capacity', 'approved_capacity'):
                            for x in _sstn_parse_transformers(st.get(field, '')):
                                rr0 = str(x.get('ratio') or '').strip()
                                if rr0 and transformer_filter_match(x) and rr0 not in ratios:
                                    ratios.append(rr0)
                        ratio_text = ', '.join(sorted(ratios, key=_ratio_sort_key)) or '—'
                        setrow(table, rr, [
                            m.get('sstn_name', ''), m.get('district', ''),
                            st.get('seq_no', ''), ratio_text,
                            st.get('existing_capacity', ''),
                            st.get('approved_capacity', ''),
                            st.get('approved_fy', ''),
                            st.get('approved_rno', '') or st.get('r_no', '') or '—',
                            'Recorded'
                        ])
                        rr += 1
                        unique_stage_total += 1
                finish_stats_table(table, [
                    'TOTAL', '', '', '',
                    '', '', '', '', f'{unique_stage_total:,} stages'
                ])
            else:
                detail_rows = _kpi_ratio_rows(recs)

                def wanted(row):
                    if kind == 'Substations':
                        return True
                    if kind == 'Existing MVA':
                        return row['existing_mva'] > 0
                    if kind == 'Existing TFs':
                        return row['existing_tf'] > 0
                    if kind == 'Approved MVA':
                        return row['approved_mva'] > 0
                    if kind == 'Approved TFs':
                        return row['approved_tf'] > 0
                    if kind == 'Needed TFs':
                        return row['needed_tf'] > 0
                    if kind == 'Spare / Plan Surplus':
                        return row['spare'] > 0
                    return True

                detail_rows = [row for row in detail_rows if wanted(row)]

                for rr, row in enumerate(detail_rows):
                    setrow(table, rr, [
                        row['substation'], row['district'], row['sstn_voltage'], row['ratio'],
                        f"{row['existing_tf']:,}", f"{row['existing_mva']:,.1f}",
                        f"{row['approved_tf']:,}", f"{row['approved_mva']:,.1f}",
                        f"{row['needed_tf']:,}", f"{row['spare']:,}",
                        f"{row['stage_count']:,}"
                    ])

                # Transformer figures are summed by ratio row exactly once.
                # Stage count is deliberately NOT summed across ratio rows;
                # it is counted once per station in the selected detail set.
                unique_station_stage_total = sum(
                    len(r['stages']) for r in recs
                    if any(
                        row['substation'] == r['master'].get('sstn_name', '')
                        and row['district'] == r['master'].get('district', '')
                        for row in detail_rows
                    )
                )
                finish_stats_table(table, [
                    'TOTAL', '', '', '',
                    f"{sum(x['existing_tf'] for x in detail_rows):,}",
                    f"{sum(x['existing_mva'] for x in detail_rows):,.1f}",
                    f"{sum(x['approved_tf'] for x in detail_rows):,}",
                    f"{sum(x['approved_mva'] for x in detail_rows):,.1f}",
                    f"{sum(x['needed_tf'] for x in detail_rows):,}",
                    f"{sum(x['spare'] for x in detail_rows):,}",
                    f"{unique_station_stage_total:,}"
                ])

            attach_stats_rno_pdf(table)
            apply_stats_row_style(table)

            close = QPushButton('Close')
            close.clicked.connect(dlg.accept)
            lay.addWidget(close)
            dlg.exec()

