        def apply_stats_row_style(table):
            try:
                mode = str(row_style_box.currentText() or 'Blue / Dark')
            except Exception:
                mode = str(self.settings.get('stats_row_style', 'Blue / Dark'))
            if mode == 'No Alternating':
                table.setAlternatingRowColors(False)
                table.setStyleSheet('')
            elif mode == 'Grey / Dark':
                table.setAlternatingRowColors(True)
                table.setStyleSheet('QTableWidget { alternate-background-color: #30343b; }')
            else:
                table.setAlternatingRowColors(True)
                table.setStyleSheet('QTableWidget { alternate-background-color: #06256f; }')

        def add_total_row(table, values):
            table.setSortingEnabled(False)
            row = table.rowCount()
            table.insertRow(row)
            for col, value in enumerate(values):
                if col >= table.columnCount(): break
                item = QTableWidgetItem(str(value))
                f = item.font(); f.setBold(True); item.setFont(f)
                table.setItem(row, col, item)
            apply_stats_row_style(table)

        def on_row_style_changed(mode):
            self.settings['stats_row_style'] = str(mode or 'Blue / Dark')
            try: save_settings(self.settings)
            except Exception: pass
            for table in list(stats_tables):
                try: apply_stats_row_style(table)
                except Exception: pass

        def open_stats_rno_pdf(rno):
            canonical = str(rno or '').strip()
            if canonical.lower().endswith('.pdf'): canonical = canonical[:-4].strip()
            if not re.fullmatch(r'\d+[A-Za-z]?', canonical): return
            dlg_pdf = QDialog(sd)
            dlg_pdf.setWindowTitle(f'Approval PDF Preview — R.No. {canonical}')
            dlg_pdf.resize(1100, 850); dlg_pdf.setMinimumSize(850, 600)
            lp = QVBoxLayout(dlg_pdf)
            title = QLabel(f'📄 Approval PDF Preview — R.No. {canonical}')
            title.setStyleSheet('font-size:16px;font-weight:800;'); lp.addWidget(title)
            viewer = PdfViewer(); lp.addWidget(viewer,1)
            status = QLabel('Loading PDF…'); lp.addWidget(status)
            close_pdf = QPushButton('Close'); close_pdf.clicked.connect(dlg_pdf.accept); lp.addWidget(close_pdf)
            try:
                pdf_bytes, original_filename = self.db.get_pdf_blob_by_filename(f'{canonical}.pdf')
                if not pdf_bytes:
                    status.setText(f'PDF not found in MASTER.db for R.No. {canonical}.')
                else:
                    viewer.load_pdf_bytes(bytes(pdf_bytes), original_filename or f'{canonical}.pdf', [],
                                          self.settings.get('highlight_color', SEARCH_HIGHLIGHT_DEFAULT))
                    status.setText('✓ PDF loaded')
            except Exception as exc:
                status.setText(f'Could not load PDF: {exc}')
            dlg_pdf.exec()
            try: viewer.close_doc()
            except Exception: pass

        def attach_stats_rno_pdf(table):
            if getattr(table, '_hvpnl_rno_pdf_attached', False): return
            table._hvpnl_rno_pdf_attached = True
            cols=[]
            for i in range(table.columnCount()):
                h=table.horizontalHeaderItem(i)
                cols.append(h.text().strip().casefold() if h else '')
            rcols=[i for i,h in enumerate(cols) if h in {'r.no.','r.no','approval r.no.','approval r.no'}]
            if not rcols: return
            def clicked(row,col):
                if col not in rcols: return
                item=table.item(row,col)
                if item:
                    v=item.text().strip()
                    if v and v not in {'—','-','TOTAL'}: open_stats_rno_pdf(v)
            table.cellClicked.connect(clicked)

