        def _ratio_sort_key(ratio):
            nums = re.findall(r'\d+(?:\.\d+)?', str(ratio))
            if len(nums) >= 2:
                return (-float(nums[0]), -float(nums[1]), str(ratio))
            return (0, 0, str(ratio))

        def _stage_ratio_rows(textv):
            rows = {}
            for x in _sstn_parse_transformers(textv):
                if not transformer_filter_match(x):
                    continue
                key = (str(x.get('ratio') or ''), round(float(x.get('high_mva') or 0), 6))
                d = rows.setdefault(key, {'ratio': key[0], 'rating': float(x.get('high_mva') or 0), 'tf': 0, 'mva': 0.0})
                d['tf'] += int(x.get('count') or 0)
                d['mva'] += int(x.get('count') or 0) * float(x.get('high_mva') or 0)
            return rows

        def _category_matches_row(row, category):
            ratio = str(row.get('ratio') or '')
            hv = float(row.get('hv') or 0)
            if category in [voltage_labels[v] for v in voltage_levels]:
                catkv = category.replace(' ', '').upper()
                return f"{hv:g}KV" == catkv
            if re.fullmatch(r'\d+(?:\.\d+)? MVA', str(category)):
                return abs(float(category.split()[0]) - float(row.get('high_mva') or 0)) < 0.001
            return True

        def _stage_required_events(category):
            """Return actual stage-level required TF additions.

            A required TF is counted only when the current approved stage has
            more transformers than the immediately preceding recorded state.
            The comparison is made by exact stored voltage ratio + rating, so
            the detail can identify the actual substation, ratio and capacity.
            """
            events = []
            recs = filtered_records(district_box.currentText(), voltage_box.currentText(), ratio_box.currentText(), capacity_box.currentText())
            for r in recs:
                m = r['master']
                stages = r['stages']
                prev_text = next(
                    (x.get('existing_capacity', '') for x in stages
                     if str(x.get('existing_capacity') or '').strip()), ''
                )
                prev_rows = _stage_ratio_rows(prev_text)

                for st in stages:
                    fy = str(st.get('approved_fy') or '').strip()
                    cur_text = str(st.get('approved_capacity') or '').strip()
                    cur_rows = _stage_ratio_rows(cur_text)
                    if not fy:
                        prev_rows = cur_rows
                        continue

                    keys = sorted(set(prev_rows) | set(cur_rows), key=lambda k: _ratio_sort_key(k[0]) + (k[1],))
                    for key in keys:
                        ratio, rating = key
                        pr = prev_rows.get(key, {'tf': 0, 'mva': 0.0})
                        cr = cur_rows.get(key, {'tf': 0, 'mva': 0.0})

                        # Find the source transformer row again so voltage
                        # filtering is based on its actual HIGH-SIDE voltage.
                        sample = next(
                            (x for x in _sstn_parse_transformers(cur_text)
                             if str(x.get('ratio') or '') == ratio and
                                abs(float(x.get('high_mva') or 0) - rating) < 0.001),
                            None
                        )
                        if sample is None:
                            sample = next(
                                (x for x in _sstn_parse_transformers(prev_text)
                                 if str(x.get('ratio') or '') == ratio and
                                    abs(float(x.get('high_mva') or 0) - rating) < 0.001),
                                None
                            )
                        if sample is None:
                            continue

                        req = max(0, int(cr['tf']) - int(pr['tf']))
                        if req <= 0 or not _category_matches_row(sample, category):
                            continue

                        events.append({
                            'fy': fy,
                            'sstn_id': str(m.get('sstn_id') or ''),
                            'substation': str(m.get('sstn_name') or ''),
                            'district': str(m.get('district') or ''),
                            'master_voltage': str(m.get('voltage_level') or ''),
                            'ratio': ratio,
                            'rating': rating,
                            'required_tf': req,
                            'required_mva': req * rating,
                            'before_tf': int(pr['tf']),
                            'before_mva': float(pr['mva']),
                            'after_tf': int(cr['tf']),
                            'after_mva': float(cr['mva']),
                            'r_no': str(st.get('r_no') or '').strip(),
                            'infra_id': str(st.get('infra_id') or ''),
                            'seq_no': st.get('seq_no') or '',
                        })
                    prev_rows = cur_rows
                    prev_text = cur_text
            return events

        def show_required_voltage_detail(label):
            target = str(label).replace(' kV','KV').upper()
            dlg = QDialog(sd)
            dlg.setWindowTitle(f'Required Transformer Details — {label}')
            dlg.resize(1550,850); dlg.setMinimumSize(1100,650)
            lay=QVBoxLayout(dlg)
            intro=QLabel(
                f'All positive final Approved − Existing transformer requirements whose '
                f'transformer voltage-ratio HIGH SIDE is {label}. '
                f'The TOTAL row exactly equals the clicked Required-TF chart value.'
            )
            intro.setWordWrap(True); lay.addWidget(intro)
            table=make_table([
                'Substation','District','SSTN Voltage','Voltage Ratio','Rating',
                'Existing TFs','Existing MVA','Approved TFs','Approved MVA',
                'Required TFs','Required MVA','R.No.','Approval FY'
            ])
            lay.addWidget(table,1)
            recs=filtered_records(district_box.currentText(),voltage_box.currentText())
            ex_total=ap_total=req_total=0; exm_total=apm_total=reqm_total=0.0; rows=0
            for r in recs:
                m=r['master']; stages=r['stages']
                if not stages: continue
                prev_text=next((x.get('existing_capacity','') for x in stages
                                if str(x.get('existing_capacity') or '').strip()),'')
                final_text=stages[-1].get('approved_capacity','') or ''
                prev_rows=_stage_ratio_rows(prev_text); final_rows=_stage_ratio_rows(final_text)
                for key in sorted(set(prev_rows)|set(final_rows),
                                  key=lambda k:(_ratio_sort_key(k[0]),k[1])):
                    ratio,rating=key
                    sample=next((x for x in _sstn_parse_transformers(final_text)
                                 if str(x.get('ratio') or '')==ratio
                                 and abs(float(x.get('high_mva') or 0)-float(rating))<.001),None)
                    if sample is None:
                        sample=next((x for x in _sstn_parse_transformers(prev_text)
                                     if str(x.get('ratio') or '')==ratio
                                     and abs(float(x.get('high_mva') or 0)-float(rating))<.001),None)
                    if sample is None or f"{float(sample.get('hv') or 0):g}KV" != target: continue
                    pr=prev_rows.get(key,{'tf':0,'mva':0.0}); fr=final_rows.get(key,{'tf':0,'mva':0.0})
                    ex=int(pr.get('tf') or 0); ap=int(fr.get('tf') or 0); req=max(0,ap-ex)
                    if req<=0: continue
                    exm=float(pr.get('mva') or 0); apm=float(fr.get('mva') or 0); reqm=max(0.0,apm-exm)
                    fy=rno=''
                    for st in reversed(stages):
                        if str(st.get('approved_fy') or '').strip() and str(st.get('approved_capacity') or '').strip():
                            fy=str(st.get('approved_fy') or '').strip()
                            rno=str(st.get('r_no') or '').strip(); break
                    setrow(table,rows,[m.get('sstn_name',''),m.get('district',''),m.get('voltage_level',''),
                                       ratio,f'{float(rating):g} MVA',ex,f'{exm:,.1f}',ap,f'{apm:,.1f}',
                                       req,f'{reqm:,.1f}',rno or '—',fy or '—'])
                    rows+=1; ex_total+=ex; exm_total+=exm; ap_total+=ap; apm_total+=apm; req_total+=req; reqm_total+=reqm
            if rows==0:
                setrow(table,0,[f'No positive required-transformer records for {label}','','','','',0,'0.0',0,'0.0',0,'0.0','—','—'])
            else:
                add_total_row(table,['TOTAL','','','','',f'{ex_total:,}',f'{exm_total:,.1f}',
                                     f'{ap_total:,}',f'{apm_total:,.1f}',f'{req_total:,}',f'{reqm_total:,.1f}','',''])
            attach_stats_rno_pdf(table); apply_stats_row_style(table)
            close=QPushButton('Close'); close.clicked.connect(dlg.accept); lay.addWidget(close); dlg.exec()

        def show_required_ratio_detail(ratio):
            # V22.3.10: local normalizer for exact voltage-ratio matching.
            # This prevents NameError when the drill-down is invoked
            # from either Required-TF ratio chart.
            def norm(value):
                return re.sub(r'[^a-z0-9]+', '', str(value or '').casefold())

            dlg = QDialog(sd)
            dlg.setWindowTitle(f'Required Transformer Details — {ratio}')
            screen = QApplication.primaryScreen()
            if screen:
                geo = screen.availableGeometry()
                dlg.resize(min(1550, geo.width() - 50), min(850, geo.height() - 70))
            else:
                dlg.resize(1500, 820)
            dlg.setMinimumSize(1100, 650)
            lay = QVBoxLayout(dlg)
            intro = QLabel(
                f'Required transformers for exact voltage ratio {ratio}. '
                f'One row represents one substation + ratio, so the required-TF total exactly matches the clicked bar. '
                f'Capacity/rating composition, existing/approved capacity and approval R.No./FY are shown.'
            )
            intro.setWordWrap(True)
            intro.setStyleSheet('padding:6px;border:1px solid #3a4250;border-radius:7px;')
            lay.addWidget(intro)
            table = make_table([
                'Substation','District','SSTN Voltage','Voltage Ratio','Rating / Capacity',
                'Existing TFs','Existing MVA','Approved TFs','Approved MVA',
                'Required TFs','Required MVA','R.No.','Approval FY'
            ])
            lay.addWidget(table, 1)
            add_stats_export_bar(lay, table)
            recs = filtered_records(district_box.currentText(), voltage_box.currentText(), ratio_box.currentText(), capacity_box.currentText())
            target = norm(ratio)
            total_ex_tf = total_ex_mva = total_ap_tf = total_ap_mva = 0
            total_req_tf = total_req_mva = 0.0
            rows_added = 0
            for r in recs:
                m = r['master']; stages = r['stages']
                if not stages: continue
                prev_text = next((x.get('existing_capacity','') for x in stages if str(x.get('existing_capacity') or '').strip()), '')
                final_text = stages[-1].get('approved_capacity','') or ''
                prev_rows = _stage_ratio_rows(prev_text)
                final_rows = _stage_ratio_rows(final_text)
                # Aggregate by substation + ratio first. This is deliberately
                # different from the old rating-level loop: it prevents the
                # detail window from showing more TFs than the ratio chart bar.
                keys = sorted(set(k[0] for k in prev_rows) | set(k[0] for k in final_rows), key=_ratio_sort_key)
                for rr in keys:
                    if norm(rr) != target: continue
                    ex_parts = [d for k,d in prev_rows.items() if k[0] == rr]
                    ap_parts = [d for k,d in final_rows.items() if k[0] == rr]
                    ex_tf = sum(int(d.get('tf') or 0) for d in ex_parts)
                    ap_tf = sum(int(d.get('tf') or 0) for d in ap_parts)
                    req_tf = max(0, ap_tf - ex_tf)
                    if req_tf <= 0: continue
                    ex_mva = sum(float(d.get('mva') or 0) for d in ex_parts)
                    ap_mva = sum(float(d.get('mva') or 0) for d in ap_parts)
                    # Match the dashboard's Required-MVA definition exactly:
                    # positive Approved-Existing additions at each rating.
                    req_mva = 0.0
                    for _rk in set(k[1] for k in prev_rows if k[0] == rr) | set(k[1] for k in final_rows if k[0] == rr):
                        _pr = prev_rows.get((rr, _rk), {'tf':0})
                        _fr = final_rows.get((rr, _rk), {'tf':0})
                        req_mva += max(0, int(_fr.get('tf') or 0) - int(_pr.get('tf') or 0)) * float(_rk)
                    ratings = sorted({float(k[1]) for k in prev_rows if k[0] == rr} | {float(k[1]) for k in final_rows if k[0] == rr})
                    rating_text = ', '.join(f'{v:g}' for v in ratings if v > 0) + ' MVA'
                    rnos=[]; fys=[]
                    for st in stages:
                        rv=str(st.get('r_no') or '').strip()
                        fy=str(st.get('approved_fy') or '').strip()
                        if rv and rv not in rnos: rnos.append(rv)
                        if fy and fy not in fys: fys.append(fy)
                    setrow(table, rows_added, [
                        m.get('sstn_name',''), m.get('district',''), m.get('voltage_level',''), rr,
                        rating_text, ex_tf, f'{ex_mva:,.1f}', ap_tf, f'{ap_mva:,.1f}',
                        req_tf, f'{req_mva:,.1f}', ', '.join(rnos) or '—', ', '.join(fys) or '—'
                    ])
                    rows_added += 1
                    total_ex_tf += ex_tf; total_ex_mva += ex_mva
                    total_ap_tf += ap_tf; total_ap_mva += ap_mva
                    total_req_tf += req_tf; total_req_mva += req_mva
            if rows_added == 0:
                setrow(table, 0, ['No required transformers for this voltage ratio.','','','','',0,'0.0',0,'0.0',0,'0.0','—','—'])
            else:
                finish_stats_table(table, [
                    'TOTAL','','',ratio,'',f'{total_ex_tf:,}',f'{total_ex_mva:,.1f}',
                    f'{total_ap_tf:,}',f'{total_ap_mva:,.1f}',f'{total_req_tf:,}',
                    f'{total_req_mva:,.1f}','',''
                ])
            close=QPushButton('Close'); close.clicked.connect(dlg.accept); lay.addWidget(close)
            dlg.exec()

        def refresh_stats():
            nonlocal active_ratio_filter, active_capacity_filter
            active_ratio_filter = ratio_box.currentText()
            active_capacity_filter = capacity_box.currentText()
            recs = filtered_records(district_box.currentText(), voltage_box.currentText(), ratio_box.currentText(), capacity_box.currentText())
            ex_mva = sum(r['existing']['mva'] for r in recs)
            ex_tf = sum(r['existing']['tf_count'] for r in recs)
            ap_mva = sum(r['approved']['mva'] for r in recs)
            ap_tf = sum(r['approved']['tf_count'] for r in recs)
            needed = max(0, ap_tf - ex_tf)
            surplus = max(0, ex_tf - ap_tf)
            stages = sum(len(r['stages']) for r in recs)
            vals = [len(recs), f'{ex_mva:,.1f}', f'{ex_tf:,}', f'{ap_mva:,.1f}', f'{ap_tf:,}', f'{needed:,}', f'{surplus:,}', f'{stages:,}']
            for lab, val in zip(klabels, vals):
                lab.setText(str(val))

            # Main abstract capacity summary: high-side voltage + transformer rating.
            # It follows the same filtered records and Existing/Approved state definitions
            # used everywhere else in Statistics.
            exvr = aggregate_voltage_rating(recs, 'existing')
            apvr = aggregate_voltage_rating(recs, 'approved')
            vrkeys = sorted(
                set(exvr) | set(apvr),
                key=lambda k: (float(k[0].split('/')[0].strip()) if '/' in k[0] else 0.0, k[0], k[1])
            )
            cap_summary_table.setRowCount(0)
            total_ex_tf = total_ex_mva = total_ap_tf = total_ap_mva = 0
            for ratio, rating in vrkeys:
                ex = exvr.get((ratio, rating), {'tf': 0, 'mva': 0.0})
                ap = apvr.get((ratio, rating), {'tf': 0, 'mva': 0.0})
                setrow(cap_summary_table, cap_summary_table.rowCount(), [
                    f'{ratio} / {rating:g} MVA',
                    f"{ex['tf']:,}", f"{ex['mva']:,.1f}",
                    f"{ap['tf']:,}", f"{ap['mva']:,.1f}"
                ])
                total_ex_tf += ex['tf']; total_ex_mva += ex['mva']
                total_ap_tf += ap['tf']; total_ap_mva += ap['mva']
            finish_stats_table(cap_summary_table, [
                'TOTAL', f'{total_ex_tf:,}', f'{total_ex_mva:,.1f}',
                f'{total_ap_tf:,}', f'{total_ap_mva:,.1f}'
            ])

            # IMPORTANT: voltage buckets are transformer high-side buckets.
            # This fixes the previous error where all transformers inherited
            # the SSTN_MASTER voltage level of the substation.
            exv = aggregate_by_high_voltage(recs, 'existing')
            apv = aggregate_by_high_voltage(recs, 'approved')
            vmap = {}
            for v in voltage_levels:
                vmap[v] = {'sstn': 0, 'exm': exv[v]['mva'], 'ext': exv[v]['tf'], 'apm': apv[v]['mva'], 'apt': apv[v]['tf'], 'st': 0}
            for r in recs:
                # Voltage-wise Statistics are transformer HIGH-SIDE based.
                # Count a station only in a voltage bucket where at least one
                # filtered transformer actually exists.  Do not use the parent
                # SSTN_MASTER voltage for this count: that caused a 400 kV
                # substation to appear under an unrelated 132/33 kV filter.
                _seen_voltage = set()
                _seen_stage_count = 0
                for _state_text in (
                    next((x.get('existing_capacity', '') for x in r['stages']
                          if str(x.get('existing_capacity') or '').strip()), ''),
                    r['stages'][-1].get('approved_capacity', '') if r['stages'] else ''
                ):
                    for _x in _sstn_parse_transformers(_state_text):
                        if not transformer_filter_match(_x):
                            continue
                        _hv = float(_x.get('hv') or 0)
                        _match = next((v for v in voltage_levels if abs(_hv - v) < 0.01), None)
                        if _match is not None:
                            _seen_voltage.add(_match)
                for _match in _seen_voltage:
                    vmap[_match]['sstn'] += 1

                # Recorded stages are counted only when that stage contains a
                # transformer matching the active Ratio/Capacity filter.
                for _st in r['stages']:
                    _stage_match = False
                    for _field in ('existing_capacity', 'approved_capacity'):
                        for _x in _sstn_parse_transformers(_st.get(_field, '')):
                            if transformer_filter_match(_x):
                                _stage_match = True
                                break
                        if _stage_match:
                            break
                    if _stage_match:
                        _seen_stage_count += 1

                for _match in _seen_voltage:
                    vmap[_match]['st'] += _seen_stage_count

            vtable.setRowCount(0)
            cv_data=[]; cv_labels=[]; cf_data=[]; cf_labels=[]; req_data=[]; req_labels=[]; spr_data=[]; spr_labels=[]
            for v in voltage_levels:
                x = vmap[v]
                need = max(0, x['apt'] - x['ext'])
                spare = max(0, x['ext'] - x['apt'])
                label = voltage_labels[v]
                setrow(vtable, vtable.rowCount(), [label, x['sstn'], f"{x['exm']:,.1f}", x['ext'], f"{x['apm']:,.1f}", x['apt'], need, spare, x['st']])
                cv_data.append((label, x['exm'])); cv_labels.append(f"{x['exm']:,.1f} MVA | {x['ext']:,} TF")
                cf_data.append((label, x['ext'])); cf_labels.append(f"{x['ext']:,} TF | {x['exm']:,.1f} MVA")
                req_data.append((label, need)); req_labels.append(f"{need:,} TF")
                spr_data.append((label, spare)); spr_labels.append(f"{spare:,} TF")
            cv.set_data(cv_data, cv_labels); cf.set_data(cf_data, cf_labels); req.set_data(req_data, req_labels); spr.set_data(spr_data, spr_labels)

            # Ratio-wise data comes directly from parsed transformer ratios.
            exr = aggregate_ratio(recs, 'existing'); apr = aggregate_ratio(recs, 'approved')
            ratios = sorted(set(exr) | set(apr), key=lambda s: (-float(re.search(r'\d+(?:\.\d+)?', s).group(0)), -float(re.search(r'/\s*(\d+(?:\.\d+)?)', s).group(1))))
            rtable.setRowCount(0); rmva=[]; rmva_labels=[]; rqty=[]; rqty_labels=[]
            for ratio in ratios:
                ex = exr.get(ratio, {'tf':0,'mva':0.0}); ap = apr.get(ratio, {'tf':0,'mva':0.0})
                need=max(0,ap['tf']-ex['tf']); spare=max(0,ex['tf']-ap['tf'])
                setrow(rtable, rtable.rowCount(), [ratio, ex['tf'], f"{ex['mva']:,.1f}", ap['tf'], f"{ap['mva']:,.1f}", need, spare])
                rmva.append((ratio, ex['mva'])); rmva_labels.append(f"{ex['mva']:,.1f} MVA | {ex['tf']:,} TF")
                rqty.append((ratio, ex['tf'])); rqty_labels.append(f"{ex['tf']:,} TF | {ex['mva']:,.1f} MVA")
            ratio_mva.set_data(rmva, rmva_labels); ratio_qty.set_data(rqty, rqty_labels)

            # Required TFs by exact voltage ratio.  IMPORTANT: calculate the
            # required capacity with the same per-substation + ratio + rating
            # logic used by show_required_ratio_detail().  Do not subtract
            # ratio-level totals first, because rating/substation differences
            # can otherwise create a false MVA requirement.  This keeps the
            # clicked chart value exactly equal to the drill-down TOTAL row.
            required_ratio = {}
            for rr in recs:
                stages = rr.get('stages') or []
                if not stages:
                    continue
                extext = next((x.get('existing_capacity', '') for x in stages
                               if str(x.get('existing_capacity') or '').strip()), '')
                aptext = stages[-1].get('approved_capacity', '') or ''
                exrows = _stage_ratio_rows(extext)
                aprows = _stage_ratio_rows(aptext)
                # IMPORTANT: Required TFs must be the NET transformer-count
                # increase for each substation + exact voltage ratio, exactly
                # as used by the clicked drill-down.  Do NOT sum positive
                # rating-level differences for the TF count, because a rating
                # change can otherwise count the same net transformer more
                # than once.
                ratio_keys = sorted(
                    set(k[0] for k in exrows) | set(k[0] for k in aprows),
                    key=_ratio_sort_key
                )
                for ratio in ratio_keys:
                    ex_parts = [d for k, d in exrows.items() if k[0] == ratio]
                    ap_parts = [d for k, d in aprows.items() if k[0] == ratio]
                    ex_tf = sum(int(d.get('tf') or 0) for d in ex_parts)
                    ap_tf = sum(int(d.get('tf') or 0) for d in ap_parts)
                    need_tf = max(0, ap_tf - ex_tf)
                    if need_tf <= 0:
                        continue

                    # Required MVA follows the same rating-level positive
                    # additions used in the drill-down.  This gives the
                    # actual add-on capacity while the TF count remains the
                    # net count for the ratio.
                    need_mva = 0.0
                    for rating in set(k[1] for k in exrows if k[0] == ratio) | set(k[1] for k in aprows if k[0] == ratio):
                        exd = exrows.get((ratio, rating), {'tf': 0})
                        apd = aprows.get((ratio, rating), {'tf': 0})
                        need_mva += max(
                            0,
                            int(apd.get('tf') or 0) - int(exd.get('tf') or 0)
                        ) * float(rating)

                    d = required_ratio.setdefault(ratio, {'tf': 0, 'mva': 0.0})
                    d['tf'] += need_tf
                    d['mva'] += need_mva

            required_ratio_table.setRowCount(0)
            rr_tf=[]; rr_tf_labels=[]; rr_mva=[]; rr_mva_labels=[]
            for ratio in sorted(required_ratio, key=_ratio_sort_key):
                d=required_ratio[ratio]
                ex=exr.get(ratio, {'tf':0,'mva':0.0})
                ap=apr.get(ratio, {'tf':0,'mva':0.0})
                setrow(required_ratio_table, required_ratio_table.rowCount(), [
                    ratio, d['tf'], f"{d['mva']:,.1f}",
                    ex['tf'], f"{ex['mva']:,.1f}", ap['tf'], f"{ap['mva']:,.1f}"
                ])
                rr_tf.append((ratio, d['tf']))
                rr_tf_labels.append(f"{d['tf']:,} TF | {d['mva']:,.1f} MVA")
                rr_mva.append((ratio, d['mva']))
                rr_mva_labels.append(f"{d['mva']:,.1f} MVA | {d['tf']:,} TF")
            required_ratio_chart.set_data(rr_tf, rr_tf_labels)
            required_ratio_mva_chart.set_data(rr_mva, rr_mva_labels)

            # Rating-wise data.
            exrate={}; aprate={}
            for r in recs:
                extext=next((x.get('existing_capacity','') for x in r['stages'] if str(x.get('existing_capacity') or '').strip()), '')
                aptext=r['stages'][-1].get('approved_capacity','')
                for state, textv in [('ex', extext), ('ap', aptext)]:
                    for x in _sstn_parse_transformers(textv):
                        if not transformer_filter_match(x):
                            continue
                        rating=f"{x['high_mva']:g} MVA"
                        d=(exrate if state=='ex' else aprate).setdefault(rating, {'tf':0,'mva':0.0})
                        d['tf'] += x['count']; d['mva'] += x['count']*x['high_mva']
            ratings=sorted(set(exrate)|set(aprate), key=lambda s: float(s.split()[0]))
            ctable.setRowCount(0); rat_mva=[]; rat_mva_labels=[]; rat_qty=[]; rat_qty_labels=[]
            for rating in ratings:
                ex=exrate.get(rating,{'tf':0,'mva':0.0}); ap=aprate.get(rating,{'tf':0,'mva':0.0}); need=max(0,ap['tf']-ex['tf']); spare=max(0,ex['tf']-ap['tf'])
                setrow(ctable, ctable.rowCount(), [rating, ex['tf'], f"{ex['mva']:,.1f}", ap['tf'], f"{ap['mva']:,.1f}", need, spare])
                rat_mva.append((rating, ex['mva'])); rat_mva_labels.append(f"{ex['mva']:,.1f} MVA | {ex['tf']:,} TF")
                rat_qty.append((rating, ex['tf'])); rat_qty_labels.append(f"{ex['tf']:,} TF | {ex['mva']:,.1f} MVA")
            rating_mva.set_data(rat_mva, rat_mva_labels); rating_qty.set_data(rat_qty, rat_qty_labels)

            # Year-wise growth:
            # 1) Calculate the NEW approved addition at each approval stage by
            #    comparing that stage with the immediately preceding state.
            # 2) Aggregate those annual additions by FY.
            # 3) Build a CUMULATIVE series for the line charts.  A growth curve
            #    must not fall merely because a later FY has a smaller addition.
            fy={}
            for r in recs:
                prev=r['existing']
                for st in r['stages']:
                    fyraw=str(st.get('approved_fy') or '').strip()
                    cur=state_totals(st.get('approved_capacity',''))
                    if fyraw:
                        d=fy.setdefault(fyraw, {'mva':0.0,'tf':0,'stations':0,'stages':0})
                        d['mva'] += max(0.0, cur['mva']-prev['mva'])
                        d['tf'] += max(0, cur['tf_count']-prev['tf_count'])
                        d['stations'] += 1
                        d['stages'] += 1
                    prev=cur

            ykeys=sorted(
                fy,
                key=lambda x: (
                    int(re.search(r'20\d{2}',x).group(0)) if re.search(r'20\d{2}',x) else 9999,
                    x
                )
            )

            # Cumulative approved growth across the selected filters.
            cum_mva=0.0
            cum_tf=0
            ytable.setRowCount(0)
            fycap_data=[]; fycap_labels=[]; fyqty_data=[]; fyqty_labels=[]
            for fykey in ykeys:
                y=fy[fykey]
                cum_mva += y['mva']
                cum_tf += y['tf']
                setrow(
                    ytable,
                    ytable.rowCount(),
                    [
                        fykey,
                        f"{y['mva']:,.1f}",
                        f"{y['tf']:,}",
                        f"{cum_mva:,.1f}",
                        f"{cum_tf:,}",
                        y['stations'],
                        y['stages']
                    ]
                )
                # Charts intentionally plot CUMULATIVE values.
                fycap_data.append((fykey, cum_mva))
                fycap_labels.append(f"{cum_mva:,.1f} MVA")
                fyqty_data.append((fykey, cum_tf))
                fyqty_labels.append(f"{cum_tf:,} TF")

            fycap.set_data(fycap_data, fycap_labels)
            fyqty.set_data(fyqty_data, fyqty_labels)

            # Column totals for every dashboard table. These are derived from the
            # same records used by the charts, so chart/table totals remain auditable.
            finish_stats_table(vtable, ['TOTAL', f'{sum(vmap[v]['sstn'] for v in voltage_levels):,}',
                f'{sum(vmap[v]['exm'] for v in voltage_levels):,.1f}', f'{sum(vmap[v]['ext'] for v in voltage_levels):,}',
                f'{sum(vmap[v]['apm'] for v in voltage_levels):,.1f}', f'{sum(vmap[v]['apt'] for v in voltage_levels):,}',
                f'{sum(max(0, vmap[v]['apt']-vmap[v]['ext']) for v in voltage_levels):,}',
                f'{sum(max(0, vmap[v]['ext']-vmap[v]['apt']) for v in voltage_levels):,}',
                f'{sum(vmap[v]['st'] for v in voltage_levels):,}'])

            finish_stats_table(rtable, ['TOTAL', f'{sum(exr.get(k,{'tf':0})['tf'] for k in ratios):,}',
                f'{sum(exr.get(k,{'mva':0})['mva'] for k in ratios):,.1f}',
                f'{sum(apr.get(k,{'tf':0})['tf'] for k in ratios):,}',
                f'{sum(apr.get(k,{'mva':0})['mva'] for k in ratios):,.1f}',
                f'{sum(max(0, apr.get(k,{'tf':0})['tf']-exr.get(k,{'tf':0})['tf']) for k in ratios):,}',
                f'{sum(max(0, exr.get(k,{'tf':0})['tf']-apr.get(k,{'tf':0})['tf']) for k in ratios):,}'])

            finish_stats_table(required_ratio_table, ['TOTAL',
                f'{sum(d['tf'] for d in required_ratio.values()):,}',
                f'{sum(d['mva'] for d in required_ratio.values()):,.1f}',
                f'{sum(exr.get(k,{'tf':0})['tf'] for k in required_ratio):,}',
                f'{sum(exr.get(k,{'mva':0})['mva'] for k in required_ratio):,.1f}',
                f'{sum(apr.get(k,{'tf':0})['tf'] for k in required_ratio):,}',
                f'{sum(apr.get(k,{'mva':0})['mva'] for k in required_ratio):,.1f}'])

            finish_stats_table(ctable, ['TOTAL', f'{sum(exrate.get(k,{'tf':0})['tf'] for k in ratings):,}',
                f'{sum(exrate.get(k,{'mva':0})['mva'] for k in ratings):,.1f}',
                f'{sum(aprate.get(k,{'tf':0})['tf'] for k in ratings):,}',
                f'{sum(aprate.get(k,{'mva':0})['mva'] for k in ratings):,.1f}',
                f'{sum(max(0,aprate.get(k,{'tf':0})['tf']-exrate.get(k,{'tf':0})['tf']) for k in ratings):,}',
                f'{sum(max(0,exrate.get(k,{'tf':0})['tf']-aprate.get(k,{'tf':0})['tf']) for k in ratings):,}'])

            # Year-wise TOTAL: annual additions are summed; cumulative columns
            # show the final cumulative value, not a sum of cumulative points.
            _fy_total_mva = sum(y['mva'] for y in fy.values())
            _fy_total_tf = sum(y['tf'] for y in fy.values())
            _fy_final_cum_mva = sum(y['mva'] for y in fy.values())
            _fy_final_cum_tf = sum(y['tf'] for y in fy.values())
            finish_stats_table(ytable, ['TOTAL',
                f'{_fy_total_mva:,.1f}',
                f'{_fy_total_tf:,}',
                f'{_fy_final_cum_mva:,.1f}',
                f'{_fy_final_cum_tf:,}',
                f'{sum(y["stations"] for y in fy.values()):,}',
                f'{sum(y["stages"] for y in fy.values()):,}'])


        # Click actions.
        cv.clicked.connect(lambda label, val, idx: show_voltage_detail(label))
        cf.clicked.connect(lambda label, val, idx: show_voltage_detail(label))
        req.clicked.connect(lambda label, val, idx: show_required_voltage_detail(label))
        spr.clicked.connect(lambda label, val, idx: show_yearwise('Spare / Surplus', label))
        ratio_mva.clicked.connect(lambda label, val, idx: show_ratio_detail(label))
        ratio_qty.clicked.connect(lambda label, val, idx: show_ratio_detail(label))
        # V22.3.8: explicit and diagnostic routing for Required TFs — Ratio.
        def _open_required_ratio_from_chart(label):
            try:
                show_required_ratio_detail(str(label))
            except Exception as exc:
                QMessageBox.critical(
                    sd,
                    APP_NAME,
                    f"Could not open Required Transformer Details for {label}:\\n\\n{exc}"
                )

        required_ratio_chart.clicked.connect(
            lambda label, val, idx: _open_required_ratio_from_chart(label)
        )
        required_ratio_mva_chart.clicked.connect(
            lambda label, val, idx: _open_required_ratio_from_chart(label)
        )
        rating_mva.clicked.connect(lambda label, val, idx: show_rating_detail(label))
        rating_qty.clicked.connect(lambda label, val, idx: show_rating_detail(label))

        district_box.currentTextChanged.connect(refresh_stats)
        voltage_box.currentTextChanged.connect(refresh_stats)
        ratio_box.currentTextChanged.connect(refresh_stats)
        capacity_box.currentTextChanged.connect(refresh_stats)
        refresh_stats()
        close = QPushButton('Close'); close.clicked.connect(sd.accept); root.addWidget(close)
        sd.exec()

