        scene = QGraphicsScene()

        class _NetworkGraphicsView(QGraphicsView):
            """Interactive network canvas: wheel zoom + hand-pan."""
            def wheelEvent(self, event):
                delta = event.angleDelta().y()
                if not delta:
                    return
                self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
                factor = 1.18 if delta > 0 else (1.0 / 1.18)
                self.scale(factor, factor)
                event.accept()

        class _NetworkNodeItem(QGraphicsRectItem):
            """Movable station block that keeps network edges live while dragging."""
            def itemChange(self, change, value):
                out = super().itemChange(change, value)
                if change == QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged:
                    refresh = getattr(self, "_edge_refresh", None)
                    if refresh:
                        QTimer.singleShot(0, refresh)
                return out

        view = _NetworkGraphicsView(scene)
        view.setRenderHint(QPainter.RenderHint.Antialiasing)
        view.setDragMode(QGraphicsView.DragMode.ScrollHandDrag)
        view.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse)
        view.setResizeAnchor(QGraphicsView.ViewportAnchor.AnchorViewCenter)
        view.setInteractive(True)
        network_lay.addWidget(view, 1)
