    def open_substation_map(self):
        """Premium HVPNL GIS workspace.

        Design goals:
          • map-first left pane (about 80% of its height)
          • compact station information / approvals above the map (about 20%)
          • dedicated PDF preview on the right
          • every approval R.No. is independently clickable
          • GIS station search focuses the map on the selected station
          • scalable presentation for hundreds of substations
          • clicking a station synchronises District Map, District Infra and Approval tabs
        """
        rows = self.db.list_substations()
        dlg = QDialog(self)
        dlg.setWindowTitle('🗺 Haryana Transmission Substation GIS Map')
        dlg.resize(1580, 920)
        dlg.setMinimumSize(1180, 700)

        # Modal GIS dialog gets its own WindowShortcut.  The main-window
        # QShortcut cannot reliably receive keys while a modal QDialog/WebEngine
        # window owns keyboard focus.  This invokes the exact same project-wide
        # Screen OCR function and therefore the same high-accuracy OCR pipeline.
        try:
            gis_ocr_shortcut = QShortcut(
                QKeySequence(str(self.settings.get('screen_ocr_shortcut', 'Ctrl+Q') or 'Ctrl+Q')),
                dlg
            )
            gis_ocr_shortcut.setContext(Qt.ShortcutContext.WindowShortcut)
            gis_ocr_shortcut.activated.connect(self.start_screen_ocr_capture)
            dlg._gis_ocr_shortcut = gis_ocr_shortcut
        except Exception:
            dlg._gis_ocr_shortcut = None

        root = QVBoxLayout(dlg)
        root.setContentsMargins(10, 8, 10, 10)
        root.setSpacing(7)

        if not rows:
            msg = QLabel(
                'No SSTN GIS records were found.\n\n'
                'SSTN_MASTER and SSTN_INFRA are expected inside MASTER.db\n'
                f'Application folder: {BASE_DIR}'
            )
            msg.setWordWrap(True)
            root.addWidget(msg)
            pick = QPushButton('Locate SSTN_MASTER.db')
            def locate_sstn():
                fn, _ = QFileDialog.getOpenFileName(dlg, 'Select SSTN_MASTER.db', str(BASE_DIR), 'SQLite Database (*.db *.sqlite);;All Files (*.*)')
                if fn:
                    try:
                        test = sqlite3.connect(fn, timeout=5)
                        try:
                            if not test.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='SSTN_MASTER'").fetchone():
                                raise RuntimeError('Selected database does not contain SSTN_MASTER table.')
                            if not test.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='SSTN_INFRA'").fetchone():
                                raise RuntimeError('Selected database does not contain SSTN_INFRA table.')
                        finally: test.close()
                        os.environ[SSTN_DB_ENV] = fn
                        QMessageBox.information(dlg, APP_NAME, 'SSTN database selected. Reopening the GIS map now.')
                        dlg.accept(); QTimer.singleShot(0, self.open_substation_map)
                    except Exception as e:
                        QMessageBox.warning(dlg, APP_NAME, f'Invalid SSTN database:\n\n{e}')
            pick.clicked.connect(locate_sstn)
            root.addWidget(pick)
            b = QPushButton('Close'); b.clicked.connect(dlg.accept); root.addWidget(b)
            dlg.exec(); return
        if not WEBENGINE_AVAILABLE:
            msg = QLabel('QtWebEngine is not installed in this build. Add PySide6-WebEngine to the setup package to display the map inside the application.')
            msg.setWordWrap(True)
            root.addWidget(msg)
            b = QPushButton('Close'); b.clicked.connect(dlg.accept); root.addWidget(b)
            dlg.exec(); return

        defaults_for_legend = {765:'#7C3AED', 400:'#D62828', 220:'#2E9B4B', 132:'#2563EB', 66:'#7C3AED'}

        # Resolve the active application theme locally.  This function is
        # opened independently from apply_styles(), so it must not rely on a
        # local variable such as `choice` from another function.  SYSTEM is
        # resolved exactly the same way as MainWindow.apply_styles().
        choice = str(self.settings.get("theme", "SYSTEM")).upper()
        if choice == "SYSTEM":
            choice = "DARK" if QApplication.palette().color(QPalette.ColorRole.Window).lightness() < 128 else "LIGHT"
        _theme_tokens = {
            "DARK":("#1f2126","#181a1f","#24262c","#292c33","#30343c","#343842","#e6e8ec","#9ca3af","#78a8ff","#4fae87"),
            "LIGHT":("#f4f6f9","#e9edf3","#ffffff","#ffffff","#eef2f7","#cbd2dc","#172033","#4b5563","#315fca","#147a55"),
            "MIDNIGHT BLUE":("#172033","#101827","#1e2a40","#23314b","#2c3c59","#38506f","#edf4ff","#9eb1cb","#62a5ff","#49c28b"),
            "FOREST":("#18261f","#101b15","#203326","#273d2d","#304b36","#3d5845","#edf7ef","#a7b9aa","#6bcf9c","#78c86d"),
            "ROYAL PURPLE":("#251d31","#1b1524","#30243f","#382a49","#443357","#5a4670","#f4edff","#c1b1d2","#ae8cff","#70d6ba"),
            "COFFEE":("#2a211d","#1e1815","#342923","#3d3028","#4b3b31","#5c493d","#f7efe7","#c7b7a7","#e0a56d","#91bd7a"),
            "SLATE":("#20272d","#171c21","#29323a","#303b45","#3a4752","#4a5966","#eef3f7","#aab7c2","#78b7ff","#64c5a2"),
            "SOLARIZED":("#002b36","#00212a","#073642","#0b4654","#145564","#1f6270","#eee8d5","#93a1a1","#268bd2","#2aa198"),
        }
